INSERT OR REPLACE INTO chapters (id, course_id, slug, chapter_number, title_sv, summary_sv, is_free, estimated_minutes, sort_order) VALUES ('chap-engelska-5-1', 'course-engelska-5', 'lasforstaelse-och-register', 1, 'Läsförståelse, språkligt register och grammatisk precision', 'Strategier för läsförståelse, skillnaden mellan formellt och vardagligt register samt vanliga grammatiska fällor som subjekt–predikatkongruens och it/there.', 1, 45, 1);
