INSERT OR REPLACE INTO chapters (id, course_id, slug, chapter_number, title_sv, summary_sv, is_free, estimated_minutes, sort_order) VALUES ('chap-engelska-6-1', 'course-engelska-6', 'formellt-skrivande-och-retorisk-analys', 1, 'Formellt skrivande, stilnivå och retorisk analys', 'Akademisk ton och sammanhangsmarkörer, retorisk analys av engelska tal och ledare samt passiv form, relativsatser och komplex meningsbyggnad.', 1, 50, 1);
INSERT OR REPLACE INTO chapters (id, course_id, slug, chapter_number, title_sv, summary_sv, is_free, estimated_minutes, sort_order) VALUES ('chap-engelska-6-2', 'course-engelska-6', 'kallkritik-och-argumenterande-essa', 2, 'Källkritik och argumenterande essä', 'Att integrera engelska källor i argumentation, bemöta motargument och undvika plagiat.', 0, 35, 2);
INSERT OR REPLACE INTO chapters (id, course_id, slug, chapter_number, title_sv, summary_sv, is_free, estimated_minutes, sort_order) VALUES ('chap-engelska-6-3', 'course-engelska-6', 'skonlitterar-analys-och-nyanser', 3, 'Skönlitterär analys och språkliga nyanser', 'Karaktärisering, berättarperspektiv, bildspråk och undertext (foreshadowing) i engelskspråkig fiktion.', 0, 35, 3);
INSERT OR REPLACE INTO chapters (id, course_id, slug, chapter_number, title_sv, summary_sv, is_free, estimated_minutes, sort_order) VALUES ('chap-engelska-7-1', 'course-engelska-7', 'akademisk-text-och-nyanserad-grammatik', 1, 'Akademisk argumentation, avancerad grammatik och källsyntes', 'Nyanserad akademisk stil med hedging, avancerad syntax som inversion och konjunktiv samt kritisk läsning och syntes av komplexa källor.', 1, 55, 1);
