INSERT OR REPLACE INTO chapters (id, course_id, slug, chapter_number, title_sv, summary_sv, is_free, estimated_minutes, sort_order) VALUES ('chap-engelska-7-3', 'course-engelska-7', 'vetenskaplig-abstract-och-rapport', 3, 'Sammanfattning, abstract och formell rapport', 'Uppbyggnaden av ett vetenskapligt abstract enligt IMRaD, objektiv sammanfattning och formell precision.', 0, 35, 3);

-- 4. STUDY LESSONS
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-1-energibegreppet', 'chap-fysik-1b-1', 'energibegreppet', 1, 'Energibegreppet', '[{"term":"Energi (E)","definition":"Förmågan att uträtta mekaniskt arbete eller avge värme.","unit":"J (joule)"},{"term":"Arbete (W)","definition":"Energiöverföring när en kraft flyttar ett föremål längs en sträcka i kraftens riktning.","unit":"J (1 J = 1 N·m)"},{"term":"Energiprincipen","definition":"Energi kan varken skapas eller förstöras, bara omvandlas mellan olika energiformer. Totalenergin i ett slutet system är konstant."},{"term":"Effekt (P)","definition":"Utfört arbete eller omvandlad energi per tidsenhet.","unit":"W (1 W = 1 J/s)"}]', '[{"heading":"Energiformer och energiprincipen","bodySv":"I fysiken är energi ett mått på förmågan att utföra arbete eller åstadkomma en förändring, exempelvis uppvärmning. Energi förekommer i flera former såsom lägesenergi, rörelseenergi, kemisk energi, elektrisk energi och termisk energi (värme). Enligt energiprincipen förblir den totala energin i ett slutet system alltid densamma — när en form minskar har lika mycket övergått till en eller flera andra former.","deepDiveSv":"SI-enheten joule kan uttryckas i grundenheterna som 1 J = 1 N·m = 1 kg·m²/s². Prefixet kilo betyder tusen, så 1 kJ = 1 000 J och 1 MJ = 1 000 000 J. I formler måste energi alltid anges i rena joule när övriga storheter är i meter, kilogram och sekunder."},{"heading":"Mekaniskt arbete och effekt","bodySv":"När du lyfter eller drar ett föremål med en konstant kraft F i rörelsens riktning längs sträckan s utför du det mekaniska arbetet W = F · s. Om tyngden redan är angiven i newton (N) är detta värde direkt kraften F och ska inte multipliceras med g = 9,82 N/kg. Divideras arbetet med den tid t som förloppet tar får man medeleffekten P.","deepDiveSv":"Allmänt gäller W = F · s · cos α, där α är vinkeln mellan kraftens riktning och förflyttningen. När kraften är vinkelrät mot rörelsen (α = 90°) är cos 90° = 0 och kraften utför inget mekaniskt arbete."}]', '[{"nameSv":"Mekaniskt arbete","latex":"W = F \\cdot s","explanationSv":"Gäller när kraften F verkar parallellt med förflyttningen s. Enheten 1 N·m motsvarar exakt 1 J.","variables":[{"symbol":"W","meaningSv":"Arbete","unit":"J"},{"symbol":"F","meaningSv":"Kraft i rörelseriktningen","unit":"N"},{"symbol":"s","meaningSv":"Sträcka","unit":"m"}]},{"nameSv":"Medeleffekt","latex":"P = \\frac{W}{t}","explanationSv":"Anger hur snabbt energi omvandlas. En watt motsvarar en joule per sekund.","variables":[{"symbol":"P","meaningSv":"Effekt","unit":"W"},{"symbol":"W","meaningSv":"Arbete eller överförd energi","unit":"J"},{"symbol":"t","meaningSv":"Tid","unit":"s"}]}]', '[{"gradeLevel":"E","titleSv":"Lyfta en skolväska med given tyngd","givenSv":"F = 65 N, s = 0,85 m","findSv":"Lyftarbetet W","methodSv":"Eftersom tyngden redan är angiven i newton används W = F · s direkt.","stepsSv":["Kontrollera enheterna: kraften är i N och sträckan i m.","Sätt in värdena: W = 65 · 0,85 = 55,25 J.","Avrunda till två gällande siffror: W ≈ 55 J."],"answerSv":"Arbetet är 55 J."},{"gradeLevel":"C","titleSv":"Effekt vid ett lådlyft i kJ","givenSv":"W = 3,6 kJ, F = 150 N, t = 12 s","findSv":"Lyfthöjden s och medeleffekten P","methodSv":"Omvandla kJ till J och lös ut s = W / F samt P = W / t.","stepsSv":["Omvandla energi till SI-enhet: W = 3,6 kJ = 3 600 J.","Beräkna sträckan: s = 3 600 / 150 = 24 m.","Beräkna effekten: P = 3 600 / 12 = 300 W."],"answerSv":"Lyfthöjden är 24 m och effekten är 300 W."},{"gradeLevel":"A","titleSv":"Dragkraft i vinkel mot underlaget","givenSv":"F = 120 N i vinkeln α = 35° mot horisontalplanet, s = 8,0 m, t = 4,0 s","findSv":"Utfört arbete W och nyttig drageffekt P","methodSv":"Använd kraftkomposanten i rörelseriktningen F_x = F · cos α.","stepsSv":["Beräkna komposanten längs golvet: F_x = 120 · cos 35° ≈ 98,30 N.","Beräkna arbetet: W = 98,30 · 8,0 ≈ 786,4 J.","Beräkna medeleffekten: P = 786,4 / 4,0 ≈ 196,6 W ≈ 0,20 kW."],"answerSv":"Arbetet är 0,79 kJ och medeleffekten är 0,20 kW."}]', '[{"trapTitleSv":"Tyngden står redan i newton","wrongApproachSv":"Att multiplicera en given tyngd i N med g = 9,82 en gång till.","rightApproachSv":"Står tyngden i N är kraften redan F. Använd W = F · s direkt."},{"trapTitleSv":"Glömt prefix mellan kJ och J","wrongApproachSv":"Att sätta in 5,0 kJ som talet 5,0 i formler med N, m och s.","rightApproachSv":"Omvandla alltid kilojoule till joule först: 1 kJ = 1 000 J."},{"trapTitleSv":"Energiprincipen tolkas som att energi försvinner","wrongApproachSv":"Att skriva att energi förstörs eller tar slut vid friktion.","rightApproachSv":"Energi kan aldrig förstöras; totalenergin är alltid bevarad och omvandlas oftast till värme."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-1-lagesenergi', 'chap-fysik-1b-1', 'lagesenergi', 2, 'Lägesenergi', '[{"term":"Lägesenergi (Ep)","definition":"Potentiell energi lagrad på grund av ett föremåls höjd över en vald nollnivå.","unit":"J (joule)"},{"term":"Tyngdfaktor (g)","definition":"Jordens tyngdkraft per kilogram massa i Sverige.","unit":"9,82 N/kg"},{"term":"Nollnivå","definition":"Den referenshöjd där h = 0 m och lägesenergin definieras som Ep = 0 J.","unit":"m"}]', '[{"heading":"Lägesenergi och val av nollnivå","bodySv":"Ett föremål med massan m som befinner sig på höjden h över en vald nollnivå har lägesenergin Ep = m · g · h. Ju större massa och ju högre höjd över nollnivån, desto mer energi finns lagrad. Nollnivån väljs fritt utifrån uppgiften — oftast marken, golvet eller dalens lägsta punkt — så länge samma nollnivå behålls genom hela beräkningen.","deepDiveSv":"För att lyfta ett föremål med konstant fart rakt upp krävs en lyftkraft lika stor som tyngden F = m · g. Lyftarbetet upp till höjden h blir då W = F · s = m · g · h = Ep. På jordytan i Sverige används standardvärdet g = 9,82 N/kg.","svgDiagram":"<svg viewBox=\"0 0 360 130\" width=\"100%\" aria-label=\"Lägesenergi över vald nollnivå\">\n  <line x1=\"24\" y1=\"108\" x2=\"336\" y2=\"108\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <text x=\"28\" y=\"123\" font-size=\"11\" fill=\"currentColor\">Nollnivå h = 0 m (Ep = 0 J)</text>\n  <line x1=\"120\" y1=\"26\" x2=\"210\" y2=\"26\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\" />\n  <circle cx=\"165\" cy=\"26\" r=\"7\" fill=\"var(--accent)\" />\n  <line x1=\"230\" y1=\"26\" x2=\"230\" y2=\"108\" stroke=\"var(--accent)\" stroke-width=\"1.5\" />\n  <text x=\"238\" y=\"70\" font-size=\"12\" fill=\"var(--accent)\">h</text>\n  <text x=\"158\" y=\"16\" font-size=\"11\" fill=\"currentColor\">m</text>\n</svg>"}]', '[{"nameSv":"Lägesenergi (potentiell energi)","latex":"E_p = m \\cdot g \\cdot h","explanationSv":"Beror linjärt av massan m och höjden h över den valda nollnivån, med g = 9{,}82 N/kg.","variables":[{"symbol":"E_p","meaningSv":"Lägesenergi","unit":"J"},{"symbol":"m","meaningSv":"Massa","unit":"kg"},{"symbol":"g","meaningSv":"Tyngdfaktor (9,82)","unit":"N/kg"},{"symbol":"h","meaningSv":"Höjd över nollnivån","unit":"m"}]}]', '[{"gradeLevel":"E","titleSv":"Simhoppare på trampolin","givenSv":"m = 62 kg, h = 10 m, g = 9,82 N/kg","findSv":"Simhopparens lägesenergi Ep relativt vattenytan","methodSv":"Sätt vattenytan som nollnivå (h = 0 m) och beräkna Ep = m · g · h.","stepsSv":["Ställ upp formeln: Ep = m · g · h.","Sätt in värdena: Ep = 62 · 9,82 · 10 = 6 088,4 J.","Avrunda: Ep ≈ 6,1 kJ."],"answerSv":"Lägesenergin är 6,1 kJ (6 088 J)."},{"gradeLevel":"C","titleSv":"Okänd höjd utifrån lagrad lägesenergi","givenSv":"m = 25 kg, Ep = 1,473 kJ, g = 9,82 N/kg","findSv":"Höjden h över golvet","methodSv":"Omvandla energi till joule och lös ut h ur Ep = m · g · h.","stepsSv":["Omvandla enheten: Ep = 1,473 kJ = 1 473 J.","Lös ut höjden: h = Ep / (m · g).","Beräkna: h = 1 473 / (25 · 9,82) = 1 473 / 245,5 = 6,0 m."],"answerSv":"Höjden är 6,0 m."},{"gradeLevel":"A","titleSv":"Val av nollnivå ovanför en källare","givenSv":"Ett föremål (4,0 kg) flyttas från 1,2 m under marknivån till 2,3 m ovanför marknivån.","findSv":"Förändringen i lägesenergi ΔEp","methodSv":"Beräkna Ep vid slutläget minus Ep vid startläget med marken som nollnivå.","stepsSv":["Vid start är h₁ = −1,2 m, vilket ger Ep₁ = 4,0 · 9,82 · (−1,2) = −47,136 J.","Vid slutet är h₂ = 2,3 m, vilket ger Ep₂ = 4,0 · 9,82 · 2,3 = 90,344 J.","Skillnaden blir ΔEp = Ep₂ − Ep₁ = 90,344 − (−47,136) = 137,48 J ≈ 137 J."],"answerSv":"Lägesenergin ökar med 137 J, oberoende av vilken nollnivå som väljs."}]', '[{"trapTitleSv":"Glömt tyngdfaktorn g = 9,82 N/kg","wrongApproachSv":"Att räkna Ep = m · h utan g = 9,82 N/kg.","rightApproachSv":"Multiplicera alltid massan i kg med g = 9,82 N/kg för att få tyngden i newton."},{"trapTitleSv":"Otydlig eller bytt nollnivå mitt i uppgiften","wrongApproachSv":"Att mäta h₁ från golvet och h₂ från bordsskivan i samma ekvation.","rightApproachSv":"Bestäm en fast nollnivå (h = 0 m) från början och mät alla höjder från den."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-1-rorelseenergi', 'chap-fysik-1b-1', 'rorelseenergi', 3, 'Rörelseenergi', '[{"term":"Rörelseenergi (Ek)","definition":"Kinetisk energi som ett föremål har på grund av sin massa och fart.","unit":"J (joule)"},{"term":"Fartomvandling","definition":"Omvandling mellan km/h och m/s via faktorn 3,6.","unit":"m/s"},{"term":"Kvadratiskt fartberoende","definition":"Eftersom farten v är kvadrerad ger faktor k i fart hela k² gånger större rörelseenergi."}]', '[{"heading":"Rörelseenergi och fartberoende","bodySv":"Ett föremål i rörelse med massan m och farten v har rörelseenergin Ek = (m · v²) / 2. Farten måste alltid anges i SI-enheten m/s innan den sätts in i formeln; står farten i km/h dividerar du med 3,6. Eftersom v är upphöjt till två växer rörelseenergin snabbt med farten — dubbel fart ger fyra gånger så stor rörelseenergi och därmed fyra gånger så lång bromssträcka vid samma bromskraft.","deepDiveSv":"Härledning: Vid konstant acceleration a från vila gäller F = m · a och v² = 2 · a · s, vilket ger s = v² / (2a). Arbetet blir då W = F · s = m · a · v² / (2a) = ½ · m · v². Omvandlingsfaktorn 3,6 kommer från att 1 km/h = 1 000 m / 3 600 s = 1 / 3,6 m/s."}]', '[{"nameSv":"Rörelseenergi (kinetisk energi)","latex":"E_k = \\frac{m \\cdot v^2}{2}","explanationSv":"Farten v måste vara i m/s. Vid förändring av farten med faktorn k ändras Ek med faktorn k².","variables":[{"symbol":"E_k","meaningSv":"Rörelseenergi","unit":"J"},{"symbol":"m","meaningSv":"Massa","unit":"kg"},{"symbol":"v","meaningSv":"Fart","unit":"m/s"}]},{"nameSv":"Fartomvandling","latex":"v_{\\text{m/s}} = \\frac{v_{\\text{km/h}}}{3{,}6}","explanationSv":"Dividera km/h med 3,6 för att få m/s, och multiplicera m/s med 3,6 för att få km/h.","variables":[{"symbol":"v_{\\text{m/s}}","meaningSv":"Fart i SI-enhet","unit":"m/s"},{"symbol":"v_{\\text{km/h}}","meaningSv":"Fart i kilometer per timme","unit":"km/h"}]}]', '[{"gradeLevel":"E","titleSv":"Personbil i stadstrafik","givenSv":"m = 1 400 kg, v = 72 km/h","findSv":"Bilens rörelseenergi Ek","methodSv":"Omvandla först farten till m/s och beräkna sedan Ek = (m · v²) / 2.","stepsSv":["Omvandla farten: v = 72 / 3,6 = 20 m/s.","Beräkna rörelseenergin: Ek = (1 400 · 20²) / 2 = (1 400 · 400) / 2 = 280 000 J.","Skriv med prefix: Ek = 280 kJ."],"answerSv":"Bilens rörelseenergi är 280 kJ (280 000 J)."},{"gradeLevel":"C","titleSv":"Bestäm farten ur given rörelseenergi","givenSv":"m = 80 kg, Ek = 14,4 kJ","findSv":"Farten v i m/s och km/h","methodSv":"Omvandla kJ till J och lös ut v = √(2 · Ek / m).","stepsSv":["Omvandla energi: Ek = 14,4 kJ = 14 400 J.","Lös ut v²: v² = (2 · 14 400) / 80 = 360.","Ta kvadratroten: v = √360 ≈ 18,97 m/s ≈ 19 m/s.","Omvandla till km/h: 18,97 · 3,6 ≈ 68 km/h."],"answerSv":"Farten är 19 m/s (cirka 68 km/h)."},{"gradeLevel":"A","titleSv":"Jämförelse av bromssträcka vid fartökning","givenSv":"En cyklist ökar farten från 18 km/h till 54 km/h.","findSv":"Med vilken faktor ökar rörelseenergin och den minimala bromssträckan?","methodSv":"Jämför fartkvoten k = v₂ / v₁ och utnyttja att W_broms = F_broms · s = Ek.","stepsSv":["Beräkna fartfaktorn: k = 54 / 18 = 3,0 (farten tredubblas).","Eftersom Ek är proportionell mot v² blir Ek,2 / Ek,1 = k² = 3,0² = 9,0.","Vid samma bromskraft F är bromssträckan s = Ek / F också 9 gånger längre."],"answerSv":"Rörelseenergin och bromssträckan blir 9 gånger så stora."}]', '[{"trapTitleSv":"Fart i km/h insatt direkt eller multiplicerad med 3,6","wrongApproachSv":"Att sätta v = 72 direkt i Ek eller räkna 72 · 3,6 = 259,2 m/s.","rightApproachSv":"Dela alltid km/h med 3,6: 72 / 3,6 = 20 m/s. Farten i m/s ska alltid ha lägre siffervärde än i km/h."},{"trapTitleSv":"Glömt kvadraten på farten v²","wrongApproachSv":"Att anta att dubbel fart ger dubbel rörelseenergi.","rightApproachSv":"Eftersom farten står i kvadrat ger dubbel fart 2² = 4 gånger så stor rörelseenergi."}]', 'unit_converter', '{"defaultKmh":72,"defaultKj":8.5,"modes":["speed","energy","formula"]}', 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-1-mekanisk-energi', 'chap-fysik-1b-1', 'mekanisk-energi', 4, 'Mekanisk energi', '[{"term":"Mekanisk energi (Emek)","definition":"Summan av ett föremåls lägesenergi och rörelseenergi i samma ögonblick.","unit":"J (joule)"}]', '[{"heading":"Summan av läges- och rörelseenergi","bodySv":"Ett föremål som både befinner sig på en höjd över nollnivån och rör sig samtidigt har både lägesenergi och rörelseenergi. Den totala mekaniska energin i det läget är summan Emek = Ep + Ek. För att jämföra mekanisk energi mellan två tidpunkter måste båda termerna beräknas med samma nollnivå och i rena SI-enheter.","deepDiveSv":"Fullständigt skrivs den mekaniska energin som Emek = m · g · h + ½ · m · v². I många förlopp växlar energin kontinuerligt mellan Ep och Ek medan summan Emek hålls konstant (utan friktion) eller avtar (med friktion)."}]', '[{"nameSv":"Total mekanisk energi","latex":"E_{\\text{mek}} = E_p + E_k = m \\cdot g \\cdot h + \\frac{m \\cdot v^2}{2}","explanationSv":"Summerar kroppens höjdenergi och rörelseenergi vid samma tidpunkt och samma nollnivå.","variables":[{"symbol":"E_{\\text{mek}}","meaningSv":"Mekanisk energi","unit":"J"},{"symbol":"E_p","meaningSv":"Lägesenergi","unit":"J"},{"symbol":"E_k","meaningSv":"Rörelseenergi","unit":"J"}]}]', '[{"gradeLevel":"E","titleSv":"Drönare i rörelse på hög höjd","givenSv":"m = 1,5 kg, h = 18 m, v = 6,0 m/s","findSv":"Drönarens mekaniska energi Emek","methodSv":"Beräkna Ep och Ek var för sig och addera dem.","stepsSv":["Lägesenergi: Ep = 1,5 · 9,82 · 18 = 265,14 J.","Rörelseenergi: Ek = (1,5 · 6,0²) / 2 = 27,0 J.","Summa: Emek = 265,14 + 27,0 = 292,14 J ≈ 292 J."],"answerSv":"Den mekaniska energin är 292 J."},{"gradeLevel":"C","titleSv":"Räkna baklänges från känd mekanisk energi","givenSv":"En fågel (0,40 kg) har Emek = 67,4 J på höjden 12 m.","findSv":"Fågelns fart v","methodSv":"Beräkna Ep, subtrahera från Emek för att få Ek, och lös ut v.","stepsSv":["Ep = 0,40 · 9,82 · 12 = 47,136 J.","Ek = Emek − Ep = 67,4 − 47,136 = 20,264 J.","v = √((2 · 20,264) / 0,40) = √101,32 ≈ 10,1 m/s."],"answerSv":"Fågelns fart är cirka 10 m/s."},{"gradeLevel":"A","titleSv":"Andel lägesenergi i ett kast","givenSv":"En boll har farten v₀ vid golvet (h = 0). Vid höjden h₁ är farten hälften så stor (v₁ = 0,5 · v₀).","findSv":"Hur stor andel av den mekaniska energin består av lägesenergi vid höjden h₁ (utan luftmotstånd)?","methodSv":"Utnyttja att Ek är proportionell mot v² och att Emek = Ek,0.","stepsSv":["Vid golvet är hela energin Ek,0 = ½ · m · v₀².","Vid höjden h₁ är farten 0,5 · v₀, så Ek,1 = ½ · m · (0,5 · v₀)² = 0,25 · Ek,0.","Eftersom Emek bevaras måste resten vara lägesenergi: Ep,1 = Emek − 0,25 · Emek = 0,75 · Emek."],"answerSv":"75 % av den mekaniska energin utgörs av lägesenergi."}]', '[{"trapTitleSv":"Blanda ihop Ep och Ek vid avläsning","wrongApproachSv":"Att bara ange Ep eller bara Ek när uppgiften frågar efter den mekaniska energin.","rightApproachSv":"Mekanisk energi är alltid summan Emek = Ep + Ek."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-1-utan-friktion', 'chap-fysik-1b-1', 'utan-friktion', 5, 'Utan friktion', '[{"term":"Bevarande av mekanisk energi","definition":"När ingen friktion eller luftmotstånd verkar är summan Ep + Ek konstant genom hela rörelsen.","unit":"J"},{"term":"Massans förkortning","definition":"Eftersom både m·g·h och ½m·v² innehåller massan m kan m förkortas bort om ingen friktionskraft är given."}]', '[{"heading":"Energiomvandling utan energiförluster","bodySv":"När ett föremål glider, faller eller pendlar utan friktion eller luftmotstånd är den mekaniska energin lika stor före som efter: Ep1 + Ek1 = Ep2 + Ek2. Lägesenergi kan omvandlas fullständigt till rörelseenergi på väg neråt, och rörelseenergi kan omvandlas tillbaka till lägesenergi på väg uppåt. Om föremålet startar från vila på höjden h₁ och når nollnivån h₂ = 0 m ger energibalansen direkt farten v₂ = √(2 · g · h₁).","deepDiveSv":"Ställ upp m · g · h₁ + 0 = 0 + ½ · m · v₂². Dividera båda led med massan m så försvinner m: g · h₁ = ½ · v₂², vilket ger v₂ = √(2 · g · h₁) och h₁ = v₂² / (2 · g). Farten i botten beror alltså inte på vagnens massa eller banans form, utan enbart på höjdskillnaden.","svgDiagram":"<svg viewBox=\"0 0 380 140\" width=\"100%\" aria-label=\"Friktionsfri bana med höjden h1 och farten v2 i dalen\">\n  <line x1=\"24\" y1=\"118\" x2=\"356\" y2=\"118\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <path d=\"M 40 28 C 145 28, 175 118, 336 118\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <rect x=\"36\" y=\"18\" width=\"14\" height=\"10\" fill=\"var(--accent)\" />\n  <line x1=\"43\" y1=\"28\" x2=\"43\" y2=\"118\" stroke=\"var(--accent)\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\" />\n  <text x=\"50\" y=\"76\" font-size=\"11\" fill=\"var(--accent)\">h1</text>\n  <rect x=\"304\" y=\"108\" width=\"14\" height=\"10\" fill=\"currentColor\" />\n  <line x1=\"322\" y1=\"113\" x2=\"348\" y2=\"113\" stroke=\"var(--accent)\" stroke-width=\"1.5\" />\n  <text x=\"322\" y=\"102\" font-size=\"11\" fill=\"var(--accent)\">v2</text>\n  <text x=\"26\" y=\"133\" font-size=\"11\" fill=\"currentColor\">Nollnivå h = 0 m</text>\n</svg>"}]', '[{"nameSv":"Mekanisk energibalans utan friktion","latex":"E_{p1} + E_{k1} = E_{p2} + E_{k2}","explanationSv":"Total mekanisk energi i läge 1 är lika med total mekanisk energi i läge 2 när inga förluster förekommer.","variables":[{"symbol":"E_{p1}, E_{k1}","meaningSv":"Läges- och rörelseenergi före","unit":"J"},{"symbol":"E_{p2}, E_{k2}","meaningSv":"Läges- och rörelseenergi efter","unit":"J"}]},{"nameSv":"Fart i dalen från vila","latex":"v_2 = \\sqrt{2 \\cdot g \\cdot h_1}","explanationSv":"Specialfall då föremålet startar från vila (v₁ = 0) vid höjden h₁ och når nollnivån (h₂ = 0). Massan förkortas bort.","variables":[{"symbol":"v_2","meaningSv":"Fart vid nollnivån","unit":"m/s"},{"symbol":"g","meaningSv":"Tyngdfaktor (9,82)","unit":"N/kg"},{"symbol":"h_1","meaningSv":"Starthöjd","unit":"m"}]}]', '[{"gradeLevel":"E","titleSv":"Berg- och dalbana från vila","givenSv":"h₁ = 24 m, v₁ = 0 m/s, h₂ = 0 m (utan friktion)","findSv":"Vagnens fart v₂ i dalen","methodSv":"Massan saknas och förkortas bort. Använd v₂ = √(2 · g · h₁).","stepsSv":["Ställ upp energibevarelsen: m · g · h₁ = ½ · m · v₂².","Förkorta bort m: v₂ = √(2 · 9,82 · 24) = √471,36.","Beräkna roten: v₂ ≈ 21,7 m/s (cirka 78 km/h)."],"answerSv":"Vagnens fart i dalen är 21,7 m/s."},{"gradeLevel":"C","titleSv":"Pendelkula som passerar ny höjd","givenSv":"En skateboardåkare åker upp i en ramp med farten v₁ = 6,0 m/s i botten (h₁ = 0 m).","findSv":"Högsta höjden h₂ utan friktion","methodSv":"Vid vändpunkten längst upp är v₂ = 0 m/s så all Ek har blivit Ep.","stepsSv":["Ställ upp ½ · m · v₁² = m · g · h₂ och förkorta bort m.","Lös ut h₂: h₂ = v₁² / (2 · g).","Sätt in talen: h₂ = 6,0² / (2 · 9,82) = 36 / 19,64 ≈ 1,83 m."],"answerSv":"Åkaren når höjden 1,8 m."},{"gradeLevel":"A","titleSv":"Kulle mellan två dalnivåer med startfart","givenSv":"En vagn passerar en starttopp på h₁ = 18 m med farten v₁ = 4,0 m/s och rullar sedan upp på nästa kulle på h₂ = 8,0 m utan friktion.","findSv":"Farten v₂ på den andra kullen","methodSv":"Använd hela balansen m·g·h₁ + ½m·v₁² = m·g·h₂ + ½m·v₂² och förkorta m.","stepsSv":["Förkorta bort m i samtliga fyra termer: g · h₁ + ½ · v₁² = g · h₂ + ½ · v₂².","Lös ut ½ · v₂² = g · (h₁ − h₂) + ½ · v₁².","Sätt in värdena: ½ · v₂² = 9,82 · (18 − 8,0) + ½ · 4,0² = 98,2 + 8,0 = 106,2.","Multiplicera med 2 och ta roten: v₂ = √(212,4) ≈ 14,6 m/s."],"answerSv":"Farten på kullen är 14,6 m/s."}]', '[{"trapTitleSv":"Tro att uppgiften saknar massa m och är olösbar","wrongApproachSv":"Att ge upp eller gissa m = 1 kg utan att motivera varför massan inte påverkar svaret.","rightApproachSv":"Skriv ut ekvationen med m på båda sidor och förkorta bort m algebraiskt."}]', 'energy_sim', '{"defaultHeight":24,"defaultMass":50,"defaultFriction":false,"presets":[{"label":"Berg- och dalbana (24 m)","heightM":24,"massKg":80,"frictionPct":0},{"label":"Pulka med friktion (45 kg, 8 m)","heightM":8,"massKg":45,"frictionPct":42.6}]}', 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-1-med-friktion', 'chap-fysik-1b-1', 'med-friktion', 6, 'Med friktion', '[{"term":"Friktionsarbete (Wf)","definition":"Den mekaniska energi som omvandlas till termisk energi (värme) under en rörelse med friktion eller luftmotstånd.","unit":"J (joule)"},{"term":"Friktionskraft (Ff)","definition":"Bromsande kraft som verkar mot rörelsens riktning längs glidsträckan s.","unit":"N (newton)"}]', '[{"heading":"Friktionsarbete och energiförlust till värme","bodySv":"I verkligheten finns nästan alltid friktion och luftmotstånd. Då är den mekaniska energin efteråt mindre än den mekaniska energin före. Skillnaden har inte förstörts utan omvandlats till värme (termisk energi) i kontaktytorna och omgivande luft. Värmeförlusten kallas friktionsarbete Wf och följer sambandet Emek,före = Emek,efter + Wf.","deepDiveSv":"Om friktionskraften Ff verkar längs glidsträckan s beräknas värmeförlusten även som Wf = Ff · s. Medelfriktionskraften längs en given sträcka kan därför bestämmas som Ff = (Emek,före − Emek,efter) / s.","svgDiagram":"<svg viewBox=\"0 0 380 120\" width=\"100%\" aria-label=\"Glidande föremål med bromsande friktionskraft Ff\">\n  <line x1=\"24\" y1=\"92\" x2=\"356\" y2=\"92\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <rect x=\"148\" y=\"64\" width=\"44\" height=\"28\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"196\" y1=\"78\" x2=\"256\" y2=\"78\" stroke=\"var(--accent)\" stroke-width=\"1.5\" />\n  <text x=\"206\" y=\"71\" font-size=\"11\" fill=\"var(--accent)\">Rörelse (v)</text>\n  <line x1=\"144\" y1=\"86\" x2=\"88\" y2=\"86\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <text x=\"92\" y=\"79\" font-size=\"11\" fill=\"currentColor\">Ff</text>\n  <line x1=\"90\" y1=\"104\" x2=\"290\" y2=\"104\" stroke=\"var(--accent)\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\" />\n  <text x=\"166\" y=\"117\" font-size=\"11\" fill=\"var(--accent)\">Sträcka s</text>\n</svg>"}]', '[{"nameSv":"Energibalans med friktion","latex":"E_{\\text{mek, före}} = E_{\\text{mek, efter}} + W_f","explanationSv":"Skillnaden mellan mekanisk energi före och efter förloppet motsvarar exakt den värmeenergi Wf som bildats.","variables":[{"symbol":"E_{\\text{mek, före}}","meaningSv":"Mekanisk energi i startläget","unit":"J"},{"symbol":"E_{\\text{mek, efter}}","meaningSv":"Mekanisk energi i slutläget","unit":"J"},{"symbol":"W_f","meaningSv":"Friktionsarbete (värmeförlust)","unit":"J"}]},{"nameSv":"Friktionsarbete via kraft och sträcka","latex":"W_f = F_f \\cdot s","explanationSv":"Ger sambandet mellan friktionskraft Ff, glidsträcka s och utvecklad värme Wf.","variables":[{"symbol":"W_f","meaningSv":"Friktionsarbete","unit":"J"},{"symbol":"F_f","meaningSv":"Medelfriktionskraft","unit":"N"},{"symbol":"s","meaningSv":"Glidsträcka","unit":"m"}]}]', '[{"gradeLevel":"E","titleSv":"Värmeutveckling hos en bromsad kälke","givenSv":"Ff = 80 N, s = 25 m","findSv":"Friktionsarbetet Wf","methodSv":"Beräkna produkten av friktionskraften och sträckan: Wf = Ff · s.","stepsSv":["Ställ upp Wf = Ff · s.","Beräkna: Wf = 80 · 25 = 2 000 J = 2,0 kJ."],"answerSv":"Friktionsarbetet är 2 000 J (2,0 kJ)."},{"gradeLevel":"C","titleSv":"Pulka i backe med energiförlust","givenSv":"m = 45 kg, starthöjd h₁ = 8,0 m (v₁ = 0), slutfart v₂ = 9,5 m/s vid h₂ = 0 m","findSv":"Hur stor energi Wf som blev värme","methodSv":"Beräkna Ep1 och Ek2 och ta skillnaden Wf = Ep1 − Ek2.","stepsSv":["Startenergi: Ep1 = 45 · 9,82 · 8,0 = 3 535,2 J.","Slutenergi: Ek2 = (45 · 9,5²) / 2 = 2 030,6 J.","Värmeförlust: Wf = 3 535,2 − 2 030,6 = 1 504,6 J ≈ 1,5 kJ."],"answerSv":"1 505 J (cirka 1,5 kJ) har omvandlats till värme."},{"gradeLevel":"A","titleSv":"Medelfriktionskraft längs en skidbacke","givenSv":"En skidåkare (70 kg) åker från vila på höjden 12 m längs en 50 m lång backe och når farten 11 m/s i dalen.","findSv":"Medelfriktionskraften Ff längs backen","methodSv":"Beräkna Wf = Ep1 − Ek2 och dividera sedan med backens längd s = 50 m.","stepsSv":["Ep1 = 70 · 9,82 · 12 = 8 248,8 J.","Ek2 = (70 · 11²) / 2 = 4 235,0 J.","Wf = 8 248,8 − 4 235,0 = 4 013,8 J.","Ff = Wf / s = 4 013,8 / 50 ≈ 80,3 N ≈ 80 N."],"answerSv":"Medelfriktionskraften är 80 N."}]', '[{"trapTitleSv":"Glömt omvandla till värme eller subtraherat i fel ordning","wrongApproachSv":"Att ta Ek2 − Ep1 och få ett negativt värde på friktionsvärmen utan att reflektera.","rightApproachSv":"När friktion bromsar är energin före alltid större än energin efter: Wf = Emek,före − Emek,efter > 0."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-1-verkningsgrad', 'chap-fysik-1b-1', 'verkningsgrad', 7, 'Verkningsgrad', '[{"term":"Verkningsgrad (η)","definition":"Andelen av den tillförda energin som omvandlas till önskad nyttig energi.","unit":"Saknar enhet (0 till 1 eller 0–100 %)"},{"term":"Energiförlust","definition":"Skillnaden E_tillförd − E_nyttig som inte utnyttjas till avsett ändamål.","unit":"J (joule)"}]', '[{"heading":"Andel nyttig energi","bodySv":"Ingen apparat eller motor kan omvandla all tillförd energi till nyttigt arbete; en del går alltid förlorad som värme. Verkningsgraden η (grekiska bokstaven eta) definieras som kvoten mellan nyttig energi och tillförd energi. Eftersom joule dividerat med joule tar ut varandra saknar verkningsgraden enhet och ligger alltid mellan 0 och 1 (motsvarande 0 % till 100 %).","deepDiveSv":"Eftersom energi = effekt · tid och tiden t är densamma för tillförsel och nyttig uttagning gäller även effektkvoten η = P_nyttig / P_tillförd. Ett värde över 100 % skulle strida mot energiprincipen."}]', '[{"nameSv":"Verkningsgrad via energi","latex":"\\eta = \\frac{E_{\\text{nyttig}}}{E_{\\text{tillförd}}}","explanationSv":"Nyttig energi divideras med totalt tillförd energi i samma enhet. Multiplicera med 100 för procent.","variables":[{"symbol":"\\eta","meaningSv":"Verkningsgrad","unit":"Enhetslös (0–1)"},{"symbol":"E_{\\text{nyttig}}","meaningSv":"Nyttig energi","unit":"J"},{"symbol":"E_{\\text{tillförd}}","meaningSv":"Totalt tillförd energi","unit":"J"}]},{"nameSv":"Verkningsgrad via effekt","latex":"\\eta = \\frac{P_{\\text{nyttig}}}{P_{\\text{tillförd}}}","explanationSv":"Likvärdigt samband när medeleffekten under samma tidsintervall är känd.","variables":[{"symbol":"P_{\\text{nyttig}}","meaningSv":"Nyttig uteffekt","unit":"W"},{"symbol":"P_{\\text{tillförd}}","meaningSv":"Tillförd ineffekt","unit":"W"}]}]', '[{"gradeLevel":"E","titleSv":"Vinsch som lyfter tung last","givenSv":"m = 120 kg lyfts h = 5,0 m, E_tillförd = 8 500 J","findSv":"Vinschens verkningsgrad η","methodSv":"Den nyttiga energin är lyftets lägesenergi Ep = m · g · h.","stepsSv":["Beräkna nyttig energi: E_nyttig = 120 · 9,82 · 5,0 = 5 892 J.","Dividera med tillförd energi: η = 5 892 / 8 500 ≈ 0,693.","Uttryck i procent: η ≈ 69 %."],"answerSv":"Verkningsgraden är 0,69 eller 69 %."},{"gradeLevel":"C","titleSv":"Nödvändig elektrisk energi för vattenkokare","givenSv":"För att värma vatten krävs E_nyttig = 252 kJ. Vattenkokarens verkningsgrad är 84 %.","findSv":"Tillförd elektrisk energi E_tillförd","methodSv":"Lös ut E_tillförd = E_nyttig / η med η = 0,84.","stepsSv":["Skriv η i decimalform: 84 % = 0,84.","Beräkna E_tillförd = 252 / 0,84 = 300 kJ."],"answerSv":"Det krävs 300 kJ elektrisk energi."},{"gradeLevel":"A","titleSv":"Två seriekopplade energiomvandlingar","givenSv":"Ett vattenkraftverk har turbinverkningsgraden 90 % och generatorverkningsgraden 95 %. Tillförd effekt är 40 MW.","findSv":"Total verkningsgrad och levererad elektrisk effekt","methodSv":"Den sammanlagda verkningsgraden är produkten η_tot = η₁ · η₂.","stepsSv":["Beräkna total verkningsgrad: η_tot = 0,90 · 0,95 = 0,855 (85,5 %).","Beräkna levererad effekt: P_nyttig = 0,855 · 40 = 34,2 MW."],"answerSv":"Totala verkningsgraden är 85,5 % och uteffekten är 34,2 MW."}]', '[{"trapTitleSv":"Dela tillförd med nyttig energi","wrongApproachSv":"Att ta E_tillförd / E_nyttig och få ett svar över 100 %, exempelvis 143 %.","rightApproachSv":"Nyttig energi är alltid högst lika stor som tillförd energi, så η ≤ 100 % alltid."},{"trapTitleSv":"Glömt göra om kJ till J i bara ena ledet","wrongApproachSv":"Att räkna 3 500 J / 5,0 kJ = 700.","rightApproachSv":"Skriv båda storheterna i samma enhet först: 3 500 J / 5 000 J = 0,70 = 70 %."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-2-krafter-och-jamvikt', 'chap-fysik-1b-2', 'krafter-och-jamvikt', 1, 'Krafter, tyngd och jämnvikt', '[{"term":"Resultantkraft (F_res)","definition":"Vektorsumman av alla krafter som verkar på ett föremål.","unit":"N"},{"term":"Normalkraft (F_N)","definition":"Stödkraft från ett underlag riktad vinkelrätt ut från ytan.","unit":"N"},{"term":"Friktionstal (μ)","definition":"Enhetslös faktor som beskriver ytornas strävhet i Ff = μ · FN."}]', '[{"heading":"Krafter och kraftjämvikt","bodySv":"En kraft beskriver växelverkan mellan två föremål och har både storlek och riktning. När alla krafter på ett föremål tar ut varandra är resultantkraften F_res = 0 N. Enligt Newtons första lag innebär det att föremålet fortsätter att vara i vila eller röra sig rätlinjigt med konstant fart.","deepDiveSv":"På ett lutande plan med vinkeln α delas tyngden Fg = m · g upp i komposanterna Fg,parallell = m · g · sin α längs planet och Fg,vinkelrät = m · g · cos α vinkelrätt mot planet.","svgDiagram":"<svg viewBox=\"0 0 320 140\" width=\"100%\" aria-label=\"Krafter på en låda som dras över ett plant underlag\">\n  <line x1=\"24\" y1=\"90\" x2=\"296\" y2=\"90\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <rect x=\"132\" y=\"54\" width=\"56\" height=\"36\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"160\" y1=\"54\" x2=\"160\" y2=\"18\" stroke=\"var(--accent)\" stroke-width=\"1.5\" />\n  <text x=\"168\" y=\"28\" font-size=\"11\" fill=\"var(--accent)\">FN</text>\n  <line x1=\"160\" y1=\"90\" x2=\"160\" y2=\"128\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <text x=\"168\" y=\"124\" font-size=\"11\" fill=\"currentColor\">Fg = m · g</text>\n  <line x1=\"188\" y1=\"72\" x2=\"254\" y2=\"72\" stroke=\"var(--accent)\" stroke-width=\"1.5\" />\n  <text x=\"204\" y=\"65\" font-size=\"11\" fill=\"var(--accent)\">Fdrag</text>\n  <line x1=\"132\" y1=\"72\" x2=\"78\" y2=\"72\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <text x=\"86\" y=\"65\" font-size=\"11\" fill=\"currentColor\">Ff</text>\n</svg>"}]', '[{"nameSv":"Tyngdkraft","latex":"F_g = m \\cdot g","explanationSv":"Jordens dragningskraft på ett föremål med massan m.","variables":[{"symbol":"F_g","meaningSv":"Tyngd","unit":"N"},{"symbol":"m","meaningSv":"Massa","unit":"kg"},{"symbol":"g","meaningSv":"Tyngdfaktor (9,82)","unit":"N/kg"}]},{"nameSv":"Glidfriktion","latex":"F_f = \\mu \\cdot F_N","explanationSv":"Friktionskraften vid glidning är proportionell mot normalkraften FN.","variables":[{"symbol":"F_f","meaningSv":"Friktionskraft","unit":"N"},{"symbol":"\\mu","meaningSv":"Friktionstal","unit":"Enhetslös"},{"symbol":"F_N","meaningSv":"Normalkraft","unit":"N"}]}]', '[{"gradeLevel":"E","titleSv":"Friktion på plant golv","givenSv":"m = 20 kg, μ = 0,25 på horisontellt golv","findSv":"Glidfriktionskraften Ff","methodSv":"På horisontellt golv balanserar FN tyngden Fg = m · g.","stepsSv":["Beräkna FN = 20 · 9,82 = 196,4 N.","Beräkna Ff = 0,25 · 196,4 = 49,1 N ≈ 49 N."],"answerSv":"Friktionskraften är 49 N."},{"gradeLevel":"C","titleSv":"Konstant fart med motverkande dragkraft","givenSv":"En låda (15 kg) dras med konstant fart över ett golv med F_drag = 36 N.","findSv":"Friktionstalet μ","methodSv":"Vid konstant fart är F_res = 0 N, så Ff = F_drag = 36 N.","stepsSv":["Beräkna normalkraften: FN = 15 · 9,82 = 147,3 N.","Sätt Ff = 36 N och lös ut μ = 36 / 147,3 ≈ 0,24."],"answerSv":"Friktionstalet är 0,24."},{"gradeLevel":"A","titleSv":"Kraftjämvikt i lutande plan","givenSv":"En låda vilar på ett plan som lutar 20° och är nära att börja glida.","findSv":"Det minsta friktionstalet μ","methodSv":"Sätt glidkomposanten Fg · sin α lika med maximal friktion μ · Fg · cos α.","stepsSv":["m · g · sin 20° = μ · m · g · cos 20°.","Förkorta m · g: μ = sin 20° / cos 20° = tan 20° ≈ 0,36."],"answerSv":"Det minsta friktionstalet är 0,36."}]', '[{"trapTitleSv":"Anta att det måste verka en nettokraft vid rörelse","wrongApproachSv":"Att tro att konstant fart kräver F_res > 0 N.","rightApproachSv":"Konstant fart rakt fram innebär alltid F_res = 0 N; drivkraften balanserar motståndet."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-2-newtons-lagar', 'chap-fysik-1b-2', 'newtons-lagar', 2, 'Newtons andra lag och rörelsemängd', '[{"term":"Acceleration (a)","definition":"Hastighetsändring per tidsenhet.","unit":"m/s²"},{"term":"Rörelsemängd (p)","definition":"Produkten av massa och hastighet.","unit":"kg·m/s (eller N·s)"},{"term":"Impuls (I)","definition":"Kraft gånger verkningstid; lika med förändringen i rörelsemängd.","unit":"N·s"}]', '[{"heading":"Kraft, acceleration och impuls","bodySv":"Newtons andra lag slår fast att ett föremåls acceleration är direkt proportionell mot resultantkraften och omvänt proportionell mot massan: F_res = m · a. Under en kollision eller spark förändras rörelsemängden Δp = m · v₂ − m · v₁ av impulsen F · Δt.","deepDiveSv":"Om kraft och verkningstid kopplas ihop fås F = Δp / Δt. Krockkuddar och deformationszoner ökar stöttiden Δt vid samma Δp, vilket minskar den maximala kraften F på passagerarna."}]', '[{"nameSv":"Newtons andra lag","latex":"F_{\\text{res}} = m \\cdot a","explanationSv":"Resultantkraften ger massan m accelerationen a.","variables":[{"symbol":"F_{\\text{res}}","meaningSv":"Resultantkraft","unit":"N"},{"symbol":"m","meaningSv":"Massa","unit":"kg"},{"symbol":"a","meaningSv":"Acceleration","unit":"m/s²"}]},{"nameSv":"Impulslagen","latex":"F \\cdot \\Delta t = m \\cdot v_2 - m \\cdot v_1","explanationSv":"Impulsen motsvarar förändringen i rörelsemängd.","variables":[{"symbol":"F","meaningSv":"Medelkraft","unit":"N"},{"symbol":"\\Delta t","meaningSv":"Kontakttid","unit":"s"},{"symbol":"v_1, v_2","meaningSv":"Hastighet före och efter","unit":"m/s"}]}]', '[{"gradeLevel":"E","titleSv":"Acceleration hos en elbil","givenSv":"m = 1 600 kg, F_res = 4 800 N","findSv":"Bilens acceleration a","methodSv":"Använd a = F_res / m.","stepsSv":["a = 4 800 / 1 600 = 3,0 m/s²."],"answerSv":"Accelerationen är 3,0 m/s²."},{"gradeLevel":"C","titleSv":"Kraft och acceleration med friktion","givenSv":"En låda (12 kg) dras med 54 N och bromsas av 18 N friktion.","findSv":"Lådans acceleration a","methodSv":"Bestäm först resultantkraften F_res = F_drag − Ff.","stepsSv":["F_res = 54 − 18 = 36 N.","a = 36 / 12 = 3,0 m/s²."],"answerSv":"Accelerationen är 3,0 m/s²."},{"gradeLevel":"A","titleSv":"Studsande boll mot vägg","givenSv":"En boll (0,20 kg) träffar en vägg vinkelrätt med 12 m/s och studsar rakt tillbaka med 10 m/s under 0,040 s.","findSv":"Medelkraften från väggen","methodSv":"Välj riktningen ut från väggen som positiv: v₁ = −12 m/s och v₂ = +10 m/s.","stepsSv":["Δp = 0,20 · (10 − (−12)) = 0,20 · 22 = 4,4 N·s.","F = Δp / Δt = 4,4 / 0,040 = 110 N."],"answerSv":"Medelkraften är 110 N."}]', '[{"trapTitleSv":"Glömt teckenbyte vid studs i impulsuppgifter","wrongApproachSv":"Att ta 10 − 12 = −2 vid beräkning av Δv när riktningen vänder.","rightApproachSv":"Hastighet är en vektor: byt tecken på den inkommande hastigheten så att ändringen blir 10 − (−12) = 22 m/s."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-2-likformigt-accelererad-rorelse', 'chap-fysik-1b-2', 'likformigt-accelererad-rorelse', 3, 'Likformigt accelererad rörelse', '[{"term":"Medelhastighet (v_m)","definition":"Sträcka delat med tid.","unit":"m/s"},{"term":"Fritt fall","definition":"Rörelse där endast tyngdkraften verkar, med accelerationen a = g = 9,82 m/s².","unit":"m/s²"}]', '[{"heading":"Rörelseekvationerna och v-t-diagram","bodySv":"Vid konstant acceleration ökar hastigheten linjärt med tiden: v = v₀ + a · t. I ett v-t-diagram motsvaras accelerationen av linjens lutning och tillryggalagd sträcka av arean under grafen: s = v₀ · t + ½ · a · t².","deepDiveSv":"Genom att eliminera tiden t mellan v = v₀ + a·t och s = ½(v₀ + v)·t fås det tidlösa sambandet v² − v₀² = 2 · a · s."}]', '[{"nameSv":"Sträcka vid konstant acceleration","latex":"s = v_0 \\cdot t + \\frac{a \\cdot t^2}{2}","explanationSv":"Ger förflyttningen efter tiden t från starthastigheten v₀.","variables":[{"symbol":"s","meaningSv":"Sträcka","unit":"m"},{"symbol":"v_0","meaningSv":"Starthastighet","unit":"m/s"},{"symbol":"a","meaningSv":"Acceleration","unit":"m/s²"},{"symbol":"t","meaningSv":"Tid","unit":"s"}]}]', '[{"gradeLevel":"E","titleSv":"Accelerationssträcka från stillastående","givenSv":"v₀ = 0 m/s, a = 2,5 m/s², t = 4,0 s","findSv":"Tillryggalagd sträcka s","methodSv":"Sätt v₀ = 0 i s = v₀·t + ½a·t².","stepsSv":["s = (2,5 · 4,0²) / 2 = (2,5 · 16) / 2 = 20 m."],"answerSv":"Sträckan är 20 m."},{"gradeLevel":"C","titleSv":"Inbromsning utan tid given","givenSv":"v₀ = 20 m/s, v = 0 m/s, s = 50 m","findSv":"Retardationen a","methodSv":"Använd v² − v₀² = 2 · a · s.","stepsSv":["0 − 20² = 2 · a · 50.","−400 = 100 · a ger a = −4,0 m/s²."],"answerSv":"Retardationen är 4,0 m/s² (a = −4,0 m/s²)."},{"gradeLevel":"A","titleSv":"Uppkastat föremål i tyngdfältet","givenSv":"En boll kastas rakt upp med v₀ = 15 m/s utan luftmotstånd.","findSv":"Tiden tills bollen når sin högsta punkt och stighöjden","methodSv":"Välj uppåt som positiv riktning: a = −9,82 m/s² och v = 0 i vändpunkten.","stepsSv":["0 = 15 − 9,82 · t ger t = 15 / 9,82 ≈ 1,53 s.","s = 15 · 1,53 − 0,5 · 9,82 · 1,53² ≈ 11,5 m."],"answerSv":"Det tar 1,5 s att nå högsta punkten på 11,5 m höjd."}]', '[{"trapTitleSv":"Glömt minustecken på a vid retardation eller uppkast","wrongApproachSv":"Att använda a = +9,82 m/s² fast rörelsen är riktad uppåt.","rightApproachSv":"Bestäm positiv riktning och ge motriktade hastigheter och accelerationer minustecken."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-3-tryck-och-arkimedes', 'chap-fysik-1b-3', 'tryck-och-arkimedes', 1, 'Tryck och Arkimedes princip', '[{"term":"Tryck (p)","definition":"Vinkelrät kraft per areaenhet.","unit":"Pa (1 Pa = 1 N/m²)"},{"term":"Vätsketryck","definition":"Trycket på djupet h i en vätska med densiteten ρ.","unit":"Pa"},{"term":"Lyftkraft (F_lyft)","definition":"Uppåtriktad kraft lika med tyngden av undanträngd vätska eller gas.","unit":"N"}]', '[{"heading":"Hydrostatiskt tryck och flytkraft","bodySv":"Tryck anger hur koncentrerad en kraft är mot en yta: p = F / A. I en vätska ökar trycket linjärt med djupet h enligt p = ρ · g · h. Eftersom trycket är större på undersidan än på ovansidan av ett nedsänkt föremål uppstår en lyftkraft. Enligt Arkimedes princip är lyftkraften alltid lika stor som tyngden av den undanträngda vätskevolymen.","deepDiveSv":"Totaltrycket på djupet h i öppet vatten är p_tot = p₀ + ρ · g · h, där lufttrycket vid ytan normalt är p₀ = 101,3 kPa."}]', '[{"nameSv":"Allmänt tryck","latex":"p = \\frac{F}{A}","explanationSv":"Kraft vinkelrätt mot arean A.","variables":[{"symbol":"p","meaningSv":"Tryck","unit":"Pa"},{"symbol":"F","meaningSv":"Normalkraft","unit":"N"},{"symbol":"A","meaningSv":"Area","unit":"m²"}]},{"nameSv":"Arkimedes princip","latex":"F_{\\text{lyft}} = \\rho \\cdot V \\cdot g","explanationSv":"Lyftkraften ges av vätskans densitet ρ och den undanträngda volymen V.","variables":[{"symbol":"F_{\\text{lyft}}","meaningSv":"Lyftkraft","unit":"N"},{"symbol":"\\rho","meaningSv":"Vätskans densitet","unit":"kg/m³"},{"symbol":"V","meaningSv":"Undanträngd volym","unit":"m³"}]}]', '[{"gradeLevel":"E","titleSv":"Vätsketryck i sötvatten","givenSv":"ρ = 1 000 kg/m³, h = 4,0 m, g = 9,82 N/kg","findSv":"Vätsketrycket på 4,0 m djup","methodSv":"Beräkna p = ρ · g · h.","stepsSv":["p = 1 000 · 9,82 · 4,0 = 39 280 Pa ≈ 39 kPa."],"answerSv":"Vätsketrycket är 39 kPa."},{"gradeLevel":"C","titleSv":"Skidåkarens tryck mot snön","givenSv":"m = 75 kg står på två skidor med total area 0,30 m²","findSv":"Trycket p mot snön","methodSv":"Beräkna tyngden Fg = m · g och dela med totala arean.","stepsSv":["F = 75 · 9,82 = 736,5 N.","p = 736,5 / 0,30 = 2 455 Pa ≈ 2,5 kPa."],"answerSv":"Trycket mot snön är 2,5 kPa."},{"gradeLevel":"A","titleSv":"Flytande isberg","givenSv":"Is har densiteten 917 kg/m³ och havsvatten 1 025 kg/m³.","findSv":"Hur stor andel av isbergets volym befinner sig under vattenytan?","methodSv":"Vid flytande jämvikt är lyftkraften lika stor som isbergets tyngd.","stepsSv":["ρ_vatten · V_under · g = ρ_is · V_tot · g.","V_under / V_tot = 917 / 1 025 ≈ 0,895 (89,5 %)."],"answerSv":"Cirka 89,5 % av isberget ligger under ytan."}]', '[{"trapTitleSv":"Fel enhet på area (cm² i stället för m²)","wrongApproachSv":"Att sätta in area i cm² direkt i p = F / A.","rightApproachSv":"1 m² = 10 000 cm². Dela alltid cm² med 10 000 för att få m²."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-3-varme-och-fasovergangar', 'chap-fysik-1b-3', 'varme-och-fasovergangar', 2, 'Värme, temperatur och fasövergångar', '[{"term":"Specifik värmekapacitet (c)","definition":"Energi som krävs för att värma 1 kg av ett ämne 1 K.","unit":"J/(kg·K)"},{"term":"Smältentalpi (l_s)","definition":"Energi per kilogram för att smälta ett ämne vid smältpunkten.","unit":"J/kg"}]', '[{"heading":"Temperaturhöjning och smältning","bodySv":"När ett ämne värms upp utan att byta aggregationstillstånd beräknas värmeenergin med Q = c · m · ΔT. Under själva smältningen eller kokningen hålls temperaturen konstant medan den tillförda energin Q = l · m går åt till att bryta bindningar mellan partiklarna.","deepDiveSv":"För vatten är c ≈ 4 180 J/(kg·K) och smältentalpin för is l_s ≈ 334 kJ/kg. Eftersom temperaturskillnaden ΔT är densamma i grader Celsius och Kelvin behöver man inte omvandla till Kelvin vid differenser."}]', '[{"nameSv":"Uppvärmningsenergi","latex":"Q = c \\cdot m \\cdot \\Delta T","explanationSv":"Energibehov vid temperaturändringen ΔT.","variables":[{"symbol":"Q","meaningSv":"Värmeenergi","unit":"J"},{"symbol":"c","meaningSv":"Specifik värmekapacitet","unit":"J/(kg·K)"},{"symbol":"m","meaningSv":"Massa","unit":"kg"},{"symbol":"\\Delta T","meaningSv":"Temperaturändring","unit":"K"}]}]', '[{"gradeLevel":"E","titleSv":"Värma vatten till te","givenSv":"m = 0,50 kg vatten värms från 20 °C till 100 °C, c = 4 180 J/(kg·K)","findSv":"Värmeenergin Q","methodSv":"Beräkna ΔT = 80 K och använd Q = c · m · ΔT.","stepsSv":["Q = 4 180 · 0,50 · 80 = 167 200 J ≈ 167 kJ."],"answerSv":"Det krävs 167 kJ."},{"gradeLevel":"C","titleSv":"Blandning av varmt och kallt vatten","givenSv":"0,20 kg vatten (80 °C) blandas med 0,40 kg vatten (20 °C).","findSv":"Sluttemperaturen t","methodSv":"Avgiven energi från varmt vatten är lika med upptagen energi i kallt vatten.","stepsSv":["c · 0,20 · (80 − t) = c · 0,40 · (t − 20).","Förkorta c: 16 − 0,20t = 0,40t − 8,0 ger 0,60t = 24 och t = 40 °C."],"answerSv":"Sluttemperaturen blir 40 °C."},{"gradeLevel":"A","titleSv":"Smälta is och värma smältvattnet","givenSv":"0,10 kg is vid 0 °C smälts och värms till 20 °C (l_s = 334 kJ/kg, c = 4 180 J/(kg·K)).","findSv":"Total energiåtgång Q_tot","methodSv":"Addera smältvärmen Q₁ = l_s · m och uppvärmningen Q₂ = c · m · ΔT.","stepsSv":["Q₁ = 334 000 · 0,10 = 33 400 J.","Q₂ = 4 180 · 0,10 · 20 = 8 360 J.","Q_tot = 33 400 + 8 360 = 41 760 J ≈ 41,8 kJ."],"answerSv":"Total energiåtgång är 41,8 kJ."}]', '[{"trapTitleSv":"Glömt fasövergången mellan 0 °C is och 0 °C vatten","wrongApproachSv":"Att bara använda Q = c · m · ΔT över smältpunkten.","rightApproachSv":"Dela upp förloppet i separata steg: temperaturändring före smältning, smältning (l_s · m) och temperaturändring efteråt."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-3-stralningsbalans-och-klimat', 'chap-fysik-1b-3', 'stralningsbalans-och-klimat', 3, 'Strålningsbalans och klimat', '[{"term":"Albedo","definition":"Andel av inkommande solstrålning som reflekteras direkt tillbaka till rymden.","unit":"Enhetslös (0–1)"},{"term":"Växthuseffekten","definition":"Atmosfärens gaser släpper igenom kortvågig solstrålning men absorberar utgående långvågig värmestrålning."}]', '[{"heading":"Jordens energibalans","bodySv":"Jorden tar emot energi via kortvågig strålning från solen och avger energi genom långvågig värmestrålning ut i rymden. När inkommande absorberad strålningseffekt P_in är lika med utgående effekt P_ut råder strålningsjämvikt och medeltemperaturen är stabil. Ökar mängden växthusgaser minskar den utstrålade effekten tillfälligt, vilket höjer jordens temperatur tills ny balans uppnås.","deepDiveSv":"Jordens genomsnittliga albedo är cirka 0,30, vilket betyder att 30 % reflekteras och 70 % absorberas. När havsis smälter minskar albedot så att ännu mer energi absorberas — en förstärkande återkoppling."}]', '[{"nameSv":"Absorberad solstrålningseffekt","latex":"P_{\\text{abs}} = (1 - a) \\cdot P_{\\text{in}}","explanationSv":"Andelen som inte reflekteras (albedo a) absorberas av planeten.","variables":[{"symbol":"P_{\\text{abs}}","meaningSv":"Absorberad effekt","unit":"W"},{"symbol":"a","meaningSv":"Albedo","unit":"0–1"},{"symbol":"P_{\\text{in}}","meaningSv":"Inkommande effekt","unit":"W"}]}]', '[{"gradeLevel":"E","titleSv":"Reflekterad effekt vid albedot 0,30","givenSv":"En yta träffas av 1 000 W solstrålning och har albedot 0,30.","findSv":"Absorberad effekt","methodSv":"Beräkna (1 − 0,30) · P_in.","stepsSv":["P_abs = (1 − 0,30) · 1 000 = 700 W."],"answerSv":"700 W absorberas."},{"gradeLevel":"C","titleSv":"Förändrat albedo när snö smälter","givenSv":"En yta på 10 m² tar emot 400 W/m². Albedot sjunker från 0,80 (snö) till 0,15 (mörk mark).","findSv":"Ökningen i absorberad effekt","methodSv":"Beräkna P_abs före och efter.","stepsSv":["P_in = 10 · 400 = 4 000 W.","Före: 0,20 · 4 000 = 800 W. Efter: 0,85 · 4 000 = 3 400 W.","Ökning: 3 400 − 800 = 2 600 W."],"answerSv":"Den absorberade effekten ökar med 2 600 W."},{"gradeLevel":"A","titleSv":"Positiv återkoppling i klimatsystemet","givenSv":"Global uppvärmning ökar vattenångan i atmosfären.","findSv":"Förklara fysikaliskt varför ökad vattenånga förstärker uppvärmningen.","methodSv":"Koppla samman mättnadsångtryck, växthusabsorption och strålningsbalans.","stepsSv":["Varmare luft kan hålla mer vattenånga genom ökad avdunstning.","Vattenånga är en kraftig växthusgas som absorberar långvågig infraröd strålning från jordytan.","Därmed sänds mer värmestrålning tillbaka mot ytan, vilket förstärker temperaturökningen."],"answerSv":"Ökad avdunstning ger mer vattenånga som fångar mer värmestrålning och höjer temperaturen ytterligare."}]', '[{"trapTitleSv":"Förväxla kortvågig solstrålning med långvågig värmestrålning","wrongApproachSv":"Att skriva att växthusgaser stoppar solens ljus på väg ner.","rightApproachSv":"Växthusgaserna släpper igenom kortvågig solstrålning men absorberar utgående långvågig värmestrålning."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-4-strom-spanning-och-resistans', 'chap-fysik-1b-4', 'strom-spanning-och-resistans', 1, 'Ström, spänning och Ohms lag', '[{"term":"Elektrisk ström (I)","definition":"Laddning som passerar ett tvärsnitt per sekund.","unit":"A (ampere)"},{"term":"Spänning (U)","definition":"Energi som överförs per enhetsladdning mellan två punkter.","unit":"V (volt)"},{"term":"Resistans (R)","definition":"Komponentens elektriska motstånd.","unit":"Ω (ohm)"}]', '[{"heading":"Sambandet i en sluten strömkrets","bodySv":"För att elektrisk ström ska flyta krävs en sluten krets och en spänningskälla som skapar en potentialskillnad U. Strömmen I definieras som laddningen per tid: I = Q / t. I metaller är spänningen över ett motstånd ofta proportionell mot strömmen enligt Ohms lag: U = R · I.","deepDiveSv":"Elementarladdningen är e = 1,602 · 10⁻¹⁹ C. En ström på 1 A motsvarar alltså drygt 6,24 · 10¹⁸ elektroner per sekund genom ledarens tvärsnitt.","svgDiagram":"<svg viewBox=\"0 0 340 130\" width=\"100%\" aria-label=\"Enkel sluten strömkrets med spänningskälla och resistor\">\n  <rect x=\"60\" y=\"24\" width=\"220\" height=\"82\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"50\" y1=\"58\" x2=\"70\" y2=\"58\" stroke=\"var(--accent)\" stroke-width=\"2\" />\n  <line x1=\"54\" y1=\"68\" x2=\"66\" y2=\"68\" stroke=\"var(--accent)\" stroke-width=\"1.5\" />\n  <text x=\"28\" y=\"66\" font-size=\"11\" fill=\"var(--accent)\">U</text>\n  <rect x=\"142\" y=\"14\" width=\"56\" height=\"20\" fill=\"var(--gray-1)\" stroke=\"var(--accent)\" stroke-width=\"1.5\" />\n  <text x=\"164\" y=\"28\" font-size=\"11\" fill=\"var(--accent)\">R</text>\n  <line x1=\"220\" y1=\"106\" x2=\"196\" y2=\"106\" stroke=\"var(--accent)\" stroke-width=\"2\" />\n  <text x=\"166\" y=\"122\" font-size=\"11\" fill=\"currentColor\">Ström I</text>\n</svg>"}]', '[{"nameSv":"Ohms lag","latex":"U = R \\cdot I","explanationSv":"Spänningen över en resistor är resistansen gånger strömmen.","variables":[{"symbol":"U","meaningSv":"Spänning","unit":"V"},{"symbol":"R","meaningSv":"Resistans","unit":"Ω"},{"symbol":"I","meaningSv":"Ström","unit":"A"}]},{"nameSv":"Elektrisk effekt","latex":"P = U \\cdot I","explanationSv":"Ger effekten som utvecklas i en komponent.","variables":[{"symbol":"P","meaningSv":"Effekt","unit":"W"},{"symbol":"U","meaningSv":"Spänning","unit":"V"},{"symbol":"I","meaningSv":"Ström","unit":"A"}]}]', '[{"gradeLevel":"E","titleSv":"Ström genom en värmeslinga","givenSv":"U = 230 V, R = 46 Ω","findSv":"Strömmen I","methodSv":"Använd Ohms lag I = U / R.","stepsSv":["I = 230 / 46 = 5,0 A."],"answerSv":"Strömmen är 5,0 A."},{"gradeLevel":"C","titleSv":"Elkostnad i kilowattimmar","givenSv":"En lampa på 60 W lyser i 5,0 timmar vid 230 V.","findSv":"Energiåtgången i J och kWh","methodSv":"Beräkna E = P · t i sekunder för J och i timmar med kW för kWh.","stepsSv":["E = 0,060 kW · 5,0 h = 0,30 kWh.","I joule: 0,30 · 3,6 MJ = 1,08 MJ."],"answerSv":"Energiåtgången är 0,30 kWh (1,08 MJ)."},{"gradeLevel":"A","titleSv":"Ersättningsresistans i blandad krets","givenSv":"Två motstånd på 6,0 Ω och 12 Ω är parallellkopplade, och denna grupp är seriekopplad med 4,0 Ω till 24 V.","findSv":"Totala strömmen från spänningskällan","methodSv":"Beräkna först parallellgruppen R_p och lägg sedan till seriemotståndet.","stepsSv":["1 / R_p = 1/6,0 + 1/12 = 3/12 ger R_p = 4,0 Ω.","R_tot = 4,0 + 4,0 = 8,0 Ω.","I_tot = 24 / 8,0 = 3,0 A."],"answerSv":"Totala strömmen är 3,0 A."}]', '[{"trapTitleSv":"Glömma invertera i parallellkoppling","wrongApproachSv":"Att ta 1 / R_p = 0,25 och svara att R_p = 0,25 Ω.","rightApproachSv":"Du måste ta det inverterade värdet 1 / 0,25 = 4,0 Ω i sista steget."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-4-magnetfalt-och-induktion', 'chap-fysik-1b-4', 'magnetfalt-och-induktion', 2, 'Magnetfält och induktion', '[{"term":"Elektromagnetisk induktion","definition":"Spänning uppstår i en spole när det magnetiska flödet genom spolen förändras."},{"term":"Transformator","definition":"Ändrar växelspänning mellan primär- och sekundärspole enligt lindningskvoten."}]', '[{"heading":"Strömförande ledare och transformatorer","bodySv":"Varje elektrisk ström omges av ett magnetfält. När en ledare med strömmen I befinner sig vinkelrätt i ett magnetfält med flödestätheten B påverkas den av kraften F = B · I · l. Omvänt induceras en spänning i en sluten krets när magnetfältet genom den ändras, vilket används i generatorer och transformatorer.","deepDiveSv":"För en ideal transformator gäller U₁ / U₂ = N₁ / N₂ samt effektbalansen U₁ · I₁ = U₂ · I₂."}]', '[{"nameSv":"Ideala transformatorsambandet","latex":"\\frac{U_1}{U_2} = \\frac{N_1}{N_2}","explanationSv":"Spänningskvoten följer förhållandet mellan antalet lindningsvarv.","variables":[{"symbol":"U_1, U_2","meaningSv":"Primär- och sekundärspänning","unit":"V"},{"symbol":"N_1, N_2","meaningSv":"Varvtal i spolarna","unit":"varv"}]}]', '[{"gradeLevel":"E","titleSv":"Spänning i en ideal transformator","givenSv":"U₁ = 230 V, N₁ = 1 000 varv, N₂ = 50 varv","findSv":"Sekundärspänningen U₂","methodSv":"Lös ut U₂ = U₁ · (N₂ / N₁).","stepsSv":["U₂ = 230 · (50 / 1 000) = 11,5 V."],"answerSv":"Sekundärspänningen är 11,5 V."},{"gradeLevel":"C","titleSv":"Kraft på strömförande ledare","givenSv":"B = 0,40 T, I = 5,0 A, ledarlängd i fältet l = 0,25 m","findSv":"Den magnetiska kraften F","methodSv":"Beräkna F = B · I · l.","stepsSv":["F = 0,40 · 5,0 · 0,25 = 0,50 N."],"answerSv":"Kraften på ledaren är 0,50 N."},{"gradeLevel":"A","titleSv":"Högspänning i kraftledningar","givenSv":"Effekten 10 MW överförs över en ledning med resistansen 4,0 Ω vid antingen 10 kV eller 100 kV.","findSv":"Jämför effektförlusten P_förlust = R · I² i de två fallen.","methodSv":"Beräkna strömmen I = P / U i båda fallen.","stepsSv":["Vid 10 kV: I = 10 000 000 / 10 000 = 1 000 A ger P_förlust = 4,0 · 1 000² = 4,0 MW.","Vid 100 kV: I = 100 A ger P_förlust = 4,0 · 100² = 40 kW (100 gånger mindre)."],"answerSv":"Tio gånger högre spänning ger 100 gånger lägre effektförlust."}]', '[{"trapTitleSv":"Tro att en transformator fungerar med likspänning","wrongApproachSv":"Att använda U₁ / U₂ = N₁ / N₂ för ett konstant batteri.","rightApproachSv":"Induktion kräver ett föränderligt magnetfält, så en transformator fungerar bara med växelspänning."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-5-atommodeller-och-fotoner', 'chap-fysik-1b-5', 'atommodeller-och-fotoner', 1, 'Atommodeller och fotonenergi', '[{"term":"Foton","definition":"Ljuspartikel med energipaketet E = h · f.","unit":"J eller eV"},{"term":"Elektronvolt (eV)","definition":"Energienhet i atomfysiken där 1 eV = 1,602 · 10⁻¹⁹ J.","unit":"eV"}]', '[{"heading":"Energinivåer och spektrallinjer","bodySv":"Elektronerna i en atom kan bara befinna sig i bestämda tillåtna energinivåer. När en elektron hoppar från en högre nivå E₂ till en lägre nivå E₁ sänds en foton ut med energin ΔE = E₂ − E₁ = h · f. Eftersom nivåerna är unika för varje grundämne ger de karakteristiska linjespektra.","deepDiveSv":"Med vågsambandet c = f · λ fås fotonenergin direkt ur våglängden via E = (h · c) / λ, där Plancks konstant är h = 6,626 · 10⁻³⁴ J·s."}]', '[{"nameSv":"Fotonens energi","latex":"E = h \\cdot f = \\frac{h \\cdot c}{\\lambda}","explanationSv":"Sambandet mellan fotonenergi, frekvens f och våglängd λ.","variables":[{"symbol":"E","meaningSv":"Fotonenergi","unit":"J"},{"symbol":"h","meaningSv":"Plancks konstant (6,626·10⁻³⁴)","unit":"J·s"},{"symbol":"f","meaningSv":"Frekvens","unit":"Hz"},{"symbol":"\\lambda","meaningSv":"Våglängd","unit":"m"}]}]', '[{"gradeLevel":"E","titleSv":"Omvandla elektronvolt till joule","givenSv":"En foton har energin 2,5 eV (1 eV = 1,602 · 10⁻¹⁹ J).","findSv":"Energin i joule","methodSv":"Multiplicera med 1,602 · 10⁻¹⁹.","stepsSv":["E = 2,5 · 1,602 · 10⁻¹⁹ ≈ 4,0 · 10⁻¹⁹ J."],"answerSv":"Energin är 4,0 · 10⁻¹⁹ J."},{"gradeLevel":"C","titleSv":"Våglängd vid elektronhopp i väte","givenSv":"ΔE = 1,89 eV, h = 6,626 · 10⁻³⁴ J·s, c = 3,00 · 10⁸ m/s","findSv":"Den utsända fotonens våglängd λ","methodSv":"Omvandla ΔE till joule och lös ut λ = h · c / ΔE.","stepsSv":["ΔE = 1,89 · 1,602 · 10⁻¹⁹ = 3,028 · 10⁻¹⁹ J.","λ = (6,626 · 10⁻³⁴ · 3,00 · 10⁸) / 3,028 · 10⁻¹⁹ ≈ 6,56 · 10⁻⁷ m = 656 nm."],"answerSv":"Våglängden är 656 nm (rött ljus)."},{"gradeLevel":"A","titleSv":"Jonisation av väteatom","givenSv":"Grundtillståndet i väte har energin −13,6 eV.","findSv":"Vilken kortaste frekvens krävs för att helt slå loss elektronen?","methodSv":"Elektronen måste få minst ΔE = 13,6 eV för att nå n = ∞ (0 eV).","stepsSv":["ΔE = 13,6 · 1,602 · 10⁻¹⁹ = 2,179 · 10⁻¹⁸ J.","f = ΔE / h = 2,179 · 10⁻¹⁸ / 6,626 · 10⁻³⁴ ≈ 3,29 · 10¹⁵ Hz."],"answerSv":"Minsta frekvens är 3,29 · 10¹⁵ Hz (ultraviolett ljus)."}]', '[{"trapTitleSv":"Sätta in eV direkt i E = h · f","wrongApproachSv":"Att dividera eV direkt med h = 6,626 · 10⁻³⁴ J·s.","rightApproachSv":"Omvandla alltid eV till joule genom att multiplicera med 1,602 · 10⁻¹⁹ först."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-fysik-1b-5-radioaktivt-sonderfall', 'chap-fysik-1b-5', 'radioaktivt-sonderfall', 2, 'Radioaktivitet och halveringstid', '[{"term":"Alfa-, beta- och gammastrålning","definition":"Heliumkärnor (α), elektroner/positroner (β) och energirika fotoner (γ)."},{"term":"Halveringstid (T₁/₂)","definition":"Tiden det tar för hälften av atomkärnorna i ett preparat att sönderfalla.","unit":"s, år m.fl."},{"term":"Aktivitet (A)","definition":"Antal sönderfall per sekund.","unit":"Bq (becquerel)"}]', '[{"heading":"Sönderfallslagen och kärnreaktioner","bodySv":"Instabila atomkärnor sänder ut joniserande strålning för att nå lägre energi. Vid alfa- och betasönderfall omvandlas kärnan till ett nytt grundämne, men summan av nukleontal A (masstal) och summan av laddningstal Z (atomnummer) bevaras alltid. Efter varje halveringstid halveras både antalet kvarvarande kärnor och aktiviteten.","deepDiveSv":"Massenergi-ekvivalensen E = Δm · c² förklarar den stora energifrigörelsen vid fission och fusion: massan av produkterna är något mindre än massan av reaktanterna, och massdefekten Δm blir energi."}]', '[{"nameSv":"Radioaktivt sönderfall","latex":"A = A_0 \\cdot \\left(\\frac{1}{2}\\right)^{\\frac{t}{T_{1/2}}}","explanationSv":"Aktiviteten A efter tiden t vid halveringstiden T₁/₂.","variables":[{"symbol":"A","meaningSv":"Aktivitet efter tiden t","unit":"Bq"},{"symbol":"A_0","meaningSv":"Startaktivitet","unit":"Bq"},{"symbol":"t","meaningSv":"Förfluten tid","unit":"tidsenhet"},{"symbol":"T_{1/2}","meaningSv":"Halveringstid","unit":"samma tidsenhet"}]},{"nameSv":"Massa-energiekvivalens","latex":"\\Delta E = \\Delta m \\cdot c^2","explanationSv":"Massdefekt Δm vid en kärnreaktion motsvarar frigjord energi ΔE.","variables":[{"symbol":"\\Delta E","meaningSv":"Frigjord energi","unit":"J"},{"symbol":"\\Delta m","meaningSv":"Massminskning","unit":"kg"},{"symbol":"c","meaningSv":"Ljusets fart (3,00·10⁸)","unit":"m/s"}]}]', '[{"gradeLevel":"E","titleSv":"Kvarvarande aktivitet efter två halveringstider","givenSv":"A₀ = 800 Bq, T₁/₂ = 6,0 timmar, t = 12 timmar","findSv":"Aktiviteten efter 12 timmar","methodSv":"12 timmar motsvarar två halveringar.","stepsSv":["A = 800 · (0,5)² = 800 · 0,25 = 200 Bq."],"answerSv":"Aktiviteten är 200 Bq."},{"gradeLevel":"C","titleSv":"Balansera ett betasönderfall","givenSv":"Kol-14 (A = 14, Z = 6) sönderfaller via β⁻-sönderfall (en elektron med A = 0, Z = −1).","findSv":"Dotterkärnans nukleontal och atomnummer","methodSv":"Bevara A och Z på båda sidor av reaktionspilen.","stepsSv":["A_dotter = 14 − 0 = 14.","Z_dotter = 6 − (−1) = 7, vilket är grundämnet kväve (N)."],"answerSv":"Dotterkärnan är kväve-14 (A = 14, Z = 7)."},{"gradeLevel":"A","titleSv":"Datering med kol-14 och logaritmer","givenSv":"Aktiviteten i ett träprov har sjunkit till 30 % av startvärdet. Kol-14 har T₁/₂ = 5 730 år.","findSv":"Provets ålder t","methodSv":"Lös exponentialekvationen 0,30 = 0,5^(t / 5730) med logaritmer.","stepsSv":["lg 0,30 = (t / 5 730) · lg 0,5.","t = 5 730 · (lg 0,30 / lg 0,5) ≈ 5 730 · 1,737 ≈ 9 950 år."],"answerSv":"Provet är cirka 9 950 år gammalt."}]', '[{"trapTitleSv":"Glömt räkna med minustecknet på elektronens laddning i β⁻","wrongApproachSv":"Att minska atomnumret Z vid β⁻-sönderfall.","rightApproachSv":"Vid β⁻-sönderfall ökar atomnumret Z med +1 eftersom en neutron blir en proton plus en elektron."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1a-1-heltal-och-brak', 'chap-matte-1a-1', 'heltal-och-brak', 1, 'Heltal, decimaltal och bråk', '[{"term":"Täljare och nämnare","definition":"I bråket a/b är a täljare (antal delar) och b nämnare (sorten)."},{"term":"Förlängning och förkortning","definition":"Att multiplicera eller dividera både täljare och nämnare med samma tal utan att ändra värdet."},{"term":"Prioriteringsreglerna","definition":"Parenteser, potenser, multiplikation/division och sist addition/subtraktion."}]', '[{"heading":"Samma värde i bråk, decimalform och procent","bodySv":"Varje andel kan uttryckas i bråkform, decimalform och procentform. Bråket 3/4 betyder tre fjärdedelar, vilket motsvarar decimaltalet 0,75 och 75 %. Vid addition eller subtraktion av bråk måste nämnarna först göras lika genom förlängning till minsta gemensamma nämnare.","deepDiveSv":"Multiplikation av två bråk kräver ingen gemensam nämnare: (a/b) · (c/d) = (a·c)/(b·d). Vid division multiplicerar man med det inverterade bråket: (a/b) / (c/d) = (a/b) · (d/c)."}]', '[{"nameSv":"Andel i procent","latex":"\\text{Andel} = \\frac{\\text{Delen}}{\\text{Det hela}}","explanationSv":"Kvoten ger andelen i decimalform; multiplicera med 100 för att få procent.","variables":[{"symbol":"\\text{Delen}","meaningSv":"Den aktuella delmängden","unit":"Samma enhet"},{"symbol":"\\text{Det hela}","meaningSv":"Totalmängden","unit":"Samma enhet"}]}]', '[{"gradeLevel":"E","titleSv":"Bråkdel av ett belopp","givenSv":"En faktura på 2 400 kr ska delas så att 3/8 betalas direkt.","findSv":"Beloppet som betalas direkt","methodSv":"Beräkna först 1/8 genom division och multiplicera sedan med 3.","stepsSv":["1/8 av 2 400 kr = 2 400 / 8 = 300 kr.","3/8 av 2 400 kr = 3 · 300 = 900 kr."],"answerSv":"900 kr betalas direkt."},{"gradeLevel":"C","titleSv":"Addition av olika nämnare","givenSv":"Två arbetsmoment tar 1/4 timme och 2/5 timme.","findSv":"Den sammanlagda tiden i bråkform och minuter","methodSv":"Förläng båda bråken till gemensamma nämnaren 20.","stepsSv":["1/4 + 2/5 = 5/20 + 8/20 = 13/20 timme.","I minuter: (13/20) · 60 = 39 minuter."],"answerSv":"Tiden är 13/20 timme, vilket motsvarar 39 minuter."},{"gradeLevel":"A","titleSv":"Återstående del efter flera avdrag","givenSv":"Av ett lager används först 1/3 på förmiddagen och sedan 3/4 av det som återstår på eftermiddagen.","findSv":"Hur stor andel av det ursprungliga lagret som finns kvar","methodSv":"Beräkna kvarvarande andel stegvis med bråkmultiplikation.","stepsSv":["Efter förmiddagen återstår 1 − 1/3 = 2/3 av lagret.","På eftermiddagen används 3/4 av detta, så 1/4 av 2/3 blir kvar.","Kvarvarande andel: (1/4) · (2/3) = 2/12 = 1/6."],"answerSv":"1/6 av lagret finns kvar."}]', '[{"trapTitleSv":"Addera både täljare och nämnare","wrongApproachSv":"Att skriva 1/4 + 2/5 = 3/9.","rightApproachSv":"Hitta en gemensam nämnare först och addera enbart täljarna: 5/20 + 8/20 = 13/20."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1a-1-procent-och-forandringsfaktor', 'chap-matte-1a-1', 'procent-och-forandringsfaktor', 2, 'Procent och förändringsfaktor', '[{"term":"Procent (%)","definition":"Betyder hundradel: 1 % = 0,01 = 1/100."},{"term":"Förändringsfaktor (ff)","definition":"Talet du multiplicerar ursprungsvärdet med för att direkt få det nya värdet."}]', '[{"heading":"Höjning och sänkning med förändringsfaktor","bodySv":"Vid en procentuell höjning med p % är förändringsfaktorn ff = 1 + p/100. En ökning med 15 % ger alltså ff = 1,15. Vid en sänkning med p % är förändringsfaktorn ff = 1 − p/100, så 20 % rabatt ger ff = 0,80. Fördelen med förändringsfaktor är att flera ändringar i rad kan multipliceras direkt och att ursprungspriset kan beräknas baklänges genom division.","deepDiveSv":"Om ett pris höjs med 20 % (ff = 1,20) och sedan sänks med 20 % (ff = 0,80) blir den totala förändringsfaktorn 1,20 · 0,80 = 0,96, alltså en minskning med 4 %, eftersom sänkningen sker från ett högre belopp."}]', '[{"nameSv":"Nytt värde med förändringsfaktor","latex":"\\text{Nytt värde} = \\text{Gammalt värde} \\cdot \\text{ff}","explanationSv":"Multiplicera med ff för att räkna framåt och dividera med ff för att räkna bakåt.","variables":[{"symbol":"\\text{ff}","meaningSv":"Förändringsfaktor (1 ± p/100)","unit":"Enhetslös"}]}]', '[{"gradeLevel":"E","titleSv":"Pris efter rabatt","givenSv":"Ordinarie pris 800 kr, rabatt 25 %","findSv":"Nya priset","methodSv":"Beräkna ff = 1 − 0,25 = 0,75 och multiplicera.","stepsSv":["800 · 0,75 = 600 kr."],"answerSv":"Det nya priset är 600 kr."},{"gradeLevel":"C","titleSv":"Upprepad prisförändring","givenSv":"Ett pris på 500 kr höjs med 20 % och sänks därefter med 20 %.","findSv":"Slutpriset och den totala procentuella förändringen","methodSv":"Multiplicera de båda förändringsfaktorerna.","stepsSv":["Total förändringsfaktor: 1,20 · 0,80 = 0,96.","Slutpris: 500 · 0,96 = 480 kr (4 % lägre än från början)."],"answerSv":"Slutpriset blir 480 kr, vilket innebär en total minskning med 4 %."},{"gradeLevel":"A","titleSv":"Pris exklusive moms","givenSv":"En tjänst kostar 1 500 kr inklusive 25 % moms.","findSv":"Priset exklusive moms","methodSv":"Priset inklusive moms motsvarar ff = 1,25 gånger baspriset. Dividera med 1,25.","stepsSv":["Baspris · 1,25 = 1 500 kr.","Baspris = 1 500 / 1,25 = 1 200 kr."],"answerSv":"Priset exklusive moms är 1 200 kr."}]', '[{"trapTitleSv":"Dra bort 25 % från priset med moms","wrongApproachSv":"Att ta 1 500 · 0,75 = 1 125 kr för att ta bort 25 % moms.","rightApproachSv":"Momsen lades på det lägre priset (· 1,25). Räkna alltid baklänges genom att dividera med 1,25."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1a-1-overslagsrakning-och-enheter', 'chap-matte-1a-1', 'overslagsrakning-och-enheter', 3, 'Överslagsräkning och enhetsbyten', '[{"term":"Överslagsräkning","definition":"Att avrunda tal till enkla värden i huvudet för att kontrollera rimlighet."},{"term":"Volym och liter","definition":"1 dm³ = 1 liter och 1 m³ = 1 000 liter.","unit":"dm³, m³"}]', '[{"heading":"Prefix och area- samt volymenheter","bodySv":"SI-systemet bygger på tiopotenser: kilo (k) betyder 1 000, centi (c) betyder 1/100 och milli (m) betyder 1/1 000. För längdenheter är steget 10 mellan angränsande enheter, för areaenheter är steget 10² = 100 och för volymenheter är steget 10³ = 1 000.","deepDiveSv":"Exempel: 1 m = 10 dm ger 1 m² = 10 · 10 = 100 dm² och 1 m³ = 10 · 10 · 10 = 1 000 dm³ = 1 000 liter."}]', '[{"nameSv":"Volymsamband","latex":"1\\text{ m}^3 = 1\\ 000\\text{ dm}^3 = 1\\ 000\\text{ liter}","explanationSv":"Varje steg mellan kubikenheter motsvarar en faktor 1 000.","variables":[{"symbol":"\\text{m}^3","meaningSv":"Kubikmeter","unit":"m³"},{"symbol":"\\text{dm}^3","meaningSv":"Kubikdecimeter (liter)","unit":"dm³"}]}]', '[{"gradeLevel":"E","titleSv":"Snabbt överslag i kassan","givenSv":"19 stycken lister à 48,50 kr","findSv":"Rimlig totalkostnad med överslag","methodSv":"Avrunda till 20 · 50.","stepsSv":["20 · 50 = 1 000 kr (exakt värde är 921,50 kr)."],"answerSv":"Totalkostnaden ligger strax under 1 000 kr."},{"gradeLevel":"C","titleSv":"Omvandla kvadratmeter till kvadratcentimeter","givenSv":"En plåt har arean 0,45 m².","findSv":"Arean i cm²","methodSv":"Eftersom 1 m = 100 cm är 1 m² = 100 · 100 = 10 000 cm².","stepsSv":["0,45 · 10 000 = 4 500 cm²."],"answerSv":"Arean är 4 500 cm²."},{"gradeLevel":"A","titleSv":"Tid i timmar och minuter som decimaltal","givenSv":"En arbetstid är 2 timmar och 24 minuter till timpris 450 kr/h.","findSv":"Total arbetskostnad","methodSv":"Omvandla 24 minuter till timmar genom att dividera med 60, inte med 100.","stepsSv":["24 / 60 = 0,40 timmar, så tiden är 2,40 h.","Kostnad: 2,40 · 450 = 1 080 kr."],"answerSv":"Arbetskostnaden är 1 080 kr."}]', '[{"trapTitleSv":"Skriva 2 h 24 min som 2,24 h","wrongApproachSv":"Att anta att det går 100 minuter på en timme.","rightApproachSv":"Dela alltid minuterna med 60: 24 / 60 = 0,40, alltså 2,40 timmar."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1a-2-uttryck-och-ekvationer', 'chap-matte-1a-2', 'uttryck-och-ekvationer', 1, 'Algebraiska uttryck och ekvationslösning', '[{"term":"Variabel","definition":"Bokstav som representerar ett okänt eller föränderligt tal."},{"term":"Ekvation","definition":"Likhet mellan två uttryck där samma räkneoperation utförs på båda sidor."}]', '[{"heading":"Balansmetoden i ekvationer","bodySv":"Likhetstecknet betyder att vänsterled och högerled har exakt samma värde. För att lösa ut variabeln x utför man alltid samma operation på båda sidor tills x står ensam.","deepDiveSv":"Står ett minustecken framför en parentes, exempelvis −(2x − 5), byter alla termer inuti parentesen tecken till −2x + 5."}]', '[{"nameSv":"Distributiva lagen","latex":"a(b + c) = a \\cdot b + a \\cdot c","explanationSv":"Faktorn framför parentesen multipliceras med varje term inuti.","variables":[{"symbol":"a, b, c","meaningSv":"Tal eller variabler","unit":"Enhetslös"}]}]', '[{"gradeLevel":"E","titleSv":"Tvåstegsekvation","givenSv":"3x + 7 = 22","findSv":"Värdet på x","methodSv":"Subtrahera 7 och dividera sedan med 3.","stepsSv":["3x = 15 ger x = 5."],"answerSv":"x = 5."},{"gradeLevel":"C","titleSv":"Ekvation med parentes","givenSv":"2(x − 4) + 6 = 18","findSv":"x","methodSv":"Multiplicera in 2 i parentesen först.","stepsSv":["2x − 8 + 6 = 18","2x − 2 = 18 ger 2x = 20 och x = 10."],"answerSv":"x = 10."},{"gradeLevel":"A","titleSv":"Ekvation uppställd från text","givenSv":"En elektriker tar 450 kr i framkörning och 600 kr per timme. Fakturan blir 2 250 kr.","findSv":"Antalet arbetade timmar t","methodSv":"Ställ upp ekvationen 450 + 600t = 2 250.","stepsSv":["600t = 1 800 ger t = 3,0 timmar."],"answerSv":"Elektrikern arbetade 3 timmar."}]', '[{"trapTitleSv":"Glömma multiplicera andra termen i parentesen","wrongApproachSv":"Att skriva 2(x − 4) = 2x − 4.","rightApproachSv":"Multiplicera med båda termerna: 2 · x − 2 · 4 = 2x − 8."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1a-3-area-volym-och-skala', 'chap-matte-1a-3', 'area-volym-och-skala', 1, 'Area, volym och skala', '[{"term":"Längdskala","definition":"Förhållandet mellan avbildningens längd och verklighetens längd."},{"term":"Areaskala","definition":"Kvadraten på längdskalan (k²)."}]', '[{"heading":"Samband mellan längd-, area- och volymskala","bodySv":"En ritning i skala 1:50 innebär att 1 cm på ritningen motsvarar 50 cm i verkligheten. Förstorar man alla sidor med faktorn k blir arean k² gånger större och volymen k³ gånger större.","deepDiveSv":"Om ett rum har längdskalan 1:50 är areaskalan 1:50² = 1:2 500."}]', '[{"nameSv":"Cylindervolym","latex":"V = \\pi \\cdot r^2 \\cdot h","explanationSv":"Basarean gånger höjden.","variables":[{"symbol":"r","meaningSv":"Radie","unit":"m"},{"symbol":"h","meaningSv":"Höjd","unit":"m"}]}]', '[{"gradeLevel":"E","titleSv":"Verklig längd från ritning","givenSv":"Skala 1:100, sträcka på ritningen 4,5 cm","findSv":"Verklig längd i meter","methodSv":"Multiplicera med 100 och omvandla cm till m.","stepsSv":["4,5 · 100 = 450 cm = 4,5 m."],"answerSv":"Verkliga längden är 4,5 m."},{"gradeLevel":"C","titleSv":"Areaskala på en karta","givenSv":"Karta i skala 1:200, parkeringsyta på kartan 6,0 cm²","findSv":"Verklig area i kvadratmeter","methodSv":"Areaskalan är 200² = 40 000.","stepsSv":["6,0 · 40 000 = 240 000 cm² = 24 m²."],"answerSv":"Verkliga arean är 24 m²."},{"gradeLevel":"A","titleSv":"Förstoringsfaktor utifrån volym","givenSv":"En behållare ska rymma 8 gånger så mycket vatten med bibehållen form.","findSv":"Hur mycket måste radien öka?","methodSv":"Volymskalan k³ = 8 ger k.","stepsSv":["k³ = 8 ger k = 2 (radien ska fördubblas)."],"answerSv":"Radien ska fördubblas."}]', '[{"trapTitleSv":"Använda längdskalan direkt för area","wrongApproachSv":"Att multiplicera en area med 100 vid skalan 1:100.","rightApproachSv":"Kvadrera längdskalan först: vid 1:100 är areaskalan 1:10 000."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1a-4-lagesmatt-och-sannolikhet', 'chap-matte-1a-4', 'lagesmatt-och-sannolikhet', 1, 'Lägesmått och klassisk sannolikhet', '[{"term":"Medelvärde","definition":"Summan av alla värden delat med antalet värden."},{"term":"Median","definition":"Det mittersta värdet när alla tal ordnats i storleksordning."},{"term":"Sannolikhet P(A)","definition":"Antalet gynnsamma utfall delat med antalet möjliga utfall vid likformig sannolikhet."}]', '[{"heading":"Val av lägesmått och träddiagram","bodySv":"När en datamängd innehåller ett extremt avvikande värde påverkas medelvärdet kraftigt, medan medianen förblir stabil. För sannolikheter i flera steg multipliceras sannolikheterna längs grenarna i ett träddiagram.","deepDiveSv":"Komplementhändelsen P(inte A) = 1 − P(A) gör uppgifter med \"minst en gång\" mycket enklare."}]', '[{"nameSv":"Klassisk sannolikhet","latex":"P(A) = \\frac{\\text{Gynnsamma utfall}}{\\text{Möjliga utfall}}","explanationSv":"Gäller när alla utfall är lika sannolika.","variables":[{"symbol":"P(A)","meaningSv":"Sannolikheten för händelsen A","unit":"0–1"}]}]', '[{"gradeLevel":"E","titleSv":"Median för fem mätvärden","givenSv":"12, 19, 14, 45, 16","findSv":"Medianen","methodSv":"Sortera talen i storleksordning först.","stepsSv":["Sorterat: 12, 14, 16, 19, 45. Mittersata talet är 16."],"answerSv":"Medianen är 16."},{"gradeLevel":"C","titleSv":"Två dragningar utan återläggning","givenSv":"En låda har 3 röda och 5 blå kulor. Två kulor dras utan återläggning.","findSv":"Sannolikheten att båda är röda","methodSv":"Multiplicera sannolikheterna i två steg.","stepsSv":["(3/8) · (2/7) = 6/56 = 3/28 ≈ 10,7 %."],"answerSv":"Sannolikheten är 3/28 (cirka 10,7 %)."},{"gradeLevel":"A","titleSv":"Komplementhändelse med tärning","givenSv":"En sexsidig tärning kastas två gånger.","findSv":"Sannolikheten att få minst en sexa","methodSv":"Beräkna 1 minus sannolikheten för ingen sexa alls.","stepsSv":["P(ingen sexa) = (5/6) · (5/6) = 25/36.","P(minst en sexa) = 1 − 25/36 = 11/36 ≈ 30,6 %."],"answerSv":"Sannolikheten är 11/36 (cirka 30,6 %)."}]', '[{"trapTitleSv":"Glömma sortera innan medianen läses av","wrongApproachSv":"Att ta mitten av den osorterade listan.","rightApproachSv":"Sortera alltid värdena i stigande ordning före avläsning."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1b-1-procent-och-procentenheter', 'chap-matte-1b-1', 'procent-och-procentenheter', 1, 'Procent och procentenheter', '[{"term":"Procentenhet","definition":"Den absoluta skillnaden mellan två procentsatser genom subtraktion."},{"term":"Relativ förändring i procent","definition":"Skillnaden dividerad med ursprungsvärdet."},{"term":"Promille (‰)","definition":"Tusendel, alltså 1 ‰ = 0,001 = 0,1 %."}]', '[{"heading":"Skillnaden mellan procentenheter och procentuell ökning","bodySv":"När två procentsatser jämförs med varandra används begreppet procentenheter för att beskriva den rena skillnaden. Om en ränta höjs från 2,0 % till 3,0 % är höjningen 1,0 procentenhet. Men den relativa ökningen av räntekostnaden är (3,0 − 2,0) / 2,0 = 0,50, alltså 50 %.","deepDiveSv":"I politiska och ekonomiska texter är det en klassisk fälla att blanda ihop procentenheter och procent. Kontrollera alltid vad nämnaren är när en procentuell förändring beräknas."}]', '[{"nameSv":"Relativ förändring","latex":"\\text{Relativ förändring} = \\frac{\\text{Nytt värde} - \\text{Gammalt värde}}{\\text{Gammalt värde}}","explanationSv":"Gäller även när värdena i sig är procentsatser.","variables":[{"symbol":"\\text{Nytt}","meaningSv":"Slutvärde","unit":"Valfri"},{"symbol":"\\text{Gammalt}","meaningSv":"Startvärde","unit":"Samma enhet"}]}]', '[{"gradeLevel":"E","titleSv":"Jämföra två skattesatser","givenSv":"Kommunalskatten ändras från 31,5 % till 32,2 %.","findSv":"Ändringen i procentenheter","methodSv":"Subtrahera den äldre procentsatsen från den nya.","stepsSv":["32,2 − 31,5 = 0,7 procentenheter."],"answerSv":"Skatten höjs med 0,7 procentenheter."},{"gradeLevel":"C","titleSv":"Relativ ökning av valdeltagande eller andel","givenSv":"Andelen nöjda kunder ökar från 20 % till 25 %.","findSv":"Ökningen i procentenheter och i procent","methodSv":"Subtrahera för procentenheter; dividera med startvärdet 20 för procent.","stepsSv":["Procentenheter: 25 − 20 = 5 procentenheter.","Relativ ökning: 5 / 20 = 0,25 = 25 %."],"answerSv":"Ökningen är 5 procentenheter, vilket motsvarar 25 %."},{"gradeLevel":"A","titleSv":"Återställa ett sänkt aktievärde","givenSv":"En fond minskar i värde med 20 % under ett år.","findSv":"Hur många procent måste fonden öka nästa år för att återta ursprungsvärdet?","methodSv":"Bestäm kvoten 1 / ff.","stepsSv":["Efter sänkningen är värdet 0,80 gånger startvärdet.","För att komma tillbaka till 1,00 krävs faktorn 1 / 0,80 = 1,25."],"answerSv":"Fonden måste öka med 25 %."}]', '[{"trapTitleSv":"Svara 20 % i stället för 25 % vid återhämtning","wrongApproachSv":"Att tro att +20 % tar ut −20 %.","rightApproachSv":"Procenten räknas alltid på det aktuella beloppet: 0,80 · 1,20 = 0,96 < 1."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1b-1-forandringsfaktor-och-ranta', 'chap-matte-1b-1', 'forandringsfaktor-och-ranta', 2, 'Förändringsfaktor, index och ränta', '[{"term":"Ränta på ränta","definition":"Kapitaltillväxt där årlig ränta läggs på både insatt kapital och tidigare ränta."},{"term":"Indextal","definition":"Relativt jämförelsetal där ett basår får värdet 100."}]', '[{"heading":"Upprepad förändring och prisindex","bodySv":"Om ett sparkapital C växer med p % per år under x år blir beloppet y = C · ff^x. Samma matematiska modell beskriver inflation och befolkningstillväxt. För att enkelt jämföra priser över tid används indextal där basåret motsvarar index 100.","deepDiveSv":"Har konsumentprisindex (KPI) ökat från 100 till 124 betyder det att prisnivån i genomsnitt ökat med 24 % sedan basåret."}]', '[{"nameSv":"Upprepad procentuell förändring","latex":"y = C \\cdot a^x","explanationSv":"Startvärdet C multipliceras med förändringsfaktorn a i x steg.","variables":[{"symbol":"y","meaningSv":"Slutvärde","unit":"kr eller antal"},{"symbol":"C","meaningSv":"Startvärde","unit":"kr eller antal"},{"symbol":"a","meaningSv":"Förändringsfaktor per tidssteg","unit":"Enhetslös"},{"symbol":"x","meaningSv":"Antal tidssteg","unit":"år"}]}]', '[{"gradeLevel":"E","titleSv":"Sparkonto i två år","givenSv":"C = 10 000 kr, årsränta 5,0 %, tid 2 år","findSv":"Saldot efter 2 år","methodSv":"Beräkna 10 000 · 1,05².","stepsSv":["10 000 · 1,05² = 10 000 · 1,1025 = 11 025 kr."],"answerSv":"Efter 2 år finns 11 025 kr på kontot."},{"gradeLevel":"C","titleSv":"Beräkna pris utifrån indextal","givenSv":"Ett index stiger från 110 till 132. Varan kostade 550 kr vid index 110.","findSv":"Nya priset vid index 132","methodSv":"Skala med kvoten mellan indextalen: 132 / 110.","stepsSv":["550 · (132 / 110) = 550 · 1,20 = 660 kr."],"answerSv":"Det nya priset är 660 kr."},{"gradeLevel":"A","titleSv":"Jämföra medelförändring per år","givenSv":"En bostad stiger i värde från 2 000 000 kr till 2 420 000 kr på 2 år.","findSv":"Den genomsnittliga årliga procentuella ökningen","methodSv":"Lös 2 000 000 · a² = 2 420 000.","stepsSv":["a² = 2 420 000 / 2 000 000 = 1,21 ger a = √1,21 = 1,10."],"answerSv":"Den årliga ökningen är i genomsnitt 10 %."}]', '[{"trapTitleSv":"Multiplicera räntesatsen linjärt i stället för ränta på ränta","wrongApproachSv":"Att ta 10 000 · (1 + 2 · 0,05) = 11 000 kr.","rightApproachSv":"Ränta läggs på kapitalet varje år, vilket ger potensen 1,05² = 1,1025."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1b-1-algebraiska-uttryck-och-ekvationer', 'chap-matte-1b-1', 'algebraiska-uttryck-och-ekvationer', 3, 'Algebraiska uttryck och ekvationer', '[{"term":"Term","definition":"Del i en summa eller differens."},{"term":"Ekvivalent ekvation","definition":"Ekvation med exakt samma lösning som den ursprungliga."}]', '[{"heading":"Förenkling av uttryck med flera parenteser","bodySv":"Vid förenkling av algebraiska uttryck multipliceras faktorer in i sina parenteser först och därefter samlas termer av samma sort (x-termer för sig och konstanter för sig). När en ekvation har variabeln x i båda leden samlar man alla x-termer på ena sidan.","deepDiveSv":"Kontrollera alltid din ekvationslösning genom att sätta tillbaka svaret i den ursprungliga ekvationen och verifiera att vänsterledet blir lika med högerledet."}]', '[{"nameSv":"Linjär ekvation med variabel i båda led","latex":"ax + b = cx + d \\implies x = \\frac{d - b}{a - c}","explanationSv":"Samla x-termer i ena ledet och konstanter i det andra (för a ≠ c).","variables":[{"symbol":"a, b, c, d","meaningSv":"Kända tal","unit":"Enhetslös"},{"symbol":"x","meaningSv":"Obekant variabel","unit":"Enhetslös"}]}]', '[{"gradeLevel":"E","titleSv":"Variabel på båda sidor","givenSv":"5x − 8 = 2x + 13","findSv":"x","methodSv":"Subtrahera 2x och addera 8 på båda sidor.","stepsSv":["3x = 21 ger x = 7."],"answerSv":"x = 7."},{"gradeLevel":"C","titleSv":"Förenkla parentesdifferens","givenSv":"4(2x − 3) − 2(x − 5)","findSv":"Förenklat uttryck","methodSv":"Multiplicera in 4 och −2 noggrant.","stepsSv":["8x − 12 − 2x + 10 = 6x − 2."],"answerSv":"Uttrycket förenklas till 6x − 2."},{"gradeLevel":"A","titleSv":"Brytpunkt mellan två abonnemang","givenSv":"Abonnemang A kostar 190 kr/mån plus 2 kr/min. Abonnemang B kostar 340 kr/mån med fria minuter.","findSv":"Vid hur många minuter per månad kostar båda lika mycket?","methodSv":"Sätt kostnadsuttrycken lika med varandra.","stepsSv":["190 + 2x = 340 ger 2x = 150 och x = 75 minuter."],"answerSv":"Vid 75 minuter per månad är kostnaden densamma."}]', '[{"trapTitleSv":"Teckenfel vid −2(x − 5)","wrongApproachSv":"Att skriva −2x − 10.","rightApproachSv":"Negativt tal gånger negativt tal blir positivt: (−2) · (−5) = +10."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1b-2-rata-linjen', 'chap-matte-1b-2', 'rata-linjen', 1, 'Räta linjens ekvation', '[{"term":"Riktningskoefficient (k)","definition":"Linjens lutning, alltså hur mycket y ändras när x ökar med 1."},{"term":"Skärningspunkt med y-axeln (m)","definition":"Funktionsvärdet när x = 0."}]', '[{"heading":"Tolka k och m i verkliga modeller","bodySv":"En linjär funktion skrivs y = kx + m. I ekonomiska modeller motsvarar m ofta den fasta grundavgiften och k den rörliga kostnaden per enhet. Lutningen mellan två punkter beräknas med k = (y₂ − y₁) / (x₂ − x₁).","deepDiveSv":"Två räta linjer är parallella om och endast om de har samma k-värde."}]', '[{"nameSv":"Räta linjens ekvation","latex":"y = kx + m, \\quad k = \\frac{y_2 - y_1}{x_2 - x_1}","explanationSv":"Beskriver linjära samband med konstant lutning k.","variables":[{"symbol":"k","meaningSv":"Lutning (ändring per steg)","unit":"Enhetsberoende"},{"symbol":"m","meaningSv":"Startvärde vid x = 0","unit":"Samma som y"}]}]', '[{"gradeLevel":"E","titleSv":"Beräkna k-värde mellan två punkter","givenSv":"Punkterna (1, 5) och (4, 14)","findSv":"Riktningskoefficienten k","methodSv":"Använd Δy / Δx.","stepsSv":["k = (14 − 5) / (4 − 1) = 9 / 3 = 3."],"answerSv":"k = 3."},{"gradeLevel":"C","titleSv":"Bestäm hela linjens ekvation","givenSv":"k = 3 och linjen går genom (1, 5).","findSv":"Ekvationen y = kx + m","methodSv":"Sätt in (1, 5) och lös ut m.","stepsSv":["5 = 3 · 1 + m ger m = 2, så y = 3x + 2."],"answerSv":"y = 3x + 2."},{"gradeLevel":"A","titleSv":"Skärning mellan två linjära funktioner","givenSv":"f(x) = 4x + 10 och g(x) = 2x + 30","findSv":"Skärningspunktens koordinater","methodSv":"Sätt f(x) = g(x).","stepsSv":["4x + 10 = 2x + 30 ger 2x = 20, x = 10 och y = 50."],"answerSv":"Linjerna skär varandra i (10, 50)."}]', '[{"trapTitleSv":"Kasta om x och y i k-formeln","wrongApproachSv":"Att skriva Δx / Δy.","rightApproachSv":"Skillnaden i y står alltid i täljaren: k = (y₂ − y₁) / (x₂ − x₁)."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1b-3-pythagoras-och-trigonometri', 'chap-matte-1b-3', 'pythagoras-och-trigonometri', 1, 'Pythagoras sats och rätvinkliga trianglar', '[{"term":"Hypotenusa","definition":"Den längsta sidan i en rätvinklig triangel, mittemot den räta vinkeln."},{"term":"Sinus, cosinus, tangens","definition":"Sidokvoter i en rätvinklig triangel som bara beror på vinkeln."}]', '[{"heading":"Samband mellan sidor och vinklar","bodySv":"I varje rätvinklig triangel med kateterna a, b och hypotenusan c gäller Pythagoras sats: a² + b² = c². Om en spetsig vinkel v är känd kan sidor och vinklar kopplas samman med sin v = motstående / hypotenusa, cos v = närliggande / hypotenusa och tan v = motstående / närliggande.","deepDiveSv":"Kom ihåg att vinkelsumman i alla trianglar är 180°, och summan av yttervinkel och innervinkel är alltid 180°."}]', '[{"nameSv":"Pythagoras sats","latex":"a^2 + b^2 = c^2","explanationSv":"Gäller i rätvinkliga trianglar där c är hypotenusan.","variables":[{"symbol":"a, b","meaningSv":"Kateter","unit":"längdenhet"},{"symbol":"c","meaningSv":"Hypotenusa","unit":"längdenhet"}]}]', '[{"gradeLevel":"E","titleSv":"Beräkna hypotenusan","givenSv":"Kateterna a = 6,0 cm och b = 8,0 cm","findSv":"Hypotenusan c","methodSv":"c = √(a² + b²).","stepsSv":["c = √(36 + 64) = √100 = 10 cm."],"answerSv":"Hypotenusan är 10 cm."},{"gradeLevel":"C","titleSv":"Beräkna en okänd katet","givenSv":"Hypotenusa c = 13 m, katet a = 5,0 m","findSv":"Kateten b","methodSv":"b² = c² − a².","stepsSv":["b = √(169 − 25) = √144 = 12 m."],"answerSv":"Kateten är 12 m."},{"gradeLevel":"A","titleSv":"Lutningsvinkel för en ramp","givenSv":"En ramp stiger 1,2 m på en horisontell sträcka av 4,8 m.","findSv":"Lutningsvinkeln v","methodSv":"Använd tan v = motstående / närliggande.","stepsSv":["tan v = 1,2 / 4,8 = 0,25 ger v = arctan 0,25 ≈ 14,0°."],"answerSv":"Lutningsvinkeln är 14°."}]', '[{"trapTitleSv":"Ställa in räknaren på radianer i stället för grader","wrongApproachSv":"Att läsa av tan⁻¹ i radianläge under Matte 1.","rightApproachSv":"Kontrollera alltid att räknaren står på DEG (grader)."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1b-4-statistik-och-korrelation', 'chap-matte-1b-4', 'statistik-och-korrelation', 1, 'Spridningsmått, korrelation och sannolikhet', '[{"term":"Variationsbredd","definition":"Skillnaden mellan största och minsta värdet."},{"term":"Korrelation","definition":"Statistiskt samband mellan två variabler, som inte automatiskt betyder orsakssamband."}]', '[{"heading":"Lådagram och källkritisk statistik","bodySv":"Ett lådagram delar in sorterade data i fyra lika stora delar (kvartiler). Mellan nedre kvartil Q₁ och övre kvartil Q₃ ligger de mittersta 50 % av observationerna (kvartilavståndet). Vid tolkning av grafer är det avgörande att skilja på korrelation (samvariation) och kausalitet (orsak och verkan).","deepDiveSv":"En bakomliggande tredje variabel kan förklara varför två saker samvarierar utan att den ena orsakar den andra."}]', '[{"nameSv":"Kvartilavstånd","latex":"\\text{IQR} = Q_3 - Q_1","explanationSv":"Visar spridningen för de mittersta 50 % av materialet.","variables":[{"symbol":"Q_3","meaningSv":"Övre kvartil","unit":"Datans enhet"},{"symbol":"Q_1","meaningSv":"Nedre kvartil","unit":"Datans enhet"}]}]', '[{"gradeLevel":"E","titleSv":"Variationsbredd","givenSv":"Temperaturer: 11 °C, 15 °C, 19 °C, 14 °C, 23 °C","findSv":"Variationsbredden","methodSv":"Största värdet minus minsta värdet.","stepsSv":["23 − 11 = 12 °C."],"answerSv":"Variationsbredden är 12 °C."},{"gradeLevel":"C","titleSv":"Kvartiler i sorterad data","givenSv":"2, 4, 6, 8, 10, 12, 14","findSv":"Q₁, median och Q₃","methodSv":"Medianen är 8; Q₁ är medianen av undre halvan och Q₃ av övre halvan.","stepsSv":["Q₁ = 4, median = 8, Q₃ = 12, kvartilavstånd = 12 − 4 = 8."],"answerSv":"Q₁ = 4, median = 8 och Q₃ = 12."},{"gradeLevel":"A","titleSv":"Bedöma korrelation kontra kausalitet","givenSv":"Statistik visar stark positiv korrelation mellan glassförsäljning och drunkningsolyckor.","findSv":"Vilken slutsats är korrekt?","methodSv":"Sök en gemensam bakomliggande faktor.","stepsSv":["Varmt sommarväder gör både att fler äter glass och att fler badar.","Glassätande orsakar alltså inte olyckor (korrelation ≠ kausalitet)."],"answerSv":"Sommaren är en bakomliggande variabel; sambandet är inte kausalt."}]', '[{"trapTitleSv":"Sätta likhetstecken mellan korrelation och orsak","wrongApproachSv":"Att hävda att X orsakar Y bara för att ett spridningsdiagram visar en trend.","rightApproachSv":"Pröva alltid om en tredje variabel eller slump kan förklara samvariationen."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1c-1-reella-tal-och-potenslagar', 'chap-matte-1c-1', 'reella-tal-och-potenslagar', 1, 'Reella tal, potenslagar och grundpotensform', '[{"term":"Potens (a^n)","definition":"Upprepad multiplikation där a är bas och n är exponent."},{"term":"Grundpotensform","definition":"Tal skrivna som a · 10^n där 1 ≤ |a| < 10 och n är ett heltal."}]', '[{"heading":"Potenslagar för alla heltaliga exponenter","bodySv":"Med potenslagarna kan stora uttryck och tiopotenser förenklas snabbt utan räknare. När baserna är lika adderas exponenterna vid multiplikation och subtraheras vid division. Dessutom definieras a⁰ = 1 (för a ≠ 0) och negativa exponenter som inverterade potenser: a⁻ⁿ = 1 / aⁿ.","deepDiveSv":"Grundpotensform används flitigt i fysik och kemi för mycket stora och mycket små tal, exempelvis 0,00045 = 4,5 · 10⁻⁴."}]', '[{"nameSv":"Centrala potenslagar","latex":"a^m \\cdot a^n = a^{m+n}, \\quad \\frac{a^m}{a^n} = a^{m-n}, \\quad (a^m)^n = a^{m \\cdot n}","explanationSv":"Gäller när basen a ≠ 0.","variables":[{"symbol":"a","meaningSv":"Bas","unit":"Reellt tal ≠ 0"},{"symbol":"m, n","meaningSv":"Exponenter","unit":"Reella tal"}]},{"nameSv":"Nollexponent och negativ exponent","latex":"a^0 = 1, \\quad a^{-n} = \\frac{1}{a^n}","explanationSv":"Gör att potenslagarna gäller konsekvent även för 0 och negativa heltal.","variables":[{"symbol":"a","meaningSv":"Bas ≠ 0","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Förenkla kvot av potenser","givenSv":"(2⁴ · 2⁵) / 2⁶","findSv":"Värdet som heltal","methodSv":"Addera exponenterna i täljaren och subtrahera nämnarens exponent.","stepsSv":["2⁴⁺⁵⁻⁶ = 2³ = 8."],"answerSv":"Värdet är 8."},{"gradeLevel":"C","titleSv":"Räkna i grundpotensform","givenSv":"(6,0 · 10⁸) / (1,5 · 10³)","findSv":"Svaret i grundpotensform","methodSv":"Dividera faktorer för sig och tiopotenser för sig.","stepsSv":["(6,0 / 1,5) · 10⁸⁻³ = 4,0 · 10⁵."],"answerSv":"4,0 · 10⁵."},{"gradeLevel":"A","titleSv":"Byte av bas i potensekvation","givenSv":"4^x = 32","findSv":"Exakta lösningen x","methodSv":"Skriv både 4 och 32 med basen 2.","stepsSv":["(2²)^x = 2⁵ ger 2^(2x) = 2⁵, alltså 2x = 5 och x = 2,5."],"answerSv":"x = 2,5."}]', '[{"trapTitleSv":"Addera exponenter i (a^m)^n","wrongApproachSv":"Att skriva (x³)² = x⁵.","rightApproachSv":"Potens av potens multiplicerar exponenterna: (x³)² = x³·² = x⁶."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1c-1-procent-och-tillvaxt', 'chap-matte-1c-1', 'procent-och-tillvaxt', 2, 'Förändringsfaktor och exponentiell tillväxt', '[{"term":"Exponentialfunktion","definition":"Modell på formen y = C · a^x där förändringen sker med konstant procent per steg."}]', '[{"heading":"Tillväxt och avklingning","bodySv":"När en storhet förändras med samma procentsats i varje steg växer eller minskar den exponentiellt. Är förändringsfaktorn a > 1 växer värdet allt snabbare; är 0 < a < 1 minskar värdet mot noll.","deepDiveSv":"Halvering innebär a = 0,50 och fördubbling innebär a = 2,0."}]', '[{"nameSv":"Exponentiell modell","latex":"y = C \\cdot a^x","explanationSv":"Beskriver värdet efter x tidssteg från startvärdet C.","variables":[{"symbol":"C","meaningSv":"Startvärde vid x = 0","unit":"Valfri"},{"symbol":"a","meaningSv":"Förändringsfaktor","unit":"Enhetslös"}]}]', '[{"gradeLevel":"E","titleSv":"Bakterietillväxt under två timmar","givenSv":"800 bakterier ökar med 25 % per timme.","findSv":"Antalet efter 2 timmar","methodSv":"y = 800 · 1,25².","stepsSv":["800 · 1,5625 = 1 250 bakterier."],"answerSv":"Efter 2 timmar finns 1 250 bakterier."},{"gradeLevel":"C","titleSv":"Hitta procentuell förändring från modell","givenSv":"V(t) = 150 000 · 0,84^t","findSv":"Årlig värdeminskning i procent","methodSv":"Jämför a = 0,84 med 1 − p/100.","stepsSv":["1 − 0,84 = 0,16 = 16 % minskning per år."],"answerSv":"Värdet minskar med 16 % per år."},{"gradeLevel":"A","titleSv":"Total procentuell ändring på ett decennium","givenSv":"En befolkning ökar med 2 % per år i 10 år.","findSv":"Totala procentuella ökningen","methodSv":"Beräkna 1,02¹⁰ − 1.","stepsSv":["1,02¹⁰ ≈ 1,2190, vilket ger 21,9 % ökning (inte 20 %)."],"answerSv":"Befolkningen ökar med totalt 21,9 %."}]', '[{"trapTitleSv":"Läsa av a = 0,84 som 84 % minskning","wrongApproachSv":"Att tolka förändringsfaktorn direkt som minskningsprocent.","rightApproachSv":"Skillnaden från 1 visar ändringen: 1 − 0,84 = 0,16 = 16 % minskning."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1c-1-ekvationer-och-olikheter', 'chap-matte-1c-1', 'ekvationer-och-olikheter', 3, 'Ekvationer, olikheter och algebraiska bevis', '[{"term":"Olikhet","definition":"Jämförelse med <, >, ≤ eller ≥."},{"term":"Generellt bevis","definition":"Algebraiskt resonemang som visar att ett påstående gäller för alla tal, inte bara ett exempel."}]', '[{"heading":"Olikhetstecken och bråkekvationer","bodySv":"Olikheter löses precis som ekvationer, med ett viktigt undantag: när båda leden multipliceras eller divideras med ett negativt tal måste olikhetstecknet vändas åt motsatt håll. För att visa att något alltid är sant räcker aldrig sifferexempel — i stället används allmänna uttryck som 2n för jämna tal och 2n + 1 för udda tal.","deepDiveSv":"Varför vänds olikhetstecknet? Jo, 4 > 2 är sant, men multiplicerar vi båda led med −1 blir −4 < −2."}]', '[{"nameSv":"Teckenbyte i olikhet","latex":"-a \\cdot x > b \\implies x < -\\frac{b}{a} \\quad (a > 0)","explanationSv":"Division med negativt tal vänder olikhetstecknet.","variables":[{"symbol":"a, b","meaningSv":"Konstanter (a > 0)","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Linjär olikhet med negativ koefficient","givenSv":"−3x > 12","findSv":"Vilka x som uppfyller olikheten","methodSv":"Dividera med −3 och vänd på tecknet.","stepsSv":["x < 12 / (−3) ger x < −4."],"answerSv":"x < −4."},{"gradeLevel":"C","titleSv":"Ekvation med olika nämnare","givenSv":"(x + 2)/3 − (x − 1)/2 = 1","findSv":"x","methodSv":"Multiplicera hela ekvationen med minsta gemensamma nämnaren 6.","stepsSv":["2(x + 2) − 3(x − 1) = 6.","2x + 4 − 3x + 3 = 6 ger −x + 7 = 6 och x = 1."],"answerSv":"x = 1."},{"gradeLevel":"A","titleSv":"Algebraiskt bevis för på varandra följande tal","givenSv":"Tre på varandra följande heltal är n, n + 1 och n + 2.","findSv":"Bevisa att summan alltid är delbar med 3.","methodSv":"Addera uttrycken och bryt ut faktorn 3.","stepsSv":["Summa = n + (n + 1) + (n + 2) = 3n + 3.","Bryt ut 3: 3(n + 1). Eftersom n + 1 är ett heltal är summan en multipel av 3."],"answerSv":"Summan kan skrivas 3(n + 1) och är alltid delbar med 3."}]', '[{"trapTitleSv":"Glömma parentesen när nämnaren 6 multipliceras in i −(x − 1)/2","wrongApproachSv":"Att skriva −3x − 3 i stället för −3(x − 1) = −3x + 3.","rightApproachSv":"Behåll alltid en skyddande parentes runt täljaren när du multiplicerar bort nämnaren."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1c-2-funktionsbegrepp-och-rata-linjen', 'chap-matte-1c-2', 'funktionsbegrepp-och-rata-linjen', 1, 'Funktionsbegrepp och räta linjen', '[{"term":"Definitionsmängd","definition":"Alla tillåtna värden på x."},{"term":"Värdemängd","definition":"Alla värden som funktionen y = f(x) kan anta."}]', '[{"heading":"Från allmän form till k-form","bodySv":"En rät linje kan anges på k-form y = kx + m eller på allmän form ax + by + c = 0. Genom att lösa ut y ser man direkt lutningen k och skärningen m.","deepDiveSv":"Två linjer är vinkelräta mot varandra om k₁ · k₂ = −1."}]', '[{"nameSv":"Enpunktsformeln","latex":"y - y_1 = k(x - x_1)","explanationSv":"Bestämmer linjens ekvation direkt utifrån lutningen k och en punkt.","variables":[{"symbol":"k","meaningSv":"Lutning","unit":"Tal"},{"symbol":"x_1, y_1","meaningSv":"Känd punkt","unit":"Koordinater"}]}]', '[{"gradeLevel":"E","titleSv":"Läsa av k och m från allmän form","givenSv":"2x + y = 7","findSv":"k och m","methodSv":"Lös ut y.","stepsSv":["y = −2x + 7 ger k = −2 och m = 7."],"answerSv":"k = −2 och m = 7."},{"gradeLevel":"C","titleSv":"Linjens ekvation genom två punkter","givenSv":"(−1, 2) och (3, 10)","findSv":"y = kx + m","methodSv":"Beräkna k och sätt in en punkt.","stepsSv":["k = (10 − 2)/(3 − (−1)) = 2. 10 = 2·3 + m ger m = 4."],"answerSv":"y = 2x + 4."},{"gradeLevel":"A","titleSv":"Parallell linje genom ny punkt","givenSv":"Parallell med 3x − y = 4 genom (2, 1)","findSv":"Ekvationen","methodSv":"Skriv 3x − y = 4 som y = 3x − 4 så k = 3.","stepsSv":["1 = 3·2 + m ger m = −5, alltså y = 3x − 5."],"answerSv":"y = 3x − 5."}]', '[{"trapTitleSv":"Läsa k direkt utan att lösa ut y","wrongApproachSv":"Att säga att 2x + 4y = 8 har lutningen k = 2.","rightApproachSv":"Lös först ut y: 4y = −2x + 8 ger y = −0,5x + 2, alltså k = −0,5."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1c-3-likformighet-och-trigonometri', 'chap-matte-1c-3', 'likformighet-och-trigonometri', 1, 'Likformighet och rätvinklig trigonometri', '[{"term":"Likformighet","definition":"Två figurer med lika stora motsvarande vinklar och proportionella sidor."}]', '[{"heading":"Topptriangelsatsen och trigonometri","bodySv":"En parallell linje genom två sidor i en triangel skapar en likformig topptriangel. I rätvinkliga trianglar används sinus, cosinus och tangens för att beräkna okända längder och vinklar.","deepDiveSv":"Exakta trigonometriska värden: sin 30° = 0,5, cos 60° = 0,5 och tan 45° = 1."}]', '[{"nameSv":"Trigonometriska definitioner","latex":"\\sin v = \\frac{a}{c}, \\quad \\cos v = \\frac{b}{c}, \\quad \\tan v = \\frac{a}{b}","explanationSv":"Där a är motstående katet, b närliggande katet och c hypotenusa.","variables":[{"symbol":"v","meaningSv":"Spetsig vinkel","unit":"°"}]}]', '[{"gradeLevel":"E","titleSv":"Beräkna sida med sinus","givenSv":"Hypotenusa 10 cm, vinkel 30°","findSv":"Motstående katet a","methodSv":"a = c · sin 30°.","stepsSv":["a = 10 · 0,5 = 5,0 cm."],"answerSv":"Kateten är 5,0 cm."},{"gradeLevel":"C","titleSv":"Likformiga trianglar","givenSv":"En liten triangel med basen 4 cm och höjden 3 cm är likformig med en triangel med basen 12 cm.","findSv":"Den stora triangelns höjd","methodSv":"Skalfaktorn är 12 / 4 = 3.","stepsSv":["Höjden = 3 · 3 = 9 cm."],"answerSv":"Höjden är 9 cm."},{"gradeLevel":"A","titleSv":"Vinkelsumma i triangel","givenSv":"Parallell linje genom triangelns topp","findSv":"Visa varför vinkelsumman är 180°","methodSv":"Använd alternatvinklar.","stepsSv":["Alternatvinklar vid den parallella linjen bildar tillsammans ett rakt streck på 180°."],"answerSv":"De tre inre vinklarna har alltid summan 180°."}]', '[{"trapTitleSv":"Förväxla motstående och närliggande katet","wrongApproachSv":"Att använda samma katet som närliggande oavsett vilken spetsig vinkel man tittar på.","rightApproachSv":"Markera vinkeln i figuren först och peka rakt över triangeln för att hitta motstående katet."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-1c-4-vektorer-i-planet', 'chap-matte-1c-4', 'vektorer-i-planet', 1, 'Vektorer i koordinatsystemet', '[{"term":"Vektor","definition":"Storhet med både storlek (längd) och riktning."},{"term":"Komposanter","definition":"Vektorns steg i x-led och y-led, skrivet (x, y)."}]', '[{"heading":"Addition och längd av vektorer","bodySv":"Två vektorer u = (x₁, y₁) och v = (x₂, y₂) adderas komponentvis: u + v = (x₁ + x₂, y₁ + y₂). Vektorns längd |v| beräknas med Pythagoras sats som √(x² + y²).","deepDiveSv":"Två vektorer är lika om de har samma längd och samma riktning, oavsett var i planet de är ritade."}]', '[{"nameSv":"Längden av en vektor","latex":"|\\vec{v}| = \\sqrt{x^2 + y^2}","explanationSv":"Följer direkt ur Pythagoras sats.","variables":[{"symbol":"x, y","meaningSv":"Vektorns koordinater","unit":"längdenhet"}]}]', '[{"gradeLevel":"E","titleSv":"Vektoraddition","givenSv":"u = (3, −1) och v = (2, 5)","findSv":"Summan u + v","methodSv":"Addera x-koordinater och y-koordinater var för sig.","stepsSv":["u + v = (3 + 2, −1 + 5) = (5, 4)."],"answerSv":"(5, 4)."},{"gradeLevel":"C","titleSv":"Längden av en vektor","givenSv":"v = (6, −8)","findSv":"|v|","methodSv":"Beräkna √(6² + (−8)²).","stepsSv":["|v| = √(36 + 64) = √100 = 10."],"answerSv":"Vektorns längd är 10 l.e."},{"gradeLevel":"A","titleSv":"Vektor mellan två punkter","givenSv":"A = (2, 3) och B = (8, 11)","findSv":"Längden av vektorn AB","methodSv":"AB = (x_B − x_A, y_B − y_A).","stepsSv":["AB = (6, 8) ger |AB| = √(36 + 64) = 10."],"answerSv":"Längden av AB är 10 l.e."}]', '[{"trapTitleSv":"Glömma parentes runt negativ koordinat vid kvadrering","wrongApproachSv":"Att skriva −8² = −64 under rottecknet.","rightApproachSv":"(−8)² = +64; en vektors komponenter ger alltid icke-negativa kvadrater."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2a-1-grafisk-losning', 'chap-matte-2a-1', 'grafisk-losning', 1, 'Grafisk lösning och antal lösningar', '[{"term":"Ekvationssystem","definition":"Två eller flera ekvationer som ska uppfyllas samtidigt av samma variabler."},{"term":"Skärningspunkt","definition":"Den gemensamma punkt (x, y) där två linjer möts."}]', '[{"heading":"Ett, noll eller oändligt många svar","bodySv":"Varje linjär ekvation med två variabler beskriver en rät linje i koordinatsystemet. När två linjer skär varandra i en punkt har systemet exakt en lösning. Om linjerna har samma lutning k men olika m-värde är de parallella och saknar lösning. Sammanfaller båda linjerna helt finns oändligt många lösningar.","deepDiveSv":"Grafisk lösning ger god översikt, men för exakta bråksvar eller stora tal krävs algebraiska metoder.","svgDiagram":"<svg viewBox=\"0 0 320 140\" width=\"100%\" aria-label=\"Två räta linjer som skär varandra i en entydig lösning\">\n  <line x1=\"30\" y1=\"115\" x2=\"290\" y2=\"115\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"55\" y1=\"15\" x2=\"55\" y2=\"128\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"40\" y1=\"108\" x2=\"260\" y2=\"26\" stroke=\"var(--accent)\" stroke-width=\"1.5\" />\n  <line x1=\"70\" y1=\"22\" x2=\"245\" y2=\"112\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <circle cx=\"152\" cy=\"66\" r=\"4\" fill=\"var(--accent)\" />\n  <text x=\"162\" y=\"61\" font-size=\"11\" fill=\"var(--accent)\">Skärningspunkt (x, y)</text>\n</svg>"}]', '[{"nameSv":"Jämförelse av k-form","latex":"\\begin{cases} y = k_1 x + m_1 \\\\ y = k_2 x + m_2 \\end{cases}","explanationSv":"Olika k-värden garanterar att linjerna skär varandra i exakt en punkt.","variables":[{"symbol":"k_1, k_2","meaningSv":"Lutningar","unit":"Tal"},{"symbol":"m_1, m_2","meaningSv":"Skärningar med y-axeln","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Två ekvationer på k-form","givenSv":"y = 2x + 1 och y = x + 4","findSv":"Lösningen (x, y)","methodSv":"Sätt högerleden lika eftersom båda är lika med y.","stepsSv":["2x + 1 = x + 4 ger x = 3.","y = 3 + 4 = 7."],"answerSv":"x = 3, y = 7."},{"gradeLevel":"C","titleSv":"Avgöra antal lösningar utan att rita","givenSv":"2x + y = 5 och 4x + 2y = 14","findSv":"Hur många lösningar systemet har","methodSv":"Skriv om båda till y = kx + m.","stepsSv":["Första linjen: y = −2x + 5.","Andra linjen: y = −2x + 7.","Samma lutning k = −2 men olika m-värden (5 ≠ 7) betyder parallella linjer."],"answerSv":"Systemet saknar lösning."},{"gradeLevel":"A","titleSv":"Bestämma okänt k-värde för utebliven skärning","givenSv":"y = kx + 3 och 6x − 2y = 8","findSv":"Vilket värde på k som gör att systemet saknar lösning","methodSv":"Lös ut y i den andra ekvationen och matcha lutningen.","stepsSv":["−2y = −6x + 8 ger y = 3x − 4.","För parallellitet krävs k = 3 (och m-värdena 3 ≠ −4 stämmer)."],"answerSv":"k = 3."}]', '[{"trapTitleSv":"Glömma ange båda koordinaterna x och y","wrongApproachSv":"Att stanna när man hittat x = 3.","rightApproachSv":"Ett system i två variabler kräver alltid både x och y i svaret."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2a-1-substitutionsmetoden', 'chap-matte-2a-1', 'substitutionsmetoden', 2, 'Substitutionsmetoden', '[{"term":"Substitution","definition":"Att lösa ut en variabel ur den ena ekvationen och ersätta den i den andra."}]', '[{"heading":"Stegvis utbyte av variabel","bodySv":"Substitutionsmetoden är särskilt smidig när en variabel redan står ensam eller har koefficienten 1. Du löser ut den variabeln och sätter in uttrycket (inom parentes) i den andra ekvationen så att bara en obekant återstår.","deepDiveSv":"Kontrollera alltid lösningen genom insättning i båda originalekvationerna."}]', '[{"nameSv":"Substitutionsprincipen","latex":"y = f(x) \\implies ax + b \\cdot f(x) = c","explanationSv":"Minskar antalet variabler från två till en.","variables":[{"symbol":"x, y","meaningSv":"Okända variabler","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"En variabel redan utlöst","givenSv":"y = 3x och 2x + y = 25","findSv":"(x, y)","methodSv":"Ersätt y med 3x i den andra ekvationen.","stepsSv":["2x + 3x = 25 ger 5x = 25 och x = 5.","y = 3 · 5 = 15."],"answerSv":"x = 5, y = 15."},{"gradeLevel":"C","titleSv":"Textuppgift om biljettpriser","givenSv":"2v + 3b = 460 och v + b = 190","findSv":"Pris för vuxenbiljett v och barnbiljett b","methodSv":"Lös ut b = 190 − v och sätt in i den första ekvationen.","stepsSv":["2v + 3(190 − v) = 460.","2v + 570 − 3v = 460 ger −v = −110 och v = 110 kr.","b = 190 − 110 = 80 kr."],"answerSv":"En vuxenbiljett kostar 110 kr och en barnbiljett 80 kr."},{"gradeLevel":"A","titleSv":"Blandningsproblem i procent","givenSv":"Två saftkoncentrat (10 % och 40 % socker) blandas till 6,0 liter med 20 % sockerhalt.","findSv":"Volymerna x och y av varje sort","methodSv":"Ställ upp en ekvation för totalvolym och en för sockermängd.","stepsSv":["x + y = 6 och 0,10x + 0,40y = 0,20 · 6 = 1,2.","x = 6 − y ger 0,10(6 − y) + 0,40y = 1,2, alltså 0,30y = 0,6 och y = 2,0 liter.","x = 4,0 liter."],"answerSv":"4,0 liter av 10 %-sorten och 2,0 liter av 40 %-sorten."}]', '[{"trapTitleSv":"Sätta in uttrycket i samma ekvation som det kom ifrån","wrongApproachSv":"Att lösa ut y ur ekvation 1 och sätta tillbaka i ekvation 1, vilket ger 0 = 0.","rightApproachSv":"Sätt alltid in det utlösta uttrycket i den andra ekvationen."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2a-1-additionsmetoden', 'chap-matte-2a-1', 'additionsmetoden', 3, 'Additionsmetoden', '[{"term":"Additionsmetoden","definition":"Att addera eller subtrahera två ekvationer ledvis så att en variabel försvinner."}]', '[{"heading":"Eliminera en variabel direkt","bodySv":"Additionsmetoden passar bäst när variablerna står rakt under varandra på formen ax + by = c. Genom att multiplicera en eller båda ekvationerna så att en variabel får motsatta koefficienter (+b och −b) tar den variabeln ut sig själv vid addition.","deepDiveSv":"Metoden minskar risken för bråkräkning tidigt i lösningen."}]', '[{"nameSv":"Ledvis addition","latex":"(a_1 x + b y) + (a_2 x - b y) = c_1 + c_2 \\implies (a_1 + a_2)x = c_1 + c_2","explanationSv":"Motsatta koefficienter eliminerar y i ett enda steg.","variables":[{"symbol":"a_1, a_2, b","meaningSv":"Koefficienter","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Direkt elimination","givenSv":"x + y = 10 och x − y = 4","findSv":"x och y","methodSv":"Addera ekvationerna rakt ner.","stepsSv":["2x = 14 ger x = 7.","7 + y = 10 ger y = 3."],"answerSv":"x = 7, y = 3."},{"gradeLevel":"C","titleSv":"Multiplicera en ekvation före addition","givenSv":"3x + y = 11 och 2x + y = 8","findSv":"x och y","methodSv":"Multiplicera den andra ekvationen med −1 och addera.","stepsSv":["3x + y = 11 plus −2x − y = −8 ger x = 3.","2(3) + y = 8 ger y = 2."],"answerSv":"x = 3, y = 2."},{"gradeLevel":"A","titleSv":"Skala båda ekvationerna","givenSv":"3x + 2y = 19 och 5x − 3y = 19","findSv":"x och y","methodSv":"Skala så y-termerna blir +6y och −6y.","stepsSv":["Första · 3: 9x + 6y = 57. Andra · 2: 10x − 6y = 38.","Addera: 19x = 95 ger x = 5.","3(5) + 2y = 19 ger 2y = 4 och y = 2."],"answerSv":"x = 5, y = 2."}]', '[{"trapTitleSv":"Glömma multiplicera högerledet vid skalning","wrongApproachSv":"Att bara multiplicera vänsterledet med −1 eller 2.","rightApproachSv":"Varje term i både vänster- och högerledet måste multipliceras med samma tal."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2a-2-pq-formeln-och-nollproduct', 'chap-matte-2a-2', 'pq-formeln-och-nollproduct', 1, 'Nollproduktmetoden och pq-formeln', '[{"term":"Andragradsekvation","definition":"Ekvation där den högsta exponenten på x är 2."},{"term":"Nollproduktmetoden","definition":"Om a · b = 0 måste antingen a = 0 eller b = 0."}]', '[{"heading":"Lösa andragradsekvationer i standardform","bodySv":"Innan pq-formeln kan användas måste koefficienten framför x² vara 1 och högerledet vara 0: x² + px + q = 0. Därefter ges rötterna av x = −p/2 ± √((p/2)² − q).","deepDiveSv":"Saknas konstantterm (x² + px = 0) är faktorisering x(x + p) = 0 snabbare och säkrare än pq-formeln."}]', '[{"nameSv":"pq-formeln","latex":"x^2 + px + q = 0 \\implies x = -\\frac{p}{2} \\pm \\sqrt{\\left(\\frac{p}{2}\\right)^2 - q}","explanationSv":"Kräver att x² står ensamt med koefficienten 1.","variables":[{"symbol":"p, q","meaningSv":"Koefficienter i normalform","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Faktorisering utan konstantterm","givenSv":"x² − 7x = 0","findSv":"Rötterna","methodSv":"Bryt ut x.","stepsSv":["x(x − 7) = 0 ger x₁ = 0 och x₂ = 7."],"answerSv":"x₁ = 0, x₂ = 7."},{"gradeLevel":"C","titleSv":"pq-formeln efter division","givenSv":"2x² − 12x + 16 = 0","findSv":"Rötterna","methodSv":"Dividera med 2 så x² blir fritt.","stepsSv":["x² − 6x + 8 = 0 ger x = 3 ± √(9 − 8) = 3 ± 1."],"answerSv":"x₁ = 2, x₂ = 4."},{"gradeLevel":"A","titleSv":"Kastparabel och maxhöjd","givenSv":"h(t) = 12t − 5t²","findSv":"När höjden är störst och vilken maxhöjden är","methodSv":"Hitta nollställena och ta medelvärdet för symmetrilinjen.","stepsSv":["t(12 − 5t) = 0 ger t₁ = 0 och t₂ = 2,4 s. Symmetri vid t = 1,2 s ger h_max = 12(1,2) − 5(1,44) = 7,2 m."],"answerSv":"Maxhöjden 7,2 m nås efter 1,2 s."}]', '[{"trapTitleSv":"Glömma dividera bort koefficienten framför x²","wrongApproachSv":"Att läsa av p = −12 i 2x² − 12x + 16 = 0.","rightApproachSv":"Dividera alla termer med 2 först så att x²-termen har koefficienten 1."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2a-3-tiologaritmer', 'chap-matte-2a-3', 'tiologaritmer', 1, 'Tiologaritmer och logaritmlagar', '[{"term":"Tiologaritm (lg x)","definition":"Den exponent som 10 måste upphöjas till för att ge x."}]', '[{"heading":"Lösa ut obekant i exponenten","bodySv":"För varje positivt tal x gäller x = 10^(lg x). Med logaritmlagen lg(a^x) = x · lg a kan exponenter flyttas ner framför logaritmen så att exponentialekvationer löses exakt.","deepDiveSv":"Logaritmer är endast definierade för strikt positiva tal (x > 0)."}]', '[{"nameSv":"Logaritmlagen för potens","latex":"\\lg(a^x) = x \\cdot \\lg a","explanationSv":"Flyttar ner en obekant exponent till en vanlig faktor.","variables":[{"symbol":"a","meaningSv":"Positiv bas","unit":"Tal > 0"},{"symbol":"x","meaningSv":"Exponent","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Enkel tiologaritm","givenSv":"lg x = 3","findSv":"x","methodSv":"Skriv om i potensform: x = 10³.","stepsSv":["x = 10³ = 1 000."],"answerSv":"x = 1 000."},{"gradeLevel":"C","titleSv":"Exponentialekvation","givenSv":"2^x = 16","findSv":"x","methodSv":"Logaritmera båda sidor eller jämför med 2⁴.","stepsSv":["x = lg 16 / lg 2 = 4."],"answerSv":"x = 4."},{"gradeLevel":"A","titleSv":"Fördubblingstid vid 8 % tillväxt","givenSv":"1,08^t = 2","findSv":"t med en decimal","methodSv":"t · lg 1,08 = lg 2.","stepsSv":["t = lg 2 / lg 1,08 ≈ 9,0 år."],"answerSv":"Fördubblingstiden är 9,0 år."}]', '[{"trapTitleSv":"Dela 2 med 1,08 innan logaritmen","wrongApproachSv":"Att skriva t = lg(2 / 1,08).","rightApproachSv":"Det är en kvot av två logaritmer: t = (lg 2) / (lg 1,08)."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2a-4-standardavvikelse', 'chap-matte-2a-4', 'standardavvikelse', 1, 'Standardavvikelse och normalfördelning', '[{"term":"Standardavvikelse (s)","definition":"Mått på hur mycket värdena i genomsnitt avviker från medelvärdet."}]', '[{"heading":"Tumregler i normalfördelningen","bodySv":"I en normalfördelad datamängd är fördelningen symmetrisk kring medelvärdet. Cirka 68 % av alla värden ligger inom ±1 standardavvikelse från medelvärdet och cirka 95 % inom ±2 standardavvikelser.","deepDiveSv":"Tack vare symmetrin ligger exakt 50 % över medelvärdet och 50 % under medelvärdet."}]', '[{"nameSv":"68-95-regeln","latex":"P(\\mu - \\sigma \\le X \\le \\mu + \\sigma) \\approx 0{,}68","explanationSv":"Ungefär 68 % ryms inom en standardavvikelse kring medelvärdet μ.","variables":[{"symbol":"\\mu","meaningSv":"Medelvärde","unit":"Datans enhet"},{"symbol":"\\sigma","meaningSv":"Standardavvikelse","unit":"Datans enhet"}]}]', '[{"gradeLevel":"E","titleSv":"Andel inom en standardavvikelse","givenSv":"Medelvärde 175 cm, standardavvikelse 6 cm (normalfördelat)","findSv":"Andelen mellan 169 cm och 181 cm","methodSv":"169 = 175 − 6 och 181 = 175 + 6.","stepsSv":["Intervallet är ±1 standardavvikelse, vilket rymmer cirka 68 %."],"answerSv":"Cirka 68 %."},{"gradeLevel":"C","titleSv":"Andel i ena svansen","givenSv":"μ = 500 g, σ = 20 g","findSv":"Andelen som väger över 520 g","methodSv":"Utanför ±1σ finns 32 %, hälften över och hälften under.","stepsSv":["(100 % − 68 %) / 2 = 16 %."],"answerSv":"Cirka 16 %."},{"gradeLevel":"A","titleSv":"Kombinera intervall i normalfördelning","givenSv":"μ = 100, σ = 15","findSv":"Andelen mellan 85 och 130","methodSv":"Summera vänstra halvan (34 %) och högra delen upp till +2σ (47,5 %).","stepsSv":["34 % + 47,5 % = 81,5 %."],"answerSv":"Cirka 81,5 %."}]', '[{"trapTitleSv":"Glömma halvera resten vid ensidig svans","wrongApproachSv":"Att svara 32 % över μ + σ.","rightApproachSv":"De 32 % delas lika mellan den övre och den undre svansen: 16 % på varje sida."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2b-1-linjara-ekvationssystem', 'chap-matte-2b-1', 'linjara-ekvationssystem', 1, 'Linjära ekvationssystem med två obekanta', '[{"term":"Substitutionsmetoden","definition":"Att lösa ut en variabel och sätta in i den andra ekvationen."},{"term":"Additionsmetoden","definition":"Att eliminera en variabel genom att addera skalade ekvationer."}]', '[{"heading":"Välja smidigaste lösningsmetod","bodySv":"Ett linjärt ekvationssystem kan lösas med substitution när en variabel är lätt att lösa ut, eller med addition när koefficienterna framför x eller y enkelt kan göras lika stora med motsatta tecken.","deepDiveSv":"Ekonomiska brytpunkter och utbuds-/efterfrågemodeller leder ofta till linjära system där skärningspunkten visar jämviktspris och jämviktskvantitet."}]', '[{"nameSv":"Allmänt linjärt system","latex":"\\begin{cases} a_1 x + b_1 y = c_1 \\\\ a_2 x + b_2 y = c_2 \\end{cases}","explanationSv":"System i två variabler med tre möjliga utfall: en, noll eller oändligt många lösningar.","variables":[{"symbol":"x, y","meaningSv":"Okända variabler","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Lösning med additionsmetoden","givenSv":"x + 2y = 14 och x − 2y = 2","findSv":"x och y","methodSv":"Addera ekvationerna direkt.","stepsSv":["2x = 16 ger x = 8.","8 + 2y = 14 ger y = 3."],"answerSv":"x = 8, y = 3."},{"gradeLevel":"C","titleSv":"Skalning före addition","givenSv":"2x + 3y = 19 och 4x − 3y = 11","findSv":"x och y","methodSv":"Addera direkt eftersom +3y och −3y tar ut varandra.","stepsSv":["6x = 30 ger x = 5.","2(5) + 3y = 19 ger 3y = 9 och y = 3."],"answerSv":"x = 5, y = 3."},{"gradeLevel":"A","titleSv":"Jämviktspris mellan utbud och efterfrågan","givenSv":"Efterfrågan: p = 500 − 2q. Utbud: p = 100 + 3q.","findSv":"Jämviktskvantitet q och jämviktspris p","methodSv":"Sätt p lika och lös ut q.","stepsSv":["500 − 2q = 100 + 3q ger 400 = 5q, alltså q = 80.","p = 100 + 3(80) = 340 kr."],"answerSv":"Jämviktspriset är 340 kr vid kvantiteten 80 enheter."}]', '[{"trapTitleSv":"Sluta efter att x har beräknats","wrongApproachSv":"Att endast skriva x = 5 som slutsvar.","rightApproachSv":"Sätt alltid in x i en av ekvationerna för att även ange y."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2b-1-kvadreringsregler-och-faktorisering', 'chap-matte-2b-1', 'kvadreringsregler-och-faktorisering', 2, 'Kvadreringsreglerna, konjugatregeln och faktorisering', '[{"term":"Första kvadreringsregeln","definition":"(a + b)² = a² + 2ab + b²."},{"term":"Andra kvadreringsregeln","definition":"(a − b)² = a² − 2ab + b²."},{"term":"Konjugatregeln","definition":"(a + b)(a − b) = a² − b²."}]', '[{"heading":"Utveckla och faktorisera snabbare","bodySv":"Kvadreringsreglerna och konjugatregeln sparar tid både när parenteser ska utvecklas och när andragradsuttryck ska faktoriseras baklänges. Den vanligaste fällan är att glömma den dubbla produkten 2ab i mitten av en kvadrerad parentes.","deepDiveSv":"Konjugatregeln baklänges gör det enkelt att lösa ekvationer som x² − 64 = (x + 8)(x − 8) = 0 och att förenkla bråk med kvadratuttryck."}]', '[{"nameSv":"Kvadreringsreglerna och konjugatregeln","latex":"(a \\pm b)^2 = a^2 \\pm 2ab + b^2, \\quad (a + b)(a - b) = a^2 - b^2","explanationSv":"De tre viktigaste omskrivningsreglerna i gymnasiets algebra.","variables":[{"symbol":"a, b","meaningSv":"Termer","unit":"Tal eller variabler"}]}]', '[{"gradeLevel":"E","titleSv":"Utveckla en kvadrat","givenSv":"(x + 5)²","findSv":"Utvecklat uttryck","methodSv":"Tillämpa första kvadreringsregeln med a = x och b = 5.","stepsSv":["x² + 2 · x · 5 + 5² = x² + 10x + 25."],"answerSv":"x² + 10x + 25."},{"gradeLevel":"C","titleSv":"Kombinera konjugatregeln med förenkling","givenSv":"(x + 3)(x − 3) − x²","findSv":"Förenklat värde","methodSv":"Utveckla med konjugatregeln först.","stepsSv":["(x² − 9) − x² = −9."],"answerSv":"−9."},{"gradeLevel":"A","titleSv":"Förenkla rationellt uttryck","givenSv":"(x² − 25) / (x² + 10x + 25) för x ≠ −5","findSv":"Förkortat uttryck","methodSv":"Faktorisera täljaren med konjugatregeln och nämnaren med första kvadreringsregeln.","stepsSv":["((x + 5)(x − 5)) / (x + 5)² = (x − 5) / (x + 5)."],"answerSv":"(x − 5) / (x + 5)."}]', '[{"trapTitleSv":"Glömma mellantermen 2ab","wrongApproachSv":"Att skriva (x + 5)² = x² + 25.","rightApproachSv":"(x + 5)² = (x + 5)(x + 5) = x² + 10x + 25."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2b-1-pq-formeln', 'chap-matte-2b-1', 'pq-formeln', 3, 'Andragradsekvationer och pq-formeln', '[{"term":"Diskriminant","definition":"Uttrycket (p/2)² − q under rottecknet som avgör antalet reella rötter."},{"term":"Dubbelrot","definition":"Uppstår när diskriminanten är exakt 0 så att ekvationen får en enda reell lösning."}]', '[{"heading":"Antalet lösningar via diskriminanten","bodySv":"När en andragradsekvation skrivits på normalformen x² + px + q = 0 avgör tecknet på uttrycket under rottecknet i pq-formeln hur många reella lösningar som finns. Är det positivt finns två lösningar, är det noll finns en lösning (dubbelrot) och är det negativt saknas reella lösningar.","deepDiveSv":"pq-formeln härleds genom kvadratkomplettering: (x + p/2)² = (p/2)² − q."}]', '[{"nameSv":"pq-formeln","latex":"x = -\\frac{p}{2} \\pm \\sqrt{\\left(\\frac{p}{2}\\right)^2 - q}","explanationSv":"Löser ekvationen x² + px + q = 0.","variables":[{"symbol":"p","meaningSv":"Koefficient framför x","unit":"Tal"},{"symbol":"q","meaningSv":"Konstantterm","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Rötter ur x² − 64 = 0","givenSv":"x² − 64 = 0","findSv":"Båda lösningarna","methodSv":"Flytta över 64 och ta roten ur (glöm inte ±).","stepsSv":["x² = 64 ger x = ±8."],"answerSv":"x₁ = 8 och x₂ = −8."},{"gradeLevel":"C","titleSv":"Lösning med pq-formeln","givenSv":"2x² − 12x + 16 = 0","findSv":"Samtliga rötter","methodSv":"Dividera med 2 och använd pq-formeln med p = −6, q = 8.","stepsSv":["x² − 6x + 8 = 0 ger x = 3 ± √(9 − 8) = 3 ± 1."],"answerSv":"x₁ = 2 och x₂ = 4."},{"gradeLevel":"A","titleSv":"Bestämma parameter för dubbelrot","givenSv":"x² + ax + 9 = 0 ska ha exakt en lösning.","findSv":"Möjliga värden på a","methodSv":"Sätt diskriminanten (a/2)² − 9 = 0.","stepsSv":["(a/2)² = 9 ger a/2 = ±3, alltså a = 6 eller a = −6."],"answerSv":"a = 6 eller a = −6."}]', '[{"trapTitleSv":"Glömma minus framför roten vid x² = 64","wrongApproachSv":"Att bara svara x = 8.","rightApproachSv":"Både (+8)² och (−8)² blir 64, så ekvationen har två rötter: ±8."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2b-2-symmetrilinje-och-vertex', 'chap-matte-2b-2', 'symmetrilinje-och-vertex', 1, 'Symmetrilinje och extrempunkt', '[{"term":"Symmetrilinje","definition":"Den lodräta linjen x = −p/2 (eller mitt emellan nollställena) som delar parabeln i två spegelhalvor."},{"term":"Vertex","definition":"Parabelns högsta eller lägsta punkt."}]', '[{"heading":"Minimipunkt eller maximipunkt","bodySv":"För f(x) = ax² + bx + c avgör tecknet på a åt vilket håll parabeln öppnar sig. Är a > 0 har grafen en minimipunkt (glad mun) och är a < 0 har den en maximipunkt (ledsen mun). Symmetrilinjen ligger alltid vid x = −b / (2a).","deepDiveSv":"Vid optimering räknar man först ut x-koordinaten för symmetrilinjen och sätter sedan in den i f(x) för att få max- eller minvärdet."}]', '[{"nameSv":"Symmetrilinjens x-värde","latex":"x_{\\text{sym}} = -\\frac{b}{2a} = \\frac{x_1 + x_2}{2}","explanationSv":"Ligger alltid mitt emellan eventuella nollställen x₁ och x₂.","variables":[{"symbol":"a, b","meaningSv":"Koefficienter i ax² + bx + c","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Hitta symmetrilinjen","givenSv":"f(x) = x² − 6x + 5","findSv":"Symmetrilinjens ekvation","methodSv":"x = −b / (2a).","stepsSv":["x = −(−6) / (2 · 1) = 3."],"answerSv":"Symmetrilinjen är x = 3."},{"gradeLevel":"C","titleSv":"Minimivärde","givenSv":"f(x) = x² − 6x + 5","findSv":"Funktionens minsta värde","methodSv":"Sätt in x = 3 i f(x).","stepsSv":["f(3) = 3² − 6 · 3 + 5 = 9 − 18 + 5 = −4."],"answerSv":"Minsta värdet är −4."},{"gradeLevel":"A","titleSv":"Maximera biljettintäkt","givenSv":"En konsert säljer (200 − 2p) biljetter vid priset p kr. Intäkten är I(p) = p(200 − 2p).","findSv":"Vilket pris som ger maximal intäkt","methodSv":"Ta medelvärdet av nollställena p = 0 och p = 100.","stepsSv":["Symmetri vid p = 50 kr ger I_max = 50 · 100 = 5 000 kr."],"answerSv":"Maximal intäkt på 5 000 kr nås vid biljettpriset 50 kr."}]', '[{"trapTitleSv":"Svara med x-värdet när frågan gäller största eller minsta värde","wrongApproachSv":"Att svara x = 3 i stället för f(3) = −4.","rightApproachSv":"Funktionsvärde betyder alltid y-värdet i vertex."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2b-3-logaritmlagar', 'chap-matte-2b-3', 'logaritmlagar', 1, 'Logaritmlagar och exponentialekvationer', '[{"term":"Logaritmlag för produkt","definition":"lg(a · b) = lg a + lg b för a, b > 0."},{"term":"Logaritmlag för kvot","definition":"lg(a / b) = lg a − lg b för a, b > 0."}]', '[{"heading":"Lösa ekonomiska och naturvetenskapliga ekvationer med lg","bodySv":"Med hjälp av tiologaritmen kan vi besvara frågor som \"hur lång tid tar det innan kapitalet fördubblas?\" eller \"när har värdet halverats?\". Först isoleras potensuttrycket a^x i ena ledet, därefter logaritmeras båda leden.","deepDiveSv":"Kom ihåg att alltid skilja mellan potensekvationer (x^n = c, där basen är okänd och löses med rot/upphöjt till 1/n) och exponentialekvationer (a^x = c, där exponenten är okänd och löses med logaritmer)."}]', '[{"nameSv":"Logaritmens räknelagar","latex":"\\lg(ab) = \\lg a + \\lg b, \\quad \\lg\\left(\\frac{a}{b}\\right) = \\lg a - \\lg b, \\quad \\lg(a^p) = p\\lg a","explanationSv":"Gäller för alla positiva reella tal a och b.","variables":[{"symbol":"a, b","meaningSv":"Positiva tal","unit":"> 0"}]}]', '[{"gradeLevel":"E","titleSv":"Förenkla logaritmuttryck","givenSv":"lg 4 + lg 25","findSv":"Exakt värde","methodSv":"lg 4 + lg 25 = lg(4 · 25).","stepsSv":["lg(100) = 2."],"answerSv":"2."},{"gradeLevel":"C","titleSv":"Potens- kontra exponentialekvation","givenSv":"3 · x⁴ = 48","findSv":"Positiv rot x","methodSv":"Detta är en potensekvation — dividera med 3 och ta fjärderoten.","stepsSv":["x⁴ = 16 ger x = 16^(1/4) = 2."],"answerSv":"x = 2 (för x > 0)."},{"gradeLevel":"A","titleSv":"Förenkla logaritmkvot","givenSv":"lg(x³) − lg(x)","findSv":"Enklare form för x > 0","methodSv":"Använd kvotlagen lg(x³ / x).","stepsSv":["lg(x²) = 2 · lg x."],"answerSv":"2 lg x."}]', '[{"trapTitleSv":"Förväxla lg(a + b) med lg a + lg b","wrongApproachSv":"Att skriva lg(10 + 90) = lg 10 + lg 90.","rightApproachSv":"Summan av logaritmer motsvarar produkten av argumenten, inte summan."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2b-4-regression-och-korrelation', 'chap-matte-2b-4', 'regression-och-korrelation', 1, 'Linjär regression och residualer', '[{"term":"Regression","definition":"Metod för att hitta den funktion som bäst ansluter till en punktmängd."},{"term":"Korrelationskoefficient (r)","definition":"Tal mellan −1 och +1 som mäter hur starkt ett linjärt samband är."}]', '[{"heading":"Tolka korrelation och extrapolering","bodySv":"Ett r-värde nära +1 visar stark positiv linjär samvariation och nära −1 stark negativ samvariation. Att läsa av värden inom det uppmätta intervallet kallas interpolering, medan extrapolering (att gissa långt utanför mätområdet) ofta medför stor osäkerhet.","deepDiveSv":"Minsta kvadratmetoden minimerar summan av de kvadrerade lodräta avstånden (residualerna) från datapunkterna till linjen."}]', '[{"nameSv":"Korrelationskoefficientens intervall","latex":"-1 \\le r \\le 1","explanationSv":"Ju närmare |r| är 1, desto tätare följer punkterna en rät linje.","variables":[{"symbol":"r","meaningSv":"Korrelationskoefficient","unit":"Enhetslös"}]}]', '[{"gradeLevel":"E","titleSv":"Tolka tecken och styrka på r","givenSv":"r = −0,94","findSv":"Vad säger detta om sambandet?","methodSv":"Tecknet ger riktningen och beloppet ger styrkan.","stepsSv":["Negativt tecken betyder avtagande samband; 0,94 nära 1 betyder mycket starkt linjärt samband."],"answerSv":"Starkt negativt linjärt samband."},{"gradeLevel":"C","titleSv":"Interpolering i regressionslinje","givenSv":"y = 4,5x + 120 anpassad för x mellan 10 och 50","findSv":"Uppskattat värde vid x = 20","methodSv":"Sätt in x = 20 (ligger inom intervallet).","stepsSv":["y = 4,5 · 20 + 120 = 210."],"answerSv":"210."},{"gradeLevel":"A","titleSv":"Risk med extrapolering","givenSv":"En barnlängdsmodell y = 6x + 50 för ålder 0–10 år används vid x = 50 år.","findSv":"Varför blir resultatet 350 cm orimligt?","methodSv":"Pröva modellens giltighetsområde.","stepsSv":["Linjär tillväxt upphör i tonåren, så extrapolering långt utanför 0–10 år bryter mot verkliga villkor."],"answerSv":"Modellen gäller bara i barnaåren; extrapolering ger orealistisk längd."}]', '[{"trapTitleSv":"Tro att r = 0 betyder att inget samband alls finns","wrongApproachSv":"Att avfärda alla samband när r ≈ 0.","rightApproachSv":"r mäter enbart linjära samband; en parabel eller periodisk kurva kan ha starkt samband trots r ≈ 0."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2c-1-ekvationssystem-och-parametrar', 'chap-matte-2c-1', 'ekvationssystem-och-parametrar', 1, 'Ekvationssystem, parametrar och räta linjens skärningar', '[{"term":"Parameter","definition":"Konstant (t.ex. k eller a) som avgör antalet lösningar i ett ekvationssystem."},{"term":"Vinkelräta linjer","definition":"Linjer vars riktningskoefficienter uppfyller k₁ · k₂ = −1."}]', '[{"heading":"Villkor för entydig, ingen eller oändlig lösning","bodySv":"Genom att skriva båda ekvationerna i ett system på k-form ser man omedelbart hur linjerna förhåller sig till varandra. Vid k₁ ≠ k₂ finns alltid exakt en lösning. Om k₁ = k₂ avgör m-värdena om linjerna är parallella utan lösning (m₁ ≠ m₂) eller helt sammanfallande med oändligt många lösningar (m₁ = m₂).","deepDiveSv":"För vinkelräta linjer i koordinatsystemet är produkten av deras lutningar −1, alltså k₂ = −1 / k₁."}]', '[{"nameSv":"Villkor för vinkelräta linjer","latex":"k_1 \\cdot k_2 = -1","explanationSv":"Gäller för två räta linjer som skär varandra under 90° (om ingen är lodrät).","variables":[{"symbol":"k_1, k_2","meaningSv":"Riktningskoefficienter","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Vinkelrät linje genom given punkt","givenSv":"Linje 1: y = 2x + 3. Linje 2 är vinkelrät mot Linje 1 och går genom (4, 1).","findSv":"Linje 2:s ekvation","methodSv":"Bestäm k₂ = −1 / 2 = −0,5 och sätt in (4, 1).","stepsSv":["1 = −0,5 · 4 + m ger 1 = −2 + m och m = 3."],"answerSv":"y = −0,5x + 3."},{"gradeLevel":"C","titleSv":"Oändligt många lösningar via parameter","givenSv":"ax + 2y = 6 och 6x + 4y = 12","findSv":"Värdet på a som ger oändligt många lösningar","methodSv":"Multiplicera första ekvationen med 2 och jämför termerna.","stepsSv":["2ax + 4y = 12 ska vara identisk med 6x + 4y = 12, alltså 2a = 6 och a = 3."],"answerSv":"a = 3."},{"gradeLevel":"A","titleSv":"Skärning mellan linje och parabel","givenSv":"y = kx + 1 och y = x² + 5","findSv":"För vilka k som graferna inte skär varandra","methodSv":"Sätt uttrycken lika och kräv negativ diskriminant.","stepsSv":["x² + 5 = kx + 1 ger x² − kx + 4 = 0.","Diskriminanten (k/2)² − 4 < 0 ger k² < 16, alltså −4 < k < 4."],"answerSv":"För −4 < k < 4 skär graferna aldrig varandra."}]', '[{"trapTitleSv":"Glömma kontrollera om rötterna i en k² < 16-olikhet bildar ett inre intervall","wrongApproachSv":"Att skriva k < 4 utan den undre gränsen k > −4.","rightApproachSv":"Teckna en skiss av parabeln k² − 16 < 0: den är negativ mellan −4 och +4."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2c-1-pq-formeln-och-diskriminant', 'chap-matte-2c-1', 'pq-formeln-och-diskriminant', 2, 'Kvadratkomplettering, diskriminant och rotekvationer', '[{"term":"Diskriminant (D)","definition":"D = (p/2)² − q avgör antalet reella rötter till x² + px + q = 0."},{"term":"Falsk rot","definition":"En lösning som dyker upp när båda led kvadreras men som inte gör ursprungsekvationen sann."}]', '[{"heading":"Rotekvationer och prövning av rötter","bodySv":"En rotekvation som √(x + 5) = x − 1 löses genom att isolera rotuttrycket i ena ledet och därefter kvadrera båda sidor. Eftersom kvadrering inte alltid är en ekvivalent operation — både a = b och a = −b ger samma kvadrat a² = b² — kan falska rötter uppstå. Därför är prövning i ursprungsekvationen alltid obligatorisk.","deepDiveSv":"Kom ihåg att symbolen √A per definition alltid avser det icke-negativa tal vars kvadrat är A (√9 = +3, aldrig −3)."}]', '[{"nameSv":"Diskriminantvillkor","latex":"D = \\left(\\frac{p}{2}\\right)^2 - q","explanationSv":"D > 0 ger två rötter, D = 0 en dubbelrot och D < 0 inga reella rötter.","variables":[{"symbol":"D","meaningSv":"Diskriminant","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Avgöra antal reella rötter","givenSv":"x² − 4x + 5 = 0","findSv":"Antalet reella lösningar","methodSv":"Beräkna diskriminanten D = (−2)² − 5.","stepsSv":["D = 4 − 5 = −1 < 0."],"answerSv":"Ekvationen har 0 reella lösningar."},{"gradeLevel":"C","titleSv":"Rotekvation med falsk rot","givenSv":"√(x + 5) = x − 1","findSv":"Samtliga giltiga rötter","methodSv":"Kvadrera båda led och pröva varje kandidat i ursprungsekvationen.","stepsSv":["x + 5 = (x − 1)² = x² − 2x + 1.","x² − 3x − 4 = 0 ger x₁ = 4 och x₂ = −1.","Prövning x = 4: VL = √9 = 3, HL = 4 − 1 = 3 (Gäller!).","Prövning x = −1: VL = √4 = 2, HL = −1 − 1 = −2 (Falsk rot!)."],"answerSv":"Den enda lösningen är x = 4."},{"gradeLevel":"A","titleSv":"Kvadratkomplettering med allmän koefficient","givenSv":"x² + 6x − 7 = 0","findSv":"Lös genom kvadratkomplettering utan pq-formeln","methodSv":"Lägg till (6/2)² = 9 på båda sidor.","stepsSv":["x² + 6x + 9 = 7 + 9 = 16.","(x + 3)² = 16 ger x + 3 = ±4.","x₁ = 1 och x₂ = −7."],"answerSv":"x₁ = 1, x₂ = −7."}]', '[{"trapTitleSv":"Glömma pröva efter kvadrering av rotekvation","wrongApproachSv":"Att godta både x = 4 och x = −1 som lösningar till √(x + 5) = x − 1.","rightApproachSv":"Pröva alltid i ursprungsekvationen före kvadreringen; här uppfyller endast x = 4 kravet HL ≥ 0."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2c-1-andragradsfunktioner-och-max-min', 'chap-matte-2c-1', 'andragradsfunktioner-och-max-min', 3, 'Andragradsfunktioner, vertexform och optimering', '[{"term":"Faktorform","definition":"f(x) = k(x − x₁)(x − x₂) när nollställena x₁ och x₂ är kända."},{"term":"Vertexform","definition":"f(x) = a(x − h)² + k där vertex direkt avläses som (h, k)."}]', '[{"heading":"Bestämma funktionsuttryck och optimera areor","bodySv":"Om en andragradsfunktion har nollställena x₁ och x₂ kan den skrivas f(x) = k(x − x₁)(x − x₂). Med en tredje punkt på grafen kan konstanten k beräknas exakt. I geometriska optimeringsproblem tecknar man arean som en funktion av en sträcka x och söker parabelns symmetrilinje.","deepDiveSv":"Observera att symmetrilinjen x = (x₁ + x₂) / 2 alltid ger x-koordinaten för extremvärdet, även om funktionen saknar reella nollställen (då via x = −b / (2a)).","svgDiagram":"<svg viewBox=\"0 0 320 150\" width=\"100%\" aria-label=\"Andragradsfunktion med nollställen, vertex och symmetrilinje\">\n  <line x1=\"25\" y1=\"100\" x2=\"295\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"160\" y1=\"14\" x2=\"160\" y2=\"140\" stroke=\"var(--accent)\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\" />\n  <path d=\"M 75 24 Q 160 220 245 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <circle cx=\"107\" cy=\"100\" r=\"3.5\" fill=\"var(--accent)\" />\n  <circle cx=\"213\" cy=\"100\" r=\"3.5\" fill=\"var(--accent)\" />\n  <circle cx=\"160\" cy=\"122\" r=\"4\" fill=\"var(--accent)\" />\n  <text x=\"90\" y=\"114\" font-size=\"11\" fill=\"currentColor\">x₁</text>\n  <text x=\"218\" y=\"114\" font-size=\"11\" fill=\"currentColor\">x₂</text>\n  <text x=\"168\" y=\"132\" font-size=\"11\" fill=\"var(--accent)\">Vertex (extrempunkt)</text>\n  <text x=\"166\" y=\"25\" font-size=\"11\" fill=\"var(--accent)\">Symmetrilinje</text>\n</svg>"}]', '[{"nameSv":"Andragradsfunktion på faktorform","latex":"f(x) = k(x - x_1)(x - x_2)","explanationSv":"Användbar när grafens skärningspunkter med x-axeln är kända.","variables":[{"symbol":"k","meaningSv":"Skalfaktor och öppningsriktning","unit":"Tal ≠ 0"},{"symbol":"x_1, x_2","meaningSv":"Nollställen","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Symmetrilinje och minimivärde","givenSv":"f(x) = x² − 8x + 12","findSv":"Vertex","methodSv":"Beräkna x_sym = −(−8) / 2 = 4 och sedan f(4).","stepsSv":["f(4) = 16 − 32 + 12 = −4."],"answerSv":"Vertex ligger i (4, −4), som är en minimipunkt."},{"gradeLevel":"C","titleSv":"Skapa funktionen från nollställen och punkt","givenSv":"Nollställen x₁ = 1 och x₂ = 7 samt f(0) = 7","findSv":"f(4)","methodSv":"Bestäm k ur f(0) = k(0 − 1)(0 − 7) = 7.","stepsSv":["7k = 7 ger k = 1, alltså f(x) = (x − 1)(x − 7).","f(4) = (4 − 1)(4 − 7) = 3 · (−3) = −9."],"answerSv":"f(4) = −9."},{"gradeLevel":"A","titleSv":"Maximal hage längs en husvägg","givenSv":"40 m staket ska bilda tre sidor av en rektangulär hage mot en husvägg.","findSv":"Maximala arean","methodSv":"Låt kortsidorna vara x; då är långsidan 40 − 2x och arean A(x) = x(40 − 2x).","stepsSv":["Nollställena är x = 0 och x = 20, så max nås vid x = 10 m.","Långsidan blir 40 − 20 = 20 m och A_max = 10 · 20 = 200 m²."],"answerSv":"Maximala arean är 200 m²."}]', '[{"trapTitleSv":"Sätta k = 1 automatiskt när bara nollställena är kända","wrongApproachSv":"Att skriva f(x) = (x − 1)(x − 7) utan att använda den tredje punkten.","rightApproachSv":"Ha alltid med faktorn k och bestäm den med hjälp av den tredje punkten på kurvan."}]', 'graph_explorer', '{"mode":"quadratic","a":1,"b":-8,"c":12}', 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2c-2-logaritmlagar-och-bevis', 'chap-matte-2c-2', 'logaritmlagar-och-bevis', 1, 'Logaritmlagar och sammansatta ekvationer', '[{"term":"Logaritmdefinition","definition":"y = lg x ⇔ 10^y = x för x > 0."}]', '[{"heading":"Härledning och förenkling","bodySv":"Eftersom 10^(lg a) = a kan produktlagen visas direkt: a · b = 10^(lg a) · 10^(lg b) = 10^(lg a + lg b), vilket ger lg(ab) = lg a + lg b.","deepDiveSv":"Logaritmekvationer som lg(x − 2) = 1 kräver kontroll av definitionsmängden x − 2 > 0."}]', '[{"nameSv":"Basomvandling","latex":"10^{\\lg x} = x \\quad (x > 0)","explanationSv":"Exponentialfunktion med bas 10 och tiologaritm är varandras inverser.","variables":[{"symbol":"x","meaningSv":"Positivt tal","unit":"> 0"}]}]', '[{"gradeLevel":"E","titleSv":"Beräkna enkel logaritmisk likhet","givenSv":"lg(x + 3) = 2","findSv":"x","methodSv":"Upphöj 10 till båda led.","stepsSv":["x + 3 = 10² = 100 ger x = 97."],"answerSv":"x = 97."},{"gradeLevel":"C","titleSv":"Förenkla logaritmsumma","givenSv":"lg 8 + lg 125","findSv":"Värdet utan räknare","methodSv":"lg(8 · 125) = lg 1 000.","stepsSv":["lg 1 000 = 3."],"answerSv":"3."},{"gradeLevel":"A","titleSv":"Ekvation med två exponentialtermer","givenSv":"3 · 2^x = 6 · 5^x","findSv":"x uttryckt med logaritmer","methodSv":"Samla potenser med x på ena sidan och konstanter på den andra.","stepsSv":["(2/5)^x = 6/3 = 2 ger 0,4^x = 2 och x = lg 2 / lg 0,4."],"answerSv":"x = lg 2 / lg 0,4 ≈ −0,76."}]', '[{"trapTitleSv":"Glömma att lg x kräver x > 0","wrongApproachSv":"Att behålla negativa rötter till lg(x²) = 2 utan kontroll om ekvationen löstes från 2 lg x = 2.","rightApproachSv":"Kontrollera alltid att argumentet i ursprungsekvationens logaritmer är strikt positivt."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-2c-3-cirkel-och-avstandsformeln', 'chap-matte-2c-3', 'cirkel-och-avstandsformeln', 1, 'Randvinkelsatsen och koordinatgeometri', '[{"term":"Randvinkelsatsen","definition":"Medelpunktsvinkeln är dubbelt så stor som randvinkeln på samma cirkelbåge."},{"term":"Cirkelns ekvation","definition":"(x − x₀)² + (y − y₀)² = r² med medelpunkt (x₀, y₀) och radie r."}]', '[{"heading":"Vinklar i cirklar och avstånd mellan punkter","bodySv":"Thales sats är ett specialfall av randvinkelsatsen: en randvinkel som spänner över en diameter (180° medelpunktsvinkel) är alltid 90°. I koordinatsystemet följer avståndsformeln och cirkelns ekvation direkt ur Pythagoras sats.","deepDiveSv":"För en fyrhörning inskriven i en cirkel är summan av motstående vinklar alltid 180°."}]', '[{"nameSv":"Avståndsformeln","latex":"d = \\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}","explanationSv":"Beräknar avståndet mellan två punkter i planet.","variables":[{"symbol":"d","meaningSv":"Avstånd","unit":"l.e."}]},{"nameSv":"Cirkelns ekvation","latex":"(x - x_0)^2 + (y - y_0)^2 = r^2","explanationSv":"Beskriver alla punkter på avståndet r från medelpunkten (x₀, y₀).","variables":[{"symbol":"r","meaningSv":"Radie","unit":"l.e."}]}]', '[{"gradeLevel":"E","titleSv":"Randvinkel från medelpunktsvinkel","givenSv":"Medelpunktsvinkeln är 110°.","findSv":"Randvinkeln på samma båge","methodSv":"Dela med 2.","stepsSv":["110° / 2 = 55°."],"answerSv":"Randvinkeln är 55°."},{"gradeLevel":"C","titleSv":"Avstånd mellan två koordinater","givenSv":"A(−1, 2) och B(5, 10)","findSv":"Sträckan AB","methodSv":"Använd avståndsformeln.","stepsSv":["d = √((5 − (−1))² + (10 − 2)²) = √(36 + 64) = 10."],"answerSv":"Avståndet är 10 l.e."},{"gradeLevel":"A","titleSv":"Läsa ut medelpunkt och radie ur cirkelekivation","givenSv":"x² − 6x + y² + 4y = 12","findSv":"Medelpunkt och radie","methodSv":"Kvadratkomplettera både x- och y-termerna.","stepsSv":["(x − 3)² − 9 + (y + 2)² − 4 = 12.","(x − 3)² + (y + 2)² = 25 ger r = 5."],"answerSv":"Medelpunkt (3, −2) och radie 5."}]', '[{"trapTitleSv":"Glömma ta roten ur r² i cirkelns ekvation","wrongApproachSv":"Att ange radien som 25 när ekvationen slutar på = 25.","rightApproachSv":"Högerledet är r², så radien är √25 = 5."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3b-1-polynom-och-faktorisering', 'chap-matte-3b-1', 'polynom-och-faktorisering', 1, 'Polynom, gradtal och faktorisering', '[{"term":"Polynom","definition":"Summa av termer på formen a · x^n där exponenterna n är icke-negativa heltal."},{"term":"Gradtal","definition":"Den högsta exponenten för variabeln x som har koefficient skild från noll."}]', '[{"heading":"Känna igen polynom och faktorisera","bodySv":"Ett uttryck som p(x) = 3x − 7x⁴ + 2x² + 9 är ett polynom av grad 4 eftersom 4 är den högsta exponenten. Uttryck med negativa exponenter (som x⁻¹ = 1/x) eller √x är inte polynom. Genom att bryta ut största gemensamma faktor eller använda kvadrerings- och konjugatreglerna kan högregradspolynom skrivas som produkter av enklare faktorer.","deepDiveSv":"Om x = a är ett nollställe till polynomet p(x) är (x − a) alltid en faktor i p(x)."}]', '[{"nameSv":"Allmän polynomform","latex":"p(x) = a_n x^n + a_{n-1} x^{n-1} + \\dots + a_1 x + a_0","explanationSv":"Polynom av grad n där ledande koefficient a_n ≠ 0 och n ∈ ℕ.","variables":[{"symbol":"n","meaningSv":"Polynomets gradtal","unit":"Heltal ≥ 0"},{"symbol":"a_n","meaningSv":"Ledande koefficient","unit":"Reellt tal"}]}]', '[{"gradeLevel":"E","titleSv":"Avgöra polynomets gradtal","givenSv":"p(x) = 5x + 2x³ − 8","findSv":"Gradtalet och konstanttermen","methodSv":"Leta upp den största exponenten oavsett termordning.","stepsSv":["Största exponenten är 3 (i 2x³) och konstanttermen är −8."],"answerSv":"Polynomet har grad 3 och konstantterm −8."},{"gradeLevel":"C","titleSv":"Faktorisera tredjegradspolynom fullständigt","givenSv":"p(x) = x³ − 16x","findSv":"Fullständig faktorisering och nollställen","methodSv":"Bryt ut x först och använd sedan konjugatregeln.","stepsSv":["p(x) = x(x² − 16) = x(x − 4)(x + 4).","Nollställen: x = 0, x = 4 och x = −4."],"answerSv":"x(x − 4)(x + 4) med nollställena −4, 0 och 4."},{"gradeLevel":"A","titleSv":"Konstruera polynom från nollställen","givenSv":"Ett tredjegradspolynom har nollställena −2, 1 och 3 samt p(0) = 12.","findSv":"Polynomets uttryck","methodSv":"Skriv p(x) = k(x + 2)(x − 1)(x − 3) och lös ut k.","stepsSv":["p(0) = k(2)(−1)(−3) = 6k = 12 ger k = 2.","p(x) = 2(x + 2)(x − 1)(x − 3)."],"answerSv":"p(x) = 2(x + 2)(x − 1)(x − 3)."}]', '[{"trapTitleSv":"Ta första termens exponent som gradtal utan sortering","wrongApproachSv":"Att säga att 5 + 3x − 2x⁴ har grad 0 eller 1.","rightApproachSv":"Leta alltid efter den högsta exponenten i hela uttrycket (här 4)."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3b-1-rationella-uttryck', 'chap-matte-3b-1', 'rationella-uttryck', 2, 'Rationella uttryck och förkortning', '[{"term":"Rationellt uttryck","definition":"Kvot P(x) / Q(x) mellan två polynom där Q(x) ≠ 0."},{"term":"Definitionsmängd","definition":"Alla reella tal utom de x-värden som gör nämnaren lika med noll."}]', '[{"heading":"Faktorisera före förkortning","bodySv":"Division med noll är förbjuden i matematiken. Därför måste man alltid ta reda på för vilka x nämnaren i ett rationellt uttryck blir 0 innan man förkortar. Förkortning får bara göras med hela faktorer — aldrig med enskilda termer som adderas eller subtraheras.","deepDiveSv":"Exempel: (x² − 9) / (x − 3) kan skrivas ((x − 3)(x + 3)) / (x − 3) = x + 3 under förutsättningen att x ≠ 3."}]', '[{"nameSv":"Förenkling av faktor","latex":"\\frac{A \\cdot C}{B \\cdot C} = \\frac{A}{B} \\quad (B \\neq 0,\\ C \\neq 0)","explanationSv":"Endast gemensamma faktorer får förkortas bort.","variables":[{"symbol":"A, B, C","meaningSv":"Polynomuttryck","unit":"Algebraisk form"}]}]', '[{"gradeLevel":"E","titleSv":"Hitta förbjudna x-värden","givenSv":"(x + 4) / (x − 6)","findSv":"För vilket x uttrycket ej är definierat","methodSv":"Sätt nämnaren lika med noll.","stepsSv":["x − 6 = 0 ger x = 6."],"answerSv":"Uttrycket är ej definierat för x = 6."},{"gradeLevel":"C","titleSv":"Förenkla kvot av polynom","givenSv":"(x² − 9) / (x − 3) där x ≠ 3","findSv":"Förenklat uttryck","methodSv":"Faktorisera täljaren med konjugatregeln.","stepsSv":["((x − 3)(x + 3)) / (x − 3) = x + 3."],"answerSv":"x + 3 (för x ≠ 3)."},{"gradeLevel":"A","titleSv":"Hela definitionsmängden ur andragradsnämnare","givenSv":"(x + 1) / (x² − 5x + 6)","findSv":"För vilka x uttrycket saknar värde","methodSv":"Lös x² − 5x + 6 = 0 med pq-formeln.","stepsSv":["x = 2,5 ± √(6,25 − 6) = 2,5 ± 0,5 ger x = 2 och x = 3."],"answerSv":"Ej definierat för x = 2 och x = 3."}]', '[{"trapTitleSv":"Stryka termer i stället för faktorer","wrongApproachSv":"Att förkorta bort x i (x + 4) / (x − 6) till 4 / (−6).","rightApproachSv":"Man får bara stryka faktorer som multipliceras med hela täljaren och hela nämnaren."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3b-1-andringskvoter-och-gransvarden', 'chap-matte-3b-1', 'andringskvoter-och-gransvarden', 3, 'Ändringskvoter och gränsvärden', '[{"term":"Genomsnittlig ändringshastighet","definition":"Lutningen hos sekanten mellan två punkter: (f(b) − f(a)) / (b − a)."},{"term":"Gränsvärde (lim)","definition":"Det värde ett uttryck närmar sig då x eller h går mot ett bestämt tal."}]', '[{"heading":"Från sekantlutning till gränsvärde","bodySv":"En funktions genomsnittliga ändringshastighet mellan x = a och x = b beräknas exakt som lutningen hos en rät linje: Δy / Δx. När punktavståndet h går mot noll i uttrycket (f(a + h) − f(a)) / h närmar vi oss den momentana förändringshastigheten i en enda punkt — grunden för hela differentialkalkylen.","deepDiveSv":"Om insättning i ett bråk ger 0/0 (obestämt uttryck) faktoriserar och förkortar man först bort den faktor som orsakar noll i nämnaren innan gränsvärdet tas."}]', '[{"nameSv":"Ändringskvot (differenskvot)","latex":"\\frac{\\Delta y}{\\Delta x} = \\frac{f(a + h) - f(a)}{h}","explanationSv":"Anger medellutningen över intervallet [a, a + h].","variables":[{"symbol":"a","meaningSv":"Startpunkt","unit":"Tal"},{"symbol":"h","meaningSv":"Steglängd","unit":"Tal ≠ 0"}]}]', '[{"gradeLevel":"E","titleSv":"Genomsnittlig ändringshastighet","givenSv":"f(x) = x² i intervallet 1 ≤ x ≤ 5","findSv":"Genomsnittliga ändringshastigheten","methodSv":"Beräkna (f(5) − f(1)) / (5 − 1).","stepsSv":["(25 − 1) / 4 = 24 / 4 = 6."],"answerSv":"Ändringshastigheten är 6."},{"gradeLevel":"C","titleSv":"Gränsvärde via förkortning","givenSv":"lim(x → 2) (x² − 4) / (x − 2)","findSv":"Gränsvärdet","methodSv":"Direkt insättning ger 0/0. Faktorisera täljaren först.","stepsSv":["((x − 2)(x + 2)) / (x − 2) = x + 2 → 2 + 2 = 4 när x → 2."],"answerSv":"Gränsvärdet är 4."},{"gradeLevel":"A","titleSv":"Gränsvärde av differenskvot","givenSv":"f(x) = 2x² − 1","findSv":"lim(h → 0) (f(3 + h) − f(3)) / h","methodSv":"Utveckla f(3 + h), förenkla täljaren, bryt ut h och förkorta.","stepsSv":["f(3 + h) = 2(9 + 6h + h²) − 1 = 17 + 12h + 2h², och f(3) = 17.","(17 + 12h + 2h² − 17) / h = (12h + 2h²) / h = 12 + 2h.","Då h → 0 går 12 + 2h mot 12."],"answerSv":"Gränsvärdet är 12."}]', '[{"trapTitleSv":"Avbryta med \"saknar värde\" när insättning ger 0/0","wrongApproachSv":"Att svara att lim(x → 2) (x² − 4)/(x − 2) inte existerar.","rightApproachSv":"0/0 betyder att täljare och nämnare delar en nollfaktor som kan förkortas bort innan gränsen tas."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3b-2-deriveringsregler', 'chap-matte-3b-2', 'deriveringsregler', 1, 'Deriveringsregler och talet e', '[{"term":"Derivata f''(x)","definition":"Funktionens momentana ändringshastighet och tangentens lutning i punkten x."},{"term":"Talet e","definition":"Eulers tal (e ≈ 2,718) där derivatan av e^x är e^x själv."}]', '[{"heading":"Potensregeln och kedjan med konstant faktor","bodySv":"För varje polynomterm a · x^n gäller deriveringsregeln f''(x) = a · n · x^(n − 1). En ensam konstant har alltid derivatan 0 eftersom en horisontell linje har lutningen 0. För exponentialfunktioner med basen e gäller att derivatan av e^(kx) är k · e^(kx).","deepDiveSv":"För allmän bas a^x gäller derivatan a^x · ln a, där ln står för den naturliga logaritmen med basen e."}]', '[{"nameSv":"Deriveringsregler för potenser och e^kx","latex":"D(x^n) = n x^{n-1}, \\quad D(e^{kx}) = k e^{kx}","explanationSv":"Används termvis över summor och differenser.","variables":[{"symbol":"n, k","meaningSv":"Konstanter","unit":"Reella tal"}]}]', '[{"gradeLevel":"E","titleSv":"Derivera ett polynom","givenSv":"f(x) = 3x² − 4x + 7","findSv":"f''(2)","methodSv":"Derivera term för term och sätt in x = 2.","stepsSv":["f''(x) = 6x − 4.","f''(2) = 6 · 2 − 4 = 8."],"answerSv":"f''(2) = 8."},{"gradeLevel":"C","titleSv":"Omskrivning av rot och bråk före derivering","givenSv":"f(x) = 4/x + 2√x","findSv":"f''(x)","methodSv":"Skriv om med negativa och bråktalsexponenter: 4x⁻¹ + 2x^(0,5).","stepsSv":["f''(x) = −4x⁻² + 2 · 0,5 · x^(−0,5) = −4/x² + 1/√x."],"answerSv":"f''(x) = −4/x² + 1/√x."},{"gradeLevel":"A","titleSv":"Tangentens ekvation i given punkt","givenSv":"f(x) = x³ − 2x i punkten där x = 2","findSv":"Tangentens ekvation y = kx + m","methodSv":"Beräkna f(2) för punkten och f''(2) för lutningen k.","stepsSv":["f(2) = 8 − 4 = 4, så tangeringspunkten är (2, 4).","f''(x) = 3x² − 2 ger k = f''(2) = 10.","4 = 10 · 2 + m ger m = −16."],"answerSv":"y = 10x − 16."}]', '[{"trapTitleSv":"Glömma att konstanten får derivatan 0","wrongApproachSv":"Att behålla +7 vid derivering av 3x² − 4x + 7.","rightApproachSv":"Konstanter ändras inte med x, så D(7) = 0."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3b-3-extremvarden-och-integraler', 'chap-matte-3b-3', 'extremvarden-och-integraler', 1, 'Extrempunkter och bestämda integraler', '[{"term":"Stationär punkt","definition":"Punkt där f''(x) = 0 (horisontell tangent)."},{"term":"Bestämd integral","definition":"Area med tecken under grafen beräknad med F(b) − F(a)."}]', '[{"heading":"Klassificera extrempunkter och beräkna integraler","bodySv":"Där f''(x) = 0 kan kurvan ha en maximipunkt, minimipunkt eller terrasspunkt. Med teckentabell för f''(x) eller andraderivatan f''''(x) avgör man karaktären (f''''(a) < 0 ger lokalt maximum, f''''(a) > 0 ger lokalt minimum). För primitiva funktioner gäller F''(x) = f(x).","deepDiveSv":"Integralkalkylens fundamentalsats säger att ∫[a till b] f(x) dx = F(b) − F(a), där F är en primitiv funktion till f."}]', '[{"nameSv":"Integralkalkylens fundamentalsats","latex":"\\int_a^b f(x)\\,dx = \\left[F(x)\\right]_a^b = F(b) - F(a)","explanationSv":"Sambandet mellan bestämd integral och primitiv funktion F.","variables":[{"symbol":"a, b","meaningSv":"Integrationsgränser","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Bestämd integral av x²","givenSv":"∫[0 till 2] 3x² dx","findSv":"Integralens värde","methodSv":"En primitiv funktion till 3x² är x³.","stepsSv":["[x³]₀² = 2³ − 0³ = 8."],"answerSv":"8."},{"gradeLevel":"C","titleSv":"Bestämma extrempunkter till tredjegradsfunktion","givenSv":"f(x) = x³ − 3x","findSv":"Lokalt maximum och minimum","methodSv":"Lös f''(x) = 0 och använd f''''(x) = 6x.","stepsSv":["f''(x) = 3x² − 3 = 0 ger x = ±1.","f''''(−1) = −6 < 0 ger max i (−1, 2); f''''(1) = 6 > 0 ger min i (1, −2)."],"answerSv":"Lokalt max (−1, 2) och lokalt min (1, −2)."},{"gradeLevel":"A","titleSv":"Största värde på slutet intervall","givenSv":"f(x) = x³ − 3x på intervallet [0, 3]","findSv":"Globala max- och minvärdet","methodSv":"Jämför stationära punkter i intervallet med ändpunkterna x = 0 och x = 3.","stepsSv":["f(0) = 0, f(1) = −2, f(3) = 27 − 9 = 18."],"answerSv":"Största värdet är 18 (vid x = 3) och minsta är −2 (vid x = 1)."}]', '[{"trapTitleSv":"Glömma pröva ändpunkterna vid max/min på slutet intervall","wrongApproachSv":"Att bara titta på f''(x) = 0.","rightApproachSv":"Det största eller minsta värdet i ett begränsat intervall kan ligga i ändpunkterna."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3c-1-polynom-och-rationella-uttryck', 'chap-matte-3c-1', 'polynom-och-rationella-uttryck', 1, 'Polynom och rationella uttryck', '[{"term":"Faktorisering","definition":"Att skriva ett polynom som en produkt av faktorer med lägre gradtal."},{"term":"Rationell ekvation","definition":"Ekvation där obekanta förekommer i nämnaren och potentiella falska rötter måste kontrolleras."}]', '[{"heading":"Faktorisering och förkortning av högregradspolynom","bodySv":"Genom att kombinera utbrytning av gemensamma faktorer med konjugatregeln och kvadreringsreglerna kan även tredjegradspolynom förenklas snabbt. När du arbetar med rationella uttryck måste du alltid hålla reda på definitionsmängden innan faktorer förkortas bort.","deepDiveSv":"Om ett rationellt uttryck ska vara lika med noll krävs att täljaren är noll medan nämnaren samtidigt är skild från noll."}]', '[{"nameSv":"Nollställe till rationellt uttryck","latex":"\\frac{P(x)}{Q(x)} = 0 \\iff P(x) = 0 \\text{ och } Q(x) \\neq 0","explanationSv":"En kvot blir noll när täljaren är noll och nämnaren ej är noll.","variables":[{"symbol":"P(x)","meaningSv":"Täljarpolynom","unit":"Polynom"},{"symbol":"Q(x)","meaningSv":"Nämnarpolynom","unit":"Polynom"}]}]', '[{"gradeLevel":"E","titleSv":"Definitionsmängd för rationellt uttryck","givenSv":"(2x + 1) / (3x − 15)","findSv":"Förbjudet värde på x","methodSv":"Sätt nämnaren lika med noll.","stepsSv":["3x − 15 = 0 ger x = 5."],"answerSv":"x ≠ 5."},{"gradeLevel":"C","titleSv":"Förenkla tredjegradskvot","givenSv":"(x³ − 4x) / (x² − 2x) för x ≠ 0 och x ≠ 2","findSv":"Förenklat uttryck","methodSv":"Faktorisera både täljare och nämnare fullständigt.","stepsSv":["Täljare: x(x² − 4) = x(x − 2)(x + 2).","Nämnare: x(x − 2).","Förkorta x(x − 2): kvar blir x + 2."],"answerSv":"x + 2 (för x ≠ 0, x ≠ 2)."},{"gradeLevel":"A","titleSv":"Lösa rationell ekvation utan falska rötter","givenSv":"(x² − 9) / (x − 3) = 5","findSv":"Eventuella lösningar","methodSv":"Kontrollera x ≠ 3, förenkla vänsterledet och lös.","stepsSv":["x + 3 = 5 ger x = 2 (vilket uppfyller x ≠ 3)."],"answerSv":"x = 2."}]', '[{"trapTitleSv":"Glömma att nollställen i nämnaren aldrig kan vara rötter","wrongApproachSv":"Att godta x = 3 om x² − 9 = 0 löstes i en ekvation med (x − 3) i nämnaren.","rightApproachSv":"Pröva alltid i nämnaren så att ingen lösning ger division med noll."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3c-1-absolutbelopp-och-gransvarden', 'chap-matte-3c-1', 'absolutbelopp-och-gransvarden', 2, 'Absolutbelopp och gränsvärden', '[{"term":"Absolutbelopp (|x|)","definition":"Talets avstånd till 0 på tallinjen, alltid ≥ 0."},{"term":"Gränsvärde mot oändligheten","definition":"Beteendet hos ett uttryck när x → ∞."}]', '[{"heading":"Absolutbelopp och oändlighetsgränser","bodySv":"Absolutbeloppet |a| är a om a ≥ 0 och −a om a < 0. Ekvationen |ax + b| = c (med c ≥ 0) har därför två fall: ax + b = c eller ax + b = −c. Vid gränsvärden där x → ∞ för en rationell funktion divideras varje term i täljare och nämnare med den högsta x-potensen i nämnaren.","deepDiveSv":"När x → ∞ går termer som 5/x och 3/x² mot 0, så kvoten mellan två andragradspolynom bestäms helt av kvoten mellan deras ledande koefficienter."}]', '[{"nameSv":"Absolutbeloppets definition","latex":"|a| = \\begin{cases} a, & a \\ge 0 \\\\ -a, & a < 0 \\end{cases}","explanationSv":"Anger det icke-negativa avståndet till origo.","variables":[{"symbol":"a","meaningSv":"Reellt tal","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Beräkna uttryck med absolutbelopp","givenSv":"|3 − 10| + |−4|","findSv":"Värdet","methodSv":"Beräkna inuti varje beloppstecken först.","stepsSv":["|−7| + |−4| = 7 + 4 = 11."],"answerSv":"11."},{"gradeLevel":"C","titleSv":"Absolutbeloppsekvation","givenSv":"|2x − 4| = 10","findSv":"Alla lösningar","methodSv":"Dela upp i fallen 2x − 4 = 10 och 2x − 4 = −10.","stepsSv":["Fall 1: 2x − 4 = 10 ger 2x = 14 och x = 7.","Fall 2: 2x − 4 = −10 ger 2x = −6 och x = −3."],"answerSv":"x₁ = 7 och x₂ = −3."},{"gradeLevel":"A","titleSv":"Gränsvärde när x går mot oändligheten","givenSv":"lim(x → ∞) (6x² + 5x) / (2x² − 3)","findSv":"Gränsvärdet","methodSv":"Förkorta med den högsta potensen x².","stepsSv":["Dividera varje term med x²: (6 + 5/x) / (2 − 3/x²).","Då x → ∞ går 5/x → 0 och 3/x² → 0, vilket ger 6 / 2 = 3."],"answerSv":"Gränsvärdet är 3."}]', '[{"trapTitleSv":"Byta tecken på alla minustecken inuti absolutbelopp","wrongApproachSv":"Att skriva |3 − 10| = 3 + 10 = 13.","rightApproachSv":"Räkna först ut värdet inuti beloppet (3 − 10 = −7) och gör sedan resultatet positivt (7)."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3c-1-andringskvoter-och-derivatans-definition', 'chap-matte-3c-1', 'andringskvoter-och-derivatans-definition', 3, 'Sekanter, tangenter och derivatans definition', '[{"term":"Sekant","definition":"Rät linje som skär en kurva i två punkter (a, f(a)) och (a + h, f(a + h))."},{"term":"Tangent","definition":"Gränsläget för sekanten när h → 0, som anger lutningen i en punkt."}]', '[{"heading":"Derivatans definition","bodySv":"Derivatan i punkten x definieras som gränsvärdet av ändringskvoten när intervallängden h går mot noll: f''(x) = lim(h → 0) (f(x + h) − f(x)) / h. Geometriskt motsvarar f''(a) riktningskoefficienten för tangenten till kurvan i punkten (a, f(a)).","deepDiveSv":"Med hjälp av derivatans definition går det att härleda samtliga deriveringsregler, exempelvis varför derivatan av x² alltid blir 2x.","svgDiagram":"<svg viewBox=\"0 0 340 150\" width=\"100%\" aria-label=\"Sekant som närmar sig tangenten när h går mot noll\">\n  <line x1=\"25\" y1=\"125\" x2=\"315\" y2=\"125\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"45\" y1=\"15\" x2=\"45\" y2=\"138\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <path d=\"M 55 118 Q 165 112 285 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"95\" y1=\"122\" x2=\"290\" y2=\"22\" stroke=\"var(--accent)\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\" />\n  <line x1=\"78\" y1=\"124\" x2=\"250\" y2=\"60\" stroke=\"var(--accent)\" stroke-width=\"1.5\" />\n  <circle cx=\"155\" cy=\"95\" r=\"3.5\" fill=\"var(--accent)\" />\n  <circle cx=\"245\" cy=\"45\" r=\"3.5\" fill=\"currentColor\" />\n  <text x=\"148\" y=\"140\" font-size=\"11\" fill=\"currentColor\">a</text>\n  <text x=\"238\" y=\"140\" font-size=\"11\" fill=\"currentColor\">a + h</text>\n  <text x=\"252\" y=\"42\" font-size=\"11\" fill=\"currentColor\">Sekant</text>\n  <text x=\"198\" y=\"88\" font-size=\"11\" fill=\"var(--accent)\">Tangent</text>\n</svg>"}]', '[{"nameSv":"Derivatans definition","latex":"f''(x) = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h}","explanationSv":"Definierar derivatan som sekantlutningens gränsvärde då h → 0.","variables":[{"symbol":"f''(x)","meaningSv":"Derivata","unit":"Lutning"},{"symbol":"h","meaningSv":"Steg i x-led","unit":"Går mot 0"}]}]', '[{"gradeLevel":"E","titleSv":"Sekantlutning för kubisk funktion","givenSv":"f(x) = x³ i intervallet [1, 3]","findSv":"Sekantens lutning","methodSv":"Beräkna (f(3) − f(1)) / (3 − 1).","stepsSv":["(27 − 1) / 2 = 26 / 2 = 13."],"answerSv":"Sekantens lutning är 13."},{"gradeLevel":"C","titleSv":"Ställa upp differenskvot för f(x) = x² + 3x","givenSv":"f(x) = x² + 3x vid x = 2","findSv":"Förenklad differenskvot före gränsvärde","methodSv":"Beräkna f(2 + h) − f(2) och dela med h.","stepsSv":["f(2) = 4 + 6 = 10.","f(2 + h) = (2 + h)² + 3(2 + h) = 4 + 4h + h² + 6 + 3h = 10 + 7h + h².","(10 + 7h + h² − 10) / h = 7 + h."],"answerSv":"Differenskvoten är 7 + h."},{"gradeLevel":"A","titleSv":"Slutföra gränsvärdet till f''(2)","givenSv":"Differenskvoten 7 + h för f(x) = x² + 3x","findSv":"f''(2)","methodSv":"Låt h → 0.","stepsSv":["lim(h → 0) (7 + h) = 7."],"answerSv":"f''(2) = 7."}]', '[{"trapTitleSv":"Glömma parentes runt f(x) vid subtraktionen −f(x)","wrongApproachSv":"Att skriva f(x + h) − x² + 3x i stället för −(x² + 3x).","rightApproachSv":"Subtrahera hela f(x) inom parentes så att samtliga konstanttermer utan h tar ut varandra."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3c-2-kurvanalys-och-talet-e', 'chap-matte-3c-2', 'kurvanalys-och-talet-e', 1, 'Derivering och kurvanalys', '[{"term":"Naturliga logaritmen (ln)","definition":"Logaritmen med basen e: ln(e^x) = x."}]', '[{"heading":"Bestämma asymptoter och extremvärden","bodySv":"Genom att kombinera förstaderivatan (var kurvan vänder) med andraderivatan (konkavitet) får man en komplett bild av en funktions utseende. För a^x gäller derivatan a^x · ln a.","deepDiveSv":"Vid optimering i Matte 3c måste du alltid motivera med teckentabell eller andraderivatan att punkten verkligen är ett maximum eller minimum."}]', '[{"nameSv":"Derivata av allmän exponentialfunktion","latex":"D(a^x) = a^x \\cdot \\ln a","explanationSv":"Specialfallet a = e ger ln e = 1 och alltså D(e^x) = e^x.","variables":[{"symbol":"a","meaningSv":"Positiv bas","unit":"> 0"}]}]', '[{"gradeLevel":"E","titleSv":"Derivata med e^x","givenSv":"f(x) = 4e^(3x)","findSv":"f''(0)","methodSv":"f''(x) = 12e^(3x).","stepsSv":["f''(0) = 12 · e⁰ = 12."],"answerSv":"f''(0) = 12."},{"gradeLevel":"C","titleSv":"Lösning med naturlig logaritm","givenSv":"e^(0,5x) = 7","findSv":"Exakta lösningen x","methodSv":"Tag ln på båda sidor.","stepsSv":["0,5x = ln 7 ger x = 2 · ln 7."],"answerSv":"x = 2 ln 7."},{"gradeLevel":"A","titleSv":"Maximal volym av öppen låda","givenSv":"En kvadratisk plåt med sidan 12 cm får lika stora kvadrater med sidan x bortklippta i hörnen och viks till en öppen låda.","findSv":"Det x som ger störst volym","methodSv":"V(x) = x(12 − 2x)² på (0, 6). Derivera V(x) = 4x³ − 48x² + 144x.","stepsSv":["V''(x) = 12x² − 96x + 144 = 0 ger x² − 8x + 12 = 0, alltså x = 2 (x = 6 ger V = 0)."],"answerSv":"Maximal volym (128 cm³) fås då x = 2 cm."}]', '[{"trapTitleSv":"Glömma den inre faktorn k när e^(kx) deriveras","wrongApproachSv":"Att skriva D(e^(3x)) = e^(3x).","rightApproachSv":"Multiplicera alltid med exponentens koefficient: D(e^(3x)) = 3e^(3x)."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3c-3-area-mellan-kurvor', 'chap-matte-3c-3', 'area-mellan-kurvor', 1, 'Areaberäkning mellan två kurvor', '[{"term":"Primitiv funktion","definition":"F(x) kallas primitiv funktion till f(x) om F''(x) = f(x)."}]', '[{"heading":"Övre funktion minus undre funktion","bodySv":"Arean av ett område som uppåt begränsas av y = f(x) och nedåt av y = g(x) mellan skärningspunkterna a och b ges av ∫[a till b] (f(x) − g(x)) dx. Detta gäller oavsett om kurvorna ligger ovanför eller under x-axeln.","deepDiveSv":"När en funktion skär x-axeln mitt i ett intervall måste integralen delas upp om den geometriska arean (alltid positiv) efterfrågas."}]', '[{"nameSv":"Area mellan två grafer","latex":"A = \\int_a^b \\left(f(x) - g(x)\\right)\\,dx","explanationSv":"Där f(x) ≥ g(x) på hela intervallet [a, b].","variables":[{"symbol":"f(x)","meaningSv":"Övre kurva","unit":"Funktion"},{"symbol":"g(x)","meaningSv":"Undre kurva","unit":"Funktion"}]}]', '[{"gradeLevel":"E","titleSv":"Bestäm en primitiv funktion med villkor","givenSv":"f(x) = 4x och F(1) = 5","findSv":"F(x)","methodSv":"F(x) = 2x² + C och använd F(1) = 5.","stepsSv":["2(1)² + C = 5 ger C = 3, alltså F(x) = 2x² + 3."],"answerSv":"F(x) = 2x² + 3."},{"gradeLevel":"C","titleSv":"Integral av exponentialfunktion","givenSv":"∫[0 till 1] 2e^(2x) dx","findSv":"Exakt värde","methodSv":"Primitiv funktion till 2e^(2x) är e^(2x).","stepsSv":["[e^(2x)]₀¹ = e² − e⁰ = e² − 1."],"answerSv":"e² − 1."},{"gradeLevel":"A","titleSv":"Area mellan rät linje och parabel","givenSv":"y = x + 2 och y = x²","findSv":"Arean av området mellan kurvorna","methodSv":"Hitta skärningspunkterna och integrera (övre − undre).","stepsSv":["x² = x + 2 ger x² − x − 2 = 0, alltså x₁ = −1 och x₂ = 2.","∫[−1 till 2] (x + 2 − x²) dx = [x²/2 + 2x − x³/3]₋₁² = (2 + 4 − 8/3) − (1/2 − 2 + 1/3) = 4,5."],"answerSv":"Arean är 4,5 a.e."}]', '[{"trapTitleSv":"Glömma att a.e. (area) alltid är positiv även när kurvan ligger under x-axeln","wrongApproachSv":"Att ange ett negativt tal som geometrisk area.","rightApproachSv":"Integrera (0 − f(x)) för delar under x-axeln eller ta absolutbeloppet av delintegralen."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-3c-4-enhetscirkel-och-triangelsatser', 'chap-matte-3c-4', 'enhetscirkel-och-triangelsatser', 1, 'Enhetscirkeln och triangelsatserna', '[{"term":"Enhetscirkeln","definition":"Cirkel med radie 1 och medelpunkt i origo där cos v är x-koordinaten och sin v är y-koordinaten."},{"term":"Supplementvinkel","definition":"sin(180° − v) = sin v medan cos(180° − v) = −cos v."}]', '[{"heading":"Lösa godtyckliga trianglar","bodySv":"I trianglar som saknar rät vinkel används areasatsen, sinussatsen och cosinussatsen. Eftersom två supplementvinklar v och 180° − v har exakt samma sinusvärde kan sinussatsen ibland ge två möjliga trianglar (ett spetsigt och ett trubbigt svar), vilket alltid måste kontrolleras mot triangelns vinkelsumma 180°.","deepDiveSv":"Cosinussatsen är en generalisering av Pythagoras sats: vid C = 90° är cos 90° = 0 och formeln reduceras till c² = a² + b².","svgDiagram":"<svg viewBox=\"0 0 260 170\" width=\"100%\" aria-label=\"Enhetscirkeln med vinkeln v, cos v och sin v\">\n  <line x1=\"30\" y1=\"85\" x2=\"230\" y2=\"85\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"130\" y1=\"12\" x2=\"130\" y2=\"158\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <circle cx=\"130\" cy=\"85\" r=\"56\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"130\" y1=\"85\" x2=\"170\" y2=\"45\" stroke=\"var(--accent)\" stroke-width=\"1.5\" />\n  <line x1=\"170\" y1=\"45\" x2=\"170\" y2=\"85\" stroke=\"var(--accent)\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\" />\n  <circle cx=\"170\" cy=\"45\" r=\"3.5\" fill=\"var(--accent)\" />\n  <text x=\"176\" y=\"42\" font-size=\"11\" fill=\"var(--accent)\">(cos v, sin v)</text>\n  <text x=\"147\" y=\"79\" font-size=\"11\" fill=\"currentColor\">v</text>\n</svg>"}]', '[{"nameSv":"Areasatsen och sinussatsen","latex":"A = \\frac{1}{2} ab\\sin C, \\quad \\frac{\\sin A}{a} = \\frac{\\sin B}{b} = \\frac{\\sin C}{c}","explanationSv":"Gäller i alla trianglar med sidor a, b, c och motstående vinklar A, B, C.","variables":[{"symbol":"a, b, c","meaningSv":"Triangelns sidor","unit":"l.e."},{"symbol":"A, B, C","meaningSv":"Motstående vinklar","unit":"°"}]},{"nameSv":"Cosinussatsen","latex":"c^2 = a^2 + b^2 - 2ab\\cos C","explanationSv":"Kopplar samman alla tre sidorna och en mellanliggande vinkel.","variables":[{"symbol":"C","meaningSv":"Vinkel mellan sidorna a och b","unit":"°"}]}]', '[{"gradeLevel":"E","titleSv":"Area med mellanliggande vinkel","givenSv":"a = 8,0 cm, b = 5,0 cm, mellanliggande vinkel C = 30°","findSv":"Triangelns area","methodSv":"A = ½ · a · b · sin C.","stepsSv":["A = 0,5 · 8,0 · 5,0 · sin 30° = 20 · 0,5 = 10 cm²."],"answerSv":"Arean är 10 cm²."},{"gradeLevel":"C","titleSv":"Tredje sidan med cosinussatsen","givenSv":"a = 5,0 cm, b = 8,0 cm, C = 60°","findSv":"Sidan c","methodSv":"cos 60° = 0,5.","stepsSv":["c² = 25 + 64 − 2 · 5 · 8 · 0,5 = 89 − 40 = 49 ger c = 7,0 cm."],"answerSv":"Sidan c är 7,0 cm."},{"gradeLevel":"A","titleSv":"Bestämma största vinkeln när alla tre sidor är kända","givenSv":"Sidor 3, 5 och 7 cm","findSv":"Vinkeln mittemot den längsta sidan (7 cm)","methodSv":"Lös ut cos C ur cosinussatsen.","stepsSv":["7² = 3² + 5² − 2 · 3 · 5 · cos C.","49 = 34 − 30 cos C ger cos C = −15 / 30 = −0,5 och C = 120°."],"answerSv":"Vinkeln är 120° (trubbig triangel)."}]', '[{"trapTitleSv":"Missa det trubbiga alternativet i sinussatsen","wrongApproachSv":"Att bara ta räknarens arcsin-värde utan att pröva 180° − v.","rightApproachSv":"Pröva alltid om även supplementvinkeln 180° − v får plats inom vinkelsumman 180°."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-4-1-radianer-och-enhetscirkeln', 'chap-matte-4-1', 'radianer-och-enhetscirkeln', 1, 'Radianer, enhetscirkeln och trigonometriska ettan', '[{"term":"Radian (rad)","definition":"Vinkelmått där båglängden på enhetscirkeln är lika med vinkeln: 2π rad = 360°."},{"term":"Trigonometriska ettan","definition":"Identiteten sin²v + cos²v = 1 som följer ur Pythagoras sats i enhetscirkeln."}]', '[{"heading":"Varför radianer krävs inom analysen","bodySv":"I trigonometriska derivator och integraler används alltid radianer eftersom sambandet D(sin x) = cos x endast gäller när x mäts i radianer. Omvandlingen utgår från att ett halvt varv motsvarar π radianer = 180°, vilket ger standardvinklarna π/6 = 30°, π/4 = 45°, π/3 = 60° och π/2 = 90°.","deepDiveSv":"I enhetscirkeln bildar punkten (cos v, sin v) en rätvinklig triangel med hypotenusan 1, vilket omedelbart ger trigonometriska ettan cos²v + sin²v = 1."}]', '[{"nameSv":"Samband mellan grader och radianer","latex":"\\pi\\text{ rad} = 180^\\circ, \\quad b = r \\cdot v","explanationSv":"Båglängden b blir direkt radien r gånger vinkeln v i radianer.","variables":[{"symbol":"b","meaningSv":"Cirkelbågens längd","unit":"l.e."},{"symbol":"r","meaningSv":"Radie","unit":"l.e."},{"symbol":"v","meaningSv":"Medelpunktsvinkel","unit":"rad"}]},{"nameSv":"Trigonometriska ettan","latex":"\\sin^2 v + \\cos^2 v = 1","explanationSv":"Gäller för alla vinklar v.","variables":[{"symbol":"v","meaningSv":"Vinkel","unit":"rad eller °"}]}]', '[{"gradeLevel":"E","titleSv":"Omvandla radianer till grader","givenSv":"v = π / 3 rad","findSv":"Vinkeln i grader","methodSv":"Ersätt π med 180°.","stepsSv":["180° / 3 = 60°."],"answerSv":"60°."},{"gradeLevel":"C","titleSv":"Bestäm cos v med trigonometriska ettan","givenSv":"sin v = 0,6 och 0 < v < π / 2 (första kvadranten)","findSv":"cos v","methodSv":"Lös cos²v = 1 − sin²v och välj positivt tecken i första kvadranten.","stepsSv":["cos²v = 1 − 0,36 = 0,64 ger cos v = +0,8."],"answerSv":"cos v = 0,8."},{"gradeLevel":"A","titleSv":"Teckenval i andra kvadranten","givenSv":"sin v = 5/13 och π/2 < v < π","findSv":"Exakt värde på tan v","methodSv":"Bestäm cos v < 0 i andra kvadranten och beräkna tan v = sin v / cos v.","stepsSv":["cos²v = 1 − 25/169 = 144/169 ger cos v = −12/13.","tan v = (5/13) / (−12/13) = −5/12."],"answerSv":"tan v = −5/12."}]', '[{"trapTitleSv":"Glömma kontrollera kvadranten vid roten ur (1 − sin²v)","wrongApproachSv":"Att alltid välja den positiva roten för cos v.","rightApproachSv":"I andra och tredje kvadranten är x-koordinaten negativ, alltså är cos v < 0."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-4-1-trigonometriska-ekvationer', 'chap-matte-4-1', 'trigonometriska-ekvationer', 2, 'Trigonometriska ekvationer och periodicitet', '[{"term":"Periodisk lösning","definition":"Varje helt varv ±n · 2π (eller ±n · 360°) ger nya vinklar med samma värde."}]', '[{"heading":"Fullständiga lösningsmängder","bodySv":"Eftersom sin x och cos x upprepar sina värden varje varv har ekvationer som sin x = a oändligt många lösningar. För sin x = sin v gäller dels x = v + n · 2π, dels x = (π − v) + n · 2π. För cos x = cos v gäller x = ±v + n · 2π. Står det sin(kx) måste man dividera hela uttrycket inklusive perioden med k i sista steget.","deepDiveSv":"Tangens har kortare period än sinus och cosinus: tan x = tan v har lösningen x = v + n · π (halvt varv)."}]', '[{"nameSv":"Grundekvationer i radianer","latex":"\\sin x = \\sin v \\implies x = \\begin{cases} v + n\\cdot 2\\pi \\\\ \\pi - v + n\\cdot 2\\pi \\end{cases}","explanationSv":"Där n ∈ ℤ anger godtyckligt antal hela varv.","variables":[{"symbol":"n","meaningSv":"Heltalsvarv","unit":"Heltal"}]}]', '[{"gradeLevel":"E","titleSv":"Alla lösningar i ett varv","givenSv":"2 sin x = 1 för 0° ≤ x ≤ 360°","findSv":"Samtliga vinklar x","methodSv":"sin x = 0,5 ger huvudvinkeln 30° och supplementvinkeln 180° − 30°.","stepsSv":["x₁ = 30° och x₂ = 150°."],"answerSv":"x = 30° eller x = 150°."},{"gradeLevel":"C","titleSv":"Ekvation med multipel vinkel","givenSv":"sin(3x) = 0,5 i intervallet 0 ≤ x < 2π","findSv":"Antalet lösningar i intervallet","methodSv":"3x har perioden 2π / 3, så det ryms 3 fulla perioder med 2 lösningar per period.","stepsSv":["3x = π/6 + n·2π eller 3x = 5π/6 + n·2π.","x = π/18 + n·2π/3 eller x = 5π/18 + n·2π/3 ger n = 0, 1, 2 (6 lösningar)."],"answerSv":"6 lösningar i intervallet."},{"gradeLevel":"A","titleSv":"Andragradsekvation i cos x","givenSv":"2 cos²x − cos x − 1 = 0 i intervallet 0 ≤ x ≤ π","findSv":"Exakta rötter","methodSv":"Substituera t = cos x och lös 2t² − t − 1 = 0.","stepsSv":["t = (1 ± √9) / 4 ger t₁ = 1 och t₂ = −0,5.","cos x = 1 ger x = 0; cos x = −0,5 ger x = 2π/3."],"answerSv":"x = 0 eller x = 2π / 3."}]', '[{"trapTitleSv":"Glömma dividera perioden 2π med k i sin(kx)","wrongApproachSv":"Att skriva 3x = π/6 + n·2π och därefter x = π/18 + n·2π.","rightApproachSv":"Dela både vinkeln och periodtermens +n·2π med 3 till +n·2π/3."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-4-1-additionsformler-och-kurvor', 'chap-matte-4-1', 'additionsformler-och-kurvor', 3, 'Sinuskurvor, additionsformler och omskrivning', '[{"term":"Amplitud (A)","definition":"Största utslaget från kurvans jämviktslinje (alltid ≥ 0)."},{"term":"Period (T)","definition":"Längden för en hel svängning: T = 2π / k (eller 360° / k)."}]', '[{"heading":"Harmonisk svängning och a sin x + b cos x","bodySv":"Funktionen y = A sin(k(x + φ)) + D beskriver svängningsrörelser med jämviktslinje y = D, maxvärde D + A och minvärde D − A. Med additionsformlerna kan summan a sin x + b cos x alltid slås ihop till en enda sinusfunktion A sin(x + v) där amplituden blir A = √(a² + b²).","deepDiveSv":"Additionsformlerna ger direkt formlerna för dubbla vinkeln: sin(2x) = 2 sin x cos x samt cos(2x) = cos²x − sin²x = 2 cos²x − 1 = 1 − 2 sin²x."}]', '[{"nameSv":"Sammanslagning av sinus och cosinus","latex":"a\\sin x + b\\cos x = \\sqrt{a^2 + b^2} \\sin(x + v), \\quad \\tan v = \\frac{b}{a}","explanationSv":"Gäller för a > 0; sammanslår två vågor med samma frekvens till en enda våg.","variables":[{"symbol":"a, b","meaningSv":"Vågornas amplituder","unit":"Tal"},{"symbol":"v","meaningSv":"Fasförskjutning","unit":"rad"}]}]', '[{"gradeLevel":"E","titleSv":"Period och maxvärde för cosinusfunktion","givenSv":"y = 5 cos(3x) − 2","findSv":"Största värdet","methodSv":"cos(3x) är högst 1.","stepsSv":["y_max = 5 · 1 − 2 = 3."],"answerSv":"Största värdet är 3."},{"gradeLevel":"C","titleSv":"Skriva om 3 sin x + 4 cos x","givenSv":"f(x) = 3 sin x + 4 cos x","findSv":"Funktionens amplitud","methodSv":"A = √(a² + b²).","stepsSv":["A = √(3² + 4²) = √25 = 5."],"answerSv":"Amplituden är 5."},{"gradeLevel":"A","titleSv":"Anpassa tidvattenmodell till mätvärden","givenSv":"Högvatten 3,2 m kl 04:00 och lågvatten 1,2 m kl 10:00.","findSv":"Jämviktslinje D, amplitud A och period T","methodSv":"Tiden mellan topp och dal är en halv period.","stepsSv":["D = (3,2 + 1,2) / 2 = 2,2 m och A = (3,2 − 1,2) / 2 = 1,0 m.","Halv period = 10 − 4 = 6 h ger hel period T = 12 h och k = 2π / 12 = π / 6."],"answerSv":"D = 2,2 m, A = 1,0 m och perioden T = 12 h."}]', '[{"trapTitleSv":"Förväxla konstanttermen k i sin(kx) med perioden","wrongApproachSv":"Att svara att perioden för sin(2x) är 2.","rightApproachSv":"Dela grundperioden med k: T = 2π / 2 = π (eller 360° / 2 = 180°)."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-4-2-produkt-kvot-och-kedjeregeln', 'chap-matte-4-2', 'produkt-kvot-och-kedjeregeln', 1, 'Produkt-, kvot- och kedjeregeln', '[{"term":"Kedjeregeln","definition":"Yttre derivata gånger inre derivata: D(f(g(x))) = f''(g(x)) · g''(x)."},{"term":"Produktregeln","definition":"D(f · g) = f'' · g + f · g''."}]', '[{"heading":"Derivera sammansatta och trigonometriska uttryck","bodySv":"I radianer gäller D(sin x) = cos x, D(cos x) = −sin x och D(ln x) = 1/x. Kombineras detta med kedjeregeln får exempelvis sin(3x) derivatan 3 cos(3x) eftersom den inre funktionen 3x har derivatan 3.","deepDiveSv":"Kvotregeln lyder D(f/g) = (f''g − fg'') / g²."}]', '[{"nameSv":"Kedjeregeln och trigonometriska derivator","latex":"\\frac{d}{dx} f(g(x)) = f''(g(x)) \\cdot g''(x), \\quad D(\\sin x) = \\cos x, \\quad D(\\cos x) = -\\sin x","explanationSv":"Gäller när vinkeln x mäts i radianer.","variables":[{"symbol":"g''(x)","meaningSv":"Inre derivata","unit":"Derivata"}]}]', '[{"gradeLevel":"E","titleSv":"Kedjeregeln på cosinus","givenSv":"f(x) = cos(4x)","findSv":"f''(x)","methodSv":"Yttre derivata −sin(4x) gånger inre derivata 4.","stepsSv":["f''(x) = −4 sin(4x)."],"answerSv":"f''(x) = −4 sin(4x)."},{"gradeLevel":"C","titleSv":"Produktregeln med e^x","givenSv":"f(x) = x · e^x","findSv":"f''(0)","methodSv":"f''(x) = 1 · e^x + x · e^x = (1 + x)e^x.","stepsSv":["f''(0) = (1 + 0) · 1 = 1."],"answerSv":"f''(0) = 1."},{"gradeLevel":"A","titleSv":"Stationär punkt till x · ln x","givenSv":"f(x) = x · ln x för x > 0","findSv":"Var f''(x) = 0","methodSv":"Använd produktregeln: 1 · ln x + x · (1/x).","stepsSv":["ln x + 1 = 0 ger ln x = −1 och x = e⁻¹ = 1/e."],"answerSv":"Stationär punkt vid x = 1/e."}]', '[{"trapTitleSv":"Glömma minustecknet vid derivering av cos x","wrongApproachSv":"Att skriva D(cos x) = sin x.","rightApproachSv":"D(sin x) = +cos x, medan D(cos x) = −sin x."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-4-3-rotationsvolymer', 'chap-matte-4-3', 'rotationsvolymer', 1, 'Integraler och rotationsvolym kring x-axeln', '[{"term":"Rotationsvolym","definition":"Volym som uppstår då en kurva roterar ett helt varv kring x-axeln: V = π ∫ y² dx."}]', '[{"heading":"Skivmetoden med cirkulära tvärsnitt","bodySv":"Varje tunt tvärsnitt vinkelrätt mot x-axeln bildar en cirkelskiva med radien r = y och arean πy². Summeras skivorna med en integral fås volymen V = π ∫[a till b] (f(x))² dx. För 1/x (x > 0) är primitiva funktionen ln x.","deepDiveSv":"Kom ihåg att alltid kvadrera hela funktionsuttrycket f(x) inuti integralen vid beräkning av rotationsvolym kring x-axeln."}]', '[{"nameSv":"Rotationsvolym kring x-axeln","latex":"V = \\pi \\int_a^b \\left(f(x)\\right)^2\\,dx","explanationSv":"Skivmetoden integrerar tvärsnittsarean πr² med r = f(x).","variables":[{"symbol":"V","meaningSv":"Rotationsvolym","unit":"v.e."}]}]', '[{"gradeLevel":"E","titleSv":"Integral med 1/x","givenSv":"∫[1 till e] (2/x) dx","findSv":"Exakt värde","methodSv":"Primitiv funktion till 2/x är 2 ln x.","stepsSv":["[2 ln x]₁ᵉ = 2 ln e − 2 ln 1 = 2 · 1 − 0 = 2."],"answerSv":"2."},{"gradeLevel":"C","titleSv":"Rotationsvolym av kon","givenSv":"Linjen y = x roterar kring x-axeln för 0 ≤ x ≤ 3.","findSv":"Volymen som multipel av π","methodSv":"V = π ∫[0 till 3] x² dx.","stepsSv":["V = π [x³/3]₀³ = π · (27 / 3) = 9π."],"answerSv":"9π v.e."},{"gradeLevel":"A","titleSv":"Rotationsvolym under rotfunktion","givenSv":"y = √(x + 1) roterar kring x-axeln för 0 ≤ x ≤ 3.","findSv":"Volymen","methodSv":"(√(x + 1))² = x + 1.","stepsSv":["V = π ∫[0 till 3] (x + 1) dx = π [x²/2 + x]₀³ = π (4,5 + 3) = 7,5π."],"answerSv":"7,5π v.e."}]', '[{"trapTitleSv":"Glömma π eller kvadraten i volymintegralen","wrongApproachSv":"Att skriva ∫ f(x) dx eller glömma multiplicera med π.","rightApproachSv":"Tvärsnittsarean är π · y², så både π och kvadraten måste vara med."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-4-4-komplexa-tal-och-polar-form', 'chap-matte-4-4', 'komplexa-tal-och-polar-form', 1, 'Komplexa tal och polär form', '[{"term":"Imaginära enheten (i)","definition":"Definieras genom i² = −1."},{"term":"Absolutbelopp (|z|)","definition":"Avståndet till origo i det komplexa talplanet: r = √(a² + b²)."},{"term":"Argument (arg z)","definition":"Vinkeln v från positiva realaxeln moturs till vektorn z."}]', '[{"heading":"Rektangulär form, polär form och de Moivres formel","bodySv":"Ett komplext tal z = a + bi har realdelen a och imaginärdelen b. På polär form skrivs det z = r(cos v + i sin v). Vid multiplikation multipliceras beloppen och argumenten adderas, vilket ger de Moivres formel för potenser: z^n = r^n(cos(nv) + i sin(nv)).","deepDiveSv":"Komplexa konjugatet till z = a + bi är z̄ = a − bi. Produkten z · z̄ = a² + b² = |z|² är alltid ett icke-negativt reellt tal och används vid division."}]', '[{"nameSv":"de Moivres formel","latex":"\\left(r(\\cos v + i\\sin v)\\right)^n = r^n(\\cos(nv) + i\\sin(nv))","explanationSv":"Gör det snabbt att beräkna höga potenser av komplexa tal.","variables":[{"symbol":"r","meaningSv":"Absolutbelopp |z|","unit":"≥ 0"},{"symbol":"v","meaningSv":"Argument","unit":"rad eller °"}]}]', '[{"gradeLevel":"E","titleSv":"Beräkna belopp","givenSv":"z = 3 + 4i","findSv":"|z|","methodSv":"|z| = √(3² + 4²).","stepsSv":["√(9 + 16) = 5."],"answerSv":"|z| = 5."},{"gradeLevel":"C","titleSv":"Division med komplext konjugat","givenSv":"(10) / (3 + i)","findSv":"Uttryck på formen a + bi","methodSv":"Förläng täljare och nämnare med konjugatet 3 − i.","stepsSv":["(10(3 − i)) / (3² + 1²) = (30 − 10i) / 10 = 3 − i."],"answerSv":"3 − i."},{"gradeLevel":"A","titleSv":"Potens med de Moivres formel","givenSv":"z = 2(cos 30° + i sin 30°)","findSv":"z³ på formen a + bi","methodSv":"Upphöj beloppet till 3 och multiplicera vinkeln med 3.","stepsSv":["z³ = 2³(cos 90° + i sin 90°) = 8(0 + i) = 8i."],"answerSv":"z³ = 8i."}]', '[{"trapTitleSv":"Inkludera i i imaginärdelen","wrongApproachSv":"Att skriva att imaginärdelen till 3 + 4i är 4i.","rightApproachSv":"Imaginärdelen Im(3 + 4i) är det reella talet 4 (utan i)."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-5-1-begreppet-differentialekvation', 'chap-matte-5-1', 'begreppet-differentialekvation', 1, 'Differentialekvationer och prövning av lösning', '[{"term":"Differentialekvation","definition":"Ekvation som innehåller en okänd funktion y och en eller flera av dess derivator."},{"term":"Begynnelsevillkor","definition":"Givet värde som t.ex. y(0) = 3 som bestämmer den obekanta konstanten C entydigt."}]', '[{"heading":"Allmän lösning, partikulärlösning och verifiering","bodySv":"Lösningen till en differentialekvation är inte ett tal utan en funktion (eller en hel familj av funktioner med en godtycklig konstant C). För att visa att en given funktion uppfyller en differentialekvation deriverar man funktionen, sätter in uttrycken för y, y'' och eventuellt y'''' i vänsterledet (VL) och högerledet (HL) var för sig och visar att VL = HL.","deepDiveSv":"Differentialekvationens ordning bestäms av den högsta derivata som ingår i ekvationen."}]', '[{"nameSv":"Proportionell tillväxt","latex":"y'' = k \\cdot y \\iff y = C \\cdot e^{kx}","explanationSv":"Den mest grundläggande differentialekvationen inom biologi, fysik och ekonomi.","variables":[{"symbol":"k","meaningSv":"Proportionalitetskonstant","unit":"Tal"},{"symbol":"C","meaningSv":"Startvärde vid x = 0","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Bestämma C ur begynnelsevillkor","givenSv":"y'' = 2y och y(0) = 3","findSv":"Den partikulära lösningen y(x)","methodSv":"Allmänna lösningen är y = C · e^(2x). Sätt in x = 0.","stepsSv":["3 = C · e⁰ = C ger C = 3, alltså y(x) = 3e^(2x)."],"answerSv":"y(x) = 3e^(2x)."},{"gradeLevel":"C","titleSv":"Verifiera lösning med VL och HL","givenSv":"Visa att y = 4e^(−3x) + 5 löser y'' + 3y = 15.","findSv":"Bevis genom insättning","methodSv":"Derivera y och beräkna VL.","stepsSv":["y'' = −12e^(−3x).","VL = −12e^(−3x) + 3(4e^(−3x) + 5) = −12e^(−3x) + 12e^(−3x) + 15 = 15 = HL."],"answerSv":"VL = HL för alla x, så funktionen är en lösning."},{"gradeLevel":"A","titleSv":"Jämviktslösning i en tillväxtmodell","givenSv":"y'' = 0,5y − 2","findSv":"Den konstanta jämviktslösningen","methodSv":"Vid jämvikt är förändringen noll: y'' = 0.","stepsSv":["0,5y − 2 = 0 ger 0,5y = 2 och y = 4."],"answerSv":"y(x) = 4."}]', '[{"trapTitleSv":"Sätta VL = HL i en ekvation i stället för att beräkna dem separat vid prövning","wrongApproachSv":"Att skriva VL = HL redan på första raden innan beviset är klart.","rightApproachSv":"Räkna ut VL för sig och HL för sig och konstatera först på sista raden att VL = HL."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-5-1-homogena-och-inhomogena-ekvationer', 'chap-matte-5-1', 'homogena-och-inhomogena-ekvationer', 2, 'Homogena och inhomogena linjära differentialekvationer', '[{"term":"Homogen ekvation","definition":"Linjär differentialekvation där högerledet är 0."},{"term":"Partikulärlösning (y_p)","definition":"En enskild lösning som uppfyller hela den inhomogena ekvationen."}]', '[{"heading":"Strukturen y = y_h + y_p och andra ordningens ekvationer","bodySv":"Den fullständiga lösningen till en inhomogen linjär differentialekvation är alltid summan y = y_h + y_p, där y_h är den allmänna lösningen till motsvarande homogena ekvation och y_p är en valfri partikulärlösning. För andra ordningens homogena ekvationer y'''' + ay'' + by = 0 ansätter man y = e^(rx), vilket leder till den karakteristiska ekvationen r² + ar + b = 0.","deepDiveSv":"Har r² + ar + b = 0 två olika reella rötter r₁ och r₂ blir lösningen y = C₁e^(r₁x) + C₂e^(r₂x). Komplexa rötter r = α ± βi ger svängningar med e^(αx)(A cos βx + B sin βx)."}]', '[{"nameSv":"Inhomogen första ordningens differentialekvation","latex":"y'' + ay = b \\implies y = C e^{-ax} + \\frac{b}{a}","explanationSv":"Gäller när a och b är konstanter (a ≠ 0).","variables":[{"symbol":"a, b","meaningSv":"Konstanter","unit":"Tal"}]},{"nameSv":"Karakteristisk ekvation","latex":"y'''' + ay'' + by = 0 \\implies r^2 + ar + b = 0","explanationSv":"Bestämmer rötterna r för ansatsen y = e^(rx).","variables":[{"symbol":"r","meaningSv":"Karakteristisk rot","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Konstant partikulärlösning","givenSv":"y'' + 2y = 10","findSv":"Konstant partikulärlösning y_p","methodSv":"Ansätt y_p = A (konstant), vilket ger y_p'' = 0.","stepsSv":["0 + 2A = 10 ger A = 5."],"answerSv":"y_p = 5."},{"gradeLevel":"C","titleSv":"Andra ordningens homogena ekvation","givenSv":"y'''' − 5y'' + 6y = 0","findSv":"Allmänna lösningen","methodSv":"Lös r² − 5r + 6 = 0.","stepsSv":["(r − 2)(r − 3) = 0 ger r₁ = 2 och r₂ = 3.","y = C₁e^(2x) + C₂e^(3x)."],"answerSv":"y = C₁e^(2x) + C₂e^(3x)."},{"gradeLevel":"A","titleSv":"Inhomogen ekvation med linjärt högerled","givenSv":"y'' + y = 2x","findSv":"Allmänna lösningen","methodSv":"Ansätt y_p = ax + b, derivera och matcha koefficienter.","stepsSv":["y_h = C · e^(−x).","y_p'' + y_p = a + ax + b = 2x ger a = 2 och a + b = 0 → b = −2.","y = C · e^(−x) + 2x − 2."],"answerSv":"y = C · e^(−x) + 2x − 2."}]', '[{"trapTitleSv":"Sätta in y = y_p som slutsvar utan den homogena delen y_h","wrongApproachSv":"Att bara svara y = 5 på y'' + 2y = 10.","rightApproachSv":"Den allmänna lösningen kräver alltid y_h med konstanten C: y = C · e^(−2x) + 5."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-5-1-riktningsfalt-och-tillampningar', 'chap-matte-5-1', 'riktningsfalt-och-tillampningar', 3, 'Riktningsfält och Eulers stegmetod', '[{"term":"Riktningsfält","definition":"Grafisk karta av små lutningsstreck med riktningskoefficienten y''(x, y) i varje punkt."},{"term":"Eulers stegmetod","definition":"Numerisk metod som stegar framåt med y_{k+1} = y_k + h · y''(x_k, y_k)."}]', '[{"heading":"Tolka riktningsfält och stega numeriskt","bodySv":"Många verkliga differentialekvationer saknar enkel exakt formel, men deras lösningar kan ändå skissas direkt ur riktningsfältet eller approximeras med Eulers stegmetod. Vid Eulers metod följer man tangentens lutning y'' under ett kort steg h för att skatta nästa y-värde.","deepDiveSv":"Om lutningsstrecken i ett riktningsfält är identiska längs varje vågrät linje (oberoende av x) beror differentialekvationen enbart av y och kallas autonom: y'' = f(y).","svgDiagram":"<svg viewBox=\"0 0 320 150\" width=\"100%\" aria-label=\"Riktningsfält och lösningskurva för en differentialekvation\">\n  <line x1=\"25\" y1=\"125\" x2=\"295\" y2=\"125\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"45\" y1=\"15\" x2=\"45\" y2=\"138\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"70\" y1=\"104\" x2=\"88\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"130\" y1=\"104\" x2=\"148\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"190\" y1=\"104\" x2=\"208\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"70\" y1=\"68\" x2=\"88\" y2=\"54\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"130\" y1=\"68\" x2=\"148\" y2=\"54\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <line x1=\"190\" y1=\"68\" x2=\"208\" y2=\"54\" stroke=\"currentColor\" stroke-width=\"1.5\" />\n  <path d=\"M 45 108 Q 160 95 270 30\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2\" />\n  <circle cx=\"45\" cy=\"108\" r=\"3.5\" fill=\"var(--accent)\" />\n  <text x=\"54\" y=\"114\" font-size=\"11\" fill=\"var(--accent)\">Begynnelsevillkor y(0)</text>\n</svg>"}]', '[{"nameSv":"Eulers stegmetod","latex":"y_{k+1} = y_k + h \\cdot f(x_k, y_k)","explanationSv":"Numerisk approximation med steglängden h för ekvationen y'' = f(x, y).","variables":[{"symbol":"h","meaningSv":"Steglängd i x-led","unit":"Tal"},{"symbol":"f(x_k, y_k)","meaningSv":"Lutning i nuvarande punkt","unit":"Derivata"}]}]', '[{"gradeLevel":"E","titleSv":"Läsa lutning ur differentialekvation","givenSv":"y'' = x − y","findSv":"Riktningsstreckets lutning i punkten (4, 1)","methodSv":"Sätt in x = 4 och y = 1.","stepsSv":["y'' = 4 − 1 = 3."],"answerSv":"Lutningen i (4, 1) är 3."},{"gradeLevel":"C","titleSv":"Ett steg med Eulers metod","givenSv":"y'' = 2x + y, y(0) = 2 och steglängd h = 0,5","findSv":"Närmevärde för y(0,5)","methodSv":"Beräkna lutningen i (0, 2) och ta ett steg av längd 0,5.","stepsSv":["y''(0, 2) = 2 · 0 + 2 = 2.","y₁ = 2 + 0,5 · 2 = 3,0."],"answerSv":"y(0,5) ≈ 3,0."},{"gradeLevel":"A","titleSv":"Två steg med Eulers metod och felanalys","givenSv":"Fortsätt exemplet ovan ett steg till x = 1,0 med h = 0,5.","findSv":"y₂ ≈ y(1,0) och om närmevärdet underskattar en konvex lösning","methodSv":"Använd (x₁, y₁) = (0,5; 3,0) i nästa steg.","stepsSv":["y''(0,5; 3,0) = 2 · 0,5 + 3,0 = 4,0.","y₂ = 3,0 + 0,5 · 4,0 = 5,0.","Eftersom lutningen växer hela tiden ligger tangentstegen under den uppåtböjda kurvan (underskattning)."],"answerSv":"y(1,0) ≈ 5,0 (underskattning)."}]', '[{"trapTitleSv":"Glömma uppdatera x-koordinaten i Eulers metod","wrongApproachSv":"Att behålla x₀ = 0 i alla steg när x ingår i högerledet.","rightApproachSv":"Öka x med +h i varje steg: x₁ = x₀ + h, x₂ = x₀ + 2h."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-5-2-kombinatorik-och-induktion', 'chap-matte-5-2', 'kombinatorik-och-induktion', 1, 'Kombinationer, talföljder och induktionsbevis', '[{"term":"Kombination C(n, k)","definition":"Antalet sätt att välja k element ur n utan hänsyn till ordning."},{"term":"Matematisk induktion","definition":"Bevismetod i tre steg: basfall, induktionsantagande och induktionssteg."}]', '[{"heading":"Ordning spelar roll eller ej, samt talföljder","bodySv":"Vid permutationer spelar ordningen roll, medan kombinationer C(n, k) = n! / (k!(n − k)!) räknar antalet oordnade urval. För en geometrisk summa med kvot k ≠ 1 gäller S_n = a₁(k^n − 1) / (k − 1).","deepDiveSv":"Induktionsbevis bevisar påståenden P(n) för alla heltal n ≥ n₀ genom att visa P(n₀) samt implikationen P(p) ⇒ P(p + 1)."}]', '[{"nameSv":"Kombinationer och geometrisk summa","latex":"\\binom{n}{k} = \\frac{n!}{k!(n - k)!}, \\quad S_n = \\frac{a_1(k^n - 1)}{k - 1}","explanationSv":"Används vid urval utan ordning respektive summor med konstant kvot k.","variables":[{"symbol":"n","meaningSv":"Totalmängd eller antal termer","unit":"Heltal ≥ 1"},{"symbol":"k","meaningSv":"Antal valda eller kvot","unit":"Tal"}]}]', '[{"gradeLevel":"E","titleSv":"Välja en kommitté","givenSv":"3 elever ska väljas ur 6 utan inbördes ordning.","findSv":"Antalet olika kommittéer","methodSv":"Beräkna C(6, 3).","stepsSv":["(6 · 5 · 4) / (3 · 2 · 1) = 120 / 6 = 20."],"answerSv":"20 sätt."},{"gradeLevel":"C","titleSv":"Aritmetisk summa","givenSv":"Summan 3 + 7 + 11 + ... + 39 (10 termer)","findSv":"Summan","methodSv":"S_n = n(a₁ + a_n) / 2.","stepsSv":["S₁₀ = 10(3 + 39) / 2 = 210."],"answerSv":"210."},{"gradeLevel":"A","titleSv":"Induktionssteget för summan av udda tal","givenSv":"Antag att 1 + 3 + ... + (2p − 1) = p².","findSv":"Visa formeln för p + 1","methodSv":"Addera nästa udda tal (2p + 1) till båda sidor.","stepsSv":["p² + (2p + 1) = (p + 1)², vilket stämmer med formeln för n = p + 1."],"answerSv":"Påståendet är bevisat för alla heltal n ≥ 1."}]', '[{"trapTitleSv":"Förväxla permutationer med kombinationer","wrongApproachSv":"Att använda 6 · 5 · 4 = 120 när ordningen saknar betydelse.","rightApproachSv":"Dela alltid med k! när ett urval sker utan inbördes ordning."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-matte-5-3-integrationsmetoder', 'chap-matte-5-3', 'integrationsmetoder', 1, 'Variabelsubstitution och partiell integration', '[{"term":"Partiell integration","definition":"Integrationsmotsvarighet till produktregeln: ∫ f''g dx = fg − ∫ fg'' dx."},{"term":"Generaliserad integral","definition":"Integral med ∞ som gräns definierad som lim(b → ∞) ∫[a till b] f(x) dx."}]', '[{"heading":"Integrera produkter och obegränsade intervall","bodySv":"Produkter som x · e^x kan inte integreras termvis utan löses med partiell integration. När en integrationsgräns är ∞ ersätts den med en variabel b varefter gränsvärdet b → ∞ beräknas.","deepDiveSv":"En generaliserad integral sägs vara konvergent om gränsvärdet existerar som ett ändligt tal, annars divergent."}]', '[{"nameSv":"Partiell integration","latex":"\\int f''(x)g(x)\\,dx = f(x)g(x) - \\int f(x)g''(x)\\,dx","explanationSv":"Välj g(x) som den faktor som blir enklare vid derivering.","variables":[{"symbol":"f''(x), g(x)","meaningSv":"Faktorer i integranden","unit":"Funktioner"}]}]', '[{"gradeLevel":"E","titleSv":"Konvergent generaliserad integral","givenSv":"∫[1 till ∞] x⁻² dx","findSv":"Värdet om den konvergerar","methodSv":"Beräkna lim(b → ∞) [−1/x]₁ᵇ.","stepsSv":["lim(b → ∞) (−1/b − (−1/1)) = 0 + 1 = 1."],"answerSv":"Integralen konvergerar mot värdet 1."},{"gradeLevel":"C","titleSv":"Variabelsubstitution","givenSv":"∫ 2x · e^(x²) dx","findSv":"Samtliga primitiva funktioner","methodSv":"Substituera u = x², då du = 2x dx.","stepsSv":["∫ e^u du = e^u + C = e^(x²) + C."],"answerSv":"e^(x²) + C."},{"gradeLevel":"A","titleSv":"Partiell integration på x · cos x","givenSv":"∫[0 till π/2] x · cos x dx","findSv":"Exakt värde","methodSv":"Välj g(x) = x och f''(x) = cos x.","stepsSv":["[x sin x]₀^(π/2) − ∫[0 till π/2] sin x dx = (π/2) − [−cos x]₀^(π/2) = π/2 − 1."],"answerSv":"π/2 − 1."}]', '[{"trapTitleSv":"Glömma byta gränser eller substituera tillbaka vid variabelbyte","wrongApproachSv":"Att sätta in x-gränserna direkt i u-uttrycket.","rightApproachSv":"Byt antingen till nya u-gränser direkt eller byt tillbaka från u till x före insättning."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-1-1-retorikens-grunder', 'chap-svenska-1-1', 'retorikens-grunder', 1, 'Retorikens tre appeller och talsituationen', '[{"term":"Etos","definition":"Talarens trovärdighet, sakkunskap och välvilja gentemot publiken."},{"term":"Logos","definition":"Sakargument, fakta, statistik och logiska slutledningar."},{"term":"Patos","definition":"Känslomässig vädjan genom värdeladdade ord, liknelser och berättelser."},{"term":"Partes-modellen","definition":"Retorikens sex arbetssteg: intellectio, inventio, dispositio, elocutio, memoria och actio."}]', '[{"heading":"Samspelet mellan etos, logos och patos","bodySv":"Redan i antikens retorik konstaterade Aristoteles att en övertygande framställning behöver balans mellan tre bevistyper. Etos bygger förtroende för avsändaren, logos tilltalar lyssnarens förnuft genom belägg och siffror, medan patos skapar engagemang och närvaro. Ett tal eller en insändare som enbart lutar sig mot patos uppfattas lätt som manipulerande, medan ren faktaredovisning utan etos eller patos sällan väcker intresse.","deepDiveSv":"I moderna svenska debattartiklar används ofta retoriska stilfigurer i elocutio-fasen: anafor (upprepning av inledningsord), tretal (rytmisk gruppering i tre led) och retoriska frågor som leder läsaren till avsändarens slutsats."}]', '[]', '[{"gradeLevel":"E","titleSv":"Identifiera appellform i ett kort citat","givenSv":"Utdrag: \"Som akutläkare med tjugo års erfarenhet vet jag att varje minut räknas när hjärtat stannar.\"","findSv":"Vilken retorisk appell som dominerar inledningen","methodSv":"Undersök om talaren främst hänvisar till fakta, känslor eller egen yrkesroll.","stepsSv":["Talaren lyfter sin yrkestitel (\"akutläkare\") och sin långa erfarenhet (\"tjugo år\").","Syftet är att få lyssnaren att lita på avsändarens omdöme och kompetens."],"answerSv":"Etos dominerar eftersom avsändaren bygger upp sin trovärdighet."},{"gradeLevel":"C","titleSv":"Analysera samspelet mellan logos och patos","givenSv":"Utdrag: \"Enligt Trafikverket sker 60 % av cykelolyckorna i korsningar utan hjälm. Ingen familj ska behöva få det samtalet på fredagskvällen.\"","findSv":"Hur meningarna samverkar retoriskt","methodSv":"Analysera första och andra meningen var för sig och förklara kombinationen.","stepsSv":["Första meningen vädjar till logos med statistik (60 %) och en namngiven myndighet (Trafikverket).","Andra meningen vädjar till patos genom en vardagsnära scen (\"det samtalet på fredagskvällen\") som väcker oro och empati.","Tillsammans gör faktaargumentet känslovädjan sakligt grundad."],"answerSv":"Avsändaren kombinerar myndighetsstatistik (logos) med en empativäckande bild (patos) för att förstärka budskapet."},{"gradeLevel":"A","titleSv":"Granska stilfigur och målgruppsanpassning (kairos)","givenSv":"Utdrag ur kommunalt inlägg inför budgetbeslut: \"Vi har råd med ny asfalt. Vi har råd med fasadbelysning. Men har vi verkligen inte råd med skolbibliotekarier åt våra barn?\"","findSv":"Vilka stilfigurer som används och hur de stärker argumentationen","methodSv":"Granska upprepningar, kontraster, retorisk fråga och tajming (kairos).","stepsSv":["Inledningen använder anafor (\"Vi har råd med...\") och tretal för att skapa retorisk stegring.","Den avslutande retoriska frågan ställer materiella utgifter (asfalt, belysning) mot mänsklig bildning (\"våra barn\") och tvingar läsaren att instämma.","Genom att publiceras precis före budgetbeslutet utnyttjas kairos — rätt ögonblick för påverkan."],"answerSv":"Anafor, tretal och en kontrastrik retorisk fråga driver fram patos och etos i rätt politiskt ögonblick."}]', '[{"trapTitleSv":"Förväxla logos med enbart svåra ord","wrongApproachSv":"Att kalla ett känsloargument för logos bara för att texten låter formell.","rightApproachSv":"Logos bygger på belägg, orsakssamband, statistik eller logik — inte på tonläge."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-1-1-argumenterande-textstruktur', 'chap-svenska-1-1', 'argumenterande-textstruktur', 2, 'Argumenterande textstruktur, tes och motargument', '[{"term":"Tes","definition":"Den tydliga ståndpunkt eller det förslag som skribenten driver i texten."},{"term":"Argument och belägg","definition":"Skäl för tesen (argument) uppbackade med fakta, exempel eller expertis (belägg)."},{"term":"Motargument och bemötande","definition":"Att lyfta fram meningsmotståndarens starkaste invändning och sakligt vederlägga den."}]', '[{"heading":"Uppbyggnad av en argumenterande text","bodySv":"En slagkraftig argumenterande text inleds med en väckande öppning och en entydigt formulerad tes. Därefter följer 2–3 tydligt avgränsade stycken med för-argument i stigande styrkeordning, varvat med konkreta belägg. För att höja trovärdigheten och visa kritiskt tänkande ingår alltid minst ett motargument som skribenten bemöter sakligt före den sammanfattande avslutningen.","deepDiveSv":"Undvik vaga värdeord som \"hemskt\" eller \"fantastiskt\" utan förklaring. Använd i stället tydliga sambandsmarkörer som \"för det första\", \"dessutom\", \"å andra sidan\" och \"trots detta\"."}]', '[]', '[{"gradeLevel":"E","titleSv":"Skilja på tes och argument","givenSv":"Meningar: A) \"Kollektivtrafiken bör vara avgiftsfri för gymnasieelever.\" B) \"Det minskar bilpendlingen i rusningstid.\"","findSv":"Vilken mening som är tes respektive argument","methodSv":"Pröva vilken mening som uttrycker själva kravet (\"bör\") och vilken som besvarar \"varför?\".","stepsSv":["Mening A formulerar ett ställningstagande med \"bör\" → tes.","Mening B förklarar nyttan av förslaget → argument för tesen."],"answerSv":"A är tesen och B är ett argument för tesen."},{"gradeLevel":"C","titleSv":"Formulera ett sakligt bemötande av motargument","givenSv":"Tes: \"Inför senare skolstart för gymnasiet.\" Motargument: \"Eleverna kommer bara lägga sig ännu senare på kvällen.\"","findSv":"Ett trovärdigt bemötande","methodSv":"Erkänn invändningen kort och visa med belägg eller logik varför tesen ändå håller.","stepsSv":["Medgivande: \"Det stämmer att sömnvanor kräver eget ansvar.\"","Bemötande: \"Sömnforskning visar dock att tonåringars biologiska dygnsrytm är förskjuten framåt, och försöksskolor med start klockan nio har uppmätt längre total sömn och minskad frånvaro.\""],"answerSv":"Ett effektivt bemötande erkänner invändningen men hänvisar till biologisk dygnsrytm och uppmätta skolresultat."},{"gradeLevel":"A","titleSv":"Bedöma hållbarhet och relevans i argumentation","givenSv":"Tes: \"Plastpåseskatten bör avskaffas.\" Argument: \"Plastpåsar går utmärkt att vika ihop och lägga i fickan.\"","findSv":"Bedöm argumentets relevans och hållbarhet","methodSv":"Pröva om argumentet stödjer själva skattefrågan (relevans) och om påståendet stämmer (hållbarhet).","stepsSv":["Hållbarheten stämmer i sak: plastpåsar kan vikas ihop.","Relevansen för att avskaffa skatten är däremot svag, eftersom vikbarheten inte besvarar frågan om miljöeffekt eller skattens styreffekt (man kan fortfarande återanvända befintliga påsar trots skatt)."],"answerSv":"Argumentet har god hållbarhet i sak men låg relevans för tesen."}]', '[{"trapTitleSv":"Presentera ett motargument utan att bemöta det","wrongApproachSv":"Att skriva \"Vissa tycker att det blir för dyrt\" och sedan byta ämne.","rightApproachSv":"Följ alltid upp motargumentet med ett tydligt motdrag (\"Trots kostnaden visar beräkningar att...\")."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-1-1-kallkritik-och-referatteknik', 'chap-svenska-1-1', 'kallkritik-och-referatteknik', 3, 'Källkritik och referatteknik', '[{"term":"Äkthet, tid, beroende, tendens","definition":"De fyra klassiska källkritiska kriterierna."},{"term":"Referatmarkör","definition":"Verb eller fras som visar vem som står för påståendet, exempelvis \"enligt\", \"menar\" eller \"konstaterar\"."}]', '[{"heading":"Granska källor och referera objektivt","bodySv":"För att bedöma en källas tillförlitlighet granskas fyra frågor: Är källan äkta? Hur nära händelsen i tid tillkom den? Är källan oberoende eller upprepar den bara vad någon annan sagt? Har avsändaren ett eget intresse att vinkla berättelsen (tendens)? När du refererar en annan text ska egna värderingar hållas utanför genom neutrala referatmarkörer.","deepDiveSv":"Undvik att enbart använda \"skriver\" eller \"säger\". Variera med nyanserade markörer utifrån skribentens syfte: \"hävdar\" (vid åsikt), \"redovisar\" (vid fakta), \"kritiserar\" (vid invändning) eller \"drar slutsatsen\"."}]', '[]', '[{"gradeLevel":"E","titleSv":"Rätta ett osynligt referat","givenSv":"Felaktigt: \"Svensk skola tappar i läsförståelse.\" (hämtat ur en rapport av Skolverket)","findSv":"Skriv om med tydlig referatmarkör","methodSv":"Infoga källan och en neutral markör.","stepsSv":["Enligt en rapport från Skolverket minskar läsförståelsen i svensk skola."],"answerSv":"Enligt Skolverket minskar läsförståelsen i svensk skola."},{"gradeLevel":"C","titleSv":"Tillämpa beroende- och tendenskriteriet","givenSv":"Ett läskföretag publicerar en bloggpost som påstår att deras nya sockerfria dryck förbättrar skolbetygen, utan att hänvisa till externa studier.","findSv":"Källkritisk bedömning utifrån två kriterier","methodSv":"Granska tendens och oberoende.","stepsSv":["Tendens: Företaget har ett tydligt ekonomiskt intresse av att sälja produkten, vilket ger hög risk för vinkling.","Beroende/verifierbarhet: Påståendet saknar oberoende forskningsstöd."],"answerSv":"Källan har låg trovärdighet på grund av stark ekonomisk tendens och avsaknad av oberoende belägg."},{"gradeLevel":"A","titleSv":"Välja nyanserad referatmarkör efter kontext","givenSv":"Författaren till en ledartext anser utan statistik att distansarbete förstör företagskulturen.","findSv":"Varför \"bevisar\" är fel markör och vilket ord som passar bättre","methodSv":"Jämför ordens sanningsanspråk.","stepsSv":["\"Bevisar\" eller \"konstaterar\" antyder att referenten håller med om att det är ett objektivt faktum.","Eftersom det rör sig om en obevisad åsikt bör markören vara \"hävdar\", \"menar\" eller \"anser\"."],"answerSv":"\"Hävdar\" eller \"menar\" bevarar objektiviteten och signalerar att det är ledarskribentens uppfattning."}]', '[{"trapTitleSv":"Kopiera meningar ur källtexten utan citattecken","wrongApproachSv":"Att bara byta ut något enstaka ord i originalmeningen och kalla det referat.","rightApproachSv":"Formulera om innehållet helt med egna ord och använd citattecken runt enstaka exakta formuleringar."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-1-2-berattarperspektiv-och-tema', 'chap-svenska-1-2', 'berattarperspektiv-och-tema', 1, 'Berättarperspektiv, tema och motiv', '[{"term":"Allvetande berättare","definition":"Tredjepersonsberättare som har insyn i flera karaktärers tankar och i framtiden."},{"term":"Tema","definition":"Den övergripande grundidén eller livsfrågan i verket (t.ex. svek, identitet, ensamhet)."},{"term":"Motiv","definition":"Återkommande konkreta händelser eller situationer som gestaltar temat."}]', '[{"heading":"Skilja berättarens röst från författaren","bodySv":"I skönlitterär analys kallas den som för ordet för berättare — aldrig författare. En jagberättare skapar närhet men har begränsat perspektiv och kan vara opålitlig. Ett tidsmässigt grepp som in medias res kastar läsaren rakt in i handlingen utan lång inledning.","deepDiveSv":"Metafor (direkt bildlig överföring utan \"som\") och liknelse (med \"som\" eller \"likt\") fördjupar stämningen och skapar tolkningsskikt."}]', '[]', '[{"gradeLevel":"E","titleSv":"Bestämma berättarperspektiv","givenSv":"\"Jag stod på perrongen och såg tåget försvinna i dimman.\"","findSv":"Berättarperspektivet","methodSv":"Se på pronomen och insyn.","stepsSv":["Pronomenet \"jag\" visar att en karaktär inne i berättelsen själv återger händelsen."],"answerSv":"Förstapersonsperspektiv (jagberättare)."},{"gradeLevel":"C","titleSv":"Skilja mellan tema och motiv","givenSv":"En novell handlar om två syskon som återvänder till sommarstugan för att tömma den efter moderns död.","findSv":"Tema respektive motiv","methodSv":"Skilj konkret handling (motiv) från abstrakt grundtanke (tema).","stepsSv":["Motiv: arvskiftet / att tömma föräldrahemmet.","Tema: sorg, försoning eller minnenas makt."],"answerSv":"Motivet är att tömma barndomshemmet; temat är sorg och försoning."},{"gradeLevel":"A","titleSv":"Tolka opålitlig berättare och metafor","givenSv":"\"Rummet var en trång kista av tystnad, fast jag naturligtvis alltid trivts utmärkt ensam.\"","findSv":"Vad bildspråket och kommentaren avslöjar","methodSv":"Jämför den dystra metaforen med det hurtiga påståendet.","stepsSv":["Metaforen \"trång kista av tystnad\" förmedlar klaustrofobi och isolering.","Bisatsen \"fast jag naturligtvis alltid trivts utmärkt\" krockar med känslan och antyder förnekelse."],"answerSv":"Spänningen mellan dödsmetaforen och det ytliga förnekandet avslöjar en opålitlig jagberättare som döljer sin ensamhet."}]', '[{"trapTitleSv":"Blanda ihop jagberättaren med författaren","wrongApproachSv":"Att skriva \"Författaren stod på perrongen\".","rightApproachSv":"Skriv alltid \"berättaren\" eller \"jagberättaren\" om rösten i fiktiva texter."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-1-3-sprakriktighet-och-dialekt', 'chap-svenska-1-3', 'sprakriktighet-och-dialekt', 1, 'De och dem, meningsbyggnad och dialekter', '[{"term":"De och dem","definition":"\"De\" fungerar som subjekt (motsvarar \"vi\") och \"dem\" som objekt (motsvarar \"oss\")."},{"term":"Satsradning","definition":"Att koppla ihop två självständiga huvudsatser med endast kommatecken utan bindeord."},{"term":"Dialektutjämning","definition":"Process där lokala dialektdrag minskar till förmån för regionala standardspråk."}]', '[{"heading":"Säkraste knepen i svensk språkriktighet","bodySv":"Osäkerhet kring \"de\" och \"dem\" löses genom att byta ut ordet mot \"vi\" eller \"oss\" (alternativt \"jag\" eller \"mig\"). Om \"vi\" passar ska det vara \"de\"; om \"oss\" passar ska det vara \"dem\". Framför substantiv i plural som bestämd artikel används alltid \"de\" (\"de nya böckerna\"). Undvik satsradning genom att använda punkt, semikolon eller konjunktion.","deepDiveSv":"I svenskan skrivs sammansatta substantiv som ett ord (\"gymnasieelev\", \"källförteckning\") och rubriker använder svensk versalisering där enbart första ordet och egennamn får stor bokstav."}]', '[]', '[{"gradeLevel":"E","titleSv":"Välja mellan de och dem","givenSv":"\"Läraren gav ___ extra tid inför provet.\"","findSv":"Rätt pronomen","methodSv":"Testa med \"vi\" eller \"oss\".","stepsSv":["\"Läraren gav oss extra tid\" låter rätt → objektsform → \"dem\"."],"answerSv":"dem."},{"gradeLevel":"C","titleSv":"Rätta en satsradning","givenSv":"\"Vädret slog om snabbt, vi fick ta skydd i skolan.\"","findSv":"Korrigera felet på två sätt","methodSv":"Infoga punkt eller samordnande konjunktion (och, så).","stepsSv":["Alternativ 1: \"Vädret slog om snabbt. Vi fick ta skydd i skolan.\"","Alternativ 2: \"Vädret slog om snabbt, så vi fick ta skydd i skolan.\""],"answerSv":"Bryt upp med punkt eller bindeordet \"så\"."},{"gradeLevel":"A","titleSv":"Subjekts- och objektsform före relativsats","givenSv":"\"Jag pratade med ___ som vann tävlingen.\"","findSv":"Varför både \"dem\" och \"de\" kan prövas men \"dem\" rekommenderas","methodSv":"Analysera funktionen efter prepositionen \"med\".","stepsSv":["Prepositionen \"med\" styr objektsform (\"oss som vann\"), vilket traditionellt ger \"dem\".","I modern svenska godtas även \"de\" framför \"som\" när uttrycket som helhet upplevs som ett obestämt pronomen, men \"dem som\" efter preposition följer grundregeln tydligast."],"answerSv":"\"dem\" eftersom prepositionen \"med\" kräver objektsform (\"oss som vann\")."}]', '[{"trapTitleSv":"Skriva \"dem\" framför substantiv","wrongApproachSv":"Att skriva \"dem nya böckerna\".","rightApproachSv":"Som bestämd artikel före substantiv heter det alltid \"de\" (\"de nya böckerna\")."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-2-1-sociolekter-och-sprakattityder', 'chap-svenska-2-1', 'sociolekter-och-sprakattityder', 1, 'Sociolekter, kronolekter och kodväxling', '[{"term":"Sociolekt","definition":"Språklig variation kopplad till social grupp, yrke, utbildning eller bostadsområde."},{"term":"Kronolekt","definition":"Språkbruk som utmärker en viss åldersgrupp eller generation."},{"term":"Kodväxling","definition":"Att medvetet eller omedvetet växla mellan två språk eller varieteter beroende på samtalssituation."}]', '[{"heading":"Språk som identitet och maktmarkör","bodySv":"Hur vi talar beror inte bara på var vi bor (dialekt), utan också på ålder, social tillhörighet och situation. Forskare skiljer på idiolekt (varje individs personliga språk), kronolekt (åldersbunden variation) och sociolekt (social variation). Språkattityder avgör ofta hur trovärdig eller kompetent en talare uppfattas, trots att alla varieteter är språkligt lika funktionella.","deepDiveSv":"Ungdomsspråk och förortssvenska skapar stark gruppsammanhållning (in-group-markörer), medan formell standardsvenska fungerar som prestigespråk i myndighets- och arbetslivssammanhang. Att kunna växla mellan dessa kallas registermedvetenhet eller kodväxling."}]', '[]', '[{"gradeLevel":"E","titleSv":"Identifiera typ av språklig variation","givenSv":"En grupp ekonomer använder termer som \"likviditet\", \"avkastning\" och \"substansvärde\" på lunchen.","findSv":"Vilket begrepp som beskriver detta språkbruk","methodSv":"Koppla språkbruket till yrkesgrupp.","stepsSv":["Ordförrådet är knutet till ett visst yrkes- och facksammanhang."],"answerSv":"Sociolekt (närmare bestämt fackspråk / yrkessociolekt)."},{"gradeLevel":"C","titleSv":"Analysera kodväxling i vardagen","givenSv":"En elev växlar från snabbt slangfyllt talspråk på rasten till saklig standardsvenska i klassrumspresentationen.","findSv":"Varför denna växling sker och vad den visar","methodSv":"Bedöm syfte, mottagare och språklig kompetens.","stepsSv":["På rasten markerar slangen tillhörighet och närhet till vännerna.","I klassrummet anpassas registret för att skapa etos och tydlighet inför lärare och klass."],"answerSv":"Eleven visar hög språklig medvetenhet genom situationell kodväxling."},{"gradeLevel":"A","titleSv":"Kritisk granskning av språkattityder","givenSv":"En platsannons avvisar sökande med brytning trots att tjänsten inte kräver kundkontakt, med motiveringen \"vi vill bara ha korrekt svenska\".","findSv":"Förklara fenomenet med språksociologiska begrepp","methodSv":"Skilj mellan språklig begriplighet och sociala språkattityder.","stepsSv":["Brytning påverkar uttal men innebär inte automatiskt brister i ordförråd eller grammatisk förståelse.","Att värdera en talare lägre utifrån uttal handlar om språkattityder och maktstrukturer kopplade till standardspråksnormen."],"answerSv":"Exemplet illustrerar hur språkattityder kring en oskriven uttalsnorm kan leda till social exkludering."}]', '[{"trapTitleSv":"Förväxla dialekt med sociolekt","wrongApproachSv":"Att kalla ungdomsslang eller fackspråk för en dialekt.","rightApproachSv":"Dialekt är geografiskt bunden; sociolekt är socialt/gruppspecifikt bunden och kronolekt är åldersbunden."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-2-1-nordiska-sprak-och-slaktskap', 'chap-svenska-2-1', 'nordiska-sprak-och-slaktskap', 2, 'Nordiska språk, språkfamiljer och grannspråksförståelse', '[{"term":"Nordgermanska språk","definition":"Svenska, norska, danska, isländska och färöiska som alla utvecklats ur fornnordiskan."},{"term":"Falska vänner","definition":"Ord som liknar varandra i två nordiska språk men betyder olika saker."},{"term":"Finno-ugriska språk","definition":"Språkfamilj som finska och samiska tillhör — inte besläktad med svenska."}]', '[{"heading":"Två språkfamiljer i Norden","bodySv":"De flesta språk i Norden — svenska, norska, danska, isländska och färöiska — tillhör den nordgermanska grenen av den indoeuropeiska språkfamiljen och har gemensamt ursprung i fornnordiskan. Svenska, norska och danska ligger så nära varandra att talarna ofta förstår varandra (semikommunikation). Finska och samiska tillhör däremot den finno-ugriska (uraliska) språkfamiljen och har helt annan grammatik och ordförråd.","deepDiveSv":"Norska har två officiella skriftspråksnormer: bokmål (historiskt starkt påverkat av danskan) och nynorsk (baserat på norska bygdedialekter). Danska skiljer sig mest i uttal från svenskan genom mjuka konsonanter och stöt (stød), medan skriftbilden är mycket lik svenskans."}]', '[]', '[{"gradeLevel":"E","titleSv":"Gruppera nordiska språk efter språkfamilj","givenSv":"Språken svenska, finska, isländska, danska","findSv":"Vilket språk som inte hör till den nordgermanska gruppen","methodSv":"Kontrollera språkfamiljerna.","stepsSv":["Svenska, isländska och danska är nordgermanska; finska är finno-ugriskt."],"answerSv":"Finska tillhör en annan språkfamilj (finno-ugriska språk)."},{"gradeLevel":"C","titleSv":"Undvika falska vänner i danska och norska","givenSv":"En svensk turist läser på en dansk skylt: \"Frokost serveres 12–14\" och på en norsk: \"Det var et rart vær i dag.\"","findSv":"Vad \"frokost\" och \"rar\" betyder i respektive språk","methodSv":"Översätt via grannspråkskunskap snarare än gissning.","stepsSv":["Danska \"frokost\" betyder lunch (svenskans frukost heter \"morgenmad\").","Norska \"rar\" betyder konstig eller märklig (inte söt/snäll)."],"answerSv":"Dansk \"frokost\" betyder lunch och norsk \"rar\" betyder konstig."},{"gradeLevel":"A","titleSv":"Jämföra svensk, norsk och dansk läsförståelse vs hörförståelse","givenSv":"Många svenskar har lättare att förstå talad norska än talad danska, men läser danska utan större problem.","findSv":"Språkhistorisk förklaring","methodSv":"Jämför ljudutveckling med ortografi (stavning).","stepsSv":["Danskans skrift bevarar äldre konsonantmönster som ligger nära svenskans och norskans ordförråd.","I tal har danskan genomgått kraftiga konsonantförsvagningar (t.ex. k/p/t blir g/b/d eller vokalisering) och stød, vilket gör ordgränser svårare att uppfatta.","Norskans uttal ligger närmare svenskans prosodi och konsonantuttal."],"answerSv":"Danskans uttal har förändrats kraftigt bort från skriftbilden, medan norskans ljudsystem liknar svenskans."}]', '[{"trapTitleSv":"Anta att finska är besläktat med svenska på grund av geografisk närhet","wrongApproachSv":"Att placera finskan i samma språkfamilj som de skandinaviska språken.","rightApproachSv":"Finska och samiska är finno-ugriska språk; svenska, norska och danska är indoeuropeiska (nordgermanska)."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-2-1-sprakforandring-och-lanord', 'chap-svenska-2-1', 'sprakforandring-och-lanord', 3, 'Lånord och Sveriges nationella minoritetsspråk', '[{"term":"Lånord","definition":"Ord som tagits in från andra språk, t.ex. från lågtyska, franska eller engelska."},{"term":"Nationella minoritetsspråk","definition":"Sveriges fem lagskyddade minoritetsspråk: finska, jiddisch, meänkieli, romani chib och samiska."}]', '[{"heading":"Historiska vågor av lånord och språklagstiftning","bodySv":"Svenskan har alltid lånat ord utifrån i vågor som speglar historiska kontakter: latin och grekiska med kristendomen, lågtyska under hansatiden (ord som \"fönster\", \"arbete\", \"stad\"), franska på 1700-talet (\"paraply\", \"fåtölj\") och engelska i modern tid. Enligt språklagen är svenska huvudspråk i Sverige, samtidigt som fem nationella minoritetsspråk samt svenskt teckenspråk har särskilt skydd.","deepDiveSv":"Många lånord anpassas i stavning och böjning till svenskan (t.ex. \"strejk\", \"mejl\"), medan andra behåller engelsk stavning men får svenska ändelser (\"mejlar\", \"streamat\")."}]', '[]', '[{"gradeLevel":"E","titleSv":"Känna igen Sveriges nationella minoritetsspråk","givenSv":"Finska, samiska, meänkieli, romani chib, jiddisch","findSv":"Varför engelska inte är ett nationellt minoritetsspråk","methodSv":"Pröva kriteriet om historisk hävd i Sverige.","stepsSv":["Nationella minoritetsspråk har talats kontinuerligt i Sverige i minst hundra år."],"answerSv":"Engelska saknar den långa historiska hävden som inhemskt minoritetsspråk i Sverige."},{"gradeLevel":"C","titleSv":"Härleda lånords historiska epok","givenSv":"Ord: A) \"borgmästare\", B) \"garderob\", C) \"podda\"","findSv":"Vilka språk orden lånats från","methodSv":"Koppla till handel, kulturinflytande och digitalisering.","stepsSv":["A (\"borgmästare\"): lågtyska under medeltidens hansahandel.","B (\"garderob\"): franska under 1700-talets hov- och kulturinflytande.","C (\"podda\"): engelska under 2000-talet."],"answerSv":"Lågtyska, franska respektive engelska."},{"gradeLevel":"A","titleSv":"Bedöma om engelska lånord hotar svenskan","givenSv":"Påstående: \"Engelska lånord förstör svenskan.\"","findSv":"Ett nyanserat språkvetenskapligt svar","methodSv":"Skilj på lånord i ordförrådet kontra domänförlust.","stepsSv":["Historiskt har svenskan tagit emot tusentals lågtyska och franska ord utan att försvinna; grammatiken har integrerat dem.","Det verkliga hotet uppstår vid domänförlust — när hela samhällsområden som högre forskning eller näringsliv helt slutar använda svenska."],"answerSv":"Enstaka lånord berikar oftast ordförrådet, medan domänförlust inom t.ex. akademin är den reella språkliga utmaningen."}]', '[{"trapTitleSv":"Glömma att svenskt teckenspråk har lagskyddad ställning vid sidan av minoritetsspråken","wrongApproachSv":"Att blanda ihop teckenspråket med de fem nationella minoritetsspråken eller glömma det helt.","rightApproachSv":"De fem nationella minoritetsspråken är finska, jiddisch, meänkieli, romani chib och samiska; dessutom jämställs teckenspråket i språklagen."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-2-2-epoker-och-ideer', 'chap-svenska-2-2', 'epoker-och-ideer', 1, 'Litterära epoker och idéströmningar', '[{"term":"Upplysningen","definition":"1700-talsepok präglad av förnuftstro, vetenskap, religionskritik och satir."},{"term":"Romantiken","definition":"Tidigt 1800-tal med fokus på känsla, naturmystik, fantasi och konstnärligt geni."},{"term":"Realismen","definition":"1800-talsriktning som skildrar vardagen och samhällsproblem objektivt och detaljrikt."}]', '[{"heading":"Växlingen mellan förnuft och känsla genom historien","bodySv":"Litteraturhistorien rör sig ofta i pendelslag. Efter upplysningens betoning av förnuft, nyttoetik och samhällssatir slog romantiken tillbaka genom att lyfta fram det oförklarliga, naturens själ och starka känslor. Under 1800-talets senare del krävde realismen och naturalismen att litteraturen skulle skildra klasskillnader, kvinnors villkor och verklighetens baksidor utan försköning.","deepDiveSv":"I Sverige markerar August Strindbergs \"Röda rummet\" (1879) det moderna genombrottet med skarp satir mot byråkrati, press och borgerlig dubbelmoral."}]', '[]', '[{"gradeLevel":"E","titleSv":"Placera kännetecken i rätt epok","givenSv":"Känsla framför förnuft, besjälad natur, längtan bort i tid och rum.","findSv":"Vilken epok som avses","methodSv":"Jämför med upplysning och romantik.","stepsSv":["Fokus på känsla, mystik och natur är kärnan i romantiken."],"answerSv":"Romantiken."},{"gradeLevel":"C","titleSv":"Jämföra realism och naturalism","givenSv":"Två verk skildrar fattigdom i storstaden.","findSv":"Vad som skiljer naturalismen från den tidiga realismen","methodSv":"Granska synen på arv, miljö och fri vilja.","stepsSv":["Realismen skildrar samhället kritiskt men lämnar utrymme för moraliskt val.","Naturalismen ser människan deterministiskt som formad av biologiskt arv och social miljö, ofta med mörkare utgång."],"answerSv":"Naturalismen lägger till en naturvetenskaplig determinism kring arv och miljö."},{"gradeLevel":"A","titleSv":"Läsa antikens tragedi utifrån hybris och katharsis","givenSv":"I Sofokles \"Kung Oidipus\" kämpar huvudpersonen emot gudarnas spådom genom egen stolthet.","findSv":"Hur begreppen hybris och katharsis förklarar tragedins verkan","methodSv":"Koppla karaktärens övermod till publikens reaktion.","stepsSv":["Hybris är hjältens övermod att tro sig kunna överlista ödet.","Undergången framkallar fruktan och medlidande hos åskådaren, vilket Aristoteles kallade katharsis (känslomässig rening)."],"answerSv":"Hjältens hybris leder till fallet, som i sin tur ger publiken katharsis."}]', '[{"trapTitleSv":"Förväxla upplysningens \"förnuft\" med \"romantik\"","wrongApproachSv":"Att kalla sagor, spökhistorier och natursvärmeri för upplysning.","rightApproachSv":"Upplysningen står för vetenskap, satir och förnuft; romantiken står för fantasi, skräck och känsla."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-2-3-utredande-text-och-stil', 'chap-svenska-2-3', 'utredande-text-och-stil', 1, 'Frågeställning, objektivitet och textbindning', '[{"term":"Utredande text","definition":"Texttyp som belyser en frågeställning ur flera perspektiv utan att ta ensidig ställning."},{"term":"Textbindning","definition":"Hur meningar och stycken hänger ihop via sambandsord, syftningar och temabindning."}]', '[{"heading":"Skilja utredande text från argumenterande text","bodySv":"Till skillnad från en insändare eller debattartikel har den utredande texten ingen tes som ska drivas igenom. I stället utgår den från en neutral frågeställning (\"Vilka orsaker och följder har...?\"), redovisar flera synvinklar utifrån olika källor och drar i slutsatsen en balanserad sammanfattning.","deepDiveSv":"För att bevara den objektiva stilen undviks \"jag tycker\" och värderande adjektiv; i stället används passivformer eller opersonliga konstruktioner som \"det framgår att\" och \"forskningen pekar på\"."}]', '[]', '[{"gradeLevel":"E","titleSv":"Göra en rubrik objektiv och utredande","givenSv":"Subjektiv: \"Därför måste elbilar subventioneras nu!\"","findSv":"Utredande frågeställning","methodSv":"Byt ut uppmaningen mot en öppen fråga som belyser flera sidor.","stepsSv":["\"Vilka för- och nackdelar medför statliga elbilssubventioner?\""],"answerSv":"\"Vilka för- och nackdelar medför statliga elbilssubventioner?\""},{"gradeLevel":"C","titleSv":"Skapa tydlig textbindning mellan två meningar","givenSv":"\"Kollektivtrafiken byggdes ut kraftigt. Färre valde bilen.\"","findSv":"Koppla samman meningarna logiskt","methodSv":"Infoga ett kausalt sambandsord som visar orsak–verkan.","stepsSv":["\"Kollektivtrafiken byggdes ut kraftigt. Till följd av detta valde färre invånare bilen.\""],"answerSv":"Sambandsmarkören \"Till följd av detta\" tydliggör orsakssambandet."},{"gradeLevel":"A","titleSv":"Syntetisera två källor i samma stycke","givenSv":"Källa A betonar höga kostnader för ny järnväg; Källa B lyfter minskade utsläpp på lång sikt.","findSv":"Ett sammanvävt stycke i utredande stil","methodSv":"Ställ källorna i dialog med varandra via koncessiv markör.","stepsSv":["\"Ekonomer i Källa A varnar för att investeringskostnaderna blir höga på kort sikt. Samtidigt framhåller klimatforskare i Källa B att utbyggnaden på sikt kan minska transportsektorns utsläpp.\""],"answerSv":"Genom kontrastmarkören \"Samtidigt\" ställs källorna mot varandra utan att skribenten tar ställning."}]', '[{"trapTitleSv":"Glida in i argumenterande ton i slutet av en utredande text","wrongApproachSv":"Att avsluta med \"Därför måste politikerna genast införa detta!\"","rightApproachSv":"Avsluta i stället med att besvara frågeställningen nyanserat utifrån de redovisade källorna."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-3-1-pm-och-problemformulering', 'chap-svenska-3-1', 'pm-och-problemformulering', 1, 'PM-struktur och vetenskaplig frågeställning', '[{"term":"PM (Promemoria)","definition":"Kortfattad vetenskapligt upplagd utredning med inledning, frågeställning, analys och slutsats."},{"term":"Avgränsning","definition":"Att snäva in ett brett ämne till en hanterbar och besvarbar fråga."}]', '[{"heading":"Från brett ämne till prövbar frågeställning","bodySv":"Ett gymnasie-PM inleds med en bakgrund som sätter läsaren in i ämnet och smalnar av ner mot ett tydligt syfte och 1–2 konkreta frågeställningar. En bra vetenskaplig frågeställning går inte att svara ja eller nej på, utan inleds ofta med \"Hur\", \"På vilket sätt\" eller \"Vilka faktorer\". I avhandlingsdelen besvaras frågan systematiskt med stöd av granskade källor.","deepDiveSv":"Den avslutande diskussionen/slutsatsen får inte introducera nya källor eller obevisade påståenden; den ska direkt svara mot inledningens frågeställning utifrån den genomförda analysen."}]', '[]', '[{"gradeLevel":"E","titleSv":"Omformulera en ja/nej-fråga till en utredande frågeställning","givenSv":"Svag fråga: \"Är läxor bra för gymnasieelever?\"","findSv":"En avgränsad vetenskaplig frågeställning","methodSv":"Ersätt \"Är...\" med \"Vilka effekter...\" och ange målgrupp.","stepsSv":["\"Vilka effekter på studieresultat och stress uppmäts vid minskad läxmängd i gymnasiet?\""],"answerSv":"\"Vilka effekter på studieresultat och stress uppmäts vid minskad läxmängd i gymnasiet?\""},{"gradeLevel":"C","titleSv":"Koppla samman syfte, huvuddel och slutsats (röd tråd)","givenSv":"Syftet gäller digitala läromedel vs tryckta böckers effekt på läsförståelse.","findSv":"Hur röd tråd säkerställs genom hela PM:et","methodSv":"Använd nyckelord från frågeställningen som underrubriker eller styckeämnen.","stepsSv":["Dela huvuddelen tematiskt i t.ex. djupläsning, distraktion och minnesbehållning.","Återkoppla i slutsatsen explicit till varje fråga från inledningen."],"answerSv":"Tematisk struktur kopplad direkt till frågeställningen skapar tydlig röd tråd."},{"gradeLevel":"A","titleSv":"Metodmedvetenhet och begränsningar i källunderlaget","givenSv":"Alla tre använda artiklar bygger på självrapporterade enkäter i stället för lästest.","findSv":"Hur detta bör lyftas i PM:ets källkritiska diskussion","methodSv":"Diskutera reliabilitet och validitet utan att underkänna hela arbetet.","stepsSv":["Självskattning mäter upplevd förståelse snarare än faktisk testprestation (begränsad validitet).","Skribenten bör påpeka att slutsatserna gäller elevernas upplevelse och att kontrollerade test behövs för säkrare orsakssamband."],"answerSv":"En kvalificerad analys synliggör skillnaden mellan självskattning och faktiska testresultat i slutdiskussionen."}]', '[{"trapTitleSv":"Införa helt nya källor i sista stycket","wrongApproachSv":"Att ta in en ny artikel i slutsatsen.","rightApproachSv":"Alla källor och fakta ska redovisas i huvuddelen; slutsatsen sammanfattar och svarar på syftet."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-3-1-kallsammanstallning-och-referat', 'chap-svenska-3-1', 'kallsammanstallning-och-referat', 2, 'Källhänvisningar, citat och källsyntes', '[{"term":"Källhänvisning i löpande text","definition":"Parenteshänvisning (Harvard) eller fotnot (Oxford) som visar exakt var uppgiften hämtats."},{"term":"Blockcitat","definition":"Längre direktcitat som sätts som eget indraget stycke utan citattecken."}]', '[{"heading":"Säkra referenser och konsekvent system","bodySv":"Vetenskapliga texter kräver full spårbarhet. Oavsett om du använder Harvardsystemet — (Andersson, 2024, s. 14) — eller Oxfordsystemet med fotnoter måste formatet vara konsekvent genom hela texten och matcha källförteckningen i slutet. När en lång referenskedja sträcker sig över flera meningar behövs upprepade referatmarkörer (\"Vidare menar Andersson...\") så läsaren vet var källans röst slutar och din egen kommentar tar vid.","deepDiveSv":"Direktcitat bör användas sparsamt och bara när den exakta ordalydelsen är avgörande. Om ett ord i ett citat utelämnas markeras det med hakparentes [...]."}]', '[]', '[{"gradeLevel":"E","titleSv":"Korrekt Harvard-hänvisning i löpande text","givenSv":"Författare Sara Lind, utgivningsår 2023, sida 42.","findSv":"Parenteshänvisning före punkt","methodSv":"Placera parentesen innan meningens punkt.","stepsSv":["Digitala verktyg förändrar anteckningstekniken (Lind, 2023, s. 42)."],"answerSv":"(Lind, 2023, s. 42)."},{"gradeLevel":"C","titleSv":"Undvika \"svävande referens\" i ett stycke","givenSv":"Mening 1: \"Enligt Holm (2022) sover unga mindre.\" Mening 2: \"Det leder till sämre minne.\" Mening 3: \"Skolan borde börja senare.\"","findSv":"Varför mening 2 och 3 blir otydliga och hur det rättas","methodSv":"Markera vad som kommer från Holm respektive skribenten.","stepsSv":["I mening 2 är det oklart om Holm påstår minnesförsämringen eller om det är skribentens egen kommentar.","Lägg till \"Hon framhåller att detta leder till...\" i mening 2 och ta bort den argumenterande rekommendationen i mening 3 i ett utredande PM."],"answerSv":"Upprepade referatmarkörer visar tydligt vilka påståenden som härrör från källan."},{"gradeLevel":"A","titleSv":"Hantera sekundärkällor korrekt","givenSv":"Du läser en artikel av Berg (2024) som nämner en studie av Ek (2018). Du har bara läst Berg.","findSv":"Hur du ska hänvisa hederligt","methodSv":"Ange aldrig en källa du inte själv har läst som om du läst originalet.","stepsSv":["Sök i första hand upp Ek (2018) direkt.","Om det inte går skriver man \"(Ek, 2018, refererad i Berg, 2024)\"."],"answerSv":"Markera sekundärkällan öppet med \"refererad i\" eller gå direkt till originalkällan."}]', '[{"trapTitleSv":"Placera källhänvisningen efter punkten i stället för före","wrongApproachSv":"Att skriva \"Skärmtid påverkar sömnen. (Lind, 2023)\"","rightApproachSv":"Parentesen tillhör meningen och sätts före punkten: \"Skärmtid påverkar sömnen (Lind, 2023).\""}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-3-1-vetenskaplig-stil-och-kriterier', 'chap-svenska-3-1', 'vetenskaplig-stil-och-kriterier', 3, 'Vetenskaplig stil, objektivitet och forskningskriterier', '[{"term":"Validitet","definition":"Om studien verkligen mäter det som den utger sig för att mäta."},{"term":"Reliabilitet","definition":"Mätningens noggrannhet och om samma resultat skulle fås vid upprepning."},{"term":"Nominalstil och hedging","definition":"Precist fackspråk med försiktiga markörer som \"indikerar\" eller \"kan tyda på\"."}]', '[{"heading":"Precision och vetenskaplig försiktighet","bodySv":"Vetenskaplig prosa undviker kategoriska överdrifter som \"bevisar bortom allt tvivel\" eller \"alla ungdomar\". I stället används nyanserande uttryck (hedging) som \"tyder på\", \"i det undersökta urvalet\" och \"under dessa förutsättningar\". För att granska en vetenskaplig text prövas även urvalets storlek, bortfall samt begreppen validitet och reliabilitet.","deepDiveSv":"En studie med bara 12 deltagare från en enda skolklass kan ha hög reliabilitet i mätningen, men låg generaliserbarhet för hela landets elever."}]', '[]', '[{"gradeLevel":"E","titleSv":"Byta talspråk mot vetenskaplig stil","givenSv":"\"Studien visar supertydligt att folk blir piggare av kaffe.\"","findSv":"Vetenskapligt omformulerad mening","methodSv":"Ersätt värdeord och vaga substantiv med precisa begrepp.","stepsSv":["\"Studien indikerar att koffeinintag kan öka vakenheten hos vuxna deltagare.\""],"answerSv":"\"Studien indikerar att koffeinintag kan öka vakenheten.\""},{"gradeLevel":"C","titleSv":"Skilja validitet från reliabilitet","givenSv":"Ett språktest mäter stavningsfel men påstås mäta \"elevernas muntliga argumentationsförmåga\".","findSv":"Vilken kvalitetssvaghet som föreligger","methodSv":"Pröva om metoden mäter rätt fenomen.","stepsSv":["Testet kan ge mycket jämna poäng vid upprepning (hög reliabilitet), men stavning mäter inte muntlig argumentation."],"answerSv":"Studien har bristande validitet eftersom den mäter fel förmåga."},{"gradeLevel":"A","titleSv":"Bedöma generaliserbarhet och bortfall","givenSv":"En enkät skickades till 1 000 hushåll men bara 90 svarade, och slutsatsen sägs gälla hela Sverige.","findSv":"Metodkritisk värdering","methodSv":"Analysera det externa bortfallet (91 %).","stepsSv":["Ett bortfall på 91 % innebär stor risk för snedvridning eftersom de som faktiskt svarar sällan är representativa för hela befolkningen.","Resultatet saknar därför statistisk generaliserbarhet till hela landet."],"answerSv":"Det extrema bortfallet gör urvalet snedvridet och omöjliggör generalisering till hela befolkningen."}]', '[{"trapTitleSv":"Påstå att en enskild studie \"bevisar\" en universell lag","wrongApproachSv":"Att skriva \"Därmed är det slutgiltigt bevisat att...\"","rightApproachSv":"Använd försiktiga verb som \"tyder på\", \"pekar mot\" eller \"stödjer antagandet\"."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-3-2-svenskans-historiska-epoker', 'chap-svenska-3-2', 'svenskans-historiska-epoker', 1, 'Runsvenska, fornsvenska, nysvenska och nusvenska', '[{"term":"Runsvenska (ca 800–1225)","definition":"Äldsta skedet, bevarat främst på runstenar i den 16-typiga futharken."},{"term":"Fornsvenska (1225–1526)","definition":"Börjar med latinska alfabetet i landskapslagarna; rikt kasussystem med fyra kasus."},{"term":"Nysvenska (1526–1906)","definition":"Inleds med Gustav Vasas bibelöversättning som lägger grunden för enhetlig svensk stavning."}]', '[{"heading":"Från böjningsrikt språk till fast ordföljd","bodySv":"I fornsvenskan visade ändelser (kasus: nominativ, genitiv, dativ, ackusativ) vem som gjorde vad i meningen, nästan som i dagens tyska eller isländska. När ändelserna nöttes bort under medeltiden och lånord strömmade in från lågtyskan blev fast ordföljd viktigare för att skilja subjekt från objekt. År 1906 genomfördes den sista stora stavningsreformen (dt blev t/tt, hv blev v, f/fv blev v).","deepDiveSv":"Uttryck som \"till sjöss\", \"i handom\" och \"man ur huse\" är fossiliserade rester av det gamla kasussystemet som lever kvar i fast form."}]', '[]', '[{"gradeLevel":"E","titleSv":"Koppla årtal till språkperiod","givenSv":"1526 (Nya testamentet på svenska) och 1906 (stavningsreformen)","findSv":"Vilka perioder dessa årtal inleder","methodSv":"Minns gränserna 1225, 1526 och 1906.","stepsSv":["1526 inleder nysvenskan; 1906 inleder nusvenskan."],"answerSv":"1526: äldre nysvenska; 1906: nusvenska."},{"gradeLevel":"C","titleSv":"Förklara stelnade kasusuttryck","givenSv":"Uttrycken \"till skogs\" och \"i godan ro\"","findSv":"Varför ändelserna finns kvar här","methodSv":"Koppla till genitiv och ackusativ/dativ efter preposition.","stepsSv":["I fornsvenskan styrde prepositionen \"till\" genitiv (\"till skogs\"), och \"i\" kunde styra maskulin ackusativ (\"godan\").","Uttrycken stelnade som fasta fraser innan kasusböjningen försvann."],"answerSv":"De är bevarade kasusrester från fornsvenskan som överlevt som fasta uttryck."},{"gradeLevel":"A","titleSv":"Sambandet mellan boktryckarkonst och enhetlig stavning","givenSv":"Under 1500-talet trycktes Gustav Vasas bibel och spreds över hela landet.","findSv":"Vilken roll boktryckarkonsten och bibeln spelade för rikssvenskans uppkomst","methodSv":"Jämför handskrivna regionala texter med tryckta upplagor.","stepsSv":["Före tryckkonsten stavade skrivare ofta efter lokal dialekt.","Masspridda tryckta texter krävde gemensamma stavningsnormer (t.ex. bokstäverna å, ä, ö för att skilja sig från danskan) och spred en enhetlig skriftspråksnorm."],"answerSv":"Tryckta skrifter standardiserade stavning och böjning nationellt och lade grunden till dagens rikssvenska."}]', '[{"trapTitleSv":"Tro att runsvenskan skrevs med latinska bokstäver","wrongApproachSv":"Att blanda ihop runraden med handskrivna pergamentböcker på latin.","rightApproachSv":"Latinska alfabetet slog igenom med kyrkan och landskapslagarna (Äldre Västgötalagen ca 1225), vilket markerar fornsvenskans början."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-svenska-3-3-litteraturvetenskapliga-perspektiv', 'chap-svenska-3-3', 'litteraturvetenskapliga-perspektiv', 1, 'Litteraturvetenskapliga analysmodeller', '[{"term":"Intertextualitet","definition":"Hur en text anspelar på, citerar eller samtalar med tidigare verk."},{"term":"Genusperspektiv","definition":"Analysmodell som granskar könsroller, makt och normer i texten."}]', '[{"heading":"Läsa samma verk genom olika teoretiska linser","bodySv":"I Svenska 3 fördjupas den litterära analysen genom teoretiska perspektiv. En närläsning fokuserar enbart på textens form, bildspråk och komposition, medan ett historiskt-biografiskt, feministiskt eller ekokritiskt perspektiv sätter verket i relation till samhälle, maktförhållanden och natur. Ingen modell är \"rätt\" i sig — det avgörande är att tolkningen beläggs med textexempel.","deepDiveSv":"I lyrisk analys undersöks även versmått, enjambement (överklivning mellan rader) och rytmens samspel med diktens motiv."}]', '[]', '[{"gradeLevel":"E","titleSv":"Känna igen intertextualitet","givenSv":"En modern ungdomsroman har en ung karaktär vid namn Ofelia som sjunker ner i en å omgiven av blommor.","findSv":"Varför detta är intertextualitet","methodSv":"Koppla till kända klassiska verk.","stepsSv":["Namnet och scenen anspelar direkt på Ofelia i Shakespeares \"Hamlet\"."],"answerSv":"Texten skapar en intertextuell blinkning till Shakespeares \"Hamlet\"."},{"gradeLevel":"C","titleSv":"Analysera enjambement (överklivning) i poesi","givenSv":"\"Hon stod vid kanten av / allt hon en gång älskat.\"","findSv":"Vilken effekt radbrytningen efter \"av\" skapar","methodSv":"Läs pausen vid radslutet.","stepsSv":["Pausen mitt i frasen \"kanten av / allt\" skapar ett kort svävande ögonblick — som om läsaren själv står vid stupet innan nästa rad tar vid."],"answerSv":"Överklivningen förstärker känslan av tvekan och avgrund."},{"gradeLevel":"A","titleSv":"Tillämpa två perspektiv på samma romanpassage","givenSv":"I en 1800-talsroman stängs huvudpersonen in i sitt rum \"för sitt eget bästa\" medan mannen sköter ekonomin.","findSv":"Skillnaden mellan närläsning och genuskritisk läsning","methodSv":"Kontrastera textinternt fokus med samhällsmakt.","stepsSv":["Närläsning betonar symboliken i det låsta rummet som spegling av inre klaustrofobi.","Genusanalys undersöker hur lagen, ekonomin och patriarkala normer fråntar kvinnan handlingsutrymme under förevändningen av beskydd."],"answerSv":"Närläsningen belyser rummets symbolik, medan genusperspektivet synliggör maktordningen bakom instängdheten."}]', '[{"trapTitleSv":"Göra en litterär analys utan textbelägg","wrongApproachSv":"Att skriva att \"dikten handlar om makt\" utan att visa med citat eller rader.","rightApproachSv":"Belägg varje tolkning med exakta citat eller konkreta detaljer ur texten."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-5-1-skimming-scanning-och-innehall', 'chap-engelska-5-1', 'skimming-scanning-och-innehall', 1, 'Läsförståelse: skimming, scanning och att läsa mellan raderna', '[{"term":"Skimming","definition":"Översiktsläsning för att snabbt fånga textens huvudbudskap och ton."},{"term":"Scanning","definition":"Sökläsning efter en specifik detalj som ett årtal, namn eller siffervärde."},{"term":"Inferens","definition":"Att dra rimliga slutsatser utifrån ledtrådar i texten trots att det inte står ordagrant."}]', '[{"heading":"Tre effektiva lässtrategier på provet","bodySv":"Vid läsförståelse i Engelska 5 gäller det att anpassa lästempot till frågan. Börja med skimming — läs rubrik, första stycket och de inledande meningarna (topic sentences) i varje stycke — för att förstå textens struktur. När frågan gäller en specifik siffra eller händelse använder du scanning och söker visuellt efter nyckelord eller synonymer. Frågor på C- och A-nivå prövar ofta inferens eller skribentens attityd, där svaret uttrycks med andra ord än i källtexten.","deepDiveSv":"En vanlig fälla på flervalsuppgifter är alternativ som återanvänder exakta ord från texten men vänder på innebörden genom ett \"not\", \"rarely\" eller ändrad syftning."}]', '[]', '[{"gradeLevel":"E","titleSv":"Hitta huvudsyftet via översiktsläsning","givenSv":"Passage: \"Every winter, thousands of commuters switch from cars to electric bicycles. Although battery range drops slightly in freezing weather, studded tyres and dedicated winter bike lanes have made year-round cycling safer than ever.\"","findSv":"Textens huvudsakliga poäng","methodSv":"Sammanfatta första och sista satsens kärna utan detaljer.","stepsSv":["Första meningen slår fast att allt fler pendlar med elcykel på vintern.","Andra meningen medger ett litet hinder (\"battery range drops\") men betonar varför vintercykling ändå blivit tryggare."],"answerSv":"Texten förklarar varför vinterpendling med elcykel växer och har blivit säkrare."},{"gradeLevel":"C","titleSv":"Tolka attityd och ordval (inferens)","givenSv":"Passage: \"The city council promised a seamless transition to the new ticketing app. Three months later, commuters are still queuing at broken machines while the helpline plays hold music.\"","findSv":"Vilken attityd skribenten intar till kommunens lansering","methodSv":"Jämför löftet (\"promised a seamless transition\") med den beskrivna verkligheten.","stepsSv":["Kontrasten mellan \"seamless\" och trasiga automater plus telefonkö skapar tydlig ironi.","Skribenten är kritisk och skeptisk till att projektet fungerat som utlovat."],"answerSv":"Skribenten är ironiskt kritisk till en misslyckad lansering."},{"gradeLevel":"A","titleSv":"Förstå omskrivning (parafras) i svarsalternativ","givenSv":"Passage: \"Far from discouraging local shopkeepers, the pedestrian-only zone boosted footfall during evening hours.\"","findSv":"Vad \"Far from discouraging...\" betyder för butiksägarnas inställning och resultat","methodSv":"Analysera negeringskonstruktionen \"Far from + -ing\".","stepsSv":["\"Far from discouraging\" betyder \"långt ifrån att avskräcka\", alltså det motsatta.","\"Boosted footfall\" betyder att antalet besökare till fots ökade."],"answerSv":"Gågatan avskräckte inte alls handlarna, utan ökade i stället antalet kvällsbesökare."}]', '[{"trapTitleSv":"Gå på exakta nyckelord i felaktiga svarsalternativ","wrongApproachSv":"Att välja ett alternativ bara för att ordet \"discouraging\" råkar stå i både texten och alternativet.","rightApproachSv":"Läs hela frasen runt nyckelordet (\"Far from discouraging...\") och kontrollera om betydelsen är omvänd."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-5-1-formellt-och-informellt-register', 'chap-engelska-5-1', 'formellt-och-informellt-register', 2, 'Formellt och informellt register', '[{"term":"Formellt register","definition":"Sakligt, neutralt språk utan sammandragningar (don''t) eller slang, använt i essäer och formella brev."},{"term":"Informellt register","definition":"Vardagligt, personligt språk med sammandragningar, partikelverb och uttryck för känslor."}]', '[{"heading":"Anpassa tonen till mottagare och texttyp","bodySv":"I engelskan är skillnaden mellan talspråkligt vardagsregister och skriftligt formellt register tydlig. I formella uppgifter (t.ex. debattartikel, formellt mejl till rektor eller utredande essä) undviks sammandragningar (\"cannot\" i stället för \"can''t\", \"it is\" i stället för \"it''s\"), talspråkliga förkortningar (\"gonna\", \"wanna\", \"a lot of\") samt slang. Partikelverb ersätts ofta av ett exakt latinskt/romanskt verb: \"find out\" blir \"investigate\" eller \"discover\", och \"put off\" blir \"postpone\".","deepDiveSv":"Undvik också att blanda register i samma text — en formell rapport som plötsligt innehåller \"kids\" eller \"super cool\" tappar trovärdighet."}]', '[]', '[{"gradeLevel":"E","titleSv":"Byta ut sammandragning och slang till formellt språk","givenSv":"Informal: \"Kids don''t get why recycling is kinda important.\"","findSv":"En formell omskrivning","methodSv":"Ersätt \"kids\", \"don''t\", \"get\" och \"kinda\".","stepsSv":["\"Young people do not always understand why recycling is essential.\""],"answerSv":"\"Young people do not always understand why recycling is essential.\""},{"gradeLevel":"C","titleSv":"Ersätta partikelverb med formella verb","givenSv":"Sentence: \"The board decided to put off the meeting until they could look into the budget issue.\"","findSv":"Formellare verb för \"put off\" och \"look into\"","methodSv":"Välj exakta enkla verb.","stepsSv":["\"put off\" → \"postpone\"; \"look into\" → \"examine\" eller \"investigate\"."],"answerSv":"\"The board decided to postpone the meeting until they could investigate the budget issue.\""},{"gradeLevel":"A","titleSv":"Inleda och avsluta ett formellt mejl med korrekt artighetsnivå","givenSv":"Du skriver till en brittisk universitetskoordinator vars namn du inte känner.","findSv":"Korrekt tilltalsfras och avslutningsfras","methodSv":"Följ konventionen för okänd mottagare.","stepsSv":["Hälsning: \"Dear Sir or Madam,\" eller \"Dear Admissions Team,\" (aldrig \"Hey!\").","Avslutning när mottagarens namn är okänt: \"Yours faithfully,\" (vid känt namn används \"Yours sincerely,\")."],"answerSv":"Inled med \"Dear Sir or Madam,\" och avsluta med \"Yours faithfully,\"."}]', '[{"trapTitleSv":"Använda slang eller sammandragningar i formella essäer","wrongApproachSv":"Att skriva \"I think it''s gonna cause lots of problems for guys.\"","rightApproachSv":"Skriv neutralt och fullt ut: \"This development is likely to create significant challenges.\""}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-5-1-centrala-verbformer-och-ordfoljd', 'chap-engelska-5-1', 'centrala-verbformer-och-ordfoljd', 3, 'Central engelsk grammatik: kongruens, it/there och tempus', '[{"term":"Kongruens (subject-verb agreement)","definition":"Verbet böjs efter subjektets antal: \"he walks\" men \"they walk\"."},{"term":"Det formella subjektet (it vs there)","definition":"\"There is/are\" anger existens (\"det finns\"), medan \"it is\" används om väder, tid, avstånd och omdömen."}]', '[{"heading":"Svenska fällor i engelsk grammatik","bodySv":"Tre fel återkommer särskilt ofta hos svenska gymnasieelever. För det första översätts svenskans \"det\" felaktigt: när \"det\" betyder \"det finns/existerar\" måste engelskan ha \"there is/there are\", inte \"it is\". För det andra styrs verbet efter \"there\" av det egentliga subjektet som kommer efteråt (\"There are three reasons\", inte \"There is three reasons\"). För det tredje kräver \"everybody\", \"everyone\" och \"everything\" alltid singularverb (\"Everybody knows\", inte \"Everybody know\").","deepDiveSv":"Observera också skillnaden mellan pågående form (present continuous: \"I am reading right now\") och enkel form (\"I read every morning\"), samt att oräknebara substantiv som \"information\", \"advice\" och \"news\" tar singularverb (\"The news is encouraging\")."}]', '[]', '[{"gradeLevel":"E","titleSv":"Välja mellan \"it\" och \"there\"","givenSv":"Mening: \"___ are several libraries in this town.\"","findSv":"Rätt inledningsord","methodSv":"Pröva om meningen betyder \"det finns\".","stepsSv":["Meningen anger att bibliotek existerar i staden → \"There are several libraries...\"."],"answerSv":"\"There\" (med pluralverbet \"are\")."},{"gradeLevel":"C","titleSv":"Kongruens med \"everybody\" och oräknebara ord","givenSv":"Fel: \"Everyone in the two classes have read the informations.\"","findSv":"Två grammatiska rättelser","methodSv":"Kontrollera subjektet \"Everyone\" och oräknebara \"information\".","stepsSv":["\"Everyone\" är alltid singular → \"has read\".","\"Information\" är oräknebart på engelska och saknar plural-s → \"the information\"."],"answerSv":"\"Everyone in the two classes has read the information.\""},{"gradeLevel":"A","titleSv":"Subjekt–predikatkongruens vid långa bestämningar","givenSv":"Mening: \"The quality of the articles published in recent journals (has / have) improved.\"","findSv":"Rätt verbform och varför","methodSv":"Identifiera huvudordet i subjektfrasen före prepositionsfrasen \"of...\".","stepsSv":["Subjektets huvudord är \"The quality\" (singular), inte \"articles\" eller \"journals\".","Därför ska verbet stå i singular: \"has improved\"."],"answerSv":"\"has improved\" eftersom huvudordet \"quality\" är singular."}]', '[{"trapTitleSv":"Översätta \"Det finns många skäl\" med \"It is many reasons\"","wrongApproachSv":"Att skriva \"It is many reasons to learn English.\"","rightApproachSv":"Skriv \"There are many reasons to learn English\" — både rätt pronomen (\"there\") och pluralverb (\"are\")."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-5-2-styckeindelning-och-lankord', 'chap-engelska-5-2', 'styckeindelning-och-lankord', 1, 'Styckeuppbyggnad med kärnmening och länkord', '[{"term":"Topic sentence","definition":"Styckets första mening som anger exakt vad stycket handlar om."},{"term":"Linking words","definition":"Sambandsord som \"however\", \"moreover\", \"consequently\" och \"for instance\"."}]', '[{"heading":"Ett tema per stycke (PEEL-strukturen)","bodySv":"Varje brödtextstycke i en engelsk essä bör följa en tydlig logisk bana: börja med din kärnmening (Point), förklara tanken närmare (Explain), ge ett konkret exempel (Example) och knyt tillbaka till huvudfrågan (Link). Länkord som \"However,\" och \"Furthermore,\" skiljs från resten av meningen med kommatecken när de står först.","deepDiveSv":"Kontrollera skillnaden mellan \"although\" (konjunktion följd av bisats: \"Although it rained, we went out\") och \"despite\" (preposition följd av substantiv/ing-form: \"Despite the rain, we went out\")."}]', '[]', '[{"gradeLevel":"E","titleSv":"Välja rätt kontrastord","givenSv":"\"Public transport is affordable. ___, it can be crowded during rush hour.\"","findSv":"Lämpligt länkord","methodSv":"Andra meningen uttrycker en invändning.","stepsSv":["\"However,\" visar kontrast mellan fördel och nackdel."],"answerSv":"\"However,\"."},{"gradeLevel":"C","titleSv":"Skilja på \"although\" och \"despite\"","givenSv":"Kombination A: \"___ the high cost, the project succeeded.\" Kombination B: \"___ it was expensive, the project succeeded.\"","findSv":"Placera \"Although\" och \"Despite\" rätt","methodSv":"Se om det följer ett substantiv (fras) eller en fullständig sats.","stepsSv":["I A följer substantivfrasen \"the high cost\" → \"Despite\".","I B följer subjekt + verb (\"it was\") → \"Although\"."],"answerSv":"A: \"Despite\", B: \"Although\"."},{"gradeLevel":"A","titleSv":"Formulera en stark topic sentence","givenSv":"Svag start: \"Now I will write about remote work and why I like it.\"","findSv":"Saklig topic sentence till ett stycke om produktivitet","methodSv":"Skippa metakommentaren (\"Now I will write\") och ange direkt styckets huvudtanke.","stepsSv":["\"Remote work can significantly increase productivity by reducing daily commuting stress.\""],"answerSv":"\"Remote work can significantly increase productivity by reducing daily commuting stress.\""}]', '[{"trapTitleSv":"Skriva \"Despite of the rain\"","wrongApproachSv":"Att blanda ihop \"despite\" med \"in spite of\".","rightApproachSv":"Skriv antingen \"despite the rain\" (utan \"of\") eller \"in spite of the rain\"."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-5-3-kollokationer-och-falska-vanner', 'chap-engelska-5-3', 'kollokationer-och-falska-vanner', 1, 'Kollokationer och svensk-engelska falska vänner', '[{"term":"Kollokation","definition":"Ord som naturligt hör ihop, som \"make a decision\" eller \"heavy rain\"."},{"term":"Falsk vän","definition":"Engelskt ord som liknar ett svenskt ord men har helt annan betydelse."}]', '[{"heading":"Undvika direkta översättningslån från svenskan","bodySv":"Många misstag i engelska uppstår när svenska uttryck översätts ord för ord. \"Eventually\" betyder inte \"eventuellt\" utan \"till slut / omsider\" (\"possibly\" motsvarar eventuellt). \"Actually\" betyder \"faktiskt / i själva verket\" (inte \"aktuellt\", som heter \"current\"). Och man gör inte \"a decision\" med \"do\" utan \"make a decision\", liksom \"do homework\".","deepDiveSv":"Andra viktiga par: \"sensible\" (förnuftig) kontra \"sensitive\" (känslig), samt \"fabric\" (tyg) kontra \"factory\" (fabrik)."}]', '[]', '[{"gradeLevel":"E","titleSv":"Rätta falsk vän med \"eventually\"","givenSv":"Felaktig avsikt: \"Eventually I might join the trip, depending on the cost.\"","findSv":"Varför \"eventually\" blir missvisande och vilket ord som passar","methodSv":"Översätt \"eventually\" korrekt.","stepsSv":["\"Eventually\" betyder \"slutligen\", medan svenskt \"eventuellt\" heter \"possibly\" eller \"perhaps\"."],"answerSv":"Byt \"Eventually\" mot \"Possibly\" eller \"Perhaps\"."},{"gradeLevel":"C","titleSv":"Välja rätt verb i kollokationer","givenSv":"\"We need to ___ a decision before Friday, and I still have to ___ my research.\"","findSv":"Rätt kombination av \"make\" och \"do\"","methodSv":"Kollokation: \"make a decision\", \"do research\".","stepsSv":["Första luckan: \"make\"; andra luckan: \"do\"."],"answerSv":"\"make a decision\" och \"do my research\"."},{"gradeLevel":"A","titleSv":"Skilja mellan \"sensible\" och \"sensitive\"","givenSv":"Context: \"Given the budget deficit, postponing the renovation was a ___ decision, even though the topic remains ___.\"","findSv":"Placera \"sensible\" och \"sensitive\" rätt","methodSv":"Pröva betydelsen \"förnuftig\" kontra \"känslig\".","stepsSv":["Ett genomtänkt ekonomiskt beslut är \"sensible\" (förnuftigt).","Ett känsloladdat ämne är \"sensitive\" (känsligt)."],"answerSv":"Först \"sensible\", sedan \"sensitive\"."}]', '[{"trapTitleSv":"Översätta \"fabrik\" med \"fabric\"","wrongApproachSv":"Att skriva \"My aunt works in a car fabric.\"","rightApproachSv":"\"Fabric\" betyder tyg; fabrik heter \"factory\" eller \"plant\"."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-6-1-akademisk-ton-och-lankord', 'chap-engelska-6-1', 'akademisk-ton-och-lankord', 1, 'Akademisk ton, nominalisering och avancerade länkord', '[{"term":"Objektiv röst","definition":"Att undvika personligt \"I think\" till förmån för sakliga belägg och passiva eller opersonliga satser."},{"term":"Nominalisering","definition":"Att omvandla verb och adjektiv till substantivfraser för tätare sakprosa, t.ex. \"implement\" → \"implementation\"."}]', '[{"heading":"Lyfta en text från vardaglig essä till formell sakprosa","bodySv":"I Engelska 6 förväntas du behärska ett mer nyanserat och formellt skriftspråk. Det märks bland annat i hur samband uttrycks: \"so\" och \"but\" ersätts av exakta konjunktioner och adverbial som \"consequently\", \"nonetheless\" och \"whereas\". Dessutom sammanfattas långa bisatser ofta med nominaliseringar eller tydliga referenser som \"This trend...\".","deepDiveSv":"Jämför: \"Because cities are growing fast, housing is expensive\" med det tätare akademiska alternativet: \"Rapid urban growth has driven up housing costs.\""}]', '[]', '[{"gradeLevel":"E","titleSv":"Byta ut \"so\" och \"but\" mot formella markörer","givenSv":"\"Electric buses cost more upfront, but they save money long term.\"","findSv":"Formell omformulering med \"Although\" eller \"However\"","methodSv":"Ersätt \"but\" och jämna till ordvalen.","stepsSv":["\"Although electric buses require higher initial investment, they reduce long-term operating costs.\""],"answerSv":"\"Although electric buses require higher initial investment, they reduce long-term operating costs.\""},{"gradeLevel":"C","titleSv":"Skapa sammanhang med \"whereas\" och nominalisering","givenSv":"\"Country A invested in rail. Country B expanded highways.\"","findSv":"En sammanhängande kontrastmening","methodSv":"Koppla med \"whereas\" som markerar direkt kontrast mellan två fall.","stepsSv":["\"While Country A prioritized railway expansion, Country B invested heavily in highway infrastructure.\""],"answerSv":"\"Country A prioritized railway expansion, whereas Country B expanded its highway network.\""},{"gradeLevel":"A","titleSv":"Rätta felaktigt bruk av \"This\" utan huvudord","givenSv":"Otydligt: \"Emissions rose by 4 %. This worried researchers.\"","findSv":"Precis akademisk syftning (shell noun)","methodSv":"Lägg till ett sammanfattande substantiv efter \"This\".","stepsSv":["\"Emissions rose by 4 %. This unexpected surge alarmed climate researchers.\""],"answerSv":"Genom att lägga till \"unexpected surge\" efter \"This\" blir syftningen entydig."}]', '[{"trapTitleSv":"Överanvända \"However\" inne i en mening som bindeord med bara komma","wrongApproachSv":"Att skriva \"The plan is expensive, however, it works.\" (comma splice!).","rightApproachSv":"\"However\" är ett adverb, inte en konjunktion: använd semikolon eller punkt före: \"...expensive; however, it works.\""}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-6-1-retorisk-analys-av-engelsk-sakprosa', 'chap-engelska-6-1', 'retorisk-analys-av-engelsk-sakprosa', 2, 'Retorisk analys av engelsk sakprosa och tal', '[{"term":"Rhetorical devices","definition":"Stilmedel som anaphora, antithesis, inclusive \"we\" och loaded language."},{"term":"Tone and register","definition":"Skribentens attityd (t.ex. urgent, measured, satirical) och stilnivå."}]', '[{"heading":"Analysera hur en engelsk text övertygar","bodySv":"När du analyserar en engelsk debattartikel eller ett tal beskriver du inte bara VAD texten handlar om, utan HUR språket används för att påverka läsaren. Håll utkik efter värdeladdade ord (loaded language), inklusivt \"we\" som skapar gemenskap, antiteser (två kontrasterande idéer sida vid sida) samt hur skribenten bygger auktoritet.","deepDiveSv":"Var noga med att i analysen skilja på själva citatet (på engelska) och effekten av greppet (förklarad klart på svenska i svensk provkontext)."}]', '[]', '[{"gradeLevel":"E","titleSv":"Identifiera inklusivt \"we\" i ett tal","givenSv":"Excerpt: \"We cannot wait for another generation to fix the problem we created together.\"","findSv":"Hur pronomenet \"we\" påverkar lyssnaren","methodSv":"Pröva om \"we\" inkluderar både talaren och publiken.","stepsSv":["Talaren skapar gemensamt ansvar och samhörighet med åhörarna."],"answerSv":"Inklusivt \"we\" skapar vi-känsla och gemensamt moraliskt ansvar."},{"gradeLevel":"C","titleSv":"Analysera antites och parallellism","givenSv":"Excerpt: \"We need policies built on evidence, not slogans driven by fear.\"","findSv":"Vilka stilgrepp som förstärker kontrasten","methodSv":"Jämför den symmetriska grammatiken och motsatsparen.","stepsSv":["Parallell struktur: \"policies built on evidence\" ställs direkt mot \"slogans driven by fear\".","Antitesen kontrasterar saklighet (\"evidence\") med populism (\"fear\")."],"answerSv":"Parallellism och antites skärper motsättningen mellan fakta och rädsla."},{"gradeLevel":"A","titleSv":"Granska dold värdering (loaded language) i en skenbart neutral rapport","givenSv":"Excerpt: \"While independent economists raised valid concerns, a handful of activists clung to outdated claims.\"","findSv":"Hur ordvalet avslöjar skribentens partiskhet","methodSv":"Kontrastera beskrivningen av ekonomerna mot aktivisterna.","stepsSv":["Ekonomerna får positiva och auktoritära markörer: \"independent\" och \"valid concerns\".","Aktivisterna förminskas genom mängdordet \"a handful\", verbet \"clung to\" (klamrade sig fast) och adjektivet \"outdated\"."],"answerSv":"Genom värdeladdade kontraster framställs den ena sidan som saklig och den andra som obetydlig och föråldrad."}]', '[{"trapTitleSv":"Bara peka ut stilfigurer utan att förklara deras verkan","wrongApproachSv":"Att skriva \"Texten använder en metafor i rad 4\" utan fortsättning.","rightApproachSv":"Koppla alltid greppet till dess effekt: vad får det läsaren att känna, tänka eller acceptera?"}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-6-1-komplex-meningsbyggnad-och-passiv', 'chap-engelska-6-1', 'komplex-meningsbyggnad-och-passiv', 3, 'Passiv form, relativsatser och kommatering', '[{"term":"Passiv form (passive voice)","definition":"Fokuserar på handlingen eller resultatet i stället för den som utför den: \"The study was published\"."},{"term":"Nödvändig vs icke-nödvändig relativsats","definition":"\"That/who\" utan komma avgränsar, medan \", which/who,\" med komma ger en extra upplysning."}]', '[{"heading":"Kommatering av relativsatser och aktiv vs passiv stil","bodySv":"I akademisk och journalistisk engelska spelar kommatecken runt relativsatser stor betydelse för meningen. I \"The students who studied hard passed\" avgränsas exakt vilka studenter som klarade sig (inga komman, \"who\" eller \"that\" kan användas). I \"The students, who studied hard, passed\" säger man att ALLA studenter pluggade hårt och klarade sig (komman krävs, och \"that\" får inte användas efter komma).","deepDiveSv":"Passiv form bildas med \"be + perfekt particip\" (\"is analysed\", \"was conducted\") och passar när aktören är okänd eller oviktig — men överdriven passiv gör texten tung och abstrakt."}]', '[]', '[{"gradeLevel":"E","titleSv":"Omskrivning från aktiv till passiv form","givenSv":"Active: \"Researchers conducted the survey in 2024.\"","findSv":"Passiv motsvarighet","methodSv":"Flytta objektet \"the survey\" till subjektplatsen och använd \"was + conducted\".","stepsSv":["\"The survey was conducted in 2024 (by researchers).\""],"answerSv":"\"The survey was conducted in 2024.\""},{"gradeLevel":"C","titleSv":"Välja mellan \"who\", \"which\" och \"that\" med komman","givenSv":"\"My sister, ___ lives in Bristol, is an architect.\"","findSv":"Rätt relativpronomen","methodSv":"Eftersom bisatsen är omgiven av komman (icke-nödvändig) får \"that\" aldrig användas.","stepsSv":["Det gäller en person (\"my sister\") efter komma → \"who\"."],"answerSv":"\"who\" (aldrig \"that\" efter komma)."},{"gradeLevel":"A","titleSv":"Rätta hängande participkonstruktion (dangling participle)","givenSv":"Fel: \"Walking through the archive, the old letters immediately caught my eye.\"","findSv":"Varför meningen blir logiskt skev och hur den rättas","methodSv":"Kontrollera vem som utför handlingen \"Walking\" (subjektet i huvudsatsen).","stepsSv":["Huvudsatsens subjekt är \"the old letters\", vilket grammatiskt får det att låta som om breven gick genom arkivet.","Gör personen till subjekt i huvudsatsen: \"Walking through the archive, I immediately noticed the old letters.\""],"answerSv":"\"Walking through the archive, I immediately noticed the old letters.\""}]', '[{"trapTitleSv":"Sätta \"that\" efter kommatecken i en parentetisk relativsats","wrongApproachSv":"Att skriva \"The report, that was published yesterday, is crucial.\"","rightApproachSv":"Efter komma måste \"which\" (för saker) eller \"who\" (för personer) användas: \"The report, which was published yesterday, is crucial.\""}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-6-2-kallsyntes-och-motargument', 'chap-engelska-6-2', 'kallsyntes-och-motargument', 1, 'Källintegration och motargument på engelska', '[{"term":"Signal phrase","definition":"Inledande referatfras som \"According to Smith (2024),\" eller \"As Patel argues,\"."},{"term":"Concession","definition":"Att medge en styrka i motståndarens ståndpunkt (\"Admittedly,\", \"While it is true that...\") före eget bemötande."}]', '[{"heading":"Integrera källor smidigt utan droppade citat","bodySv":"Ett citat eller referat bör aldrig stå helt fristående som en egen mening utan inledning (dropped quote). Väva i stället in källan i din egen meningsbyggnad med en signalfras och följ upp med egen analys. När du bemöter motargument skapar fraser som \"Admittedly...\" följt av \"Nevertheless...\" en mogen och balanserad argumentation.","deepDiveSv":"Variera dina engelska referatverb efter sammanhang: \"observes\" (konstaterar), \"contends\" (hävdar), \"demonstrates\" (visar) eller \"questions\" (ifrågasätter)."}]', '[]', '[{"gradeLevel":"E","titleSv":"Integrera ett kort citat med signalfras","givenSv":"Citat av Dr. Lee: \"Sleep deprivation impairs memory consolidation.\"","findSv":"Inbäddad mening","methodSv":"Inled med signalfras och verb i presens.","stepsSv":["As Dr. Lee points out, \"sleep deprivation impairs memory consolidation.\""],"answerSv":"\"As Dr. Lee points out, ''sleep deprivation impairs memory consolidation.''\""},{"gradeLevel":"C","titleSv":"Bygga ett balanserat motargument med medgivande","givenSv":"Tes: \"Universities should retain in-person lectures.\" Invändning: \"Recorded videos offer flexible scheduling.\"","findSv":"Tvåsatser med concession + rebuttal","methodSv":"Börja med \"While it is true that...\" och vänd med \"nevertheless\".","stepsSv":["\"While recorded lectures certainly offer greater scheduling flexibility, live seminars foster spontaneous debate that pre-recorded videos cannot replicate.\""],"answerSv":"Konstrukturen erkänner flexibiliteten men försvarar tesen med direkt akademisk interaktion."},{"gradeLevel":"A","titleSv":"Granska anekdotisk bevisföring i engelsk debattartikel","givenSv":"Excerpt: \"My cousin skipped university and built a thriving app, proving that higher education is pointless.\"","findSv":"Vilket argumentationsfel som begås","methodSv":"Pröva slutsatsens underlag.","stepsSv":["Ett enda personligt exempel (anekdotiskt belägg) kan inte generaliseras till att gälla hela utbildningssystemet (hasty generalization)."],"answerSv":"Texten bygger på en förhastad generalisering utifrån en enstaka anekdot."}]', '[{"trapTitleSv":"Slänga in ett fristående citat utan förklaring","wrongApproachSv":"Att skriva en mening och direkt därefter sätta ett helt citat inom citattecken utan inledande fras.","rightApproachSv":"Koppla alltid citatet grammatiskt till din text med en signalfras och kommentera vad det visar."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-6-3-karaktarisering-och-subtext', 'chap-engelska-6-3', 'karaktarisering-och-subtext', 1, 'Karaktärisering, bildspråk och foreshadowing', '[{"term":"Foreshadowing","definition":"Subtila ledtrådar tidigt i berättelsen som förebådar vad som ska hända senare."},{"term":"Show, don''t tell","definition":"Att avslöja känslor genom handlingar, miljö och kroppsspråk i stället för att bara nämna dem."}]', '[{"heading":"Tolka stämning och karaktär i engelsk skönlitteratur","bodySv":"I skönlitterära utdrag förmedlar författare ofta spänning och inre konflikter indirekt genom miljöskildring, korta meningar eller symbolik. När vädret eller omgivningen speglar huvudpersonens sinnesstämning kallas greppet pathetic fallacy. Observera även skillnaden mellan verbal ironi och dramatisk ironi (när läsaren vet något viktigt som karaktären själv ännu inte känner till).","deepDiveSv":"Kom ihåg tempuskonventionen vid litteraturanalys: själva handlingen i en bok återges alltid i litterärt presens (\"In Chapter 2, Maya discovers...\"), även om romanen själv är skriven i preteritum."}]', '[]', '[{"gradeLevel":"E","titleSv":"Känna igen \"show, don''t tell\"","givenSv":"Excerpt: \"He folded the letter three times until its creases turned white, then stared out at the empty driveway.\"","findSv":"Vilken känsla som gestaltas indirekt","methodSv":"Tolka kroppsspråket och blicken ut mot den tomma uppfarten.","stepsSv":["Det hårda vikandet och blicken mot uppfarten visar spänning, besvikelse eller rastlös väntan."],"answerSv":"Handlingen gestaltar stark oro, besvikelse eller otålig väntan utan att nämna orden."},{"gradeLevel":"C","titleSv":"Identifiera dramatisk ironi","givenSv":"Läsaren har just sett att båtens skrov läcker, men kaptenen säger glatt till besättningen: \"Nothing can stop us reaching harbour tonight.\"","findSv":"Vilket litterärt grepp som skapar spänning","methodSv":"Jämför läsarens kunskap med karaktärens uttalande.","stepsSv":["Läsaren vet om faran medan kaptenen är ovetande och alltför säker."],"answerSv":"Dramatisk ironi, som skapar ödesmättad spänning inför det kommande misslyckandet."},{"gradeLevel":"A","titleSv":"Analysera pathetic fallacy och rytm","givenSv":"Excerpt: \"The wind rattled the shutters. One hinge snapped. Another held. Inside, the clock ticked louder.\"","findSv":"Hur meningslängd och miljö förstärker psykologisk oro","methodSv":"Granska både vädersymbolik och meningslängd.","stepsSv":["De korta, avhuggna meningarna (\"One hinge snapped. Another held.\") skapar en uppjagad, klaustrofobisk rytm.","Stormen och den hotande bristningen speglar en inre psykologisk bristningsgräns (pathetic fallacy)."],"answerSv":"Staccato-rytmen och den stormiga omgivningen speglar karaktärens inre press och annalkande kris."}]', '[{"trapTitleSv":"Skriva litteraturanalys i blandat presens och preteritum","wrongApproachSv":"Att börja med \"The narrator walks in\" och plötsligt byta till \"and saw the key\".","rightApproachSv":"Håll konsekvent litterärt presens när du beskriver händelser inne i textens värld."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-7-1-akademisk-argumentation-och-hedging', 'chap-engelska-7-1', 'akademisk-argumentation-och-hedging', 1, 'Akademisk stil, hedging och precis nyansering', '[{"term":"Hedging","definition":"Försiktighetsmarkörer i akademisk engelska som \"appears to\", \"suggests\", \"to some extent\" och modala verb."},{"term":"Booster","definition":"Förstärkare som \"clearly demonstrates\" — används endast när beläggen är mycket starka."}]', '[{"heading":"Balansera säkerhet och vetenskaplig ödmjukhet","bodySv":"I Engelska 7 utmärks hög nivå av förmågan att uttrycka exakt säkerhetsgrad. Överdrivna generaliseringar (\"This proves that all schools fail\") ersätts med kvalificerade påståenden (\"These findings indicate that certain institutions may face challenges\"). Hedging uppnås med modala verb (may, might, could), lexikala verb (suggest, appear, tend to) och avgränsande adverb (primarily, largely, arguably).","deepDiveSv":"Samtidigt får hedging inte bli så överlastad (\"It might possibly perhaps seem to indicate\") att texten tappar kraft; en väl avvägd markör per påstående räcker."}]', '[]', '[{"gradeLevel":"E","titleSv":"Införa hedging i ett alltför kategoriskt påstående","givenSv":"Overstated: \"Digital distraction ruins concentration for every student.\"","findSv":"Nyanserad akademisk formulering","methodSv":"Ersätt \"ruins\" och \"every\" med modala och försiktiga uttryck.","stepsSv":["\"Digital distraction can impair concentration for many students.\""],"answerSv":"\"Digital distraction can impair concentration for many students.\""},{"gradeLevel":"C","titleSv":"Variera modala och lexikala hedging-uttryck","givenSv":"Data shows correlation between green spaces and lower stress, though income also varies.","findSv":"Två akademiska meningar med tydlig nyansering","methodSv":"Använd \"suggest\" och \"cannot be attributed solely to\".","stepsSv":["\"The data suggest a correlation between urban green spaces and reduced stress levels. However, this outcome cannot be attributed solely to park access, as socioeconomic factors may also play a role.\""],"answerSv":"Formuleringen väger in alternativa faktorer med \"suggest\", \"solely\" och \"may\"."},{"gradeLevel":"A","titleSv":"Skilja mellan korrelerad försiktighet och ogrundad tvekan","givenSv":"A) \"Preliminary trials indicate that the vaccine could reduce transmission.\" B) \"Maybe it sort of kinda helps a little bit.\"","findSv":"Varför A är akademiskt precis medan B är svagt talspråk","methodSv":"Jämför register och precision.","stepsSv":["A avgränsar säkerheten professionellt via \"Preliminary trials indicate\" och modalt \"could\".","B staplar vaga vardagsord (\"maybe\", \"sort of\", \"kinda\") utan saklig grund."],"answerSv":"Akademisk hedging bygger på precis avgränsning av belägg, aldrig på vaga vardagsutfyllnader."}]', '[{"trapTitleSv":"Stapla flera tveksamma ord på varandra","wrongApproachSv":"Att skriva \"It could perhaps possibly tend to suggest...\".","rightApproachSv":"Välj en klar och precis markör, till exempel \"The findings tend to suggest...\"."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-7-1-invers-ordfoljd-och-konjunktiv', 'chap-engelska-7-1', 'invers-ordfoljd-och-konjunktiv', 2, 'Inversion, klyvsatser och konjunktiv', '[{"term":"Inversion","definition":"Omvänd ordföljd (hjälpverb före subjekt) efter negerade adverbial i spetsen, t.ex. \"Not only did she...\"."},{"term":"Mandative subjunctive","definition":"Grundform av verbet i formaliserade kravsatser efter \"recommend\", \"insist\" eller \"essential\": \"...that he attend\"."}]', '[{"heading":"Retorisk kraft genom avancerad syntax","bodySv":"När ett negativt eller begränsande adverbial flyttas längst fram i meningen för emfas — som \"Not only\", \"Seldom\", \"Never\" eller \"Under no circumstances\" — utlöses inversion: hjälpverbet placeras före subjektet precis som i en fråga (\"Seldom have we seen such progress\"). Saknas hjälpverb i enkel nutid eller dåtid skjuts \"do/does/did\" in (\"Not only did the policy cut costs...\").","deepDiveSv":"Samma höga stil ses i klyvsatser (\"What the committee overlooked was...\") och formell konjunktiv (\"It is imperative that every applicant submit the form on time\" eller villkorssatsen \"Were the government to intervene...\")."}]', '[]', '[{"gradeLevel":"E","titleSv":"Inversion med \"Never\"","givenSv":"Normal: \"I have never witnessed such cooperation.\"","findSv":"Emfatisk omformulering med \"Never\" först","methodSv":"Byt plats på \"have\" och \"I\".","stepsSv":["\"Never have I witnessed such cooperation.\""],"answerSv":"\"Never have I witnessed such cooperation.\""},{"gradeLevel":"C","titleSv":"Inversion med hjälpverbet \"did\" efter \"Not only\"","givenSv":"Normal: \"The reform lowered emissions and created new jobs.\"","findSv":"Börja med \"Not only\"","methodSv":"Skjut in \"did\" före subjektet och sätt huvudverbet i grundform (\"lower\").","stepsSv":["\"Not only did the reform lower emissions, but it also created new jobs.\""],"answerSv":"\"Not only did the reform lower emissions, but it also created new jobs.\""},{"gradeLevel":"A","titleSv":"Inverterad villkorssats utan \"if\"","givenSv":"Standard: \"If the funding were withdrawn, the laboratory would close.\"","findSv":"Formell inverterad villkorssats","methodSv":"Stryk \"If\" och placera \"Were\" först.","stepsSv":["\"Were the funding to be withdrawn (eller Were the funding withdrawn), the laboratory would close.\""],"answerSv":"\"Were the funding withdrawn, the laboratory would close.\""}]', '[{"trapTitleSv":"Glömma sätta huvudverbet i infinitiv efter \"did\"","wrongApproachSv":"Att skriva \"Not only did the reform lowered emissions...\".","rightApproachSv":"När \"did\" bär dåtid står huvudverbet alltid i grundform: \"Not only did the reform lower...\"."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-7-1-syntes-av-engelska-kallor', 'chap-engelska-7-1', 'syntes-av-engelska-kallor', 3, 'Källsyntes och kritisk värdering av komplexa texter', '[{"term":"Source synthesis","definition":"Att väva samman flera olika källor tematiskt för att belysa en komplex forskningsfråga."},{"term":"Implicit bias","definition":"Dolda antaganden eller perspektivval som styr vad en skribent tar för givet."}]', '[{"heading":"Från referatlista till analytisk syntes","bodySv":"I stället för att sammanfatta Källa A i ett stycke och Källa B i nästa organiseras en syntes efter teman eller argumentationslinjer. I ett stycke om ekonomiska konsekvenser ställs exempelvis Alvarez (2023) mot Lindholm (2024) med formuleringar som \"Whereas Alvarez stresses short-term disruption, Lindholm contends that long-term gains outweigh initial friction.\"","deepDiveSv":"Kontrollera alltid källornas omfång, metod och eventuella intressekonflikter (t.ex. industrifinansierade rapporter) när du väger deras tyngd mot varandra."}]', '[]', '[{"gradeLevel":"E","titleSv":"Parafrasera utan att plagiera meningsbyggnad (patchwriting)","givenSv":"Original: \"Autonomous vehicles promise to reduce human error, yet legal liability remains unresolved.\"","findSv":"Självständig omskrivning med bibehållen innebörd","methodSv":"Ändra både ordval och meningsstruktur.","stepsSv":["\"While self-driving cars could curb accidents caused by drivers, courts have yet to clarify who bears responsibility when collisions occur.\""],"answerSv":"Hela satsstrukturen och vokabulären omformuleras självständigt."},{"gradeLevel":"C","titleSv":"Kombinera två motsatta källor i ett stycke","givenSv":"Källa 1 (Chen): AI-handledning ökar tempot i matte. Källa 2 (Bauer): Elever riskerar ytlig inlärning utan eget kämpande.","findSv":"Tematiskt syntesstycke","methodSv":"Koppla samman snabbhet mot djupinlärning.","stepsSv":["\"Although Chen (2024) demonstrates that adaptive software accelerates routine problem-solving, Bauer (2025) cautions that bypassing productive struggle may weaken conceptual retention.\""],"answerSv":"Syntesen visar spänningen mellan snabbare uppgiftslösning och djup begreppsförståelse."},{"gradeLevel":"A","titleSv":"Avslöja dold vinkling genom urval av jämförelsebas","givenSv":"En energirapport framhäver att vindkraften producerade \"300 % mer el än för tio år sedan\" men utelämnar att den fortfarande står för en liten andel av totalt vinterbehov.","findSv":"Hur statistisk inramning skapar ensidig bild","methodSv":"Skilj relativ procentökning från absolut andel och effektbalans.","stepsSv":["Hög relativ procentökning från låg startnivå låter dramatisk (logos-intryck).","Genom att utelämna absoluta terawattimmar och årstidsvariation snedvrids läsarens bild av försörjningstryggheten."],"answerSv":"Rapporten använder selektiv relativ statistik och utelämnar säsongsmässigt sammanhang."}]', '[{"trapTitleSv":"Syssla med \"patchwriting\" vid omskrivning","wrongApproachSv":"Att behålla originalets exakta ordföljd och bara byta vart tredje ord mot en synonym.","rightApproachSv":"Förstå kärntanken, lägg bort originaltexten och formulera om med egen satsstruktur."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-7-2-presupposition-och-metaforik', 'chap-engelska-7-2', 'presupposition-och-metaforik', 1, 'Presuppositioner och konceptuella metaforer', '[{"term":"Presupposition","definition":"Ett outtalat antagande som byggts in i meningen som om det redan vore sant."},{"term":"Konceptuell metafor","definition":"Ett genomgående bildområde (t.ex. krig eller sjukdom) som präglar hur ett samhällsproblem inramas."}]', '[{"heading":"Läsa bortom ytan i engelska ledare och tal","bodySv":"På Engelska 7-nivå granskas hur skribenter styr tanken genom inramning (framing) och presuppositioner. Frågan \"Why has the ministry failed to address this crisis?\" förutsätter redan som obestritt faktum både att det är en kris och att ministeriet har misslyckats. På samma sätt påverkar valet mellan att beskriva migration som \"a wave\" (naturkatastrof) eller \"human capital\" (resurs) läsarens attityd.","deepDiveSv":"Eufemismer (förskönande omskrivningar som \"workforce optimization\" för uppsägningar) döljer obekväma konsekvenser och är viktiga att genomskåda i kritisk diskursanalys."}]', '[]', '[{"gradeLevel":"E","titleSv":"Upptäcka eufemism","givenSv":"Corporate memo: \"We are implementing targeted headcount reductions to enhance agility.\"","findSv":"Vad \"targeted headcount reductions\" döljer","methodSv":"Översätt abstrakta affärstermer till konkret handling.","stepsSv":["Uttrycket är en eufemism för att säga upp personal."],"answerSv":"En eufemism som mildrar beskedet om uppsägningar."},{"gradeLevel":"C","titleSv":"Identifiera presupposition","givenSv":"Headline: \"When will city leaders finally abandon their reckless transit experiment?\"","findSv":"Två dolda antaganden i frågan","methodSv":"Plocka ut vad frågan tar för givet utan bevis.","stepsSv":["Den förutsätter att trafikpolitiken är \"reckless\" (vårdslös) och att det är ett misslyckat \"experiment\" som måste överges."],"answerSv":"Rubriken förutsätter att politiken är vårdslös och att den oundvikligen kommer att överges."},{"gradeLevel":"A","titleSv":"Analysera genomgående krigsmetaforik","givenSv":"Speech: \"We stand at the front line against inflation, deploying every fiscal weapon in our arsenal until victory is secured.\"","findSv":"Effekten av metaforiken i ekonomisk politik","methodSv":"Koppla samman \"front line\", \"weapon\", \"arsenal\" och \"victory\".","stepsSv":["Ekonomisk politik ramas in som ett krig med tydlig fiende.","Detta manar till samling, legitimerar hårda uppoffringar och framställer kritiker som svaga inför \"fienden\"."],"answerSv":"Krigsmetaforiken skapar krismedvetenhet och stärker kravet på enighet bakom tuffa ekonomiska beslut."}]', '[{"trapTitleSv":"Nöja sig med att kalla en metafor för \"en snygg bild\"","wrongApproachSv":"Att skriva \"Skribenten använder krigsord för att texten ska bli levande.\"","rightApproachSv":"Visa alltid hur inramningen styr läsarens politiska eller moraliska slutsatser."}]', 'none', NULL, 1794787200000);
INSERT OR REPLACE INTO study_lessons (id, chapter_id, section_slug, sort_order, title_sv, overview_concepts_json, theory_blocks_json, formulas_json, worked_examples_eca_json, exam_pitfalls_json, interactive_widget_type, interactive_config_json, updated_at) VALUES ('les-engelska-7-3-abstract-och-imrad', 'chap-engelska-7-3', 'abstract-och-imrad', 1, 'Vetenskapligt abstract och IMRaD-logik', '[{"term":"Abstract","definition":"Kortfattad, fristående sammanfattning (ofta 150–250 ord) av syfte, metod, huvudresultat och slutsats."},{"term":"IMRaD","definition":"Standardstruktur för vetenskapliga artiklar: Introduction, Methods, Results and Discussion."}]', '[{"heading":"Struktur och tempusväxling i ett engelskt abstract","bodySv":"Ett välgjort engelskt abstract ger hela studien i miniatyrformat på några få meningar: bakgrund och forskningslucka (1–2 meningar), syfte och metod (1–2 meningar), centrala resultat (1–2 meningar) samt implikation/slutsats (1 mening). Tempus följer innehållet noggrant: etablerade fakta och nuvarande syfte står ofta i presens (\"This paper examines...\"), medan genomförd metod och uppmätta resultat står i preteritum (\"Interviews were conducted...\").","deepDiveSv":"Till skillnad från en spänningsroman ska ett abstract aldrig hålla slutsatsen hemlig till slutet — de viktigaste fynden ska redovisas klart och tydligt."}]', '[]', '[{"gradeLevel":"E","titleSv":"Ordna delarna i IMRaD","givenSv":"Sektioner: Discussion, Methods, Introduction, Results","findSv":"Rätt ordningsföljd","methodSv":"Följ akronymen IMRaD.","stepsSv":["Introduction → Methods → Results → Discussion."],"answerSv":"Introduction, Methods, Results, Discussion."},{"gradeLevel":"C","titleSv":"Välja rätt tempus för metod och slutsats i ett abstract","givenSv":"Abstract draft: \"This study (investigate) sleep habits. Data (collect) from 300 pupils. The results (suggest) a clear link.\"","findSv":"Korrekta verbformer","methodSv":"Syftet i presens, insamlingen i preteritum passiv, tolkningen i presens.","stepsSv":["\"investigates\", \"were collected\", \"suggest\"."],"answerSv":"\"This study investigates... Data were collected... The results suggest...\"."},{"gradeLevel":"A","titleSv":"Identifiera forskningslucka (research gap) i inledning","givenSv":"Excerpt: \"While numerous studies have assessed screen time among teenagers, few have examined its effects on rural commuters aged 16 to 19.\"","findSv":"Hur meningen motiverar studiens relevans","methodSv":"Peka på kontrasten mellan \"numerous studies\" och \"few have examined\".","stepsSv":["Meningen visar först vad forskningen redan vet (etablerat fält) och identifierar sedan en specifik kunskapslucka kring landsbygdspendlare."],"answerSv":"Genom kontrasterande \"While... few have examined...\" skapas en tydlig vetenskaplig nisch och motivering."}]', '[{"trapTitleSv":"Ta in nya källor eller citat i ett abstract","wrongApproachSv":"Att fylla sammanfattningen med citat från andra böcker.","rightApproachSv":"Ett abstract ska kunna läsas helt fristående och redovisa enbart denna studies egen fråga, metod och slutsats."}]', 'none', NULL, 1794787200000);

-- 5. QUESTIONS
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-01', 'chap-fysik-1b-1', 'les-fysik-1b-1-lagesenergi', 1, 'E', 'multiple_choice', 'Lägesenergi', 'Vad avgör hur stor ett föremåls potentiella energi (Ep) är i jordens tyngdfält?', 'E_p = m \cdot g \cdot h', '["Föremålets massa och höjd över en vald nollnivå","Föremålets massa och fart","Endast föremålets höjd över havsytan","Föremålets volym och friktion"]', '0', NULL, NULL, 'Titta på storheterna i Ep = m · g · h.', 'Ep = m · g · h beror direkt på föremålets massa m och höjden h över den valda nollnivån.', 'Eftersom g = 9,82 N/kg är konstant nära jordytan avgörs Ep proportionellt av massan m och höjden h relativt vald nollnivå.', 'lagesenergi');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-02', 'chap-fysik-1b-1', 'les-fysik-1b-1-rorelseenergi', 2, 'C', 'multiple_choice', 'Rörelseenergi', 'En cyklist ökar sin fart till det dubbla. Vad händer med den kinetiska energin?', 'E_k = \frac{m \cdot v^2}{2}', '["Den blir dubbelt så stor","Den blir fyra gånger så stor","Den blir hälften så stor","Den ändras inte"]', '1', NULL, NULL, 'Farten v är upphöjt till 2 i formeln för rörelseenergi.', 'Eftersom farten är kvadrerad ger dubbel fart 2² = 4 gånger så stor rörelseenergi.', 'E_k,ny = ½ · m · (2v)² = 4 · (½ · m · v²).', 'rorelseenergi');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-03', 'chap-fysik-1b-1', 'les-fysik-1b-1-rorelseenergi', 3, 'E', 'multiple_choice', 'Rörelseenergi', 'Du ska räkna ut kinetisk energi för en bil som kör i 108 km/h. Vilket värde på v ska du sätta in?', NULL, '["108 m/s","30 m/s","388,8 m/s","10,8 m/s"]', '1', NULL, NULL, 'Dela farten i km/h med 3,6.', 'v = 108 / 3,6 = 30 m/s.', '108 000 m / 3 600 s = 30 m/s. Multiplicerar man med 3,6 får man fällan 388,8 m/s.', 'rorelseenergi');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-04', 'chap-fysik-1b-1', 'les-fysik-1b-1-mekanisk-energi', 4, 'E', 'multiple_choice', 'Mekanisk energi', 'Vad är mekanisk energi (Emek)?', NULL, '["Skillnaden mellan lägesenergi och värme","Summan av potentiell energi och kinetisk energi","Endast energi som blir friktion","Verkningsgrad gånger effekt"]', '1', NULL, NULL, 'Lägesenergi plus rörelseenergi i samma läge.', 'Mekanisk energi är summan av potentiell och kinetisk energi: Emek = Ep + Ek.', 'Storheten sammanfattar föremålets makroskopiska höjdenergi och rörelseenergi relativt samma nollnivå.', 'mekanisk-energi');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-05', 'chap-fysik-1b-1', 'les-fysik-1b-1-utan-friktion', 5, 'A', 'multiple_choice', 'Utan friktion', 'En kula släpps från vila i en friktionsfri backe. Du vet höjden h₁ men inte massan m. Kan farten ändå räknas ut?', 'm \cdot g \cdot h_1 = \frac{m \cdot v_2^2}{2}', '["Nej, massan m behövs alltid","Ja, för massan m finns på båda sidor och förkortas bort","Ja, om man gissar m = 1 kg","Nej, man behöver kulans radie"]', '1', NULL, NULL, 'Skriv upp energiekvationen m · g · h₁ = (m · v₂²) / 2.', 'Massan m finns i båda leden och kan divideras bort, vilket ger v₂ = √(2 · g · h₁).', 'm · g · h₁ = ½ · m · v₂² delas med m så att g · h₁ = ½ · v₂².', 'utan-friktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-06', 'chap-fysik-1b-1', 'les-fysik-1b-1-med-friktion', 6, 'C', 'multiple_choice', 'Med friktion', 'En låda glider nerför en ramp med friktion. Vart tar den saknade mekaniska energin vägen?', NULL, '["Den blir ny lägesenergi","Den förblir oförändrad","Den omvandlas till termisk energi (värme)","Den försvinner helt"]', '2', NULL, NULL, 'Energiprincipen gäller alltid.', 'Den saknade mekaniska energin omvandlas till termisk energi (värme) genom friktionsarbetet Wf.', 'Friktionsarbetet Wf = Ff · s överför mekanisk energi till molekylrörelse (värme) i glidytorna.', 'med-friktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-07', 'chap-fysik-1b-1', 'les-fysik-1b-1-verkningsgrad', 7, 'C', 'multiple_choice', 'Verkningsgrad', 'Vilket påstående om verkningsgrad (η) är rätt?', '\eta = \frac{E_{\text{nyttig}}}{E_{\text{tillförd}}}', '["Mäts i joule och kan vara över 100 %","Mäts i watt","Saknar enhet och ligger mellan 0 och 1 (0 till 100 %)","Beräknas som tillförd energi delat med nyttig energi"]', '2', NULL, NULL, 'Jämför enheterna i täljare och nämnare i formeln för η.', 'Verkningsgraden saknar enhet eftersom joule delas med joule, och kan högst vara 1 (100 %).', 'Värden över 100 % skulle innebära att energi skapas ur intet.', 'verkningsgrad');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-08', 'chap-fysik-1b-1', 'les-fysik-1b-1-utan-friktion', 8, 'E', 'multiple_choice', 'Utan friktion', 'En vagn i en friktionsfri bana når botten (nollnivån h = 0 m). Hur fördelar sig energin där?', NULL, '["All energi är lägesenergi","All mekanisk energi är rörelseenergi och Ep = 0 J","Hälften är värme","Både Ep och Ek är 0 J"]', '1', NULL, NULL, 'Vid nollnivån h = 0 m är Ep = 0 J.', 'Vid h = 0 m är Ep = 0 J, så hela den mekaniska energin utgörs av rörelseenergi Ek.', 'All lägesenergi från toppen har omvandlats utan förlust till rörelseenergi.', 'utan-friktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-09', 'chap-fysik-1b-1', 'les-fysik-1b-1-lagesenergi', 9, 'E', 'multiple_choice', 'Lägesenergi — beräkning', 'En ryggsäck (8,0 kg) lyfts 2,5 m upp från golvet. Hur stor är dess lägesenergi? (g = 9,82 N/kg)', NULL, '["196 J","20 J","78,6 J","393 J"]', '0', NULL, NULL, 'Använd Ep = m · g · h.', 'Ep = 8,0 · 9,82 · 2,5 = 196,4 J ≈ 196 J.', 'Svarsalternativet 20 J fås om man glömmer att multiplicera med g = 9,82.', 'lagesenergi');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-10', 'chap-fysik-1b-1', 'les-fysik-1b-1-rorelseenergi', 10, 'C', 'multiple_choice', 'Rörelseenergi — beräkning', 'En moped med förare (150 kg) kör i 36 km/h. Hur stor är rörelseenergin?', NULL, '["7,5 kJ","15 kJ","97,2 kJ","750 J"]', '0', NULL, NULL, 'Omvandla 36 km/h till m/s innan du sätter in i Ek.', 'v = 36 / 3,6 = 10 m/s ger Ek = (150 · 10²) / 2 = 7 500 J = 7,5 kJ.', '97,2 kJ är fällan utan division med 3,6 och 750 J fås utan kvadrat på farten.', 'rorelseenergi');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-11', 'chap-fysik-1b-1', 'les-fysik-1b-1-mekanisk-energi', 11, 'C', 'multiple_choice', 'Mekanisk energi — beräkning', 'En fågel (0,50 kg) flyger på höjden 10 m med farten 8,0 m/s. Vad är den mekaniska energin?', NULL, '["65 J","49 J","16 J","81 J"]', '0', NULL, NULL, 'Beräkna Ep och Ek var för sig och addera dem.', 'Ep = 0,50 · 9,82 · 10 = 49,1 J och Ek = (0,50 · 8,0²) / 2 = 16,0 J. Summan Emek = 65,1 J ≈ 65 J.', 'Både höjdenergin och rörelseenergin måste räknas samman.', 'mekanisk-energi');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-12', 'chap-fysik-1b-1', 'les-fysik-1b-1-utan-friktion', 12, 'A', 'multiple_choice', 'Utan friktion — beräkning', 'En sten släpps från vila 15 m över vattnet utan luftmotstånd. Vilken fart har den vid ytan?', NULL, '["17 m/s","12 m/s","295 m/s","24 m/s"]', '0', NULL, NULL, 'Använd v₂ = √(2 · g · h₁).', 'v₂ = √(2 · 9,82 · 15) = √294,6 ≈ 17,2 m/s (17 m/s).', 'm · g · h₁ = ½ · m · v₂² ger v₂ = √294,6 = 17,16 m/s. 295 m/s fås om man glömmer kvadratroten.', 'utan-friktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-13', 'chap-fysik-1b-1', 'les-fysik-1b-1-utan-friktion', 13, 'A', 'multiple_choice', 'Utan friktion — beräkning', 'En skateboardåkare åker upp i en ramp med farten 6,0 m/s i botten utan friktion. Hur högt kommer hen?', NULL, '["1,8 m","3,7 m","0,31 m","6,0 m"]', '0', NULL, NULL, 'Lös ut höjden h₂ = v₁² / (2 · g).', 'h₂ = 6,0² / (2 · 9,82) = 36 / 19,64 ≈ 1,83 m (1,8 m).', '½ · m · v₁² = m · g · h₂ ger h₂ = v₁² / (2 · g).', 'utan-friktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-14', 'chap-fysik-1b-1', 'les-fysik-1b-1-med-friktion', 14, 'A', 'multiple_choice', 'Med friktion — beräkning', 'Ett barn med kälke (40 kg) åker från vila nerför 5,0 m och når farten 6,0 m/s i dalen. Hur mycket blev värme?', NULL, '["1 244 J","1 964 J","720 J","2 684 J"]', '0', NULL, NULL, 'Beräkna Wf = Ep1 − Ek2.', 'Ep1 = 40 · 9,82 · 5,0 = 1 964 J och Ek2 = (40 · 6,0²) / 2 = 720 J. Värmen blir Wf = 1 964 − 720 = 1 244 J.', 'Skillnaden mellan startens lägesenergi och bottens rörelseenergi är den energi som omvandlats till värme.', 'med-friktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-15', 'chap-fysik-1b-1', 'les-fysik-1b-1-med-friktion', 15, 'E', 'multiple_choice', 'Med friktion — beräkning', 'En kälke bromsas av friktionskraften 80 N längs 25 m. Hur stort är friktionsarbetet Wf?', NULL, '["2 000 J","3,2 J","105 J","200 J"]', '0', NULL, NULL, 'Använd Wf = Ff · s.', 'Wf = 80 · 25 = 2 000 J.', '80 N · 25 m = 2 000 N·m = 2 000 J.', 'med-friktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-16', 'chap-fysik-1b-1', 'les-fysik-1b-1-verkningsgrad', 16, 'C', 'multiple_choice', 'Verkningsgrad — beräkning', 'En motor förbrukar 5,0 kJ och ger 3 500 J lägesenergi. Vad är verkningsgraden?', NULL, '["70 %","30 %","143 %","1,5 kJ"]', '0', NULL, NULL, 'Gör om 5,0 kJ till 5 000 J först.', '5,0 kJ = 5 000 J ger η = 3 500 / 5 000 = 0,70 = 70 %.', '30 % är förlustandelen, medan verkningsgraden mäter den nyttiga andelen.', 'verkningsgrad');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-17', 'chap-fysik-1b-1', 'les-fysik-1b-1-energibegreppet', 17, 'E', 'multiple_choice', 'Energibegreppet', 'Vad säger energiprincipen?', NULL, '["Energi skapas när något faller","Energi kan varken skapas eller förstöras, bara omvandlas","Energi förstörs av friktion","Lägesenergi är alltid störst"]', '1', NULL, NULL, 'Totalenergin i ett slutet system förändras aldrig.', 'Energiprincipen innebär att energi aldrig kan skapas eller förstöras, bara omvandlas mellan olika former.', NULL, 'energibegreppet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-18', 'chap-fysik-1b-1', 'les-fysik-1b-1-energibegreppet', 18, 'E', 'multiple_choice', 'Energibegreppet', 'Vilken är enheten för energi och vad motsvarar 1 J?', NULL, '["Watt (1 W = 1 N/m)","Newton (1 N = 1 kg·m)","Joule (1 J = 1 N·m)","Kilojoule (1 kJ = 100 N·m)"]', '2', NULL, NULL, 'Titta på definitionen av arbete W = F · s.', 'Energi mäts i joule (J), där 1 J = 1 N·m.', 'Watt är effekt (J/s), medan energi är kraft gånger sträcka.', 'energibegreppet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-19', 'chap-fysik-1b-1', 'les-fysik-1b-1-energibegreppet', 19, 'E', 'multiple_choice', 'Energibegreppet — beräkning', 'Du drar en låda längs golvet med 40 N i 6,0 m. Hur stort arbete utför du?', NULL, '["240 J","6,7 J","46 J","24 J"]', '0', NULL, NULL, 'Använd W = F · s.', 'W = 40 · 6,0 = 240 J.', NULL, 'energibegreppet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-20', 'chap-fysik-1b-1', 'les-fysik-1b-1-energibegreppet', 20, 'A', 'multiple_choice', 'Energibegreppet — beräkning', 'En matkasse med tyngden 50 N lyfts 0,90 m rakt upp. Hur mycket energi tillförs kassen?', NULL, '["45 J","55,6 J","442 J","4,5 J"]', '0', NULL, NULL, 'Tyngden står redan i newton.', 'W = 50 · 0,90 = 45 J. Man ska inte multiplicera med 9,82 eftersom tyngden redan är i N.', '442 J är fällan som uppstår om man felaktigt multiplicerar 50 N med g = 9,82.', 'energibegreppet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-21', 'chap-fysik-1b-1', 'les-fysik-1b-1-lagesenergi', 21, 'E', 'numeric', 'Beräkning', 'Beräkna lägesenergin för en låda med massan 10 kg som lyfts 5,0 m upp från golvet (g = 9,82 N/kg).', 'E_p = m \cdot g \cdot h', NULL, '491', 1, 'J', 'Multiplicera massa, tyngdfaktor och höjd.', 'Ep = 10 · 9,82 · 5,0 = 491 J.', NULL, 'lagesenergi');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-22', 'chap-fysik-1b-1', 'les-fysik-1b-1-rorelseenergi', 22, 'C', 'numeric', 'Beräkning', 'En cyklist inklusive cykel väger 80 kg och kör i 36 km/h. Beräkna rörelseenergin i joule.', 'E_k = \frac{m \cdot v^2}{2}', NULL, '4000', 10, 'J', 'Omvandla först 36 km/h till m/s genom att dela med 3,6.', 'v = 36 / 3,6 = 10 m/s. Ek = (80 · 10²) / 2 = 4 000 J.', NULL, 'rorelseenergi');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-23', 'chap-fysik-1b-1', 'les-fysik-1b-1-verkningsgrad', 23, 'C', 'numeric', 'Beräkning', 'En elvinsch tillförs 2,5 kJ energi och uträttar 1 750 J nyttigt lyftarbete. Ange verkningsgraden i procent.', '\eta = \frac{E_{\text{nyttig}}}{E_{\text{tillförd}}}', NULL, '70', 0.5, '%', 'Omvandla 2,5 kJ till 2 500 J innan du dividerar.', 'E_tillförd = 2 500 J. η = 1 750 / 2 500 = 0,70 = 70 %.', NULL, 'verkningsgrad');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-1-24', 'chap-fysik-1b-1', 'les-fysik-1b-1-utan-friktion', 24, 'A', 'numeric', 'Härledning', 'En vagn startar från vila på höjden 18,0 m i en friktionsfri bana och passerar nästa kulle på höjden 8,0 m. Beräkna farten på kullen (g = 9,82 N/kg), avrundad till närmaste heltal.', 'g \cdot h_1 = g \cdot h_2 + \frac{v_2^2}{2}', NULL, '14', 0.2, 'm/s', 'Förkorta bort massan och räkna på höjdskillnaden Δh = 18,0 − 8,0 m.', 'm·g·h₁ = m·g·h₂ + ½m·v₂² ger v₂ = √(2 · g · (h₁ − h₂)) = √(2 · 9,82 · 10,0) = √196,4 ≈ 14,0 m/s.', 'Höjdminskningen 10,0 m ger samma rörelseenergi per kilogram som ett fritt fall på 10,0 m.', 'utan-friktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-2-01', 'chap-fysik-1b-2', 'les-fysik-1b-2-newtons-lagar', 1, 'E', 'numeric', 'Beräkning', 'En bil med massan 1 200 kg accelererar med 2,5 m/s². Hur stor är resultantkraften i newton?', 'F_{\text{res}} = m \cdot a', NULL, '3000', 5, 'N', 'Multiplicera massan med accelerationen.', 'F_res = 1 200 · 2,5 = 3 000 N.', NULL, 'newtons-lagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-2-02', 'chap-fysik-1b-2', 'les-fysik-1b-2-krafter-och-jamvikt', 2, 'E', 'multiple_choice', 'Begrepp', 'En cyklist cyklar rakt fram med konstant fart på en plan väg. Vad gäller för krafterna på cyklisten?', NULL, '["Framåtriktad kraft är större än motståndet","Resultantkraften är noll","Endast tyngdkraften verkar","Accelerationen ökar stadigt"]', '1', NULL, NULL, 'Tillämpa Newtons första lag.', 'Konstant fart rakt fram innebär noll acceleration och därmed F_res = 0 N.', NULL, 'krafter-och-jamvikt');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-2-03', 'chap-fysik-1b-2', 'les-fysik-1b-2-likformigt-accelererad-rorelse', 3, 'C', 'numeric', 'Beräkning', 'Ett föremål startar från vila och accelererar likformigt med 3,0 m/s² i 6,0 s. Hur långt har det rört sig i meter?', 's = v_0 \cdot t + \frac{a \cdot t^2}{2}', NULL, '54', 0.5, 'm', 'Sätt v₀ = 0 i sträckformeln.', 's = 0 + (3,0 · 6,0²) / 2 = (3,0 · 36) / 2 = 54 m.', NULL, 'likformigt-accelererad-rorelse');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-2-04', 'chap-fysik-1b-2', 'les-fysik-1b-2-newtons-lagar', 4, 'C', 'multiple_choice', 'Begrepp', 'Varför minskar en krockkudde skaderisken vid en kollision?', NULL, '["Den minskar bilens totala rörelsemängd före krocken","Den förlänger stöttiden Δt så att medelkraften blir mindre","Den eliminerar normalkraften helt","Den ökar accelerationen under inbromsningen"]', '1', NULL, NULL, 'Utgå från impulssambandet F · Δt = Δp.', 'Förändringen i rörelsemängd Δp är densamma, så längre Δt ger mindre kraft F = Δp / Δt.', NULL, 'newtons-lagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-2-05', 'chap-fysik-1b-2', 'les-fysik-1b-2-newtons-lagar', 5, 'A', 'numeric', 'Beräkning', 'En boll (0,50 kg) som rör sig med 8,0 m/s träffar en vägg och studsar rakt tillbaka med 6,0 m/s på 0,20 s. Beräkna medelkraften i newton.', 'F = \frac{\Delta p}{\Delta t}', NULL, '35', 0.5, 'N', 'Kom ihåg teckenbytet på hastigheten vid studsen.', 'Δp = 0,50 · (6,0 − (−8,0)) = 7,0 N·s. F = 7,0 / 0,20 = 35 N.', NULL, 'newtons-lagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-2-06', 'chap-fysik-1b-2', 'les-fysik-1b-2-krafter-och-jamvikt', 6, 'A', 'multiple_choice', 'Härledning', 'En låda vilar på ett plan med lutningen α precis innan den börjar glida. Vilket uttryck ger det minimala friktionstalet μ?', NULL, '["μ = sin α","μ = cos α","μ = tan α","μ = 1 / tan α"]', '2', NULL, NULL, 'Ställ upp kraftjämvikt längs planet: m·g·sin α = μ·m·g·cos α.', 'Förkortning av m·g ger μ = sin α / cos α = tan α.', NULL, 'krafter-och-jamvikt');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-3-01', 'chap-fysik-1b-3', 'les-fysik-1b-3-tryck-och-arkimedes', 1, 'E', 'numeric', 'Beräkning', 'Hur stort är vätsketrycket i kPa på 5,0 m djup i sötvatten (ρ = 1 000 kg/m³, g = 9,82 N/kg), avrundat till närmaste heltal?', 'p = \rho \cdot g \cdot h', NULL, '49', 0.5, 'kPa', 'Räkna i pascal och dela sedan med 1 000.', 'p = 1 000 · 9,82 · 5,0 = 49 100 Pa = 49,1 kPa ≈ 49 kPa.', NULL, 'tryck-och-arkimedes');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-3-02', 'chap-fysik-1b-3', 'les-fysik-1b-3-varme-och-fasovergangar', 2, 'E', 'multiple_choice', 'Begrepp', 'Vad händer med vattnets temperatur medan is smälter i en kastrull vid 0 °C?', NULL, '["Temperaturen stiger linjärt","Temperaturen hålls konstant vid 0 °C tills all is har smält","Temperaturen sjunker under smältningen","Vattnet kokar omedelbart"]', '1', NULL, NULL, 'Tillförd energi används till att bryta bindningar.', 'Under fasövergången går all tillförd värme till smältentalpin så att temperaturen är konstant.', NULL, 'varme-och-fasovergangar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-3-03', 'chap-fysik-1b-3', 'les-fysik-1b-3-varme-och-fasovergangar', 3, 'C', 'numeric', 'Beräkning', 'Hur mycket energi i kilojoule krävs för att värma 2,0 kg vatten från 15 °C till 65 °C? (c = 4 180 J/(kg·K))', 'Q = c \cdot m \cdot \Delta T', NULL, '418', 1, 'kJ', 'Beräkna ΔT = 50 K och omvandla joule till kJ.', 'Q = 4 180 · 2,0 · 50 = 418 000 J = 418 kJ.', NULL, 'varme-och-fasovergangar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-3-04', 'chap-fysik-1b-3', 'les-fysik-1b-3-stralningsbalans-och-klimat', 4, 'C', 'multiple_choice', 'Begrepp', 'Varför ökar värmebalansen på jorden när ljus havsis smälter och ersätts av mörkt öppet hav?', NULL, '["Albedot ökar och mer solstrålning reflekteras","Albedot minskar så att mer kortvågig solstrålning absorberas","Vattnets specifika värmekapacitet blir noll","Växthuseffekten upphör"]', '1', NULL, NULL, 'Mörka ytor har lägre albedo än ljus snö och is.', 'Lägre albedo innebär mindre reflektion och högre andel absorberad solenergi.', NULL, 'stralningsbalans-och-klimat');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-3-05', 'chap-fysik-1b-3', 'les-fysik-1b-3-tryck-och-arkimedes', 5, 'A', 'numeric', 'Beräkning', 'En sten med volymen 0,0020 m³ sänks helt ner i vatten (ρ = 1 000 kg/m³, g = 9,82 N/kg). Hur stor är lyftkraften på stenen i newton, avrundad till en decimal?', 'F_{\text{lyft}} = \rho \cdot V \cdot g', NULL, '19.6', 0.2, 'N', 'Multiplicera vattnets densitet med volymen och g.', 'F_lyft = 1 000 · 0,0020 · 9,82 = 19,64 N ≈ 19,6 N.', NULL, 'tryck-och-arkimedes');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-3-06', 'chap-fysik-1b-3', 'les-fysik-1b-3-tryck-och-arkimedes', 6, 'A', 'multiple_choice', 'Analys', 'Ett isberg flyter i havsvatten med 89 % av volymen under ytan. Hur skulle andelen under ytan ändras om isberget flöt i sötvatten som har lägre densitet?', NULL, '["En mindre andel skulle ligga under ytan","En större andel skulle ligga under ytan","Andelen skulle vara exakt oförändrad","Isberget skulle sjunka till botten"]', '1', NULL, NULL, 'Titta på kvoten V_under / V_tot = ρ_is / ρ_vätska.', 'När vätskans densitet ρ_vätska minskar måste en större volym trängas undan för samma lyftkraft.', NULL, 'tryck-och-arkimedes');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-4-01', 'chap-fysik-1b-4', 'les-fysik-1b-4-strom-spanning-och-resistans', 1, 'E', 'numeric', 'Beräkning', 'En resistor på 24 Ω ansluts till spänningen 12 V. Hur stor blir strömmen i ampere?', 'U = R \cdot I', NULL, '0.5', 0.02, 'A', 'Lös ut I = U / R.', 'I = 12 / 24 = 0,50 A.', NULL, 'strom-spanning-och-resistans');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-4-02', 'chap-fysik-1b-4', 'les-fysik-1b-4-strom-spanning-och-resistans', 2, 'E', 'multiple_choice', 'Begrepp', 'Vilken enhet används för elektrisk energi på elräkningen när 1 kW används i 1 timme?', NULL, '["1 kW","1 kWh (= 3,6 MJ)","1 V/A","1 J/s"]', '1', NULL, NULL, 'Effekt gånger tid blir energi.', '1 kWh = 1 000 W · 3 600 s = 3,6 MJ.', NULL, 'strom-spanning-och-resistans');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-4-03', 'chap-fysik-1b-4', 'les-fysik-1b-4-strom-spanning-och-resistans', 3, 'C', 'numeric', 'Beräkning', 'Två motstånd på 10 Ω vardera är parallellkopplade. Vad är deras totala ersättningsresistans i ohm?', '\frac{1}{R_{\text{tot}}} = \frac{1}{R_1} + \frac{1}{R_2}', NULL, '5', 0.1, 'Ω', 'Två lika stora parallella motstånd halverar resistansen.', '1 / R_tot = 1/10 + 1/10 = 2/10 = 1/5 ger R_tot = 5,0 Ω.', NULL, 'strom-spanning-och-resistans');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-4-04', 'chap-fysik-1b-4', 'les-fysik-1b-4-magnetfalt-och-induktion', 4, 'C', 'numeric', 'Beräkning', 'En ideal transformator har 400 varv på primärspolen (230 V) och 100 varv på sekundärspolen. Ange sekundärspänningen i volt.', '\frac{U_1}{U_2} = \frac{N_1}{N_2}', NULL, '57.5', 0.2, 'V', 'Spänningen skalas med kvoten 100 / 400.', 'U₂ = 230 · (100 / 400) = 57,5 V.', NULL, 'magnetfalt-och-induktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-4-05', 'chap-fysik-1b-4', 'les-fysik-1b-4-magnetfalt-och-induktion', 5, 'A', 'multiple_choice', 'Analys', 'Varför överförs elenergi i stamnätet med mycket hög spänning?', NULL, '["För att minska strömmen I = P / U och därmed effektförlusten R · I²","För att öka resistansen i kopparledningarna","För att kunna använda likspänning i transformatorer","För att minska spänningen hos kunderna till noll"]', '0', NULL, NULL, 'Se på hur förlusteffekten P_förlust = R · I² beror av strömmen.', 'Hög spänning ger låg ström för samma överförda effekt, vilket minskar värmeförlusterna kvadratiskt.', NULL, 'magnetfalt-och-induktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-4-06', 'chap-fysik-1b-4', 'les-fysik-1b-4-magnetfalt-och-induktion', 6, 'A', 'multiple_choice', 'Begrepp', 'Vad krävs för att en spänning ska induceras i en sluten spole?', NULL, '["Att en permanentmagnet hålls helt stilla inuti spolen","Att det magnetiska flödet genom spolen förändras med tiden","Att spolen ansluts till ett likströmsbatteri","Att spolens resistans är noll"]', '1', NULL, NULL, 'Tänk på Faradays induktionslag.', 'Endast en förändring av magnetfältet eller arean genom spolen ger inducerad spänning.', NULL, 'magnetfalt-och-induktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-5-01', 'chap-fysik-1b-5', 'les-fysik-1b-5-radioaktivt-sonderfall', 1, 'E', 'numeric', 'Beräkning', 'Ett preparat har startaktiviteten 1 600 Bq och halveringstiden 4,0 dygn. Hur stor är aktiviteten i Bq efter 12 dygn?', 'A = A_0 \cdot \left(\frac{1}{2}\right)^{\frac{t}{T_{1/2}}}', NULL, '200', 1, 'Bq', '12 dygn motsvarar 3 halveringstider.', 'A = 1 600 · (0,5)³ = 1 600 / 8 = 200 Bq.', NULL, 'radioaktivt-sonderfall');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-5-02', 'chap-fysik-1b-5', 'les-fysik-1b-5-radioaktivt-sonderfall', 2, 'E', 'multiple_choice', 'Begrepp', 'Vad består alfastrålning av?', NULL, '["Snabba elektroner","Heliumkärnor (2 protoner och 2 neutroner)","Elektromagnetisk strålning","Fria neutroner"]', '1', NULL, NULL, 'Alfapartikeln har masstal 4 och laddning +2.', 'Alfastrålning består av tunga heliumkärnor med två protoner och två neutroner.', NULL, 'radioaktivt-sonderfall');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-5-03', 'chap-fysik-1b-5', 'les-fysik-1b-5-radioaktivt-sonderfall', 3, 'C', 'multiple_choice', 'Kärnfysik', 'Vad händer med en atomkärnas atomnummer Z när den sänder ut en β⁻-partikel (elektron)?', NULL, '["Det minskar med 2","Det ökar med 1","Det är oförändrat","Det minskar med 1"]', '1', NULL, NULL, 'En neutron omvandlas till en proton och en elektron.', 'Antalet protoner (Z) ökar med 1 medan masstalet A är oförändrat.', NULL, 'radioaktivt-sonderfall');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-5-04', 'chap-fysik-1b-5', 'les-fysik-1b-5-atommodeller-och-fotoner', 4, 'C', 'multiple_choice', 'Begrepp', 'Hur bildas en emissionslinje i ett atomspektrum?', NULL, '["En elektron hoppar från en lägre till en högre energinivå utan foton","En elektron faller från en högre till en lägre energinivå och sänder ut en foton med energin ΔE","Atomkärnan klyvs i två delar","Alla elektroner lämnar atomen samtidigt"]', '1', NULL, NULL, 'Energin bevaras när elektronen tappar energi.', 'Energiskillnaden ΔE = E₂ − E₁ sänds ut som en foton med frekvensen f = ΔE / h.', NULL, 'atommodeller-och-fotoner');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-5-05', 'chap-fysik-1b-5', 'les-fysik-1b-5-atommodeller-och-fotoner', 5, 'A', 'numeric', 'Beräkning', 'En foton har energin 3,313 · 10⁻¹⁹ J. Beräkna dess frekvens i enheten 10¹⁴ Hz (ange endast faktorn före 10¹⁴, t.ex. 5,0). (h = 6,626 · 10⁻³⁴ J·s)', 'f = \frac{E}{h}', NULL, '5', 0.1, '· 10¹⁴ Hz', 'Dividera fotonenergin med Plancks konstant.', 'f = 3,313 · 10⁻¹⁹ / (6,626 · 10⁻³⁴) = 5,0 · 10¹⁴ Hz.', NULL, 'atommodeller-och-fotoner');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-fysik-1b-5-06', 'chap-fysik-1b-5', 'les-fysik-1b-5-radioaktivt-sonderfall', 6, 'A', 'multiple_choice', 'Härledning', 'Varför frigörs enorma energimängder vid kärnfission och kärnfusion?', NULL, '["Reaktanterna har lägre massa än produkterna","Produkternas sammanlagda massa är mindre än reaktanternas, och massdefekten blir energi enligt ΔE = Δm · c²","Elektronerna i yttersta skalet brinner upp","Halveringstiden blir oändlig"]', '1', NULL, NULL, 'Använd Einsteins massenergisamband.', 'En liten massminskning Δm ger stor energi ΔE eftersom c² = 9,0 · 10¹⁶ m²/s².', NULL, 'radioaktivt-sonderfall');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-1-01', 'chap-matte-1a-1', 'les-matte-1a-1-procent-och-forandringsfaktor', 1, 'E', 'numeric', 'Beräkning', 'Hur mycket är 15 % av 400 kr?', NULL, NULL, '60', 0.5, 'kr', 'Multiplicera 400 med 0,15.', '0,15 · 400 = 60 kr.', NULL, 'procent-och-forandringsfaktor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-1-02', 'chap-matte-1a-1', 'les-matte-1a-1-heltal-och-brak', 2, 'E', 'multiple_choice', 'Bråk', 'Hur mycket motsvarar bråket 3/8 uttryckt i procent?', NULL, '["38 %","37,5 %","30,8 %","40 %"]', '1', NULL, NULL, 'Beräkna 3 / 8 i decimalform och multiplicera med 100.', '3 / 8 = 0,375 = 37,5 %.', NULL, 'heltal-och-brak');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-1-03', 'chap-matte-1a-1', 'les-matte-1a-1-procent-och-forandringsfaktor', 3, 'E', 'numeric', 'Beräkning', 'En jacka kostar 1 200 kr och säljs med 25 % rabatt. Vad blir det nya priset i kronor?', NULL, NULL, '900', 1, 'kr', 'Förändringsfaktorn är 1 − 0,25 = 0,75.', '1 200 · 0,75 = 900 kr.', NULL, 'procent-och-forandringsfaktor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-1-04', 'chap-matte-1a-1', 'les-matte-1a-1-procent-och-forandringsfaktor', 4, 'C', 'numeric', 'Beräkning', 'En vara kostar 500 kr. Priset höjs först med 20 % och sänks därefter med 20 %. Vad kostar varan i kronor efter båda ändringarna?', NULL, NULL, '480', 1, 'kr', 'Multiplicera med 1,20 och sedan med 0,80.', '500 · 1,20 · 0,80 = 500 · 0,96 = 480 kr.', NULL, 'procent-och-forandringsfaktor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-1-05', 'chap-matte-1a-1', 'les-matte-1a-1-overslagsrakning-och-enheter', 5, 'C', 'multiple_choice', 'Enheter', 'En vattentank rymmer 2,5 m³. Hur många liter vatten motsvarar det?', NULL, '["25 liter","250 liter","2 500 liter","25 000 liter"]', '2', NULL, NULL, '1 m³ = 1 000 dm³ = 1 000 liter.', '2,5 · 1 000 = 2 500 liter.', NULL, 'overslagsrakning-och-enheter');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-1-06', 'chap-matte-1a-1', 'les-matte-1a-1-procent-och-forandringsfaktor', 6, 'A', 'numeric', 'Problemlösning', 'Priset på en tjänst är 1 500 kr inklusive 25 % moms. Vad är priset exklusive moms i kronor?', NULL, NULL, '1200', 1, 'kr', 'Priset med moms är 1,25 gånger priset utan moms.', '1 500 / 1,25 = 1 200 kr.', NULL, 'procent-och-forandringsfaktor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-1-07', 'chap-matte-1a-1', 'les-matte-1a-1-procent-och-forandringsfaktor', 7, 'A', 'multiple_choice', 'Analys', 'Efter två lika stora årliga procentuella höjningar har en hyra ökat totalt med 44 %. Hur stor var höjningen varje år?', NULL, '["22 %","20 %","18 %","24 %"]', '1', NULL, NULL, 'Lös ff² = 1,44.', 'ff = √1,44 = 1,20, vilket motsvarar 20 % per år.', NULL, 'procent-och-forandringsfaktor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-2-01', 'chap-matte-1a-2', 'les-matte-1a-2-uttryck-och-ekvationer', 1, 'E', 'numeric', 'Ekvationer', 'Lös ekvationen 3x + 7 = 22. Ange x.', NULL, NULL, '5', 0.01, NULL, 'Subtrahera 7 från båda sidor först.', '3x = 22 − 7 = 15 ger x = 15 / 3 = 5.', NULL, 'uttryck-och-ekvationer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-2-02', 'chap-matte-1a-2', 'les-matte-1a-2-uttryck-och-ekvationer', 2, 'C', 'multiple_choice', 'Algebra', 'Förenkla uttrycket 5x − (2x − 4).', NULL, '["3x − 4","3x + 4","7x − 4","7x + 4"]', '1', NULL, NULL, 'Minustecknet framför parentesen vänder tecknet på −4.', '5x − 2x + 4 = 3x + 4.', NULL, 'uttryck-och-ekvationer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-2-03', 'chap-matte-1a-2', 'les-matte-1a-2-uttryck-och-ekvationer', 3, 'C', 'numeric', 'Ekvationer', 'Lös ekvationen 4(x − 2) = 20. Ange x.', NULL, NULL, '7', 0.01, NULL, 'Dividera båda sidor med 4 eller multiplicera in 4 i parentesen.', 'x − 2 = 5 ger x = 7.', NULL, 'uttryck-och-ekvationer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-2-04', 'chap-matte-1a-2', 'les-matte-1a-2-uttryck-och-ekvationer', 4, 'A', 'numeric', 'Problemlösning', 'En hyrbil kostar 350 kr i grundavgift plus 15 kr per mil. Total kostnad blir 650 kr. Hur många mil kördes bilen?', NULL, NULL, '20', 0.1, 'mil', 'Lös ekvationen 350 + 15x = 650.', '15x = 650 − 350 = 300 ger x = 20 mil.', NULL, 'uttryck-och-ekvationer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-3-01', 'chap-matte-1a-3', 'les-matte-1a-3-area-volym-och-skala', 1, 'E', 'numeric', 'Geometri', 'På en ritning i skala 1:50 är en vägg 8,0 cm lång. Hur lång är väggen i verkligheten uttryckt i meter?', NULL, NULL, '4', 0.05, 'm', 'Multiplicera 8,0 cm med 50 och gör om till meter.', '8,0 · 50 = 400 cm = 4,0 m.', NULL, 'area-volym-och-skala');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-3-02', 'chap-matte-1a-3', 'les-matte-1a-3-area-volym-och-skala', 2, 'C', 'numeric', 'Geometri', 'En triangel har basen 12 cm och höjden 7,0 cm. Beräkna arean i cm².', NULL, NULL, '42', 0.2, 'cm²', 'Area = (b · h) / 2.', '(12 · 7,0) / 2 = 42 cm².', NULL, 'area-volym-och-skala');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-3-03', 'chap-matte-1a-3', 'les-matte-1a-3-area-volym-och-skala', 3, 'C', 'multiple_choice', 'Skala', 'En kvadrat har sidorna som fördubblas. Hur ändras kvadratens area?', NULL, '["Den fördubblas","Den blir 4 gånger så stor","Den blir 8 gånger så stor","Den är oförändrad"]', '1', NULL, NULL, 'Areaskalan är längdskalan i kvadrat.', '2² = 4 gånger så stor area.', NULL, 'area-volym-och-skala');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-3-04', 'chap-matte-1a-3', 'les-matte-1a-3-area-volym-och-skala', 4, 'A', 'multiple_choice', 'Skala', 'En modellbil byggs i längdskalan 1:10. Hur många gånger större är den verkliga bilens tankvolym jämfört med modellens?', NULL, '["10 gånger","100 gånger","1 000 gånger","30 gånger"]', '2', NULL, NULL, 'Volymskalan är k³.', '10³ = 1 000 gånger större volym.', NULL, 'area-volym-och-skala');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-4-01', 'chap-matte-1a-4', 'les-matte-1a-4-lagesmatt-och-sannolikhet', 1, 'E', 'numeric', 'Statistik', 'Beräkna medianen för mätvärdena 8, 22, 10, 15, 11.', NULL, NULL, '11', 0.01, NULL, 'Ordna värdena från minst till störst.', 'Sorterad lista: 8, 10, 11, 15, 22. Mittersta talet är 11.', NULL, 'lagesmatt-och-sannolikhet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-4-02', 'chap-matte-1a-4', 'les-matte-1a-4-lagesmatt-och-sannolikhet', 2, 'E', 'multiple_choice', 'Sannolikhet', 'Vad är sannolikheten att slå ett udda tal med en vanlig sexsidig tärning?', NULL, '["1/6","1/3","1/2","2/3"]', '2', NULL, NULL, 'Udda tal är 1, 3 och 5.', '3 gynnsamma av 6 möjliga ger 3/6 = 1/2.', NULL, 'lagesmatt-och-sannolikhet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-4-03', 'chap-matte-1a-4', 'les-matte-1a-4-lagesmatt-och-sannolikhet', 3, 'C', 'numeric', 'Statistik', 'Fyra provresultat har medelvärdet 18 poäng. Vilken blir den sammanlagda poängsumman?', NULL, NULL, '72', 0.1, 'poäng', 'Summan = medelvärde · antal.', '18 · 4 = 72 poäng.', NULL, 'lagesmatt-och-sannolikhet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1a-4-04', 'chap-matte-1a-4', 'les-matte-1a-4-lagesmatt-och-sannolikhet', 4, 'A', 'multiple_choice', 'Sannolikhet', 'Ett mynt singlas tre gånger. Vad är sannolikheten att få minst en krona?', NULL, '["1/8","3/8","7/8","1/2"]', '2', NULL, NULL, 'Använd komplementhändelsen: 1 − P(tre klave).', 'P(ingen krona) = (1/2)³ = 1/8, så P(minst en krona) = 1 − 1/8 = 7/8.', NULL, 'lagesmatt-och-sannolikhet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-1-01', 'chap-matte-1b-1', 'les-matte-1b-1-procent-och-procentenheter', 1, 'E', 'multiple_choice', 'Begrepp', 'Skatten i en kommun höjs från 30 % till 33 %. Hur beskrivs höjningen i procentenheter?', NULL, '["3 procentenheter","10 procentenheter","3,3 procentenheter","0,3 procentenheter"]', '0', NULL, NULL, 'Subtrahera de två procentsatserna.', '33 − 30 = 3 procentenheter.', NULL, 'procent-och-procentenheter');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-1-02', 'chap-matte-1b-1', 'les-matte-1b-1-forandringsfaktor-och-ranta', 2, 'E', 'numeric', 'Beräkning', 'Du sätter in 10 000 kr på ett konto med 5 % årsränta. Hur många kronor finns på kontot efter 2 år om ingen ränta tas ut?', NULL, NULL, '11025', 1, 'kr', 'Beräkna 10 000 · 1,05².', '10 000 · 1,05² = 10 000 · 1,1025 = 11 025 kr.', NULL, 'forandringsfaktor-och-ranta');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-1-03', 'chap-matte-1b-1', 'les-matte-1b-1-algebraiska-uttryck-och-ekvationer', 3, 'E', 'numeric', 'Ekvationer', 'Lös ekvationen 5x − 8 = 2x + 13. Ange x.', NULL, NULL, '7', 0.01, NULL, 'Samla x-termerna på vänster sida.', '5x − 2x = 13 + 8 ger 3x = 21 och x = 7.', NULL, 'algebraiska-uttryck-och-ekvationer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-1-04', 'chap-matte-1b-1', 'les-matte-1b-1-procent-och-procentenheter', 4, 'C', 'numeric', 'Beräkning', 'Andelen elever som väljer idrott ökar från 20 % till 25 %. Hur många procents relativ ökning motsvarar det?', NULL, NULL, '25', 0.2, '%', 'Dela ökningen (5 procentenheter) med startvärdet (20).', '(25 − 20) / 20 = 5 / 20 = 0,25 = 25 %.', NULL, 'procent-och-procentenheter');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-1-05', 'chap-matte-1b-1', 'les-matte-1b-1-algebraiska-uttryck-och-ekvationer', 5, 'C', 'multiple_choice', 'Algebra', 'Vilket uttryck är lika med 4(2x − 3) − 2(x − 5)?', NULL, '["6x − 22","6x − 2","6x + 2","10x − 2"]', '1', NULL, NULL, 'Multiplicera in −2 i den andra parentesen med rätt tecken.', '8x − 12 − 2x + 10 = 6x − 2.', NULL, 'algebraiska-uttryck-och-ekvationer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-1-06', 'chap-matte-1b-1', 'les-matte-1b-1-forandringsfaktor-och-ranta', 6, 'A', 'numeric', 'Problemlösning', 'En vara hade prisindex 120 år 2024 och kostade då 1 800 kr. Vad kostade varan i basåret (index 100)?', NULL, NULL, '1500', 1, 'kr', 'Dividera 1 800 med 1,20.', '1 800 / 1,20 = 1 500 kr.', NULL, 'forandringsfaktor-och-ranta');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-1-07', 'chap-matte-1b-1', 'les-matte-1b-1-procent-och-procentenheter', 7, 'A', 'multiple_choice', 'Analys', 'En aktie faller först med 20 %. Med hur många procent måste den därefter stiga för att återfå sitt ursprungliga värde?', NULL, '["20 %","22 %","25 %","30 %"]', '2', NULL, NULL, 'Lös 0,80 · ff = 1.', 'ff = 1 / 0,80 = 1,25, vilket motsvarar en uppgång på 25 %.', NULL, 'procent-och-procentenheter');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-2-01', 'chap-matte-1b-2', 'les-matte-1b-2-rata-linjen', 1, 'E', 'numeric', 'Funktioner', 'Vad är värdet av f(4) för funktionen f(x) = 3x + 5?', NULL, NULL, '17', 0.01, NULL, 'Ersätt x med 4.', 'f(4) = 3 · 4 + 5 = 17.', NULL, 'rata-linjen');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-2-02', 'chap-matte-1b-2', 'les-matte-1b-2-rata-linjen', 2, 'C', 'numeric', 'Funktioner', 'Bestäm lutningen k för den räta linje som går genom (2, 7) och (6, 19).', NULL, NULL, '3', 0.01, NULL, 'Beräkna (19 − 7) / (6 − 2).', 'k = 12 / 4 = 3.', NULL, 'rata-linjen');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-2-03', 'chap-matte-1b-2', 'les-matte-1b-2-rata-linjen', 3, 'C', 'multiple_choice', 'Funktioner', 'Vilken linje är parallell med y = −2x + 5?', NULL, '["y = 2x + 5","y = −2x − 9","y = 5x − 2","y = 0,5x + 5"]', '1', NULL, NULL, 'Parallella linjer har samma k-värde.', 'Båda linjerna har k = −2.', NULL, 'rata-linjen');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-2-04', 'chap-matte-1b-2', 'les-matte-1b-2-rata-linjen', 4, 'A', 'numeric', 'Funktioner', 'En rät linje har k = 2 och går genom punkten (3, 10). Vad är linjens m-värde?', NULL, NULL, '4', 0.01, NULL, 'Sätt in x = 3 och y = 10 i y = 2x + m.', '10 = 2 · 3 + m ger m = 4.', NULL, 'rata-linjen');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-3-01', 'chap-matte-1b-3', 'les-matte-1b-3-pythagoras-och-trigonometri', 1, 'E', 'numeric', 'Geometri', 'Kateterna i en rätvinklig triangel är 9 cm och 12 cm. Hur lång är hypotenusan i cm?', NULL, NULL, '15', 0.1, 'cm', 'Beräkna √(9² + 12²).', 'c = √(81 + 144) = √225 = 15 cm.', NULL, 'pythagoras-och-trigonometri');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-3-02', 'chap-matte-1b-3', 'les-matte-1b-3-pythagoras-och-trigonometri', 2, 'C', 'numeric', 'Geometri', 'En likbent triangel har toppvinkeln 40°. Hur stor är vardera basvinkeln i grader?', NULL, NULL, '70', 0.1, '°', 'Vinkelsumman är 180° och de två basvinklarna är lika stora.', '(180 − 40) / 2 = 70°.', NULL, 'pythagoras-och-trigonometri');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-3-03', 'chap-matte-1b-3', 'les-matte-1b-3-pythagoras-och-trigonometri', 3, 'C', 'multiple_choice', 'Trigonometri', 'Hur definieras sin v i en rätvinklig triangel?', NULL, '["Närliggande katet / hypotenusa","Motstående katet / hypotenusa","Motstående katet / närliggande katet","Hypotenusa / motstående katet"]', '1', NULL, NULL, 'Sinus kopplar ihop den sida som ligger mittemot vinkeln med hypotenusan.', 'sin v = motstående katet / hypotenusa.', NULL, 'pythagoras-och-trigonometri');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-3-04', 'chap-matte-1b-3', 'les-matte-1b-3-pythagoras-och-trigonometri', 4, 'A', 'numeric', 'Geometri', 'En stege på 5,0 m lutas mot en vägg så att foten står 3,0 m från väggen. Hur högt upp på väggen når stegen i meter?', NULL, NULL, '4', 0.05, 'm', 'Stegen är hypotenusan.', 'h = √(5,0² − 3,0²) = √(25 − 9) = √16 = 4,0 m.', NULL, 'pythagoras-och-trigonometri');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-4-01', 'chap-matte-1b-4', 'les-matte-1b-4-statistik-och-korrelation', 1, 'E', 'numeric', 'Statistik', 'Vad är variationsbredden för talen 4, 18, 9, 25, 11?', NULL, NULL, '21', 0.01, NULL, 'Ta största värdet minus minsta värdet.', '25 − 4 = 21.', NULL, 'statistik-och-korrelation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-4-02', 'chap-matte-1b-4', 'les-matte-1b-4-statistik-och-korrelation', 2, 'C', 'numeric', 'Statistik', 'I ett lådagram är Q₁ = 15 och Q₃ = 27. Hur stort är kvartilavståndet?', NULL, NULL, '12', 0.01, NULL, 'Beräkna Q₃ − Q₁.', '27 − 15 = 12.', NULL, 'statistik-och-korrelation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-4-03', 'chap-matte-1b-4', 'les-matte-1b-4-statistik-och-korrelation', 3, 'C', 'multiple_choice', 'Statistik', 'Hur stor andel av mätvärdena ligger mellan nedre kvartilen och övre kvartilen i ett lådagram?', NULL, '["25 %","50 %","75 %","100 %"]', '1', NULL, NULL, 'Lådan i ett lådagram omfattar värdena mellan 25 %- och 75 %-gränserna.', '75 % − 25 % = 50 % av värdena.', NULL, 'statistik-och-korrelation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1b-4-04', 'chap-matte-1b-4', 'les-matte-1b-4-statistik-och-korrelation', 4, 'A', 'multiple_choice', 'Analys', 'En graf startar y-axeln på 95 i stället för 0, vilket får en stapel på 100 att se fem gånger högre ut än en på 96. Vad bör granskas kritiskt?', NULL, '["Källans ålder","Avklippt y-axel som visuellt överdriver skillnaden","Att medelvärdet saknas","Att medianen alltid är noll"]', '1', NULL, NULL, 'Kontrollera alltid axlarnas gradering i diagram.', 'En bruten eller avklippt y-axel förstorar små skillnader och kan vilseleda läsaren.', NULL, 'statistik-och-korrelation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-1-01', 'chap-matte-1c-1', 'les-matte-1c-1-reella-tal-och-potenslagar', 1, 'E', 'multiple_choice', 'Potenser', 'Förenkla uttrycket x³ · x⁴.', NULL, '["x¹²","x⁷","2x⁷","x⁻¹"]', '1', NULL, NULL, 'Addera exponenterna när basen är densamma.', 'x³ · x⁴ = x³⁺⁴ = x⁷.', NULL, 'reella-tal-och-potenslagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-1-02', 'chap-matte-1c-1', 'les-matte-1c-1-reella-tal-och-potenslagar', 2, 'E', 'numeric', 'Potenser', 'Beräkna värdet av 5⁰ + 2³.', NULL, NULL, '9', 0.01, NULL, 'Alla tal (utom 0) upphöjt till 0 blir 1.', '5⁰ + 2³ = 1 + 8 = 9.', NULL, 'reella-tal-och-potenslagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-1-03', 'chap-matte-1c-1', 'les-matte-1c-1-ekvationer-och-olikheter', 3, 'E', 'multiple_choice', 'Olikheter', 'Lös olikheten −3x > 12.', NULL, '["x > −4","x < −4","x > 4","x < 4"]', '1', NULL, NULL, 'Vänd olikhetstecknet när du dividerar med −3.', 'Division med −3 vänder tecknet: x < −4.', NULL, 'ekvationer-och-olikheter');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-1-04', 'chap-matte-1c-1', 'les-matte-1c-1-reella-tal-och-potenslagar', 4, 'C', 'numeric', 'Potenser', 'Beräkna värdet av (2⁴ · 2⁵) / 2⁶.', NULL, NULL, '8', 0.01, NULL, '2^(4 + 5 − 6).', '2^(9−6) = 2³ = 8.', NULL, 'reella-tal-och-potenslagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-1-05', 'chap-matte-1c-1', 'les-matte-1c-1-reella-tal-och-potenslagar', 5, 'C', 'multiple_choice', 'Grundpotensform', 'Hur skrivs talet 0,00045 i grundpotensform?', NULL, '["45 · 10⁻⁵","4,5 · 10⁻⁴","0,45 · 10⁻³","4,5 · 10⁴"]', '1', NULL, NULL, 'Faktorn före tiopotensen måste ligga mellan 1 och 10.', 'Kommat flyttas 4 steg åt höger, så 0,00045 = 4,5 · 10⁻⁴.', NULL, 'reella-tal-och-potenslagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-1-06', 'chap-matte-1c-1', 'les-matte-1c-1-procent-och-tillvaxt', 6, 'C', 'numeric', 'Tillväxt', 'En bakteriekultur startar på 800 bakterier och ökar med 25 % per timme. Hur många bakterier finns efter 2 timmar?', NULL, NULL, '1250', 1, NULL, 'Beräkna 800 · 1,25².', '800 · 1,25² = 800 · 1,5625 = 1 250.', NULL, 'procent-och-tillvaxt');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-1-07', 'chap-matte-1c-1', 'les-matte-1c-1-ekvationer-och-olikheter', 7, 'A', 'numeric', 'Ekvationer', 'Lös ekvationen (x + 2)/3 − (x − 1)/2 = 1. Ange x.', NULL, NULL, '1', 0.01, NULL, 'Multiplicera alla termer med 6.', '2(x + 2) − 3(x − 1) = 6 ger 2x + 4 − 3x + 3 = 6, alltså −x = −1 och x = 1.', NULL, 'ekvationer-och-olikheter');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-1-08', 'chap-matte-1c-1', 'les-matte-1c-1-ekvationer-och-olikheter', 8, 'A', 'multiple_choice', 'Bevis', 'Vilket uttryck bevisar allmänt att summan av två godtyckliga udda heltal alltid är jämn?', NULL, '["3 + 5 = 8, vilket är jämnt","(2n + 1) + (2m + 1) = 2(n + m + 1)","n + (n + 1) = 2n + 1","2n · 2m = 4nm"]', '1', NULL, NULL, 'Två godtyckliga udda tal kan ha olika heltalsindex n och m.', '(2n + 1) + (2m + 1) = 2(n + m + 1), som är delbart med 2 för alla heltal n och m.', NULL, 'ekvationer-och-olikheter');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-2-01', 'chap-matte-1c-2', 'les-matte-1c-2-funktionsbegrepp-och-rata-linjen', 1, 'E', 'numeric', 'Funktioner', 'Linjen 6x + 2y = 10 skrivs på formen y = kx + m. Vad är k?', NULL, NULL, '-3', 0.01, NULL, 'Lös ut y genom att subtrahera 6x och dividera med 2.', '2y = −6x + 10 ger y = −3x + 5, så k = −3.', NULL, 'funktionsbegrepp-och-rata-linjen');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-2-02', 'chap-matte-1c-2', 'les-matte-1c-2-funktionsbegrepp-och-rata-linjen', 2, 'C', 'numeric', 'Funktioner', 'För vilket värde på x gäller f(x) = 19 om f(x) = 4x − 5?', NULL, NULL, '6', 0.01, NULL, 'Lös 4x − 5 = 19.', '4x = 24 ger x = 6.', NULL, 'funktionsbegrepp-och-rata-linjen');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-2-03', 'chap-matte-1c-2', 'les-matte-1c-2-funktionsbegrepp-och-rata-linjen', 3, 'C', 'multiple_choice', 'Begrepp', 'Vad kallas mängden av alla tillåtna x-värden till en funktion?', NULL, '["Värdemängden","Definitionsmängden","Riktningskoefficienten","Nollstället"]', '1', NULL, NULL, 'Det definierar var funktionen gäller.', 'De tillåtna x-värdena utgör funktionens definitionsmängd.', NULL, 'funktionsbegrepp-och-rata-linjen');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-2-04', 'chap-matte-1c-2', 'les-matte-1c-2-funktionsbegrepp-och-rata-linjen', 4, 'A', 'numeric', 'Funktioner', 'En rät linje går genom (2, 1) och är parallell med linjen 3x − y = 4. Vad är den nya linjens m-värde?', NULL, NULL, '-5', 0.01, NULL, 'Bestäm k = 3 från y = 3x − 4 och sätt in (2, 1).', '1 = 3 · 2 + m ger m = −5.', NULL, 'funktionsbegrepp-och-rata-linjen');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-3-01', 'chap-matte-1c-3', 'les-matte-1c-3-likformighet-och-trigonometri', 1, 'E', 'numeric', 'Trigonometri', 'En rätvinklig triangel har hypotenusan 14 cm och en spetsig vinkel på 30°. Hur lång är motstående katet i cm?', NULL, NULL, '7', 0.1, 'cm', 'sin 30° = 0,5.', 'a = 14 · sin 30° = 14 · 0,5 = 7 cm.', NULL, 'likformighet-och-trigonometri');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-3-02', 'chap-matte-1c-3', 'les-matte-1c-3-likformighet-och-trigonometri', 2, 'C', 'numeric', 'Geometri', 'Två trianglar är likformiga. Den mindre har sidorna 5, 7 och 9 cm. Den störres kortaste sida är 15 cm. Hur lång är den störres längsta sida i cm?', NULL, NULL, '27', 0.1, 'cm', 'Skalfaktorn är 15 / 5 = 3.', '9 · 3 = 27 cm.', NULL, 'likformighet-och-trigonometri');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-3-03', 'chap-matte-1c-3', 'les-matte-1c-3-likformighet-och-trigonometri', 3, 'C', 'multiple_choice', 'Trigonometri', 'För vilken vinkel v i en rätvinklig triangel gäller tan v = 1?', NULL, '["30°","45°","60°","90°"]', '1', NULL, NULL, 'När tan v = 1 är de båda kateterna lika långa.', 'En likbent rätvinklig triangel har de spetsiga vinklarna 45°.', NULL, 'likformighet-och-trigonometri');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-3-04', 'chap-matte-1c-3', 'les-matte-1c-3-likformighet-och-trigonometri', 4, 'A', 'numeric', 'Geometri', 'En triangel har arean 12 cm². Alla dess sidor förstoras med längdskalan 3:1. Vad blir den nya arean i cm²?', NULL, NULL, '108', 0.5, 'cm²', 'Areaskalan är 3² = 9.', '12 · 3² = 12 · 9 = 108 cm².', NULL, 'likformighet-och-trigonometri');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-4-01', 'chap-matte-1c-4', 'les-matte-1c-4-vektorer-i-planet', 1, 'E', 'multiple_choice', 'Vektorer', 'Givet vektorerna u = (4, −2) och v = (−1, 7). Vad blir u + v?', NULL, '["(3, 5)","(5, −9)","(3, −5)","(−4, −14)"]', '0', NULL, NULL, 'Addera x-värden för sig och y-värden för sig.', '(4 + (−1), −2 + 7) = (3, 5).', NULL, 'vektorer-i-planet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-4-02', 'chap-matte-1c-4', 'les-matte-1c-4-vektorer-i-planet', 2, 'C', 'numeric', 'Vektorer', 'Beräkna längden av vektorn v = (3, −4).', NULL, NULL, '5', 0.01, NULL, 'Använd |v| = √(3² + (−4)²).', '√(9 + 16) = √25 = 5.', NULL, 'vektorer-i-planet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-4-03', 'chap-matte-1c-4', 'les-matte-1c-4-vektorer-i-planet', 3, 'C', 'numeric', 'Vektorer', 'Punkterna A(1, 2) och B(7, 10) bildar vektorn AB. Hur lång är AB?', NULL, NULL, '10', 0.05, NULL, 'AB = (7 − 1, 10 − 2) = (6, 8).', '|AB| = √(6² + 8²) = √100 = 10.', NULL, 'vektorer-i-planet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-1c-4-04', 'chap-matte-1c-4', 'les-matte-1c-4-vektorer-i-planet', 4, 'A', 'multiple_choice', 'Sannolikhet', 'I en skål finns 4 gröna och 6 gula kulor. Du drar två kulor utan återläggning. Vad är sannolikheten att exakt en kula är grön?', NULL, '["24/90","48/90","16/100","12/45"]', '1', NULL, NULL, 'Addera P(grön sedan gul) + P(gul sedan grön).', '(4/10)·(6/9) + (6/10)·(4/9) = 24/90 + 24/90 = 48/90 (= 8/15).', NULL, 'vektorer-i-planet');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-1-01', 'chap-matte-2a-1', 'les-matte-2a-1-grafisk-losning', 1, 'E', 'multiple_choice', 'Begrepp', 'Vad motsvarar skärningspunkten mellan graferna till två linjära ekvationer i ett koordinatsystem?', NULL, '["Linjernas medelvärde","Den lösning (x, y) som uppfyller båda ekvationerna samtidigt","Linjernas m-värde","Ett tecken på att lösning saknas"]', '1', NULL, NULL, 'Punkten ligger på båda linjerna samtidigt.', 'En punkt på båda linjerna gör båda likheterna sanna samtidigt.', NULL, 'grafisk-losning');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-1-02', 'chap-matte-2a-1', 'les-matte-2a-1-grafisk-losning', 2, 'E', 'numeric', 'Ekvationssystem', 'Lös ekvationssystemet y = 2x + 1 och y = x + 4. Ange x.', NULL, NULL, '3', 0.01, NULL, 'Sätt 2x + 1 = x + 4.', '2x + 1 = x + 4 ger x = 3 (och y = 7).', NULL, 'grafisk-losning');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-1-03', 'chap-matte-2a-1', 'les-matte-2a-1-additionsmetoden', 3, 'C', 'numeric', 'Ekvationssystem', 'Lös ekvationssystemet x + y = 10 och x − y = 4. Ange x.', NULL, NULL, '7', 0.01, NULL, 'Addera de båda ekvationerna ledvis.', '2x = 14 ger x = 7 (och y = 3).', NULL, 'additionsmetoden');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-1-04', 'chap-matte-2a-1', 'les-matte-2a-1-additionsmetoden', 4, 'C', 'numeric', 'Ekvationssystem', 'Lös ekvationssystemet 3x + y = 11 och 2x + y = 8. Ange y.', NULL, NULL, '2', 0.01, NULL, 'Subtrahera den andra ekvationen från den första för att få x först.', 'x = 3 ger 2·3 + y = 8, alltså y = 2.', NULL, 'additionsmetoden');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-1-05', 'chap-matte-2a-1', 'les-matte-2a-1-grafisk-losning', 5, 'A', 'multiple_choice', 'Analys', 'När saknar ett system av två räta linjer helt lösning?', NULL, '["När linjerna har olika k-värden","När linjerna har samma k-värde men olika m-värden","När båda linjerna går genom origo","När produkten av k-värdena är −1"]', '1', NULL, NULL, 'Parallella linjer som inte ligger på varandra skär aldrig varandra.', 'Samma k-värde ger parallella linjer, och olika m-värden gör att de aldrig möts.', NULL, 'grafisk-losning');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-1-06', 'chap-matte-2a-1', 'les-matte-2a-1-substitutionsmetoden', 6, 'A', 'numeric', 'Problemlösning', 'Två vuxenbiljetter och tre barnbiljetter kostar tillsammans 460 kr. En vuxen- och en barnbiljett kostar 190 kr. Vad kostar en vuxenbiljett i kronor?', NULL, NULL, '110', 0.5, 'kr', 'Ställ upp 2v + 3b = 460 och v + b = 190.', 'b = 190 − v ger 2v + 3(190 − v) = 460, alltså −v = −110 och v = 110 kr.', NULL, 'substitutionsmetoden');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-2-01', 'chap-matte-2a-2', 'les-matte-2a-2-pq-formeln-och-nollproduct', 1, 'E', 'numeric', 'Andragradsekvation', 'Lös ekvationen x² − 10x + 21 = 0. Ange den största roten.', NULL, NULL, '7', 0.01, NULL, 'x = 5 ± √(25 − 21).', 'x = 5 ± √4 = 5 ± 2 ger rötterna 3 och 7.', NULL, 'pq-formeln-och-nollproduct');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-2-02', 'chap-matte-2a-2', 'les-matte-2a-2-pq-formeln-och-nollproduct', 2, 'C', 'numeric', 'Andragradsekvation', 'Lös ekvationen 3x² − 18x = 0. Ange den positiva roten.', NULL, NULL, '6', 0.01, NULL, 'Bryt ut 3x.', '3x(x − 6) = 0 ger x = 0 eller x = 6.', NULL, 'pq-formeln-och-nollproduct');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-2-03', 'chap-matte-2a-2', 'les-matte-2a-2-pq-formeln-och-nollproduct', 3, 'C', 'multiple_choice', 'Begrepp', 'Vad måste göras först innan pq-formeln tillämpas på 4x² + 8x − 12 = 0?', NULL, '["Ta kvadratroten ur hela ekvationen","Dividera samtliga termer med 4","Flytta 8x till högerledet","Sätta x = 0"]', '1', NULL, NULL, 'Koefficienten framför x² måste bli 1.', 'Division med 4 ger normalformen x² + 2x − 3 = 0.', NULL, 'pq-formeln-och-nollproduct');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-2-04', 'chap-matte-2a-2', 'les-matte-2a-2-pq-formeln-och-nollproduct', 4, 'A', 'numeric', 'Andragradsfunktion', 'En boll följer höjdkurvan h(t) = 20t − 5t² där t är tid i sekunder. Efter hur många sekunder når bollen sin högsta höjd?', NULL, NULL, '2', 0.05, 's', 'Hitta nollställena t₁ och t₂ och ta mitten mellan dem.', '5t(4 − t) = 0 ger nollställena 0 och 4. Symmetrilinjen ligger vid t = 2 s.', NULL, 'pq-formeln-och-nollproduct');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-3-01', 'chap-matte-2a-3', 'les-matte-2a-3-tiologaritmer', 1, 'E', 'numeric', 'Logaritmer', 'Vad är lg 10 000?', NULL, NULL, '4', 0.01, NULL, '10 000 = 10⁴.', 'lg(10⁴) = 4.', NULL, 'tiologaritmer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-3-02', 'chap-matte-2a-3', 'les-matte-2a-3-tiologaritmer', 2, 'E', 'numeric', 'Logaritmer', 'Lös ekvationen lg x = 2. Ange x.', NULL, NULL, '100', 0.1, NULL, 'x = 10².', '10² = 100.', NULL, 'tiologaritmer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-3-03', 'chap-matte-2a-3', 'les-matte-2a-3-tiologaritmer', 3, 'C', 'numeric', 'Potensekvationer', 'Lös ekvationen x³ = 125. Ange x.', NULL, NULL, '5', 0.01, NULL, 'Ta tredjeroten ur 125.', '125^(1/3) = 5 eftersom 5³ = 125.', NULL, 'tiologaritmer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-3-04', 'chap-matte-2a-3', 'les-matte-2a-3-tiologaritmer', 4, 'A', 'multiple_choice', 'Logaritmer', 'Vilket uttryck ger den exakta lösningen till 5 · 1,2^x = 30?', NULL, '["x = lg 6 / lg 1,2","x = lg(6 / 1,2)","x = lg 30 / lg 6","x = 6 / 1,2"]', '0', NULL, NULL, 'Dividera först med 5 så att 1,2^x = 6.', '1,2^x = 6 ger x · lg 1,2 = lg 6, alltså x = lg 6 / lg 1,2.', NULL, 'tiologaritmer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-4-01', 'chap-matte-2a-4', 'les-matte-2a-4-standardavvikelse', 1, 'E', 'numeric', 'Statistik', 'En normalfördelad storhet har medelvärdet 80 och standardavvikelsen 5. Ungefär hur många procent av värdena ligger mellan 75 och 85?', NULL, NULL, '68', 1, '%', '75 till 85 är ±1 standardavvikelse.', 'Cirka 68 % ligger inom ±1 standardavvikelse.', NULL, 'standardavvikelse');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-4-02', 'chap-matte-2a-4', 'les-matte-2a-4-standardavvikelse', 2, 'C', 'numeric', 'Statistik', 'Medelvärdet är 100 och standardavvikelsen 10. Ungefär hur många procent av värdena överstiger 110?', NULL, NULL, '16', 1, '%', 'Ta (100 − 68) / 2.', 'Utanför ±1 standardavvikelse finns 32 %, varav hälften (16 %) ligger ovanför +1 standardavvikelse.', NULL, 'standardavvikelse');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-4-03', 'chap-matte-2a-4', 'les-matte-2a-4-standardavvikelse', 3, 'C', 'multiple_choice', 'Statistik', 'Vad säger en mindre standardavvikelse om en mätserie?', NULL, '["Att medelvärdet alltid är lägre","Att mätvärdena ligger tätare samlade kring medelvärdet","Att datamängden har fler mätpunkter","Att medianen är noll"]', '1', NULL, NULL, 'Standardavvikelse är ett spridningsmått.', 'Liten standardavvikelse betyder låg spridning runt medelvärdet.', NULL, 'standardavvikelse');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2a-4-04', 'chap-matte-2a-4', 'les-matte-2a-4-standardavvikelse', 4, 'A', 'numeric', 'Statistik', 'I en normalfördelning med μ = 50 och σ = 4, ungefär hur många procent ligger mellan 46 och 58?', NULL, NULL, '81.5', 1, '%', 'Addera 34 % (från 46 till 50) och 47,5 % (från 50 till 58).', '68/2 + 95/2 = 34 + 47,5 = 81,5 %.', NULL, 'standardavvikelse');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-1-01', 'chap-matte-2b-1', 'les-matte-2b-1-kvadreringsregler-och-faktorisering', 1, 'E', 'multiple_choice', 'Algebra', 'Utveckla uttrycket (x + 5)².', NULL, '["x² + 25","x² + 5x + 25","x² + 10x + 25","x² + 10x + 10"]', '2', NULL, NULL, 'Använd första kvadreringsregeln: a² + 2ab + b².', '(x + 5)² = x² + 2 · x · 5 + 5² = x² + 10x + 25.', NULL, 'kvadreringsregler-och-faktorisering');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-1-02', 'chap-matte-2b-1', 'les-matte-2b-1-pq-formeln', 2, 'E', 'numeric', 'Andragradsekvation', 'Lös ekvationen x² − 64 = 0. Ange den positiva roten.', NULL, NULL, '8', 0.01, NULL, 'x² = 64.', 'x = ±√64 = ±8. Den positiva roten är 8.', NULL, 'pq-formeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-1-03', 'chap-matte-2b-1', 'les-matte-2b-1-pq-formeln', 3, 'E', 'numeric', 'Andragradsekvation', 'Lös ekvationen x² − 6x + 8 = 0. Ange den största roten.', NULL, NULL, '4', 0.01, NULL, 'Använd pq-formeln med p = −6 och q = 8.', 'x = 3 ± √(9 − 8) = 3 ± 1 ger x₁ = 2 och x₂ = 4.', NULL, 'pq-formeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-1-04', 'chap-matte-2b-1', 'les-matte-2b-1-kvadreringsregler-och-faktorisering', 4, 'C', 'multiple_choice', 'Algebra', 'Förenkla uttrycket (x + 3)(x − 3) − x².', NULL, '["9","−9","6x − 9","−6x − 9"]', '1', NULL, NULL, 'Använd konjugatregeln på (x + 3)(x − 3).', '(x² − 9) − x² = −9.', NULL, 'kvadreringsregler-och-faktorisering');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-1-05', 'chap-matte-2b-1', 'les-matte-2b-1-pq-formeln', 5, 'C', 'numeric', 'Andragradsekvation', 'Lös ekvationen 2x² − 12x + 16 = 0. Ange den minsta roten.', NULL, NULL, '2', 0.01, NULL, 'Dividera först hela ekvationen med 2.', 'x² − 6x + 8 = 0 ger rötterna 2 och 4.', NULL, 'pq-formeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-1-06', 'chap-matte-2b-1', 'les-matte-2b-1-linjara-ekvationssystem', 6, 'A', 'numeric', 'Ekvationssystem', 'Lös ekvationssystemet 2x + 3y = 19 och 4x − 3y = 11. Ange x.', NULL, NULL, '5', 0.01, NULL, 'Addera ekvationerna direkt så att y försvinner.', '6x = 30 ger x = 5 (och y = 3).', NULL, 'linjara-ekvationssystem');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-1-07', 'chap-matte-2b-1', 'les-matte-2b-1-pq-formeln', 7, 'A', 'multiple_choice', 'Analys', 'För vilka värden på a har andragradsekvationen x² + ax + 9 = 0 exakt en reell lösning?', NULL, '["Endast a = 3","a = 6 eller a = −6","Endast a = 9","a = 18 eller a = −18"]', '1', NULL, NULL, 'Sätt uttrycket under rottecknet i pq-formeln lika med noll: (a/2)² − 9 = 0.', '(a/2)² = 9 ger a/2 = ±3, alltså a = ±6.', NULL, 'pq-formeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-2-01', 'chap-matte-2b-2', 'les-matte-2b-2-symmetrilinje-och-vertex', 1, 'E', 'numeric', 'Andragradsfunktion', 'Vad är symmetrilinjens x-värde för funktionen f(x) = x² − 10x + 16?', NULL, NULL, '5', 0.01, NULL, 'Använd x = −b / (2a).', 'x = −(−10) / 2 = 5.', NULL, 'symmetrilinje-och-vertex');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-2-02', 'chap-matte-2b-2', 'les-matte-2b-2-symmetrilinje-och-vertex', 2, 'C', 'numeric', 'Andragradsfunktion', 'Vad är det minsta värdet funktionen f(x) = x² − 10x + 28 antar?', NULL, NULL, '3', 0.01, NULL, 'Symmetrilinjen är x = 5. Beräkna f(5).', 'f(5) = 25 − 50 + 28 = 3.', NULL, 'symmetrilinje-och-vertex');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-2-03', 'chap-matte-2b-2', 'les-matte-2b-2-symmetrilinje-och-vertex', 3, 'C', 'multiple_choice', 'Begrepp', 'Vilken egenskap har grafen till f(x) = −2x² + 8x + 1?', NULL, '["Den har en minimipunkt","Den har en maximipunkt","Den är en rät linje","Den saknar symmetrilinje"]', '1', NULL, NULL, 'Se på tecknet framför x².', 'Koefficienten −2 < 0 betyder att parabeln är vänd nedåt och har en maximipunkt.', NULL, 'symmetrilinje-och-vertex');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-2-04', 'chap-matte-2b-2', 'les-matte-2b-2-symmetrilinje-och-vertex', 4, 'A', 'numeric', 'Optimering', 'Två tal har summan 24. Vad är det största möjliga värdet för deras produkt?', NULL, NULL, '144', 0.5, NULL, 'Ställ upp produkten P(x) = x(24 − x) och hitta vertex.', 'Nollställena är 0 och 24, så max nås vid x = 12: 12 · 12 = 144.', NULL, 'symmetrilinje-och-vertex');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-3-01', 'chap-matte-2b-3', 'les-matte-2b-3-logaritmlagar', 1, 'E', 'numeric', 'Logaritmer', 'Beräkna det exakta värdet av lg 20 + lg 5.', NULL, NULL, '2', 0.01, NULL, 'lg(20 · 5).', 'lg(20 · 5) = lg 100 = 2.', NULL, 'logaritmlagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-3-02', 'chap-matte-2b-3', 'les-matte-2b-3-logaritmlagar', 2, 'C', 'numeric', 'Potensekvationer', 'Lös ekvationen 2 · x³ = 54. Ange x.', NULL, NULL, '3', 0.01, NULL, 'Dividera med 2 innan du tar tredjeroten.', 'x³ = 27 ger x = 3.', NULL, 'logaritmlagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-3-03', 'chap-matte-2b-3', 'les-matte-2b-3-logaritmlagar', 3, 'C', 'multiple_choice', 'Logaritmer', 'Vilket uttryck motsvarar lg 50 − lg 5?', NULL, '["lg 45","1","10","lg 250"]', '1', NULL, NULL, 'lg(50 / 5).', 'lg(50 / 5) = lg 10 = 1.', NULL, 'logaritmlagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-3-04', 'chap-matte-2b-3', 'les-matte-2b-3-logaritmlagar', 4, 'A', 'numeric', 'Logaritmer', 'Beräkna det exakta värdet av (lg 1 000) / (lg 10).', NULL, NULL, '3', 0.01, NULL, 'Räkna ut täljare och nämnare var för sig.', 'lg 1 000 = 3 och lg 10 = 1, så 3 / 1 = 3.', NULL, 'logaritmlagar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-4-01', 'chap-matte-2b-4', 'les-matte-2b-4-regression-och-korrelation', 1, 'E', 'multiple_choice', 'Regression', 'Vilken korrelationskoefficient r visar det starkaste linjära sambandet?', NULL, '["r = 0,45","r = −0,92","r = 0,05","r = 0,78"]', '1', NULL, NULL, 'Se på absolutbeloppet |r|, alltså avståndet till 0.', '|−0,92| = 0,92 är närmast 1, vilket ger starkast linjärt samband.', NULL, 'regression-och-korrelation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-4-02', 'chap-matte-2b-4', 'les-matte-2b-4-regression-och-korrelation', 2, 'C', 'numeric', 'Regression', 'En anpassad regressionslinje för försäljning ges av y = 12x + 300. Vilket y-värde förutsäger modellen vid x = 25?', NULL, NULL, '600', 0.5, NULL, 'Beräkna 12 · 25 + 300.', '12 · 25 + 300 = 300 + 300 = 600.', NULL, 'regression-och-korrelation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-4-03', 'chap-matte-2b-4', 'les-matte-2b-4-regression-och-korrelation', 3, 'C', 'multiple_choice', 'Begrepp', 'Vad kallas det när man använder en regressionsmodell för att beräkna ett värde utanför det uppmätta mätintervallet?', NULL, '["Interpolering","Extrapolering","Normalfördelning","Faktorisering"]', '1', NULL, NULL, 'Extra betyder utanför.', 'Utanför det observerade intervallet kallas skattningen extrapolering.', NULL, 'regression-och-korrelation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2b-4-04', 'chap-matte-2b-4', 'les-matte-2b-4-regression-och-korrelation', 4, 'A', 'multiple_choice', 'Analys', 'Datapunkter ligger exakt på parabeln y = x² symmetriskt för x mellan −5 och 5. Vad blir korrelationskoefficienten r?', NULL, '["r = 1","r = −1","r ≈ 0","r = 25"]', '2', NULL, NULL, 'r mäter bara rätlinjiga samband.', 'Eftersom parabeln är symmetrisk kring y-axeln finns ingen rätlinjig lutning, så r = 0.', NULL, 'regression-och-korrelation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-1-01', 'chap-matte-2c-1', 'les-matte-2c-1-andragradsfunktioner-och-max-min', 1, 'E', 'numeric', 'Andragradsfunktion', 'Vad är symmetrilinjens x-koordinat för f(x) = x² − 8x + 12?', NULL, NULL, '4', 0.01, NULL, 'x = −b / (2a).', 'x = −(−8) / 2 = 4.', NULL, 'andragradsfunktioner-och-max-min');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-1-02', 'chap-matte-2c-1', 'les-matte-2c-1-andragradsfunktioner-och-max-min', 2, 'E', 'numeric', 'Andragradsfunktion', 'Vad är minimivärdet för funktionen f(x) = x² − 8x + 12?', NULL, NULL, '-4', 0.01, NULL, 'Beräkna f(4).', 'f(4) = 4² − 8 · 4 + 12 = 16 − 32 + 12 = −4.', NULL, 'andragradsfunktioner-och-max-min');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-1-03', 'chap-matte-2c-1', 'les-matte-2c-1-pq-formeln-och-diskriminant', 3, 'E', 'numeric', 'Andragradsekvation', 'Lös ekvationen x² + 2x − 15 = 0. Ange den positiva roten.', NULL, NULL, '3', 0.01, NULL, 'x = −1 ± √(1 + 15).', 'x = −1 ± 4 ger rötterna 3 och −5.', NULL, 'pq-formeln-och-diskriminant');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-1-04', 'chap-matte-2c-1', 'les-matte-2c-1-pq-formeln-och-diskriminant', 4, 'C', 'multiple_choice', 'Diskriminant', 'Hur många reella lösningar har ekvationen x² − 4x + 5 = 0?', NULL, '["Två reella lösningar","En dubbelrot","Inga reella lösningar","Oändligt många lösningar"]', '2', NULL, NULL, 'Beräkna uttrycket under rottecknet i pq-formeln.', 'D = (−2)² − 5 = 4 − 5 = −1 < 0, så reella lösningar saknas.', NULL, 'pq-formeln-och-diskriminant');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-1-05', 'chap-matte-2c-1', 'les-matte-2c-1-andragradsfunktioner-och-max-min', 5, 'C', 'numeric', 'Andragradsfunktion', 'En andragradsfunktion har nollställena x₁ = 1 och x₂ = 7 samt går genom punkten (0, 7). Beräkna funktionens extremvärde f(4).', NULL, NULL, '-9', 0.01, NULL, 'Ställ upp f(x) = k(x − 1)(x − 7) och bestäm k från f(0) = 7.', '7 = k(−1)(−7) ger k = 1. f(4) = 1 · (4 − 1)(4 − 7) = 3 · (−3) = −9.', NULL, 'andragradsfunktioner-och-max-min');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-1-06', 'chap-matte-2c-1', 'les-matte-2c-1-pq-formeln-och-diskriminant', 6, 'C', 'numeric', 'Rotekvationer', 'Lös rotekvationen √(x + 5) = x − 1. Ange den giltiga roten x.', NULL, NULL, '4', 0.01, NULL, 'Kvadrera båda led, lös andragradsekvationen och pröva rötterna i ursprungsekvationen.', 'x + 5 = x² − 2x + 1 ger x² − 3x − 4 = 0 med kandidater 4 och −1. Vid x = −1 blir VL = 2 ≠ HL = −2 (falsk rot). Endast x = 4 gäller.', NULL, 'pq-formeln-och-diskriminant');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-1-07', 'chap-matte-2c-1', 'les-matte-2c-1-ekvationssystem-och-parametrar', 7, 'A', 'multiple_choice', 'Analys', 'För vilka värden på k skär linjen y = kx + 1 och parabeln y = x² + 5 aldrig varandra?', NULL, '["k < −4 eller k > 4","−4 < k < 4","Endast k = 4","k > 0"]', '1', NULL, NULL, 'Sätt x² + 5 = kx + 1 och kräv att diskriminanten är negativ.', 'x² − kx + 4 = 0 saknar reella lösningar då (k/2)² − 4 < 0, dvs. k² < 16 eller −4 < k < 4.', NULL, 'ekvationssystem-och-parametrar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-1-08', 'chap-matte-2c-1', 'les-matte-2c-1-andragradsfunktioner-och-max-min', 8, 'A', 'numeric', 'Optimering', 'Med 40 m staket ska en rektangulär hage inhägnas mot en husvägg (staketet bildar tre av sidorna). Vad är den största möjliga arean i m²?', NULL, NULL, '200', 0.5, 'm²', 'Arean är A(x) = x(40 − 2x). Sök parabelns maximipunkt.', 'Nollställena är 0 och 20, så max sker vid x = 10 m: A(10) = 10 · 20 = 200 m².', NULL, 'andragradsfunktioner-och-max-min');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-2-01', 'chap-matte-2c-2', 'les-matte-2c-2-logaritmlagar-och-bevis', 1, 'E', 'numeric', 'Logaritmer', 'Lös ekvationen lg(x − 5) = 1. Ange x.', NULL, NULL, '15', 0.01, NULL, 'x − 5 = 10¹.', 'x − 5 = 10 ger x = 15.', NULL, 'logaritmlagar-och-bevis');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-2-02', 'chap-matte-2c-2', 'les-matte-2c-2-logaritmlagar-och-bevis', 2, 'C', 'numeric', 'Logaritmer', 'Beräkna värdet av lg 8 + lg 125 utan räknare.', NULL, NULL, '3', 0.01, NULL, 'Använd lg a + lg b = lg(a · b).', 'lg(8 · 125) = lg 1 000 = 3.', NULL, 'logaritmlagar-och-bevis');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-2-03', 'chap-matte-2c-2', 'les-matte-2c-2-logaritmlagar-och-bevis', 3, 'C', 'multiple_choice', 'Logaritmer', 'Vilket uttryck motsvarar 2 lg 3 + lg 4?', NULL, '["lg 10","lg 36","lg 12","lg 24"]', '1', NULL, NULL, '2 lg 3 = lg(3²) = lg 9.', 'lg 9 + lg 4 = lg(9 · 4) = lg 36.', NULL, 'logaritmlagar-och-bevis');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-2-04', 'chap-matte-2c-2', 'les-matte-2c-2-logaritmlagar-och-bevis', 4, 'A', 'numeric', 'Logaritmer', 'Om lg a = 2,4 och lg b = 0,6, vad blir värdet av lg(a² / b)?', NULL, NULL, '4.2', 0.05, NULL, 'Skriv om uttrycket till 2 lg a − lg b.', '2 · 2,4 − 0,6 = 4,8 − 0,6 = 4,2.', NULL, 'logaritmlagar-och-bevis');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-3-01', 'chap-matte-2c-3', 'les-matte-2c-3-cirkel-och-avstandsformeln', 1, 'E', 'numeric', 'Geometri', 'En medelpunktsvinkel i en cirkel är 124°. Hur stor är randvinkeln som står på samma cirkelbåge, i grader?', NULL, NULL, '62', 0.1, '°', 'Randvinkeln är hälften av medelpunktsvinkeln.', '124° / 2 = 62°.', NULL, 'cirkel-och-avstandsformeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-3-02', 'chap-matte-2c-3', 'les-matte-2c-3-cirkel-och-avstandsformeln', 2, 'C', 'numeric', 'Koordinatgeometri', 'Vad är radien för cirkeln (x − 2)² + (y + 5)² = 36?', NULL, NULL, '6', 0.01, NULL, 'Högerledet i cirkelns ekvation är r².', 'r = √36 = 6.', NULL, 'cirkel-och-avstandsformeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-3-03', 'chap-matte-2c-3', 'les-matte-2c-3-cirkel-och-avstandsformeln', 3, 'C', 'numeric', 'Koordinatgeometri', 'Beräkna avståndet mellan punkterna (1, 1) och (9, 7).', NULL, NULL, '10', 0.05, NULL, 'd = √((9 − 1)² + (7 − 1)²).', '√(8² + 6²) = √(64 + 36) = √100 = 10.', NULL, 'cirkel-och-avstandsformeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-2c-3-04', 'chap-matte-2c-3', 'les-matte-2c-3-cirkel-och-avstandsformeln', 4, 'A', 'multiple_choice', 'Geometri', 'En triangel är inskriven i en cirkel så att en av triangelns sidor utgör cirkelns diameter. Hur stort är motstående hörn?', NULL, '["45°","60°","90°","120°"]', '2', NULL, NULL, 'Medelpunktsvinkeln över en diameter är 180°.', 'Enligt randvinkelsatsen (Thales sats) är vinkeln 180° / 2 = 90°.', NULL, 'cirkel-och-avstandsformeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-1-01', 'chap-matte-3b-1', 'les-matte-3b-1-polynom-och-faktorisering', 1, 'E', 'numeric', 'Polynom', 'Vad är gradtalet för polynomet p(x) = 3x − 7x⁴ + 2x² + 9?', NULL, NULL, '4', 0.01, NULL, 'Sök den högsta exponenten för x.', 'Termen −7x⁴ har högst exponent, så gradtalet är 4.', NULL, 'polynom-och-faktorisering');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-1-02', 'chap-matte-3b-1', 'les-matte-3b-1-rationella-uttryck', 2, 'E', 'numeric', 'Rationella uttryck', 'För vilket värde på x är det rationella uttrycket (x + 4) / (x − 6) inte definierat?', NULL, NULL, '6', 0.01, NULL, 'Nämnaren får inte bli noll.', 'x − 6 = 0 ger x = 6.', NULL, 'rationella-uttryck');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-1-03', 'chap-matte-3b-1', 'les-matte-3b-1-andringskvoter-och-gransvarden', 3, 'E', 'numeric', 'Ändringskvot', 'Beräkna den genomsnittliga ändringshastigheten för f(x) = x² i intervallet 1 ≤ x ≤ 5.', NULL, NULL, '6', 0.01, NULL, 'Beräkna (f(5) − f(1)) / (5 − 1).', '(25 − 1) / (5 − 1) = 24 / 4 = 6.', NULL, 'andringskvoter-och-gransvarden');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-1-04', 'chap-matte-3b-1', 'les-matte-3b-1-rationella-uttryck', 4, 'C', 'multiple_choice', 'Rationella uttryck', 'Förenkla uttrycket (x² − 9) / (x − 3) så långt som möjligt för x ≠ 3.', NULL, '["x − 3","x + 3","x² + 3","3"]', '1', NULL, NULL, 'Faktorisera x² − 9 med konjugatregeln.', '((x − 3)(x + 3)) / (x − 3) = x + 3.', NULL, 'rationella-uttryck');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-1-05', 'chap-matte-3b-1', 'les-matte-3b-1-andringskvoter-och-gransvarden', 5, 'C', 'numeric', 'Gränsvärden', 'Beräkna gränsvärdet lim(x → 2) (x² − 4) / (x − 2).', '\lim_{x \to 2} \frac{x^2 - 4}{x - 2}', NULL, '4', 0.01, NULL, 'Faktorisera täljaren och förkorta bort (x − 2) innan du sätter in x = 2.', '((x − 2)(x + 2)) / (x − 2) = x + 2, som går mot 2 + 2 = 4.', NULL, 'andringskvoter-och-gransvarden');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-1-06', 'chap-matte-3b-1', 'les-matte-3b-1-andringskvoter-och-gransvarden', 6, 'A', 'numeric', 'Gränsvärden', 'Givet f(x) = 2x² − 1. Beräkna gränsvärdet av ändringskvoten lim(h → 0) (f(3 + h) − f(3)) / h.', '\lim_{h \to 0} \frac{f(3 + h) - f(3)}{h}', NULL, '12', 0.01, NULL, 'Utveckla f(3 + h) = 2(3 + h)² − 1, förenkla och förkorta med h.', '(17 + 12h + 2h² − 17) / h = 12 + 2h → 12 då h → 0.', NULL, 'andringskvoter-och-gransvarden');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-1-07', 'chap-matte-3b-1', 'les-matte-3b-1-rationella-uttryck', 7, 'A', 'multiple_choice', 'Rationella uttryck', 'För vilka värden på x är uttrycket (x + 1) / (x² − 5x + 6) inte definierat?', NULL, '["x = −1","x = 2 och x = 3","x = −2 och x = −3","x = 0 och x = 6"]', '1', NULL, NULL, 'Lös x² − 5x + 6 = 0.', 'Nämnaren faktoriseras till (x − 2)(x − 3), så uttrycket saknar värde för x = 2 och x = 3.', NULL, 'rationella-uttryck');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-2-01', 'chap-matte-3b-2', 'les-matte-3b-2-deriveringsregler', 1, 'E', 'numeric', 'Derivata', 'Givet f(x) = 3x² − 4x + 7. Beräkna f''(2).', NULL, NULL, '8', 0.01, NULL, 'Bestäm f''(x) först.', 'f''(x) = 6x − 4 ger f''(2) = 12 − 4 = 8.', NULL, 'deriveringsregler');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-2-02', 'chap-matte-3b-2', 'les-matte-3b-2-deriveringsregler', 2, 'C', 'multiple_choice', 'Derivata', 'Vad är derivatan f''(x) av funktionen f(x) = 5e^(2x)?', NULL, '["5e^(2x)","10e^(2x)","2e^(2x)","10x e^(2x)"]', '1', NULL, NULL, 'Använd regeln D(e^(kx)) = k · e^(kx).', 'f''(x) = 5 · 2 · e^(2x) = 10e^(2x).', NULL, 'deriveringsregler');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-2-03', 'chap-matte-3b-2', 'les-matte-3b-2-deriveringsregler', 3, 'C', 'numeric', 'Derivata', 'För vilket positivt värde på x har f(x) = x³ − 12x derivatan 0?', NULL, NULL, '2', 0.01, NULL, 'Lös 3x² − 12 = 0.', '3x² = 12 ger x² = 4 och x = 2 (för x > 0).', NULL, 'deriveringsregler');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-2-04', 'chap-matte-3b-2', 'les-matte-3b-2-deriveringsregler', 4, 'A', 'numeric', 'Tangent', 'Tangenten till f(x) = x² + 3x i punkten där x = 1 skrivs på formen y = kx + m. Vad blir m-värdet?', NULL, NULL, '-1', 0.01, NULL, 'Hitta f(1) och k = f''(1), och sätt in i y = kx + m.', 'f(1) = 4, f''(x) = 2x + 3 ger k = 5. 4 = 5 · 1 + m ger m = −1.', NULL, 'deriveringsregler');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-3-01', 'chap-matte-3b-3', 'les-matte-3b-3-extremvarden-och-integraler', 1, 'E', 'numeric', 'Integraler', 'Beräkna den bestämda integralen ∫[0 till 2] 3x² dx.', '\int_0^2 3x^2\,dx', NULL, '8', 0.01, NULL, 'Primitiv funktion till 3x² är x³.', '2³ − 0³ = 8.', NULL, 'extremvarden-och-integraler');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-3-02', 'chap-matte-3b-3', 'les-matte-3b-3-extremvarden-och-integraler', 2, 'C', 'multiple_choice', 'Extremvärden', 'För en funktion gäller att f''(4) = 0 och f''''(4) = −6. Vad har kurvan vid x = 4?', NULL, '["En minimipunkt","En maximipunkt","En terrasspunkt","Ett nollställe"]', '1', NULL, NULL, 'Negativ andraderivata betyder att grafen är konkav nedåt.', 'f''(4) = 0 och f''''(4) < 0 ger en lokal maximipunkt.', NULL, 'extremvarden-och-integraler');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-3-03', 'chap-matte-3b-3', 'les-matte-3b-3-extremvarden-och-integraler', 3, 'C', 'numeric', 'Integraler', 'Beräkna ∫[1 till 3] (2x + 1) dx.', '\int_1^3 (2x + 1)\,dx', NULL, '10', 0.05, NULL, 'Primitiv funktion är x² + x.', '(3² + 3) − (1² + 1) = 12 − 2 = 10.', NULL, 'extremvarden-och-integraler');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3b-3-04', 'chap-matte-3b-3', 'les-matte-3b-3-extremvarden-och-integraler', 4, 'A', 'numeric', 'Optimering', 'Vad är det största värdet som f(x) = x³ − 3x antar på det slutna intervallet 0 ≤ x ≤ 3?', NULL, NULL, '18', 0.1, NULL, 'Testa ändpunkterna x = 0 och x = 3 samt eventuella extrempunkter i intervallet.', 'f(0) = 0, f(1) = −2 och f(3) = 27 − 9 = 18. Största värdet är 18.', NULL, 'extremvarden-och-integraler');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-1-01', 'chap-matte-3c-1', 'les-matte-3c-1-absolutbelopp-och-gransvarden', 1, 'E', 'numeric', 'Absolutbelopp', 'Beräkna värdet av |3 − 10| + |−4|.', NULL, NULL, '11', 0.01, NULL, 'Räkna ut varje absolutbelopp för sig: |−7| = 7.', '7 + 4 = 11.', NULL, 'absolutbelopp-och-gransvarden');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-1-02', 'chap-matte-3c-1', 'les-matte-3c-1-polynom-och-rationella-uttryck', 2, 'E', 'numeric', 'Rationella uttryck', 'För vilket värde på x är uttrycket (2x + 1) / (3x − 15) inte definierat?', NULL, NULL, '5', 0.01, NULL, 'Sätt nämnaren 3x − 15 = 0.', '3x = 15 ger x = 5.', NULL, 'polynom-och-rationella-uttryck');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-1-03', 'chap-matte-3c-1', 'les-matte-3c-1-andringskvoter-och-derivatans-definition', 3, 'E', 'numeric', 'Ändringskvot', 'Beräkna den genomsnittliga ändringshastigheten för f(x) = x³ på intervallet 1 ≤ x ≤ 3.', NULL, NULL, '13', 0.01, NULL, '(f(3) − f(1)) / (3 − 1).', '(27 − 1) / 2 = 26 / 2 = 13.', NULL, 'andringskvoter-och-derivatans-definition');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-1-04', 'chap-matte-3c-1', 'les-matte-3c-1-absolutbelopp-och-gransvarden', 4, 'C', 'multiple_choice', 'Absolutbelopp', 'Vilka lösningar har ekvationen |2x − 4| = 10?', NULL, '["Endast x = 7","x = 7 och x = −3","x = −7 och x = 3","x = 5 och x = −5"]', '1', NULL, NULL, 'Pröva både 2x − 4 = 10 och 2x − 4 = −10.', '2x = 14 ger x = 7, och 2x = −6 ger x = −3.', NULL, 'absolutbelopp-och-gransvarden');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-1-05', 'chap-matte-3c-1', 'les-matte-3c-1-absolutbelopp-och-gransvarden', 5, 'C', 'numeric', 'Gränsvärden', 'Beräkna gränsvärdet lim(x → ∞) (6x² + 5x) / (2x² − 3).', '\lim_{x \to \infty} \frac{6x^2 + 5x}{2x^2 - 3}', NULL, '3', 0.01, NULL, 'Dividera täljare och nämnare med x².', '(6 + 5/x) / (2 − 3/x²) → 6 / 2 = 3 när x → ∞.', NULL, 'absolutbelopp-och-gransvarden');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-1-06', 'chap-matte-3c-1', 'les-matte-3c-1-polynom-och-rationella-uttryck', 6, 'C', 'multiple_choice', 'Rationella uttryck', 'Förenkla (x³ − 4x) / (x² − 2x) då x ≠ 0 och x ≠ 2.', NULL, '["x − 2","x + 2","x² + 2","2x"]', '1', NULL, NULL, 'Bryt ut x i både täljare och nämnare och använd konjugatregeln.', '(x(x − 2)(x + 2)) / (x(x − 2)) = x + 2.', NULL, 'polynom-och-rationella-uttryck');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-1-07', 'chap-matte-3c-1', 'les-matte-3c-1-andringskvoter-och-derivatans-definition', 7, 'A', 'numeric', 'Derivatans definition', 'Använd derivatans definition på f(x) = x² + 3x för att beräkna f''(2).', 'f''(2) = \lim_{h \to 0} \frac{f(2 + h) - f(2)}{h}', NULL, '7', 0.01, NULL, 'Förenkla (f(2 + h) − f(2)) / h till 7 + h.', '((10 + 7h + h²) − 10) / h = 7 + h → 7 då h → 0.', NULL, 'andringskvoter-och-derivatans-definition');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-1-08', 'chap-matte-3c-1', 'les-matte-3c-1-andringskvoter-och-derivatans-definition', 8, 'A', 'multiple_choice', 'Begrepp', 'Vad beskriver uttrycket lim(h → 0) (f(a + h) − f(a)) / h geometriskt?', NULL, '["Arean under kurvan upp till x = a","Riktningskoefficienten för tangenten till kurvan i punkten (a, f(a))","Medelvärdet av f på intervallet [0, a]","Skärningen med y-axeln"]', '1', NULL, NULL, 'När h går mot noll övergår sekanten till tangenten i punkten a.', 'Gränsvärdet ger tangentens lutning i punkten (a, f(a)).', NULL, 'andringskvoter-och-derivatans-definition');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-2-01', 'chap-matte-3c-2', 'les-matte-3c-2-kurvanalys-och-talet-e', 1, 'E', 'numeric', 'Derivata', 'Givet f(x) = 4e^(3x). Vad är f''(0)?', NULL, NULL, '12', 0.01, NULL, 'f''(x) = 12e^(3x) och e⁰ = 1.', 'f''(0) = 12 · e⁰ = 12.', NULL, 'kurvanalys-och-talet-e');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-2-02', 'chap-matte-3c-2', 'les-matte-3c-2-kurvanalys-och-talet-e', 2, 'C', 'multiple_choice', 'Derivata', 'Vad är derivatan av f(x) = 2^x?', NULL, '["x · 2^(x−1)","2^x","2^x · ln 2","ln 2"]', '2', NULL, NULL, 'Använd regeln D(a^x) = a^x · ln a.', 'D(2^x) = 2^x · ln 2.', NULL, 'kurvanalys-och-talet-e');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-2-03', 'chap-matte-3c-2', 'les-matte-3c-2-kurvanalys-och-talet-e', 3, 'C', 'numeric', 'Extremvärden', 'Bestäm x-koordinaten för den lokala extrempunkten till f(x) = x² − 6x + 10.', NULL, NULL, '3', 0.01, NULL, 'Sätt f''(x) = 0.', '2x − 6 = 0 ger x = 3.', NULL, 'kurvanalys-och-talet-e');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-2-04', 'chap-matte-3c-2', 'les-matte-3c-2-kurvanalys-och-talet-e', 4, 'A', 'numeric', 'Optimering', 'En öppen låda viks ur en kvadratisk pappbit med sidan 12 cm genom att klippa bort kvadrater med sidan x cm i varje hörn. För vilket x (i cm) blir lådans volym som störst?', NULL, NULL, '2', 0.05, 'cm', 'Ställ upp V(x) = x(12 − 2x)² = 4x³ − 48x² + 144x och lös V''(x) = 0 i intervallet 0 < x < 6.', 'V''(x) = 12(x² − 8x + 12) = 0 ger x = 2 cm (x = 6 ligger på randen med volym 0).', NULL, 'kurvanalys-och-talet-e');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-3-01', 'chap-matte-3c-3', 'les-matte-3c-3-area-mellan-kurvor', 1, 'E', 'numeric', 'Primitiv funktion', 'F(x) är en primitiv funktion till f(x) = 6x med villkoret F(2) = 15. Vad är F(0)?', NULL, NULL, '3', 0.01, NULL, 'F(x) = 3x² + C.', '3 · 2² + C = 15 ger C = 3, så F(0) = 3.', NULL, 'area-mellan-kurvor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-3-02', 'chap-matte-3c-3', 'les-matte-3c-3-area-mellan-kurvor', 2, 'C', 'numeric', 'Integraler', 'Beräkna arean mellan x-axeln och f(x) = 4 − x² mellan nollställena x = −2 och x = 2, avrundad till en decimal (eller bråk 32/3 ≈ 10,7). Ange med en decimal.', NULL, NULL, '10.7', 0.15, 'a.e.', 'Primitiv funktion är 4x − x³/3.', '(8 − 8/3) − (−8 + 8/3) = 32/3 ≈ 10,7 a.e.', NULL, 'area-mellan-kurvor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-3-03', 'chap-matte-3c-3', 'les-matte-3c-3-area-mellan-kurvor', 3, 'C', 'multiple_choice', 'Primitiv funktion', 'Vilken av följande är en primitiv funktion till f(x) = e^(3x)?', NULL, '["3e^(3x)","e^(3x)","e^(3x) / 3","3x · e^(3x)"]', '2', NULL, NULL, 'Derivera alternativen för att se vilket som ger e^(3x).', 'D(e^(3x) / 3) = (3e^(3x)) / 3 = e^(3x).', NULL, 'area-mellan-kurvor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-3-04', 'chap-matte-3c-3', 'les-matte-3c-3-area-mellan-kurvor', 4, 'A', 'numeric', 'Area', 'Beräkna arean mellan linjen y = x + 2 och parabeln y = x² från x = −1 till x = 2.', NULL, NULL, '4.5', 0.05, 'a.e.', 'Integrera (x + 2 − x²) mellan −1 och 2.', '[x²/2 + 2x − x³/3]₋₁² = (10/3) − (−7/6) = 27/6 = 4,5 a.e.', NULL, 'area-mellan-kurvor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-4-01', 'chap-matte-3c-4', 'les-matte-3c-4-enhetscirkel-och-triangelsatser', 1, 'E', 'numeric', 'Areasatsen', 'En triangel har två sidor med längderna 10 cm och 6 cm samt mellanliggande vinkel 30°. Vad är arean i cm²?', 'A = \frac{1}{2} a b \sin C', NULL, '15', 0.1, 'cm²', 'sin 30° = 0,5.', 'A = 0,5 · 10 · 6 · 0,5 = 15 cm².', NULL, 'enhetscirkel-och-triangelsatser');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-4-02', 'chap-matte-3c-4', 'les-matte-3c-4-enhetscirkel-och-triangelsatser', 2, 'C', 'numeric', 'Cosinussatsen', 'I en triangel är a = 5 cm, b = 8 cm och mellanliggande vinkel C = 60°. Hur lång är sidan c i cm?', 'c^2 = a^2 + b^2 - 2ab\cos C', NULL, '7', 0.05, 'cm', 'cos 60° = 0,5.', 'c² = 25 + 64 − 2 · 5 · 8 · 0,5 = 49 ger c = 7 cm.', NULL, 'enhetscirkel-och-triangelsatser');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-4-03', 'chap-matte-3c-4', 'les-matte-3c-4-enhetscirkel-och-triangelsatser', 3, 'C', 'multiple_choice', 'Enhetscirkeln', 'Vilket värde har cos 120°?', NULL, '["0,5","−0,5","0,866","−0,866"]', '1', NULL, NULL, 'cos(180° − v) = −cos v och cos 60° = 0,5.', 'cos 120° = −cos 60° = −0,5.', NULL, 'enhetscirkel-och-triangelsatser');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-3c-4-04', 'chap-matte-3c-4', 'les-matte-3c-4-enhetscirkel-och-triangelsatser', 4, 'A', 'numeric', 'Cosinussatsen', 'En triangel har sidorna 3 cm, 5 cm och 7 cm. Hur stor är vinkeln mittemot den längsta sidan i grader?', NULL, NULL, '120', 0.5, '°', 'Lös ut cos C ur 7² = 3² + 5² − 2 · 3 · 5 · cos C.', '49 = 34 − 30 cos C ger cos C = −0,5 och C = 120°.', NULL, 'enhetscirkel-och-triangelsatser');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-1-01', 'chap-matte-4-1', 'les-matte-4-1-radianer-och-enhetscirkeln', 1, 'E', 'numeric', 'Radianer', 'Hur många grader motsvarar vinkeln π / 3 radianer?', NULL, NULL, '60', 0.1, '°', 'π radianer motsvarar 180°.', '180° / 3 = 60°.', NULL, 'radianer-och-enhetscirkeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-1-02', 'chap-matte-4-1', 'les-matte-4-1-additionsformler-och-kurvor', 2, 'E', 'numeric', 'Trigonometriska kurvor', 'Vad är perioden i grader för funktionen y = 4 sin(2x) + 3?', NULL, NULL, '180', 0.5, '°', 'Perioden är 360° / k.', '360° / 2 = 180°.', NULL, 'additionsformler-och-kurvor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-1-03', 'chap-matte-4-1', 'les-matte-4-1-additionsformler-och-kurvor', 3, 'E', 'numeric', 'Trigonometriska kurvor', 'Vad är det största värdet funktionen y = 5 cos(3x) − 2 kan anta?', NULL, NULL, '3', 0.01, NULL, 'Det största värdet cosinus antar är +1.', 'y_max = 5 · 1 − 2 = 3.', NULL, 'additionsformler-och-kurvor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-1-04', 'chap-matte-4-1', 'les-matte-4-1-radianer-och-enhetscirkeln', 4, 'C', 'multiple_choice', 'Trigonometriska ettan', 'Om sin v = 0,6 och 0 < v < π/2, vad är cos v?', NULL, '["0,4","0,8","−0,8","0,64"]', '1', NULL, NULL, 'Använd sin²v + cos²v = 1 i första kvadranten.', 'cos²v = 1 − 0,36 = 0,64 ger cos v = 0,8 eftersom v ligger i första kvadranten.', NULL, 'radianer-och-enhetscirkeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-1-05', 'chap-matte-4-1', 'les-matte-4-1-trigonometriska-ekvationer', 5, 'C', 'numeric', 'Ekvationer', 'Lös ekvationen 2 sin x = 1 i intervallet 0° ≤ x ≤ 360°. Ange den största lösningen i grader.', NULL, NULL, '150', 0.5, '°', 'sin x = 0,5 har lösningarna 30° och 180° − 30°.', 'Lösningarna i intervallet är 30° och 150°. Den största är 150°.', NULL, 'trigonometriska-ekvationer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-1-06', 'chap-matte-4-1', 'les-matte-4-1-additionsformler-och-kurvor', 6, 'A', 'numeric', 'Additionsformler', 'Uttrycket 3 sin x + 4 cos x kan skrivas som A sin(x + v). Vad är amplituden A?', 'a\sin x + b\cos x = A\sin(x + v)', NULL, '5', 0.05, NULL, 'A = √(a² + b²).', 'A = √(3² + 4²) = √(9 + 16) = 5.', NULL, 'additionsformler-och-kurvor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-1-07', 'chap-matte-4-1', 'les-matte-4-1-trigonometriska-ekvationer', 7, 'A', 'numeric', 'Ekvationer', 'Hur många lösningar har ekvationen sin(3x) = 0,5 i intervallet 0 ≤ x < 2π?', NULL, NULL, '6', 0.01, NULL, 'Varje period på 2π/3 rymmer 2 lösningar.', 'På [0, 2π) ryms 3 perioder av sin(3x), och varje period ger 2 skärningar med 0,5, alltså 3 · 2 = 6 lösningar.', NULL, 'trigonometriska-ekvationer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-2-01', 'chap-matte-4-2', 'les-matte-4-2-produkt-kvot-och-kedjeregeln', 1, 'E', 'multiple_choice', 'Derivata', 'Vad är derivatan f''(x) av f(x) = cos(4x)?', NULL, '["4 sin(4x)","−4 sin(4x)","−sin(4x)","4 cos(4x)"]', '1', NULL, NULL, 'Yttre derivatan av cos är −sin, gånger inre derivatan 4.', 'f''(x) = −sin(4x) · 4 = −4 sin(4x).', NULL, 'produkt-kvot-och-kedjeregeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-2-02', 'chap-matte-4-2', 'les-matte-4-2-produkt-kvot-och-kedjeregeln', 2, 'C', 'numeric', 'Derivata', 'Givet f(x) = x · e^x. Beräkna f''(0).', NULL, NULL, '1', 0.01, NULL, 'Använd produktregeln: f''(x) = e^x + x · e^x.', 'f''(0) = e⁰ + 0 = 1.', NULL, 'produkt-kvot-och-kedjeregeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-2-03', 'chap-matte-4-2', 'les-matte-4-2-produkt-kvot-och-kedjeregeln', 3, 'C', 'numeric', 'Derivata', 'Beräkna derivatan f''(2) för funktionen f(x) = 6 ln(x).', NULL, NULL, '3', 0.01, NULL, 'D(ln x) = 1/x.', 'f''(x) = 6/x ger f''(2) = 6/2 = 3.', NULL, 'produkt-kvot-och-kedjeregeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-2-04', 'chap-matte-4-2', 'les-matte-4-2-produkt-kvot-och-kedjeregeln', 4, 'A', 'multiple_choice', 'Kvotregeln', 'Vad blir derivatan av f(x) = (x + 1) / (x − 1) för x ≠ 1?', NULL, '["−2 / (x − 1)²","2 / (x − 1)²","1","(2x) / (x − 1)²"]', '0', NULL, NULL, 'Tillämpa kvotregeln (f''g − fg'') / g².', '(1(x − 1) − (x + 1)·1) / (x − 1)² = −2 / (x − 1)².', NULL, 'produkt-kvot-och-kedjeregeln');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-3-01', 'chap-matte-4-3', 'les-matte-4-3-rotationsvolymer', 1, 'E', 'numeric', 'Integraler', 'Beräkna det exakta värdet av ∫[1 till e] (3/x) dx.', '\int_1^e \frac{3}{x}\,dx', NULL, '3', 0.01, NULL, 'Primitiv funktion är 3 ln x, och ln e = 1, ln 1 = 0.', '3(ln e − ln 1) = 3(1 − 0) = 3.', NULL, 'rotationsvolymer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-3-02', 'chap-matte-4-3', 'les-matte-4-3-rotationsvolymer', 2, 'C', 'numeric', 'Integraler', 'Beräkna det exakta värdet av ∫[0 till π] sin(x) dx.', '\int_0^{\pi} \sin x\,dx', NULL, '2', 0.01, NULL, 'Primitiv funktion till sin x är −cos x.', '[−cos x]₀^π = −cos π − (−cos 0) = −(−1) + 1 = 2.', NULL, 'rotationsvolymer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-3-03', 'chap-matte-4-3', 'les-matte-4-3-rotationsvolymer', 3, 'C', 'multiple_choice', 'Rotationsvolym', 'Området under y = x för 0 ≤ x ≤ 3 roterar ett helt varv kring x-axeln. Vad blir volymen?', NULL, '["3π","4,5π","9π","27π"]', '2', NULL, NULL, 'V = π ∫[0 till 3] x² dx.', 'π [x³/3]₀³ = 9π v.e.', NULL, 'rotationsvolymer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-3-04', 'chap-matte-4-3', 'les-matte-4-3-rotationsvolymer', 4, 'A', 'multiple_choice', 'Rotationsvolym', 'Kurvan y = √x roterar kring x-axeln för 0 ≤ x ≤ 4. Vad blir volymen?', NULL, '["4π","8π","16π","2π"]', '1', NULL, NULL, '(√x)² = x.', 'π ∫[0 till 4] x dx = π [x²/2]₀⁴ = 8π v.e.', NULL, 'rotationsvolymer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-4-01', 'chap-matte-4-4', 'les-matte-4-4-komplexa-tal-och-polar-form', 1, 'E', 'numeric', 'Komplexa tal', 'Beräkna absolutbeloppet |z| för det komplexa talet z = 6 − 8i.', NULL, NULL, '10', 0.01, NULL, '|z| = √(6² + (−8)²).', '√(36 + 64) = √100 = 10.', NULL, 'komplexa-tal-och-polar-form');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-4-02', 'chap-matte-4-4', 'les-matte-4-4-komplexa-tal-och-polar-form', 2, 'E', 'multiple_choice', 'Komplexa tal', 'Vad är produkten (2 + 3i)(2 − 3i)?', NULL, '["−5","13","4 − 9i","13i"]', '1', NULL, NULL, 'Använd konjugatregeln och att i² = −1.', '2² − (3i)² = 4 − 9(−1) = 4 + 9 = 13.', NULL, 'komplexa-tal-och-polar-form');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-4-03', 'chap-matte-4-4', 'les-matte-4-4-komplexa-tal-och-polar-form', 3, 'C', 'numeric', 'Komplexa tal', 'Vad blir (1 + i)² om det skrivs på formen a + bi? Ange imaginärdelen b.', NULL, NULL, '2', 0.01, NULL, 'Utveckla med första kvadreringsregeln och använd i² = −1.', '1 + 2i + i² = 1 + 2i − 1 = 2i, så b = 2.', NULL, 'komplexa-tal-och-polar-form');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-4-4-04', 'chap-matte-4-4', 'les-matte-4-4-komplexa-tal-och-polar-form', 4, 'A', 'numeric', 'de Moivres formel', 'Om z = 2(cos 20° + i sin 20°), vad är absolutbeloppet |z⁴|?', NULL, NULL, '16', 0.01, NULL, 'Beloppet upphöjs till n enligt de Moivres formel.', '|z⁴| = 2⁴ = 16.', NULL, 'komplexa-tal-och-polar-form');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-1-01', 'chap-matte-5-1', 'les-matte-5-1-begreppet-differentialekvation', 1, 'E', 'multiple_choice', 'Differentialekvationer', 'Vilken är den allmänna lösningen till differentialekvationen y'' = 3y?', NULL, '["y = 3x + C","y = C · e^(3x)","y = 3e^x","y = C · e^(−3x)"]', '1', NULL, NULL, 'y'' = ky har lösningen y = C · e^(kx).', 'Deriveras y = C · e^(3x) fås y'' = 3 · C · e^(3x) = 3y.', NULL, 'begreppet-differentialekvation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-1-02', 'chap-matte-5-1', 'les-matte-5-1-begreppet-differentialekvation', 2, 'E', 'numeric', 'Begynnelsevillkor', 'Funktionen y = C · e^(2x) löser y'' = 2y med begynnelsevillkoret y(0) = 3. Vad är konstanten C?', NULL, NULL, '3', 0.01, NULL, 'Sätt in x = 0 och y = 3.', '3 = C · e⁰ = C · 1 ger C = 3.', NULL, 'begreppet-differentialekvation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-1-03', 'chap-matte-5-1', 'les-matte-5-1-begreppet-differentialekvation', 3, 'E', 'numeric', 'Jämvikt', 'Differentialekvationen y'' = 0,5y − 2 har en konstant jämviktslösning där y'' = 0. Vilket värde har denna lösning y?', NULL, NULL, '4', 0.01, NULL, 'Lös 0,5y − 2 = 0.', '0,5y = 2 ger y = 4.', NULL, 'begreppet-differentialekvation');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-1-04', 'chap-matte-5-1', 'les-matte-5-1-homogena-och-inhomogena-ekvationer', 4, 'C', 'multiple_choice', 'Andra ordningen', 'Vilken karakteristisk ekvation hör till y'''' − 5y'' + 6y = 0?', NULL, '["r² + 5r + 6 = 0","r² − 5r + 6 = 0","r² − 6r + 5 = 0","2r − 5 = 0"]', '1', NULL, NULL, 'Ansätt y = e^(rx) så att y'' = re^(rx) och y'''' = r²e^(rx).', 'Division med e^(rx) ger r² − 5r + 6 = 0.', NULL, 'homogena-och-inhomogena-ekvationer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-1-05', 'chap-matte-5-1', 'les-matte-5-1-riktningsfalt-och-tillampningar', 5, 'C', 'numeric', 'Numerisk metod', 'Använd Eulers stegmetod med steglängden h = 0,5 på y'' = 2x + y och startvärdet y(0) = 2. Vad blir närmevärdet för y(0,5)?', NULL, NULL, '3', 0.05, NULL, 'y₁ = y₀ + h · y''(0, 2).', 'y''(0, 2) = 2 · 0 + 2 = 2, så y₁ = 2 + 0,5 · 2 = 3.', NULL, 'riktningsfalt-och-tillampningar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-1-06', 'chap-matte-5-1', 'les-matte-5-1-homogena-och-inhomogena-ekvationer', 6, 'A', 'numeric', 'Inhomogen ekvation', 'Den inhomogena differentialekvationen y'' + 2y = 10 har en konstant partikulärlösning y_p. Vad är y_p?', NULL, NULL, '5', 0.01, NULL, 'För en konstant är derivatan y_p'' = 0.', '0 + 2y_p = 10 ger y_p = 5.', NULL, 'homogena-och-inhomogena-ekvationer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-1-07', 'chap-matte-5-1', 'les-matte-5-1-riktningsfalt-och-tillampningar', 7, 'A', 'multiple_choice', 'Riktningsfält', 'I ett riktningsfält har alla streck längs varje horisontell linje exakt samma lutning oavsett x-koordinat. Vad säger detta om differentialekvationen?', NULL, '["Att den saknar lösningar","Att högerledet y'' endast beror av y (inte av x)","Att lösningen alltid är en rät linje","Att y'' alltid är noll"]', '1', NULL, NULL, 'Om x inte påverkar lutningen saknas variabeln x i uttrycket för y''.', 'Konstant lutning längs y = konstant innebär en autonom ekvation y'' = f(y).', NULL, 'riktningsfalt-och-tillampningar');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-2-01', 'chap-matte-5-2', 'les-matte-5-2-kombinatorik-och-induktion', 1, 'E', 'numeric', 'Kombinatorik', 'På hur många sätt kan man välja 2 personer ur en grupp på 6 personer utan hänsyn till ordning?', '\binom{6}{2}', NULL, '15', 0.01, NULL, 'Beräkna (6 · 5) / 2.', 'C(6, 2) = 30 / 2 = 15.', NULL, 'kombinatorik-och-induktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-2-02', 'chap-matte-5-2', 'les-matte-5-2-kombinatorik-och-induktion', 2, 'C', 'numeric', 'Talföljder', 'Beräkna den geometriska summan 2 + 4 + 8 + 16 + 32.', NULL, NULL, '62', 0.01, NULL, 'S₅ = 2(2⁵ − 1) / (2 − 1).', '2(32 − 1) / 1 = 62.', NULL, 'kombinatorik-och-induktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-2-03', 'chap-matte-5-2', 'les-matte-5-2-kombinatorik-och-induktion', 3, 'C', 'multiple_choice', 'Induktion', 'Vad görs i det tredje steget (induktionssteget) av ett induktionsbevis?', NULL, '["Man kontrollerar formeln för n = 1, 2 och 3","Man visar att om påståendet gäller för n = p, så gäller det även för n = p + 1","Man löser ekvationen p = 0","Man integrerar funktionen"]', '1', NULL, NULL, 'Kedjeeffekten kräver steget från p till p + 1.', 'Man bevisar implikationen P(p) ⇒ P(p + 1).', NULL, 'kombinatorik-och-induktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-2-04', 'chap-matte-5-2', 'les-matte-5-2-kombinatorik-och-induktion', 4, 'A', 'numeric', 'Binomialsatsen', 'Vad är koefficienten framför x²-termen i utvecklingen av (x + 2)⁴?', NULL, NULL, '24', 0.1, NULL, 'Termen är C(4, 2) · x² · 2².', 'C(4, 2) · 4 = 6 · 4 = 24.', NULL, 'kombinatorik-och-induktion');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-3-01', 'chap-matte-5-3', 'les-matte-5-3-integrationsmetoder', 1, 'E', 'numeric', 'Generaliserad integral', 'Beräkna värdet av den generaliserade integralen ∫[1 till ∞] x⁻² dx.', '\int_1^{\infty} x^{-2}\,dx', NULL, '1', 0.01, NULL, 'Primitiv funktion är −1/x.', 'lim(b → ∞) (−1/b + 1) = 1.', NULL, 'integrationsmetoder');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-3-02', 'chap-matte-5-3', 'les-matte-5-3-integrationsmetoder', 2, 'C', 'numeric', 'Generaliserad integral', 'Beräkna värdet av ∫[0 till ∞] 2e^(−2x) dx.', '\int_0^{\infty} 2e^{-2x}\,dx', NULL, '1', 0.01, NULL, 'Primitiv funktion är −e^(−2x).', 'lim(b → ∞) (−e^(−2b) − (−e⁰)) = 0 + 1 = 1.', NULL, 'integrationsmetoder');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-3-03', 'chap-matte-5-3', 'les-matte-5-3-integrationsmetoder', 3, 'C', 'multiple_choice', 'Analys', 'Vad gäller för den generaliserade integralen ∫[1 till ∞] (1/x) dx?', NULL, '["Den konvergerar mot 1","Den konvergerar mot ln 2","Den divergerar eftersom ln b → ∞ då b → ∞","Den är lika med 0"]', '2', NULL, NULL, 'Primitiv funktion till 1/x är ln x.', 'ln b växer obegränsat när b → ∞, så integralen divergerar.', NULL, 'integrationsmetoder');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-matte-5-3-04', 'chap-matte-5-3', 'les-matte-5-3-integrationsmetoder', 4, 'A', 'multiple_choice', 'Partiell integration', 'Vilken primitiv funktion fås för ∫ x · e^x dx via partiell integration?', NULL, '["x · e^x + C","(x − 1)e^x + C","(x + 1)e^x + C","x² · e^x / 2 + C"]', '1', NULL, NULL, 'Välj g(x) = x och f''(x) = e^x.', 'x·e^x − ∫ 1·e^x dx = x·e^x − e^x + C = (x − 1)e^x + C.', NULL, 'integrationsmetoder');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-1-01', 'chap-svenska-1-1', 'les-svenska-1-1-retorikens-grunder', 1, 'E', 'multiple_choice', 'Retorik', 'Vilken retorisk appell använder en talare främst när hen redovisar statistik från Statistiska centralbyrån för att styrka sitt förslag?', NULL, '["Etos","Patos","Logos","Actio"]', '2', NULL, NULL, 'Fakta och sakargument vädjar till lyssnarens förnuft.', 'Statistik och sakliga belägg utgör logos.', NULL, 'retorikens-grunder');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-1-02', 'chap-svenska-1-1', 'les-svenska-1-1-argumenterande-textstruktur', 2, 'E', 'multiple_choice', 'Argumentation', 'Vilken av följande meningar är en tydligt formulerad tes?', NULL, '["Många elever reser långt varje morgon","Längre skoldagar ger ibland tröttare elever","Kommunen bör införa avgiftsfri frukost på alla gymnasieskolor","En enkät från 2024 visade att 40 % hoppar över frukosten"]', '2', NULL, NULL, 'En tes uttrycker själva åsikten eller uppmaningen som texten vill få läsaren att acceptera.', 'Meningen med "bör införa" formulerar en klar ståndpunkt och fungerar som tes.', NULL, 'argumenterande-textstruktur');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-1-03', 'chap-svenska-1-1', 'les-svenska-1-1-kallkritik-och-referatteknik', 3, 'C', 'multiple_choice', 'Källkritik', 'Två tidningar publicerar samma siffra om ett trafikprojekt, men det visar sig att båda bara har skrivit av ett pressmeddelande från byggherren. Vilket källkritiskt kriterium belyser bristen?', NULL, '["Äkthet","Tidssamband","Beroendekriteriet","Stilistik"]', '2', NULL, NULL, 'Är de två tidningarna fristående från varandra?', 'Tidningarna är inte oberoende källor eftersom båda återger samma ursprungskälla (beroendekriteriet).', NULL, 'kallkritik-och-referatteknik');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-1-04', 'chap-svenska-1-1', 'les-svenska-1-1-kallkritik-och-referatteknik', 4, 'C', 'multiple_choice', 'Referatteknik', 'En debattör skriver en subjektiv åsikt utan siffror. Vilken referatmarkör är mest saklig när du återger åsikten?', NULL, '["Debattören bevisar att...","Debattören hävdar att...","Debattören konstaterar självklart att...","Alla vet genom debattören att..."]', '1', NULL, NULL, 'Välj en markör som visar att det är skribentens egen uppfattning, inte ett fastställt faktum.', '"Hävdar" markerar tydligt att påståendet är en åsikt som kan diskuteras.', NULL, 'kallkritik-och-referatteknik');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-1-05', 'chap-svenska-1-1', 'les-svenska-1-1-retorikens-grunder', 5, 'A', 'multiple_choice', 'Retorik', 'Läs utdraget: "Vi måste värna våra skogar. Vi måste skydda våra vattendrag. Vi måste rädda vår framtid." Vilka två stilmedel samverkar här?', NULL, '["Metafor och allitteration","Anafor och tretal","Oxymoron och kiasm","Liknelse och antites"]', '1', NULL, NULL, 'Räkna antalet upprepade meningar och se hur alla tre inleds.', 'De tre meningarna bildar ett tretal och inleds med samma fras ("Vi måste..."), vilket är en anafor.', NULL, 'retorikens-grunder');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-1-06', 'chap-svenska-1-1', 'les-svenska-1-1-argumenterande-textstruktur', 6, 'A', 'multiple_choice', 'Argumentation', 'Varför bör ett bemött motargument ingå i en argumenterande text på högre nivå?', NULL, '["För att göra texten längre utan nya fakta","För att visa osäkerhet kring den egna tesen","För att stärka avsändarens etos och föregripa läsarens starkaste invändning","För att ersätta behovet av en egen tes"]', '2', NULL, NULL, 'Hur uppfattar en kritisk läsare en text som öppet tar upp motargument och svarar på dem?', 'Att bemöta en stark invändning visar att man har prövat frågan allsidigt och stärker etos.', NULL, 'argumenterande-textstruktur');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-2-01', 'chap-svenska-1-2', 'les-svenska-1-2-berattarperspektiv-och-tema', 1, 'E', 'multiple_choice', 'Narratologi', 'Vad innebär att en berättelse börjar in medias res?', NULL, '["Att den börjar med en lång miljöbeskrivning","Att den börjar mitt i handlingen utan förklaring","Att slutet avslöjas på sista sidan","Att den är skriven på vers"]', '1', NULL, NULL, 'Latinska uttrycket betyder "mitt i tingen".', 'In medias res innebär att berättelsen kastar läsaren rakt in i ett pågående skeende.', NULL, 'berattarperspektiv-och-tema');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-2-02', 'chap-svenska-1-2', 'les-svenska-1-2-berattarperspektiv-och-tema', 2, 'C', 'multiple_choice', 'Stilmedel', 'Vilket stilmedel används i meningen "Natten la en tung filt över staden"?', NULL, '["Liknelse","Metafor","Allitteration","Retorisk fråga"]', '1', NULL, NULL, 'Finns jämförelseordet "som" eller "likt" med?', 'Utan jämförelseord kallas den bildliga överföringen metafor.', NULL, 'berattarperspektiv-och-tema');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-2-03', 'chap-svenska-1-2', 'les-svenska-1-2-berattarperspektiv-och-tema', 3, 'C', 'multiple_choice', 'Textanalys', 'Vilket av följande beskriver bäst skillnaden mellan tema och motiv?', NULL, '["Tema är huvudpersonens namn, motiv är miljön","Tema är verkets abstrakta grundtanke, medan motiv är konkreta återkommande situationer","Tema finns bara i poesi och motiv bara i romaner","Orden är fullständiga synonymer"]', '1', NULL, NULL, 'Tänk på skillnaden mellan "kärlek" och "ett avskedsbrev på köksbordet".', 'Temat är det abstrakta budskapet (t.ex. svek) och motivet det konkreta elementet.', NULL, 'berattarperspektiv-och-tema');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-2-04', 'chap-svenska-1-2', 'les-svenska-1-2-berattarperspektiv-och-tema', 4, 'A', 'multiple_choice', 'Textanalys', 'Vad kännetecknar en opålitlig berättare?', NULL, '["En allvetande berättare som kommenterar historien utifrån","En berättare vars beskrivning motsägs av ledtrådar i texten så att läsaren får genomskåda skildringen","En berättare som alltid talar i tredje person plural","En text utan några dialoger"]', '1', NULL, NULL, 'Läsaren ser en spricka mellan det berättaren påstår och det som sker.', 'Genom motsägelser eller överdrifter märker läsaren att berättarens version inte kan tas för god.', NULL, 'berattarperspektiv-och-tema');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-3-01', 'chap-svenska-1-3', 'les-svenska-1-3-sprakriktighet-och-dialekt', 1, 'E', 'multiple_choice', 'Språkriktighet', 'Vilken mening använder de/dem korrekt?', NULL, '["Dem kom för sent till lektionen","Jag skickade mejlet till de i morse","De hämtade dem nya böckerna i biblioteket","De bad oss att lämna boken till dem"]', '3', NULL, NULL, 'Testa med vi/oss i både första och sista positionen.', '"Vi bad oss att lämna boken till oss" ger subjekt "De" och objekt "dem".', NULL, 'sprakriktighet-och-dialekt');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-3-02', 'chap-svenska-1-3', 'les-svenska-1-3-sprakriktighet-och-dialekt', 2, 'C', 'multiple_choice', 'Språkriktighet', 'Vilket av följande exempel innehåller en satsradning?', NULL, '["Eftersom bussen var sen fick vi gå","Bussen var sen, vi fick gå till skolan","Bussen var sen, så vi fick gå till skolan","Bussen var sen; därför gick vi till skolan"]', '1', NULL, NULL, 'Leta efter två fullständiga huvudsatser skilda enbart av ett kommatecken.', '"Bussen var sen" och "vi fick gå till skolan" är två huvudsatser med bara komma emellan.', NULL, 'sprakriktighet-och-dialekt');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-3-03', 'chap-svenska-1-3', 'les-svenska-1-3-sprakriktighet-och-dialekt', 3, 'C', 'multiple_choice', 'Språklig variation', 'Vad innebär begreppet dialektutjämning?', NULL, '["Att nya utländska lånord förbjuds","Att utpräglade lokala dialektdrag försvinner och närmar sig regionalt riksspråk","Att alla dialekter får eget skriftspråk","Att sociolekter bara talas på landsbygden"]', '1', NULL, NULL, 'Ökad rörlighet och media gör att lokala skillnader slipas av.', 'Dialektutjämning betyder att gamla sockenmål jämnas ut mot mer utbredda regionala varianter.', NULL, 'sprakriktighet-och-dialekt');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-1-3-04', 'chap-svenska-1-3', 'les-svenska-1-3-sprakriktighet-och-dialekt', 4, 'A', 'multiple_choice', 'Språkriktighet', 'Vilken rubrik följer svensk versalisering korrekt?', NULL, '["Källkritik Och Referatteknik I Gymnasiet","Källkritik och referatteknik i gymnasiet.","Källkritik och referatteknik i gymnasiet","KÄLLKRITIK OCH REFERATTEKNIK I GYMNASIET"]', '2', NULL, NULL, 'Svenska rubriker har bara stor bokstav i början och på egennamn, och avslutas inte med punkt.', 'Endast första ordet inleds med versal och ingen punkt sätts ut.', NULL, 'sprakriktighet-och-dialekt');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-1-01', 'chap-svenska-2-1', 'les-svenska-2-1-sociolekter-och-sprakattityder', 1, 'E', 'multiple_choice', 'Språksociologi', 'Vad kallas språklig variation som är typisk för en viss åldersgrupp eller generation?', NULL, '["Dialekt","Kronolekt","Idiolekt","Semikommunikation"]', '1', NULL, NULL, 'Kronos betyder tid.', 'Kronolekt avser språkbruk knutet till ålder och generation.', NULL, 'sociolekter-och-sprakattityder');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-1-02', 'chap-svenska-2-1', 'les-svenska-2-1-nordiska-sprak-och-slaktskap', 2, 'E', 'multiple_choice', 'Nordiska språk', 'Vilket av följande språk tillhör INTE den nordgermanska språkfamiljen?', NULL, '["Isländska","Norska","Finska","Danska"]', '2', NULL, NULL, 'Sök språket som tillhör den finno-ugriska språkfamiljen.', 'Finska är ett finno-ugriskt språk och inte besläktat med de skandinaviska språken.', NULL, 'nordiska-sprak-och-slaktskap');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-1-03', 'chap-svenska-2-1', 'les-svenska-2-1-nordiska-sprak-och-slaktskap', 3, 'C', 'multiple_choice', 'Nordiska språk', 'Vad betyder det danska ordet "frokost" på svenska?', NULL, '["Frukost","Lunch","Middag","Kvällsfika"]', '1', NULL, NULL, 'En klassisk falsk vän i danskan.', 'Danska "frokost" motsvarar svenskans lunch (morgonmåltiden heter "morgenmad").', NULL, 'nordiska-sprak-och-slaktskap');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-1-04', 'chap-svenska-2-1', 'les-svenska-2-1-sprakforandring-och-lanord', 4, 'C', 'multiple_choice', 'Språklagstiftning', 'Vilka är Sveriges fem nationella minoritetsspråk?', NULL, '["Norska, danska, finska, engelska och samiska","Finska, meänkieli, samiska, romani chib och jiddisch","Finska, samiska, isländska, arabiska och jiddisch","Svenska, finska, norska, danska och färöiska"]', '1', NULL, NULL, 'Alla fem har talats i Sverige under lång historisk tid.', 'Enligt språklagen är de fem nationella minoritetsspråken finska, jiddisch, meänkieli, romani chib och samiska.', NULL, 'sprakforandring-och-lanord');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-1-05', 'chap-svenska-2-1', 'les-svenska-2-1-sprakforandring-och-lanord', 5, 'A', 'multiple_choice', 'Språkhistoria', 'Vad avses med begreppet domänförlust i språkpolitiska diskussioner?', NULL, '["Att enskilda engelska lånord stavas enligt svenska regler","Att ett språk slutar användas och utveckla facktermer inom hela samhällsområden, såsom högre forskning","Att regionala dialekter lever kvar i glesbygden","Att antalet punkter i en mening minskar"]', '1', NULL, NULL, 'Domän betyder här samhällsområde eller användningssfär.', 'Domänförlust uppstår när exempelvis universitet eller teknikbranscher övergår helt till engelska och svenskan saknar termer.', NULL, 'sprakforandring-och-lanord');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-1-06', 'chap-svenska-2-1', 'les-svenska-2-1-nordiska-sprak-och-slaktskap', 6, 'A', 'multiple_choice', 'Nordiska språk', 'Varför förstår många svenskar ofta skriven danska mycket lättare än talad danska?', NULL, '["Danska språket saknar böjningsändelser i skrift","Danskans ortografi ligger nära svenskans ordförråd, medan det talade språket har försvagade konsonanter och stød","Danska och svenska använder olika alfabet","Talad danska är närmare finskan än fornnordiskan"]', '1', NULL, NULL, 'Jämför bevarad stavning med förändrat uttal.', 'Dansk stavning speglar det gemensamma nordiska ordförrådet, medan uttalet genomgått stark konsonantförsvagning.', NULL, 'nordiska-sprak-och-slaktskap');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-2-01', 'chap-svenska-2-2', 'les-svenska-2-2-epoker-och-ideer', 1, 'E', 'multiple_choice', 'Litteraturhistoria', 'Vilken litterär epok betonade känsla, fantasi, besjälad natur och längtan bort i tid och rum?', NULL, '["Upplysningen","Romantiken","Realismen","Naturalismen"]', '1', NULL, NULL, 'Den uppstod som en reaktion mot 1700-talets förnuftstro.', 'Romantiken satte känslan och naturens mystik i centrum.', NULL, 'epoker-och-ideer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-2-02', 'chap-svenska-2-2', 'les-svenska-2-2-epoker-och-ideer', 2, 'C', 'multiple_choice', 'Litteraturhistoria', 'Vilken författare skrev "Röda rummet" (1879), som brukar räknas som genombrottet för svensk realism?', NULL, '["Selma Lagerlöf","August Strindberg","Carl Michael Bellman","Verner von Heidenstam"]', '1', NULL, NULL, 'Romanen skildrar Stockholm och konstnärslivet satiriskt.', 'August Strindberg fick sitt genombrott med "Röda rummet" 1879.', NULL, 'epoker-och-ideer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-2-03', 'chap-svenska-2-2', 'les-svenska-2-2-epoker-och-ideer', 3, 'C', 'multiple_choice', 'Antiken', 'Vad innebar begreppet katharsis i Aristoteles beskrivning av den antika tragedin?', NULL, '["Att hjältens övermod kallas hybris","Att publiken upplever en känslomässig rening genom fruktan och medlidande","Att pjäsen måste utspela sig på tre olika platser","Att kören alltid sjunger i slutet av komedier"]', '1', NULL, NULL, 'Ordet betyder rening.', 'Katharsis betecknar den känslomässiga rening publiken genomgår vid tragedins fall.', NULL, 'epoker-och-ideer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-2-04', 'chap-svenska-2-2', 'les-svenska-2-2-epoker-och-ideer', 4, 'A', 'multiple_choice', 'Litteraturhistoria', 'Vad utmärker naturalismen jämfört med klassisk realism under slutet av 1800-talet?', NULL, '["En idealiserad bild av adelns vardag","En deterministisk syn där människan styrs hårt av biologiskt arv och social miljö","Att berättelserna alltid slutar lyckligt","Att naturväsen och gudar avgör handlingen"]', '1', NULL, NULL, 'Naturalismen inspirerades starkt av naturvetenskap och Darwin.', 'Naturalistiska författare såg litteraturen som ett laboratorium där arv och miljö avgör människans öde.', NULL, 'epoker-och-ideer');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-3-01', 'chap-svenska-2-3', 'les-svenska-2-3-utredande-text-och-stil', 1, 'E', 'multiple_choice', 'Texttyper', 'Vad utmärker en utredande text jämfört med en argumenterande text?', NULL, '["Den drivs av en stark personlig tes","Den belyser en öppen frågeställning sakligt ur flera perspektiv utifrån källor","Den använder många retoriska utrop och värdeord","Den saknar helt källhänvisningar"]', '1', NULL, NULL, 'Ska en utredande text övertala eller utreda?', 'En utredande text undersöker och väger olika perspektiv mot varandra med objektiv ton.', NULL, 'utredande-text-och-stil');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-3-02', 'chap-svenska-2-3', 'les-svenska-2-3-utredande-text-och-stil', 2, 'C', 'multiple_choice', 'Stilistik', 'Vilken formulering passar bäst i formell utredande sakprosa?', NULL, '["Jag tycker personligen att studien känns jättekonstig","Resultaten tyder på att sambandet är mer komplext än väntat","Man fattar ju direkt att forskarna har helt fel","Sjukt många ungdomar svarade ja i enkäten"]', '1', NULL, NULL, 'Sök den sakliga och opersonliga formuleringen.', '"Resultaten tyder på..." är sakligt, försiktigt nyanserat och fritt från talspråkliga värdeord.', NULL, 'utredande-text-och-stil');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-3-03', 'chap-svenska-2-3', 'les-svenska-2-3-utredande-text-och-stil', 3, 'C', 'multiple_choice', 'Textbindning', 'Vilket sambandsord markerar ett motsatsförhållande mellan två källor?', NULL, '["Dessutom","Därför","Däremot","Nämligen"]', '2', NULL, NULL, 'Vilket ord motsvarar "å andra sidan"?', '"Däremot" fungerar adversativt och ställer två påståenden i kontrast mot varandra.', NULL, 'utredande-text-och-stil');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-2-3-04', 'chap-svenska-2-3', 'les-svenska-2-3-utredande-text-och-stil', 4, 'A', 'multiple_choice', 'Källsyntes', 'Vad innebär att källorna "ställs i dialog med varandra" i en utredande text?', NULL, '["Att varje stycke bara handlar om en källa utan koppling till övriga","Att skribenten jämför var källorna stämmer överens eller motsäger varandra kring samma aspekt","Att källorna citeras ordagrant sida efter sida","Att endast en källa väljs ut och övriga stryks"]', '1', NULL, NULL, 'Syntes betyder att väva ihop flera källor kring gemensamma teman.', 'Källsyntes innebär att källorna jämförs tematiskt så att likheter, skillnader och nyanser framträder.', NULL, 'utredande-text-och-stil');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-1-01', 'chap-svenska-3-1', 'les-svenska-3-1-kallsammanstallning-och-referat', 1, 'E', 'multiple_choice', 'Vetenskapligt skrivande', 'Var i en mening ska en parenteshänvisning enligt Harvardsystemet normalt placeras?', NULL, '["Efter meningens punkt","Före meningens punkt","Endast i källförteckningen på sista sidan","Inuti inledningens rubrik"]', '1', NULL, NULL, 'Parentesen tillhör den mening vars innehåll den styrker.', 'Parentesen sätts direkt efter uppgiften och före punkten: "... (Lind, 2024)."', NULL, 'kallsammanstallning-och-referat');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-1-02', 'chap-svenska-3-1', 'les-svenska-3-1-pm-och-problemformulering', 2, 'E', 'multiple_choice', 'PM-struktur', 'Vilken formulering fungerar bäst som vetenskaplig frågeställning i ett PM?', NULL, '["Är kärnkraft bra?","Hur påverkar skoluniformer studiero och social gemenskap enligt aktuell forskning?","Varför borde skolan alltid ha prov?","Allt om Sveriges historia"]', '1', NULL, NULL, 'Sök en öppen, neutral och avgränsad fråga.', 'Alternativ 2 är neutralt formulerat, avgränsat och kräver en utredande analys.', NULL, 'pm-och-problemformulering');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-1-03', 'chap-svenska-3-1', 'les-svenska-3-1-vetenskaplig-stil-och-kriterier', 3, 'C', 'multiple_choice', 'Metodkritik', 'En studie påstår sig mäta "elevers läsförståelse" men testet kontrollerar egentligen bara hur snabbt de kan läsa ordlistor högt. Vilket begrepp beskriver bristen?', NULL, '["Låg validitet","Hög validitet","Hög objektivitet","Sekundärkälla"]', '0', NULL, NULL, 'Mäter testet det som det säger sig mäta?', 'När mätinstrumentet fångar fel egenskap har studien låg validitet.', NULL, 'vetenskaplig-stil-och-kriterier');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-1-04', 'chap-svenska-3-1', 'les-svenska-3-1-vetenskaplig-stil-och-kriterier', 4, 'C', 'multiple_choice', 'Vetenskaplig stil', 'Vilken mening präglas av korrekt vetenskaplig försiktighet (hedging)?', NULL, '["Undersökningen bevisar hundraprocentigt att alla elever påverkas likadant","Materialet tyder på ett visst samband mellan sömnbrist och koncentrationssvårigheter i den studerade gruppen","Man förstår genast att resultatet är helt självklart","Ingen kan någonsin tvivla på den här sanningen"]', '1', NULL, NULL, 'Vetenskapliga texter markerar osäkerhet och avgränsar sina slutsatser till underlaget.', '"Tyder på" och "i den studerade gruppen" uttrycker vetenskaplig precision.', NULL, 'vetenskaplig-stil-och-kriterier');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-1-05', 'chap-svenska-3-1', 'les-svenska-3-1-kallsammanstallning-och-referat', 5, 'A', 'multiple_choice', 'Referatteknik', 'Du skriver ett PM och ser att forskaren Holm (2023) citerar en äldre studie av Berg (2019), men du har inte läst Berg i original. Hur bör du hantera källan?', NULL, '["Ange enbart \"(Berg, 2019)\" så att källförteckningen ser äldre ut","Stryka uppgiften helt eftersom inga sekundärkällor får nämnas","Gå i första hand till originalet (Berg, 2019), eller ange öppet \"(Berg, 2019, refererad i Holm, 2023)\"","Låtsas att det var din egen slutsats"]', '2', NULL, NULL, 'Full transparens och kontroll mot primärkällan är en grundregel i akademiskt skrivande.', 'Man ska antingen läsa originalkällan eller redovisa att det är en sekundärreferering.', NULL, 'kallsammanstallning-och-referat');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-1-06', 'chap-svenska-3-1', 'les-svenska-3-1-vetenskaplig-stil-och-kriterier', 6, 'A', 'multiple_choice', 'Metodkritik', 'En forskare gör en enkät där bara 12 % av de utvalda svarar, men presenterar svaren som typiska för hela landets befolkning. Vilken är den främsta källkritiska invändningen?', NULL, '["Att enkäten saknade retorisk patos","Att det stora bortfallet skapar osäker representativitet och låg generaliserbarhet","Att 12 % alltid motsvarar hälften av urvalet","Att enkäter inte kan använda siffror"]', '1', NULL, NULL, 'Vilka väljer oftast att svara när 88 % struntar i enkäten?', 'Vid stort bortfall blir de svarande sällan representativa, vilket undergräver generaliserbarheten.', NULL, 'vetenskaplig-stil-och-kriterier');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-2-01', 'chap-svenska-3-2', 'les-svenska-3-2-svenskans-historiska-epoker', 1, 'E', 'multiple_choice', 'Språkhistoria', 'Vilken händelse år 1526 brukar markera början på den nysvenska perioden?', NULL, '["Rökstenen restes i Östergötland","Nya testamentet gavs ut på svenska","Stavningsreformen tog bort hv och dt","Svenska Akademien grundades"]', '1', NULL, NULL, 'Det skedde under Gustav Vasas tid och spreds genom tryckkonsten.', 'Utgivningen av Nya testamentet på svenska år 1526 inledde äldre nysvenska.', NULL, 'svenskans-historiska-epoker');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-2-02', 'chap-svenska-3-2', 'les-svenska-3-2-svenskans-historiska-epoker', 2, 'C', 'multiple_choice', 'Språkhistoria', 'Vad hände i svenskan när det gamla fyrkasussystemet förenklades under fornsvensk tid?', NULL, '["Ordföljden blev friare än tidigare","Fast ordföljd blev viktigare för att visa vem som är subjekt respektive objekt","Alla substantiv förlorade pluraländelser","Svenskan slutade använda prepositioner"]', '1', NULL, NULL, 'När ändelsen inte längre visar om "mannen" är subjekt eller objekt måste platsen i meningen visa det.', 'Förlusten av kasusändelser ersattes av fastare ordföljd och fler prepositioner.', NULL, 'svenskans-historiska-epoker');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-2-03', 'chap-svenska-3-2', 'les-svenska-3-2-svenskans-historiska-epoker', 3, 'C', 'multiple_choice', 'Språkhistoria', 'Vilket uttryck är en stelnad rest av fornsvensk kasusböjning?', NULL, '["Att surfa på nätet","Att gå till skogs","Att skriva ett mejl","En röd cykel"]', '1', NULL, NULL, 'Leta efter genitiv-s efter prepositionen "till".', '"Till skogs" bevarar gammal genitiv efter prepositionen till.', NULL, 'svenskans-historiska-epoker');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-2-04', 'chap-svenska-3-2', 'les-svenska-3-2-svenskans-historiska-epoker', 4, 'A', 'multiple_choice', 'Språkhistoria', 'Vilka stavningsändringar infördes i den stora reformen 1906, som markerar övergången till nusvenska?', NULL, '["Bokstäverna å, ä och ö infördes för första gången","Stavningen av v-ljudet (f, fv, hv) blev v och dt i neutrum blev t eller tt","Verbens pluralformer avskaffades i lagtext","Runskriften återinfördes på skolor"]', '1', NULL, NULL, 'Exempel: "hvad" blev "vad" och "godt" blev "gott".', '1906 års stavningsreform förenklade stavningen av v-ljudet och t-ljudet (dt → t/tt).', NULL, 'svenskans-historiska-epoker');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-3-01', 'chap-svenska-3-3', 'les-svenska-3-3-litteraturvetenskapliga-perspektiv', 1, 'E', 'multiple_choice', 'Litteraturvetenskap', 'Vad betyder begreppet intertextualitet?', NULL, '["Att en text saknar styckeindelning","Att en text anspelar på eller står i förbindelse med andra texter","Att boken bara får läsas tyst","Att varje rad har exakt lika många stavelser"]', '1', NULL, NULL, 'Inter betyder mellan.', 'Intertextualitet handlar om hur texter refererar till eller omarbetar andra texter.', NULL, 'litteraturvetenskapliga-perspektiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-3-02', 'chap-svenska-3-3', 'les-svenska-3-3-litteraturvetenskapliga-perspektiv', 2, 'C', 'multiple_choice', 'Lyrikanalys', 'Vad innebär överklivning (enjambement) i en dikt?', NULL, '["Att en dikt inte rimmar","Att en mening eller fras fortsätter över radslutet utan skiljetecken","Att sista ordet upprepas tre gånger","Att dikten börjar på ett annat språk"]', '1', NULL, NULL, 'Meningsbyggnaden kliver över från en versrad till nästa.', 'Överklivning sker när en syntaktisk enhet bryts vid radslutet och fortsätter på nästa rad.', NULL, 'litteraturvetenskapliga-perspektiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-3-03', 'chap-svenska-3-3', 'les-svenska-3-3-litteraturvetenskapliga-perspektiv', 3, 'C', 'multiple_choice', 'Litteraturvetenskap', 'Vad utmärker en renodlad närläsning som analysmetod?', NULL, '["Att man utgår från författarens privata brev och dagböcker","Att man koncentrerar sig på själva textens form, språk, struktur och bildspråk","Att man jämför försäljningssiffror mellan förlag","Att man bara sammanfattar handlingen kronologiskt"]', '1', NULL, NULL, 'Fokus ligger helt inne i själva texten.', 'Närläsning studerar textens inre uppbyggnad och språkliga detaljer utan att söka förklaringar utanför verket.', NULL, 'litteraturvetenskapliga-perspektiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-svenska-3-3-04', 'chap-svenska-3-3', 'les-svenska-3-3-litteraturvetenskapliga-perspektiv', 4, 'A', 'multiple_choice', 'Litteraturvetenskap', 'Vad undersöker en ekokritisk läsning av en roman?', NULL, '["Enbart ekonomiska termer i dialoger","Hur relationen mellan människa, natur, miljö och ekosystem gestaltas i texten","Antalet vokaler i varje kapitel","Förlagets papperskvalitet"]', '1', NULL, NULL, 'Eko- syftar här på ekologi.', 'Ekokritik analyserar natursyn, miljöskildring och samspelet mellan människa och omgivning i litteraturen.', NULL, 'litteraturvetenskapliga-perspektiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-1-01', 'chap-engelska-5-1', 'les-engelska-5-1-centrala-verbformer-och-ordfoljd', 1, 'E', 'multiple_choice', 'Grammatik', 'Vilken mening använder "there" eller "it" korrekt?', NULL, '["It is many students waiting outside","There is two laptops on the desk","There are several solutions to this problem","There is raining heavily today"]', '2', NULL, NULL, 'Använd "there are" vid existens i plural och "it is" för väder.', '"There are several solutions" använder både rätt formellt subjekt ("there") och pluralverb ("are").', NULL, 'centrala-verbformer-och-ordfoljd');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-1-02', 'chap-engelska-5-1', 'les-engelska-5-1-formellt-och-informellt-register', 2, 'E', 'multiple_choice', 'Register', 'Vilken mening passar bäst i en formell skoluppsats på engelska?', NULL, '["Lots of teens think social media is super stressful","Many teenagers experience significant stress from social media","Teenagers don''t wanna deal with social media stress","Social media kinda stresses teens out a lot"]', '1', NULL, NULL, 'Undvik sammandragningar och slangord som "lots of", "super", "wanna" och "kinda".', 'Alternativ 2 använder exakt, sakligt ordförråd utan talspråkliga förkortningar.', NULL, 'formellt-och-informellt-register');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-1-03', 'chap-engelska-5-1', 'les-engelska-5-1-centrala-verbformer-och-ordfoljd', 3, 'C', 'multiple_choice', 'Grammatik', 'Vilken mening är grammatiskt korrekt?', NULL, '["Everyone in the room know the answer","The news from the laboratory are very promising","She gave me a good advice before the interview","Everybody in the group has submitted the report"]', '3', NULL, NULL, 'Kom ihåg att "everybody", "news" och "advice" har specialregler på engelska.', '"Everybody" tar singularverb ("has"); i de andra alternativen borde det stå "knows", "is" och "some good advice".', NULL, 'centrala-verbformer-och-ordfoljd');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-1-04', 'chap-engelska-5-1', 'les-engelska-5-1-skimming-scanning-och-innehall', 4, 'C', 'multiple_choice', 'Läsförståelse', 'Läs textutdraget: "Unlike the previous model, which required daily charging, the new sensor operates for three weeks on a single battery." Vad framgår om den nya sensorn?', NULL, '["Den måste laddas varje dag precis som föregångaren","Den håller batteriet betydligt längre än den äldre modellen","Den saknar helt batteri","Den fungerar sämre än den förra modellen"]', '1', NULL, NULL, '"Unlike" markerar en kontrast mellan föregående modell och den nya.', 'Tidigare modell krävde daglig laddning, medan den nya går i tre veckor på en laddning.', NULL, 'skimming-scanning-och-innehall');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-1-05', 'chap-engelska-5-1', 'les-engelska-5-1-centrala-verbformer-och-ordfoljd', 5, 'A', 'multiple_choice', 'Grammatik', 'Välj korrekt verbform: "The impact of rising energy prices on small businesses ___ widely debated."', NULL, '["are","were","has been","have been"]', '2', NULL, NULL, 'Vad är det egentliga huvudordet i subjektet?', 'Huvudordet är "The impact" (singular), inte "prices" eller "businesses", vilket kräver "has been".', NULL, 'centrala-verbformer-och-ordfoljd');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-1-06', 'chap-engelska-5-1', 'les-engelska-5-1-skimming-scanning-och-innehall', 6, 'A', 'multiple_choice', 'Läsförståelse', 'Läs meningen: "Far from resolving the housing shortage, the new regulation appears to have slowed construction down." Vad hävdar skribenten?', NULL, '["Den nya regeln har löst bostadsbristen nästan helt","Regeln har inte alls löst bristen, utan tycks tvärtom ha bromsat byggandet","Byggandet har ökat långt från stadskärnan","Bostadsbristen har ingen koppling till byggtakt"]', '1', NULL, NULL, '"Far from + -ing" betyder "långt ifrån att...".', '"Far from resolving" negerar lösningen, och "slowed construction down" visar en negativ effekt.', NULL, 'skimming-scanning-och-innehall');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-2-01', 'chap-engelska-5-2', 'les-engelska-5-2-styckeindelning-och-lankord', 1, 'E', 'multiple_choice', 'Textbindning', 'Vilket länkord passar bäst i luckan? "Solar power reduces emissions. ___, installation costs have fallen rapidly."', NULL, '["However","Moreover","Otherwise","Instead"]', '1', NULL, NULL, 'Den andra meningen lägger till ännu ett positivt argument.', '"Moreover" betyder dessutom och bygger vidare på samma linje.', NULL, 'styckeindelning-och-lankord');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-2-02', 'chap-engelska-5-2', 'les-engelska-5-2-styckeindelning-och-lankord', 2, 'C', 'multiple_choice', 'Grammatik', 'Vilken mening är korrekt?', NULL, '["Despite of the delay, the team finished on time","Although the delay, the team finished on time","Despite the delay, the team finished on time","In spite the delay, the team finished on time"]', '2', NULL, NULL, 'Prepositionen "despite" tar substantivfras utan "of".', '"Despite the delay" är grammatiskt korrekt ("although" kräver sats; "in spite" kräver "of").', NULL, 'styckeindelning-och-lankord');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-2-03', 'chap-engelska-5-2', 'les-engelska-5-2-styckeindelning-och-lankord', 3, 'C', 'multiple_choice', 'Skrivande', 'Vilken funktion har en "topic sentence" i början av ett essästycke?', NULL, '["Den tackar läsaren för uppmärksamheten","Den presenterar styckets centrala tanke som resten av stycket utvecklar och exemplifierar","Den innehåller alltid ett direkt citat","Den avslutar hela texten med en sammanfattning"]', '1', NULL, NULL, 'Varje stycke ska ha en tydlig röd tråd.', 'En topic sentence anger styckets huvudpoäng och skapar orientering för läsaren.', NULL, 'styckeindelning-och-lankord');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-2-04', 'chap-engelska-5-2', 'les-engelska-5-2-styckeindelning-och-lankord', 4, 'A', 'multiple_choice', 'Stilistik', 'Vilken inledningsmening passar bäst i en formell essä på hög nivå?', NULL, '["In this essay I am going to tell you about why electric cars are good","The rapid shift toward electric vehicles raises crucial questions about infrastructure and sustainability","Have you ever wondered about electric cars? Well, let me explain","Electric cars are really great and everybody should buy one today"]', '1', NULL, NULL, 'Undvik metatexter som "I am going to tell you" och talspråkliga uppmaningar.', 'Alternativ 2 öppnar sakligt direkt i ämnet med precist ordförråd.', NULL, 'styckeindelning-och-lankord');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-3-01', 'chap-engelska-5-3', 'les-engelska-5-3-kollokationer-och-falska-vanner', 1, 'E', 'multiple_choice', 'Ordförråd', 'Vad betyder det engelska ordet "eventually" på svenska?', NULL, '["Eventuellt","Kanske","Slutligen / så småningom","Faktiskt"]', '2', NULL, NULL, 'Se upp för den falska vännen!', '"Eventually" betyder till slut eller så småningom (inte eventuellt).', NULL, 'kollokationer-och-falska-vanner');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-3-02', 'chap-engelska-5-3', 'les-engelska-5-3-kollokationer-och-falska-vanner', 2, 'C', 'multiple_choice', 'Kollokationer', 'Vilken ordkombination är idiomatisk engelska?', NULL, '["do a mistake","make homework","make a decision","do a promise"]', '2', NULL, NULL, 'Man säger "make a mistake", "do homework", "make a promise".', '"Make a decision" är den naturliga kollokationen.', NULL, 'kollokationer-och-falska-vanner');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-3-03', 'chap-engelska-5-3', 'les-engelska-5-3-kollokationer-och-falska-vanner', 3, 'C', 'multiple_choice', 'Ordförråd', 'Vilket ord saknas? "Wearing a helmet while cycling is a ___ precaution."', NULL, '["sensitive","sensible","sentimental","sensation"]', '1', NULL, NULL, 'Det handlar om en förnuftig och klok åtgärd.', '"Sensible" betyder förnuftig eller klok, medan "sensitive" betyder känslig.', NULL, 'kollokationer-och-falska-vanner');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-5-3-04', 'chap-engelska-5-3', 'les-engelska-5-3-kollokationer-och-falska-vanner', 4, 'A', 'multiple_choice', 'Ordförståelse i kontext', 'Läs meningen: "The new policy turned out to be a double-edged sword: it lowered costs, yet alienated loyal staff." Vad betyder uttrycket "a double-edged sword"?', NULL, '["En lösning utan några nackdelar alls","Något som både har positiva effekter och allvarliga nackdelar samtidigt","Ett gammalt militärt misstag","En åtgärd som aldrig genomfördes"]', '1', NULL, NULL, 'Läs förklaringen efter kolonet.', 'Uttrycket beskriver något tveeggat som både gagnar och skadar.', NULL, 'kollokationer-och-falska-vanner');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-1-01', 'chap-engelska-6-1', 'les-engelska-6-1-komplex-meningsbyggnad-och-passiv', 1, 'E', 'multiple_choice', 'Grammatik', 'Vilken passiv mening motsvarar korrekt "Engineers tested the new turbine yesterday"?', NULL, '["The new turbine tested yesterday by engineers","The new turbine was tested yesterday by engineers","The new turbine is tested yesterday by engineers","The new turbine were tested yesterday by engineers"]', '1', NULL, NULL, 'Tidpunkten "yesterday" kräver dåtid av "be" i singular ("was").', '"The new turbine was tested yesterday" har korrekt tempus och kongruens.', NULL, 'komplex-meningsbyggnad-och-passiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-1-02', 'chap-engelska-6-1', 'les-engelska-6-1-akademisk-ton-och-lankord', 2, 'E', 'multiple_choice', 'Stilistik', 'Vilken mening har mest konsekvent akademisk ton?', NULL, '["Kids these days don''t read books as much as before","Recent surveys indicate a decline in daily reading among adolescents","It''s super sad that young people barely open books anymore","Reading is basically going down for teens everywhere"]', '1', NULL, NULL, 'Sök saklig röst utan värdeord eller sammandragningar.', 'Alternativ 2 använder precist, neutralt sakprosaspråk ("indicate a decline", "adolescents").', NULL, 'akademisk-ton-och-lankord');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-1-03', 'chap-engelska-6-1', 'les-engelska-6-1-akademisk-ton-och-lankord', 3, 'C', 'multiple_choice', 'Kommatering', 'Vilken mening följer engelska skrivregler för "however"?', NULL, '["The battery lasts all day, however, it charges slowly","The battery lasts all day; however, it charges slowly","The battery lasts all day however it charges slowly","However the battery lasts all day, it charges slowly"]', '1', NULL, NULL, '"However" kan inte binda ihop två huvudsatser med bara komma.', 'Ett semikolon (eller punkt) krävs före "however" när två fullständiga satser fogas samman.', NULL, 'akademisk-ton-och-lankord');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-1-04', 'chap-engelska-6-1', 'les-engelska-6-1-komplex-meningsbyggnad-och-passiv', 4, 'C', 'multiple_choice', 'Grammatik', 'Välj rätt relativpronomen: "The university campus, ___ was renovated in 2022, now runs on solar energy."', NULL, '["that","which","what","whom"]', '1', NULL, NULL, 'Efter ett kommatecken i en icke-nödvändig relativsats om ett ting används bara ett alternativ.', '"which" måste användas i parentetiska (kommaavskilda) relativsatser om saker.', NULL, 'komplex-meningsbyggnad-och-passiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-1-05', 'chap-engelska-6-1', 'les-engelska-6-1-retorisk-analys-av-engelsk-sakprosa', 5, 'A', 'multiple_choice', 'Retorisk analys', 'Läs utdraget: "While seasoned experts offered measured warnings, a handful of critics peddled sensationalist fears." Hur vinklar ordvalet läsarens syn?', NULL, '["Båda grupperna skildras lika objektivt och sakligt","Experterna ges auktoritet (\"seasoned\", \"measured\"), medan kritikerna nedvärderas (\"a handful\", \"peddled\")","Kritikerna framställs som mer pålitliga än experterna","Texten innehåller inga värdeladdade ord alls"]', '1', NULL, NULL, 'Jämför adjektiven och verben för de två sidorna.', 'Värdeladdade ord ("seasoned" vs "peddled sensationalist fears") skapar en skev kontrast till förmån för experterna.', NULL, 'retorisk-analys-av-engelsk-sakprosa');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-1-06', 'chap-engelska-6-1', 'les-engelska-6-1-komplex-meningsbyggnad-och-passiv', 6, 'A', 'multiple_choice', 'Grammatik', 'Vilken mening undviker felet med hängande particip (dangling participle)?', NULL, '["Having reviewed the evidence, the verdict was announced immediately","Having reviewed the evidence, the jury announced the verdict immediately","Driving down the highway, the mountain peaks appeared on the horizon","After finishing the lab report, the computer crashed suddenly"]', '1', NULL, NULL, 'Subjektet efter kommat måste vara den som faktiskt utförde participhandlingen.', '"the jury" är den som granskade bevisen ("Having reviewed the evidence").', NULL, 'komplex-meningsbyggnad-och-passiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-2-01', 'chap-engelska-6-2', 'les-engelska-6-2-kallsyntes-och-motargument', 1, 'E', 'multiple_choice', 'Källhantering', 'Vad menas med ett "dropped quote" i engelskt skrivande?', NULL, '["Ett citat som tagits bort av redaktören","Ett fristående citat som placerats utan inledande signalfras eller koppling till egen text","Ett citat från en mycket gammal bok","Ett citat som översatts till svenska"]', '1', NULL, NULL, 'Citatet "släpps" rakt ner i stycket utan sammanhang.', 'Citat ska alltid integreras med en signalfras (t.ex. "According to...") och följas av kommentar.', NULL, 'kallsyntes-och-motargument');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-2-02', 'chap-engelska-6-2', 'les-engelska-6-2-kallsyntes-och-motargument', 2, 'C', 'multiple_choice', 'Argumentation', 'Vilken inledning markerar tydligast ett nyanserat medgivande (concession) innan man framför sin egen ståndpunkt?', NULL, '["Everyone knows without a doubt that...","Admittedly, the initial cost is high; however, ...","First of all, I totally disagree because...","Finally, let us ignore all critics because..."]', '1', NULL, NULL, 'Ordet "admittedly" betyder "visserligen / det ska medges".', '"Admittedly...; however, ..." erkänner motpartens poäng innan man argumenterar vidare.', NULL, 'kallsyntes-och-motargument');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-2-03', 'chap-engelska-6-2', 'les-engelska-6-2-kallsyntes-och-motargument', 3, 'C', 'multiple_choice', 'Referatteknik', 'Vilket referatverb passar bäst när en författare i källtexten aktivt försöker bevisa ett kontroversiellt förslag utan full enighet?', NULL, '["contends","proves beyond doubt","guarantees","whispers"]', '0', NULL, NULL, 'Välj ett sakligt ord som betyder "hävdar / driver tesen".', '"Contends" eller "argues" markerar neutralt att det rör sig om skribentens ståndpunkt.', NULL, 'kallsyntes-och-motargument');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-2-04', 'chap-engelska-6-2', 'les-engelska-6-2-kallsyntes-och-motargument', 4, 'A', 'multiple_choice', 'Källkritik', 'En krönikör skriver: "Two athletes in our club improved their times after buying these shoes, which proves they work for all runners." Vilket logiskt felslut förekommer?', NULL, '["Hasty generalization (förhastad generalisering utifrån enstaka anekdoter)","Ad hominem (personangrepp)","Appeal to authority (auktoritetsargument)","Equivocation (ordvits)"]', '0', NULL, NULL, 'Två individer räcker inte som bevis för alla löpare.', 'Att dra generella slutsatser av ett par enstaka exempel är en förhastad generalisering.', NULL, 'kallsyntes-och-motargument');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-3-01', 'chap-engelska-6-3', 'les-engelska-6-3-karaktarisering-och-subtext', 1, 'E', 'multiple_choice', 'Litterär analys', 'Vad innebär begreppet "foreshadowing" i en berättelse?', NULL, '["Att en ny karaktär dyker upp i sista kapitlet utan förvarning","Att tidiga ledtrådar i texten antyder händelser som kommer senare","Att hela boken berättas baklänges","Att vädret alltid är soligt"]', '1', NULL, NULL, 'En skugga av något som ska komma.', 'Foreshadowing planterar subtila ledtrådar som förbereder läsaren på senare vändningar.', NULL, 'karaktarisering-och-subtext');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-3-02', 'chap-engelska-6-3', 'les-engelska-6-3-karaktarisering-och-subtext', 2, 'C', 'multiple_choice', 'Litterär analys', 'När uppstår "dramatic irony" i en roman eller pjäs?', NULL, '["När vädret är dåligt under ett bröllop","När läsaren eller publiken känner till en avgörande omständighet som karaktären själv inte vet om","När två karaktärer skämtar med varandra","När berättaren avslöjar sitt eget namn"]', '1', NULL, NULL, 'Informationsövertag hos publiken.', 'Dramatisk ironi bygger på att publiken vet mer än karaktären och därför ser ödesdigra misstag.', NULL, 'karaktarisering-och-subtext');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-3-03', 'chap-engelska-6-3', 'les-engelska-6-3-karaktarisering-och-subtext', 3, 'C', 'multiple_choice', 'Stilistik', 'Vilken mening följer konventionen för litterärt presens vid analys?', NULL, '["In the opening scene, the protagonist left the city and felt relieved","In the opening scene, the protagonist leaves the city and feels relieved","In the opening scene, the protagonist has left and felt relieved","In the opening scene, the protagonist will leaving the city"]', '1', NULL, NULL, 'Verkets handling beskrivs alltid i presens i litterär analys.', '"leaves... and feels..." håller konsekvent litterärt presens.', NULL, 'karaktarisering-och-subtext');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-6-3-04', 'chap-engelska-6-3', 'les-engelska-6-3-karaktarisering-och-subtext', 4, 'A', 'multiple_choice', 'Litterär analys', 'Vad avses med "pathetic fallacy" i engelskspråkig litteraturanalys?', NULL, '["Ett svagt argument i en debattartikel","Att natur, väder eller omgivning tillskrivs mänskliga känslor så att miljön speglar karaktärernas stämning","Att en berättare glömmer huvudpersonens namn","Att ett rim faller på fel stavelse"]', '1', NULL, NULL, 'Exempel: "weeping skies" eller ett rasande oväder vid en inre kris.', 'Pathetic fallacy speglar mänskliga känslor i naturen och vädret.', NULL, 'karaktarisering-och-subtext');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-1-01', 'chap-engelska-7-1', 'les-engelska-7-1-akademisk-argumentation-och-hedging', 1, 'E', 'multiple_choice', 'Hedging', 'Vilken mening uttrycker lämplig akademisk försiktighet (hedging)?', NULL, '["The experiment proves completely that no other factor matters","The findings suggest that sleep quality may influence exam performance","Sleep definitely controls all academic grades everywhere","It is obviously impossible to disagree with this result"]', '1', NULL, NULL, 'Sök kombinationen av försiktigt verb ("suggest") och modalt verb ("may").', '"Suggest" och "may" markerar sakligt ett troligt samband utan överdrivna anspråk.', NULL, 'akademisk-argumentation-och-hedging');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-1-02', 'chap-engelska-7-1', 'les-engelska-7-1-invers-ordfoljd-och-konjunktiv', 2, 'E', 'multiple_choice', 'Grammatik', 'Välj korrekt inversion: "Seldom ___ such unanimous support in parliament."', NULL, '["we have seen","have we seen","did we saw","seen have we"]', '1', NULL, NULL, 'Efter "Seldom" i spetsen placeras hjälpverbet före subjektet.', 'Hjälpverbet "have" flyttas framför subjektet "we": "Seldom have we seen...".', NULL, 'invers-ordfoljd-och-konjunktiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-1-03', 'chap-engelska-7-1', 'les-engelska-7-1-invers-ordfoljd-och-konjunktiv', 3, 'C', 'multiple_choice', 'Grammatik', 'Vilken mening använder korrekt inversion efter "Not only"?', NULL, '["Not only the new law reduced waste, it also saved money","Not only did the new law reduced waste, but it also saved money","Not only did the new law reduce waste, but it also saved money","Not only reduced the new law waste, it also saved money"]', '2', NULL, NULL, 'Använd "did + subjekt + infinitiv".', '"Not only did the new law reduce..." sätter "did" före subjektet och huvudverbet i grundform.', NULL, 'invers-ordfoljd-och-konjunktiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-1-04', 'chap-engelska-7-1', 'les-engelska-7-1-syntes-av-engelska-kallor', 4, 'C', 'multiple_choice', 'Källsyntes', 'Vad kännetecknar så kallad "patchwriting" vid omskrivning av engelska källor?', NULL, '["Att man sammanfattar tre olika artiklar helt självständigt","Att man kopierar originalets meningsbyggnad och bara byter ut enstaka synonymer","Att man använder tydliga fotnoter enligt Oxford","Att man skriver en kort rubrik över varje stycke"]', '1', NULL, NULL, 'Ordet "patch" syftar på att lappa ihop originaltexten.', 'Patchwriting är otillräcklig parafrasering som ligger för nära källans exakta syntax och lätt gränsar till plagiat.', NULL, 'syntes-av-engelska-kallor');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-1-05', 'chap-engelska-7-1', 'les-engelska-7-1-invers-ordfoljd-och-konjunktiv', 5, 'A', 'multiple_choice', 'Grammatik', 'Vilken mening illustrerar korrekt formell konjunktiv (mandative subjunctive) på engelska?', NULL, '["The ethics board insisted that the researcher submits raw data","The ethics board insisted that the researcher submit raw data","The ethics board insisted that the researcher submitting raw data","The ethics board insisted that the researcher to submit raw data"]', '1', NULL, NULL, 'I formell konjunktiv efter "insisted that" står verbet i ren grundform utan -s i tredje person singular.', '"...that the researcher submit..." använder ren infinitivform (utan -s) som mandative subjunctive.', NULL, 'invers-ordfoljd-och-konjunktiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-1-06', 'chap-engelska-7-1', 'les-engelska-7-1-invers-ordfoljd-och-konjunktiv', 6, 'A', 'multiple_choice', 'Grammatik', 'Vad motsvarar den inverterade satsen "Were the committee to reject the proposal,..."?', NULL, '["En fråga om vad kommittén gjorde förra året","En formell hypotetisk villkorssats med innebörden \"If the committee were to reject the proposal,...\"","Ett påstående om att förslaget redan godkänts","En uppmaning i imperativ"]', '1', NULL, NULL, 'Inversion i villkorssatser ersätter "if".', 'Att flytta "Were" först ersätter konjunktionen "If" i formella hypotetiska villkorssatser.', NULL, 'invers-ordfoljd-och-konjunktiv');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-2-01', 'chap-engelska-7-2', 'les-engelska-7-2-presupposition-och-metaforik', 1, 'E', 'multiple_choice', 'Stilanalys', 'Vad är syftet med en eufemism som "downsizing" i stället för "laying off staff"?', NULL, '["Att göra beskedet mer skrämmande","Att mildra eller dölja en obehaglig verklighet bakom ett neutralt eller tekniskt ordval","Att förkorta meningen grammatiskt","Att skapa en rolig ordlek"]', '1', NULL, NULL, 'En eufemism är en förskönande omskrivning.', 'Eufemismer använder mildare formuleringar för att tona ned negativa besked.', NULL, 'presupposition-och-metaforik');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-2-02', 'chap-engelska-7-2', 'les-engelska-7-2-presupposition-och-metaforik', 2, 'C', 'multiple_choice', 'Diskursanalys', 'Vilket dolt antagande (presupposition) rymms i frågan "Why does the council keep ignoring residents'' safety"?', NULL, '["Att rådet faktiskt redan ignorerar invånarnas säkerhet","Att invånarna vill sänka säkerheten","Att rådet inte existerar","Frågan innehåller inget dolt antagande"]', '0', NULL, NULL, 'Frågan handlar om "varför" det sker, inte "om" det sker.', 'Genom att fråga "Why does... keep ignoring" tas det för givet som fakta att säkerheten ignoreras.', NULL, 'presupposition-och-metaforik');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-2-03', 'chap-engelska-7-2', 'les-engelska-7-2-presupposition-och-metaforik', 3, 'C', 'multiple_choice', 'Retorik', 'Vad avses med begreppet "framing" (inramning) i textanalys?', NULL, '["Vilket typsnitt en bok är tryckt i","Hur ett ämne presenteras med bestämda perspektiv och metaforer som styr läsarens tolkning","Antalet sidor i en rapport","Att alla citat placeras i en ram"]', '1', NULL, NULL, 'Man sätter en ram runt hur problemet ska förstås.', 'Framing innebär att välja begrepp och metaforer som lyfter fram vissa aspekter och döljer andra.', NULL, 'presupposition-och-metaforik');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-2-04', 'chap-engelska-7-2', 'les-engelska-7-2-presupposition-och-metaforik', 4, 'A', 'multiple_choice', 'Stilanalys', 'I ett pressmeddelande används passiv agentlös konstruktion: "Mistakes were made during the rollout." Vad uppnås stilistiskt?', NULL, '["Den ansvarige aktören pekas ut tydligare än i aktiv form","Ansvar och aktör osynliggörs så att ingen specifik person eller grupp behöver ta skulden","Meningen blir grammatiskt inkorrekt","Budskapet blir mer personligt och intimt"]', '1', NULL, NULL, 'Jämför med "Our department made mistakes".', 'Agentlös passiv form tar bort subjektet som handlade och dämpar därmed ansvarstagandet.', NULL, 'presupposition-och-metaforik');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-3-01', 'chap-engelska-7-3', 'les-engelska-7-3-abstract-och-imrad', 1, 'E', 'multiple_choice', 'Akademiskt skrivande', 'Vad står förkortningen IMRaD för i vetenskapliga rapporter?', NULL, '["Index, Methods, References and Data","Introduction, Methods, Results and Discussion","Idea, Model, Research and Draft","Information, Meaning, Rhetoric and Design"]', '1', NULL, NULL, 'De fyra huvudavsnitten i en vetenskaplig artikel.', 'IMRaD står för Introduction, Methods, Results and Discussion.', NULL, 'abstract-och-imrad');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-3-02', 'chap-engelska-7-3', 'les-engelska-7-3-abstract-och-imrad', 2, 'C', 'multiple_choice', 'Tempus', 'Vilken tempusform är standard när du i ett abstract beskriver hur datainsamlingen genomfördes?', NULL, '["Futurum (\"Data will be collected...\")","Preteritum (\"Data were collected from 200 participants...\")","Imperativ (\"Collect the data...\")","Pågående presens (\"Data are collecting...\")"]', '1', NULL, NULL, 'Undersökningen har redan ägt rum när rapporten skrivs.', 'Genomförda metodsteg beskrivs i preteritum ("Data were collected...").', NULL, 'abstract-och-imrad');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-3-03', 'chap-engelska-7-3', 'les-engelska-7-3-abstract-och-imrad', 3, 'C', 'multiple_choice', 'Akademiskt skrivande', 'Vilken mening markerar tydligast en forskningslucka (research gap) i en engelsk inledning?', NULL, '["I am very interested in this topic","However, little empirical attention has been paid to long-term effects in smaller municipalities","Everyone has studied everything about this already","This paper contains four sections and a bibliography"]', '1', NULL, NULL, 'Leta efter formuleringen som pekar på vad tidigare forskning saknar.', '"However, little empirical attention has been paid to..." motiverar varför den nya studien behövs.', NULL, 'abstract-och-imrad');
INSERT OR REPLACE INTO questions (id, chapter_id, lesson_id, sort_order, grade_level, question_type, category_sv, prompt_sv, latex_formula, options_json, correct_answer, numeric_tolerance, unit_sv, hint_sv, step_by_step_solution_sv, deep_derivation_sv, related_section_slug) VALUES ('q-engelska-7-3-04', 'chap-engelska-7-3', 'les-engelska-7-3-abstract-och-imrad', 4, 'A', 'multiple_choice', 'Akademiskt skrivande', 'Varför ska ett vetenskapligt abstract inte bara beskriva vad uppsatsen handlar om ("This paper discusses...") utan även redovisa resultat och slutsats?', NULL, '["För att läsaren snabbt ska kunna bedöma studiens faktiska fynd och relevans utan att läsa hela artikeln","För att ersätta själva resultatkapitlet helt","För att fylla ut ordantalet till 1 000 ord","För att undvika att ange metod"]', '0', NULL, NULL, 'Ett abstract är en fristående miniatyrversion av hela undersökningen.', 'Forskare läser abstracts för att se både fråga, metod, huvudresultat och slutsats direkt.', NULL, 'abstract-och-imrad');
